window.BANK = {"built":"2026-10-17","subjects":[{"id":"hcip_cloud","name":"HCIP-Cloud Service","file":"HCIP-Cloud Service题库.pdf","count":338},{"id":"ict_calc","name":"ICT 大赛 计算赛道","file":"ICT大赛-计算赛道（最新省赛题库）.pdf","count":146},{"id":"hcna_storage","name":"HCNA-Storage H13-611","file":"HCNA-Storage-(H13-611)题库-v4.0.doc","count":254},{"id":"hcna_cloud","name":"HCNA-Cloud 云计算","file":"华为认证HCNA-Cloud云计算题库.pdf","count":222}],"questions":[{"id":"hcip_cloud-1","subject":"hcip_cloud","num":1,"pnum":1,"page":0,"type":"multi","stem":"以下哪些是云原生的优势？","options":[["A","模块松耦合"],["B","快速部署"],["C","硬件虚拟化"],["D","服务快速恢复"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"云原生靠容器与微服务带来模块松耦合、快速迭代部署和故障自愈式的服务快速恢复，故选 ABD。硬件虚拟化由 Hypervisor 实现，属 IaaS 层虚拟机的能力，不是云原生带来的架构优势，排除 C。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-2","subject":"hcip_cloud","num":2,"pnum":2,"page":0,"type":"single","stem":"云架构设计非常灵活不需要掌握 UML。","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。UML 是架构设计的通用建模语言，云上应用同样要用类图、顺序图、部署图来表达结构与交互；架构灵活恰恰需要规范建模来约束和沟通，「不需要掌握」不成立，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-3","subject":"hcip_cloud","num":3,"pnum":3,"page":0,"type":"multi","stem":"云原生四大应用是指？","options":[["A","DevOps"],["B","持续交付"],["C","容器"],["D","微服务"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"云原生四大要素即容器、微服务、DevOps 与持续交付：容器是运行时载体，微服务是架构形态，DevOps 是研发协作流程，持续交付是发布实践，四项全选，故选 ABCD。易错点是只把容器、微服务当技术而漏掉后两项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-4","subject":"hcip_cloud","num":4,"pnum":4,"page":0,"type":"multi","stem":"华为云三大中间件服务是？","options":[["A","DCS 分布式缓存服务"],["B","DMS 分布式消息服务"],["C","DDM 分布式数据库中间件"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"华为云中间件三件套为 DCS 分布式缓存、DMS 分布式消息、DDM 分布式数据库中间件，分别对应缓存加速、异步解耦与分库分表，故选 ABC。易错点：DDM 自身不存数据，只是 RDS 前的访问层，别按「不是数据库」把它排除。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-5","subject":"hcip_cloud","num":5,"pnum":5,"page":0,"type":"single","stem":"以下哪个服务不属于华为云 PaaS 服务？","options":[["A","微服务云应用平台 ServiceStage"],["B","弹性云服务器 ECS"],["C","云器引擎 CCE"],["D","云性能测试服务 CPTS"]],"answer":["B"],"ans_raw":"B","explain":"ECS 交付的是虚拟机形态的计算资源，应用与运行环境仍由用户自己装，属 IaaS 而非 PaaS，故选 B。ServiceStage、CCE、CPTS 都由平台托管运行与运维，是典型 PaaS。选项 C 的「云器引擎」是「云容器引擎」的错字，不影响判断。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-6","subject":"hcip_cloud","num":6,"pnum":6,"page":1,"type":"single","stem":"ServiceStage 包含以下能力除了？","options":[["A","集群和节点的资源管理"],["B","微服务应用开发工具盒微服务管理"],["C","数据库管理"],["D","容器和虚拟机应用的部署和应用管理"]],"answer":["C"],"ans_raw":"C","explain":"ServiceStage 的能力覆盖集群与节点资源管理、微服务开发工具与微服务管理、容器和虚拟机应用的部署与应用管理，故选 C 之外的三项；数据库实例本身的管理归 RDS 等数据服务，不在其范围内，故选 C。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-7","subject":"hcip_cloud","num":7,"pnum":7,"page":1,"type":"single","stem":"应用架构变迁已经发展到了什么阶段？","options":[["A","单体架构"],["B","SOA 架构"],["C","微服务架构"],["D","雾技术架构"]],"answer":["C"],"ans_raw":"C","explain":"演进主线是单体架构→SOA 架构→微服务架构，当前落点为微服务，故选 C。单体与 SOA 是被替代的前两代，「雾技术架构」不是应用架构演进的正式阶段，属生造名词。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-8","subject":"hcip_cloud","num":8,"pnum":8,"page":1,"type":"multi","stem":"华为云 PaaS 有哪些 level 的解决方案？","options":[["A","应用零改造上云.自动部署和运维"],["B","应用+云中间件.减少运营和运维的成本"],["C","应用容器化.秒级弹性伸缩、资源利用更高"],["D","应用微服务化.特性解耦。快速上线"],["E","业务极致创新.基于函数的编程"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"五个 level 是从浅到深的上云路径：应用零改造上云、换用云中间件、应用容器化、应用微服务化、基于函数的 Serverless 极致创新，五项都成立，故选 ABCDE。本题问的是 PaaS 全部层级，别按「传统行业上云」只取前四项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-9","subject":"hcip_cloud","num":9,"pnum":9,"page":2,"type":"multi","stem":"业务使用容器后能带来哪些好处？","options":[["A","通过共享 kernel 细粒度资源隔离。（降低企业成本）"],["B","为业务提高了安全性"],["C","定义了环境无关的标准的交付、部署规范。（提高交付效率）"],["D","秒级快速启动和停止（适合敏捷扩缩容场景）"],["E","提升代码开发质量"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"容器的价值在共享内核做细粒度资源隔离（提升利用率、降本）、以标准交付物实现环境无关的部署规范、秒级启停适配敏捷扩缩容，故选 ACD。易错项 B：容器共享宿主内核，隔离强度弱于虚拟机，安全性算不上优势；E 与容器无关。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-10","subject":"hcip_cloud","num":10,"pnum":10,"page":2,"type":"multi","stem":"微服务较传统单体架构可以解决以下哪些问题？","options":[["A","维护成本高"],["B","交付周期长"],["C","代码质量差"],["D","可伸缩性差"],["E","新人培养周期长"]],"answer":["A","B","D","E"],"ans_raw":"ABDE","explain":"微服务把大单体拆成独立可部署的小服务，改动影响面小、交付周期短、可按瓶颈单独伸缩、新人只需吃透单个服务，故选 ABDE。代码质量取决于团队工程实践，架构拆分并不能保证代码变好，排除 C。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-11","subject":"hcip_cloud","num":11,"pnum":11,"page":2,"type":"single","stem":"DCS 主要用于热点数据缓存，用于提升数据访问能力，降低数据库压力。","options":[["A","YES"],["B","NO"]],"answer":["A"],"ans_raw":"A","explain":"对。DCS 的定位就是把热点数据放进内存供快速读取，用缓存命中减少后端访问，既提升数据访问能力又给数据库减压，这一描述与其产品定位一致，故选 A（YES）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-12","subject":"hcip_cloud","num":12,"pnum":12,"page":3,"type":"single","stem":"如果企业自己开发或维护中间件.则企业需要自己处理软硬件的安装部署、故障和维护以及 bug 修复等；如果使用云中间件服务则可以实现开箱即用。","options":[["A","YES"],["B","NO"]],"answer":["A"],"ans_raw":"A","explain":"对。自建中间件时软硬件安装部署、故障维护与 bug 修复全由企业自己承担，云中间件把这些工作托管到平台侧，实例开通即可接入使用，实现开箱即用，故选 A（YES）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-13","subject":"hcip_cloud","num":13,"pnum":13,"page":3,"type":"single","stem":"创建应用时一个应用可以创建多个容器么","options":[["A","可以"],["B","不可以"]],"answer":["A"],"ans_raw":"A","explain":"可以。一个应用可由多个组件、多类实例构成，而每个实例（Pod）本身又允许包含共享网络与存储的多个容器，所以创建应用时设置多个容器是正常用法，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-14","subject":"hcip_cloud","num":14,"pnum":14,"page":3,"type":"single","stem":"CCE 目前支持的集群类型有哪些","options":[["A","虚拟机"],["B","裸金属"],["C","Windows"],["D","以上三种都支持"]],"answer":["D"],"ans_raw":"D","explain":"CCE 既能以 ECS 虚拟机作为集群节点，也支持裸金属服务器形态的节点，还可支持承载 Windows 容器工作负载的节点，三种形态都能建，故选 D。易错点是以为 Kubernetes 只能跑 Linux 工作负载。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-15","subject":"hcip_cloud","num":15,"pnum":15,"page":3,"type":"multi","stem":"华为 CSE 支持多语言微服务接入与互通.其中支持的语言包括","options":[["A","Java"],["B","GO"],["C","net"],["D","Node.js"],["E","PHP"],["F","Python"]],"answer":["A","B","C","D","E","F"],"ans_raw":"ABCDEF","explain":"选 ABCDEF。CSE 面向多语言微服务提供统一接入与互通，Java、Go、.NET、Node.js、PHP、Python 都能通过服务治理框架注册到同一注册中心并跨语言互调，六项全在支持范围内。要留意的是清单里没有 C 语言，遇到把 C 语言列为支持项的说法应判为不正确。","note":"题源原解析（排版截断）：“注意不支持 C 语言。”","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-16","subject":"hcip_cloud","num":16,"pnum":16,"page":4,"type":"multi","stem":"华为 CSE 微服务全生命周期管理提供哪些能力","options":[["A","服务创建---本地工程、云上工程"],["B","CCD---应用开发流水线"],["C","服务运维---微服务治理"],["D","服务监控---仪表盘、对接 APM"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"全生命周期就是从建到看一路覆盖：本地/云上工程创建服务、云上 CI/CD 流水线支撑开发构建、微服务治理承担服务运维、仪表盘并对接 APM 做服务监控，四项都在 CSE 能力内，故选 ABCD。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-17","subject":"hcip_cloud","num":17,"pnum":17,"page":4,"type":"multi","stem":"下述哪些场景下适合使用 Mesher 接入 CSE","options":[["A","将非 java 语言编写的业务代码改造为微服务"],["B","老旧的 java 服务改造微服务"],["C","将非 java SDK 开发的服务与 java SDK 编写的服务对接"],["D","使用了分布式事务"],["E","java 语言编写的微服务，尤其是新的微服务项目"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"Mesher 是无侵入的 sidecar 接入方式，适合非 Java 语言业务、不便改代码的老旧 Java 服务，以及把非 Java SDK 服务与 Java SDK 服务对接，故选 ABC。最易误选的是 E：新建 Java 微服务应直接用 SDK 接入；D 用了分布式事务同样不宜走 Mesher。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-18","subject":"hcip_cloud","num":18,"pnum":18,"page":4,"type":"single","stem":"在华为云应用运维的拓扑图上.不同的颜色代表该实例的健康程度.颜色由 Apdex 值决定。Apdex 值越接近 1 表示应用越健康。若一个应用实例未被其他应用调用。则其颜色为","options":[["A","绿色"],["B","灰色"],["C","黄色"],["D","红色"]],"answer":["B"],"ans_raw":"B","explain":"实例未被其他应用调用时没有调用样本，Apdex 算不出来，拓扑图用灰色表示这种无流量/未接入状态，故选 B。绿、黄、红都对应已有 Apdex 评价的健康度区间，前提是有调用发生。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-19","subject":"hcip_cloud","num":19,"pnum":19,"page":5,"type":"single","stem":"TP99 时延即满足 99%的网络请求所需要的最长耗时。有四次请求耗时分别为","options":[["A","10ms"],["B","500ms"],["C","20ms"],["D","100ms"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）（题干不全）题干「有四次请求耗时分别为」之后缺值，四个耗时数字被当成了选项。TP99 的考法是样本耗时升序排列后取覆盖 99% 请求的最长耗时：若四值为 10/20/100/500ms，TP99 应落在 500ms，与给定 A（10ms）方向相反，请复核原题与答案。","note":"","flag":"stem-truncated","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-20","subject":"hcip_cloud","num":20,"pnum":20,"page":5,"type":"single","stem":"用户部署好应用之后.需要在代码中手动埋点以便 APM 监控应用的性能。","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。APM 靠探针/Java Agent 在应用启动时自动做字节码增强，采集调用链与性能指标，部署完即可观测，不要求为监控去修改业务代码手工埋点（自定义埋点只是可选补充），故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-21","subject":"hcip_cloud","num":21,"pnum":21,"page":5,"type":"single","stem":"单体应用可以使用中间件。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。中间件解决的是缓存、消息、数据库访问这类通用问题，与上层是单体还是微服务无关，单体应用照样可以挂 DCS 做热点缓存、用 DMS 做异步解耦，故选 A（正确）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-22","subject":"hcip_cloud","num":22,"pnum":22,"page":5,"type":"multi","stem":"下面哪些是常用容灾架构模式","options":[["A","备份复原"],["B","异地恢复"],["C","冷待机"],["D","暖待机"],["E","多活模式"]],"answer":["A","C","D","E"],"ans_raw":"ACDE","explain":"常用容灾模式按站点就绪程度递进为备份复原、冷待机、暖待机、多活模式，故选 ACDE。「异地」描述的是容灾站点之间的距离维度而不是架构模式，其效果已被备份复原与待机覆盖，故 B 不选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-23","subject":"hcip_cloud","num":23,"pnum":23,"page":6,"type":"single","stem":"IOT 行业中.设备传输数据量非常小并且通常都是有着固定的时间间隔.这种情况下 CPU 的利用率非常低.为节省成本可采用华为云 PaaS 的哪种解决方案？","options":[["A","Serverless 函数计算平台"],["B","应用微服务化方案"],["C","能力开放 API 网关"],["D","应用 SaaS 化改造方案"]],"answer":["A"],"ans_raw":"A","explain":"定时的小流量让常驻实例大部分时间空转，Serverless 函数按调用次数与执行时长计费、无请求不占算力，正好消掉空转成本，故选 A。微服务化与 SaaS 改造仍需常驻算力，API 网关只解决能力开放与接入。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-24","subject":"hcip_cloud","num":24,"pnum":24,"page":6,"type":"single","stem":"基于应用编排服务（AOS）可以实现应用的自动化运维。","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。AOS 是按编排模板把云资源与应用拓扑声明化拉起来，定位是自动化部署；运行期的监控、告警、日志与故障处理属 AOM 等运维服务，「实现自动化运维」的说法不成立，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-25","subject":"hcip_cloud","num":25,"pnum":25,"page":6,"type":"multi","stem":"华为云分布式缓存 DCS 服务包含以下哪些缓存引擎？","options":[["A","Redis"],["B","Memcached"],["C","IMDG"],["D","MySQL"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"DCS 提供 Redis（键值缓存与丰富数据结构）、Memcached（纯内存键值缓存）两类实例，另有 IMDG 内存数据网格实例，故选 ABC。MySQL 是关系型数据库、由 RDS 提供，不做 DCS 的引擎，D 是易混项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-26","subject":"hcip_cloud","num":26,"pnum":26,"page":6,"type":"single","stem":"当业务不需要缓存的高可用性.并且希里较低成本时.此时应该为应用选择以下哪种类型的华为云分布式缓存 DCS 服务？","options":[["A","单机"],["B","主备"],["C","集群"],["D","以上都不对"]],"answer":["A"],"ans_raw":"A","explain":"单机实例只有一个节点，不带备机同步与故障切换，价格最低，正好匹配不要求高可用又控成本的场景，故选 A。主备为可用性、集群为大容量高吞吐各多付一份成本，故 D「以上都不对」不成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-27","subject":"hcip_cloud","num":27,"pnum":27,"page":7,"type":"single","stem":"华为云分布式数据库中间件 DDM 服务是作为（）前置的分布式数据库访问服务。","options":[["A","DCS"],["B","DMS"],["C","RDS"],["D","Oracle"]],"answer":["C"],"ans_raw":"C","explain":"DDM 位于应用与数据库之间，负责分库分表、读写分离与 SQL 路由，把多个 RDS 实例聚合成一个逻辑库对外，故是 RDS 前置的分布式数据库访问服务，选 C。干扰项 Oracle：DDM 面向 MySQL 生态，不给 Oracle 做前置。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-28","subject":"hcip_cloud","num":28,"pnum":28,"page":7,"type":"multi","stem":"以下哪些是容器引擎？","options":[["A","Docker"],["B","rkt"],["C","Warden"],["D","eclipse"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"Docker、rkt 与 Warden 都属于负责容器创建、运行与管理的容器引擎，故选 ABC。eclipse 是写 Java 用的 IDE/开源开发平台，不承载容器运行时，是本题最容易误选的干扰项；判断时按「是不是跑容器的引擎」这一条排除即可。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-29","subject":"hcip_cloud","num":29,"pnum":29,"page":7,"type":"single","stem":"在 Kubernetes 中一个 Pod 可以包含多个容器。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。Pod 是 Kubernetes 的最小调度单元，同一 Pod 内的多个容器共享网络与存储命名空间、被一同调度到同一节点，主容器加 sidecar 或初始化容器就是典型的多容器形态，故选 A（正确）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-30","subject":"hcip_cloud","num":30,"pnum":30,"page":7,"type":"multi","stem":"华为 CCE 为有状态容器提供的服务的优势是？","options":[["A","数据持久化存储"],["B","多实例数据共享"],["C","支持一种存储格式"],["D","容器实例故障或迁移时.数据不丢失"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"有状态容器要的是存储能力：数据持久化存储、多实例共享同一存储、实例故障或迁移后数据不丢失，故选 ABD。C 与事实相反，CCE 可对接 EVS、SFS、OBS 等多种存储类型而非只支持一种格式。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-31","subject":"hcip_cloud","num":31,"pnum":31,"page":8,"type":"single","stem":"docker 的资源隔离使用的是 Linux 的以下哪种特性？","options":[["A","namespace"],["B","Cgroup"],["C","selinux"],["D","aufs"]],"answer":["A"],"ans_raw":"A","explain":"namespace 让每个容器拥有独立的进程、网络、挂载点等系统视图，实现的是「隔离」，故选 A。Cgroup 管的是资源用量的限制与配额，SELinux 是强制访问控制，aufs 是联合文件系统，都不负责隔离视图。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-32","subject":"hcip_cloud","num":32,"pnum":32,"page":8,"type":"single","stem":"应用向云原生（CloudNative）模式演进.微服务是 Cloud Native 的事实标准。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。云原生以容器为标准交付载体、以 DevOps 与持续交付为实践流程，其中架构形态这一环由微服务承担，业界普遍把微服务当作 Cloud Native 的事实标准，故选 A（正确）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-33","subject":"hcip_cloud","num":33,"pnum":33,"page":8,"type":"multi","stem":"微服务架构能带来哪些好处？","options":[["A","服务模块的边界更清晰：微服务强调模块化结构（REST 接口调用）.这对大型团队非常重要。"],["B","支持独立部署：简单服务更易部署.由于服务是自治的.出现问题之后不会引起系统崩溃。"],["C","运维简单：无状态、自助运维使得系统无需成熟的运维团队（机制）。极大地节约了成本"],["D","允许技术多样性：有了微服务.你可以混合使用多种编程语言、开发框架和数据存储技术。"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"微服务收益体现在模块边界更清晰（以 REST 接口约束）、各服务独立部署且故障不拖垮整体、允许按服务混合选型，故选 ABD。C 恰好说反：服务数量与调用链暴增，运维更复杂，必须有成熟的自动化运维与监控体系。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-34","subject":"hcip_cloud","num":34,"pnum":34,"page":9,"type":"single","stem":"微服务引起提供的一系列能力中。以下哪项是与微服务发现相关的？","options":[["A","注册中心"],["B","配置中心"],["C","治理中心"],["D","服务监控"]],"answer":["A"],"ans_raw":"A","explain":"注册中心保存服务实例的地址与版本，消费方从中查询实例位置完成服务发现，故选 A。配置中心负责动态配置下发，治理中心负责限流熔断等策略，服务监控负责运行指标，都不解决「服务在哪」。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-35","subject":"hcip_cloud","num":35,"pnum":35,"page":9,"type":"single","stem":"在微服务实战指导中。以下示意图中的哪个微服务可以使用灰度发布？","options":[["A","weathermapweb"],["B","fusionweather"],["C","weather"],["D","forecast"]],"answer":["C"],"ans_raw":"C","explain":"（题干不全）题面引用的示意图未随题给出。灰度发布的判据是：该服务已注册到服务中心、同时部署了新旧两个版本的实例，且调用方按版本分流；据此才能选出题给的 weather，而前端入口类应用与图中未做多版本部署的服务不具备该条件。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-36","subject":"hcip_cloud","num":36,"pnum":36,"page":9,"type":"multi","stem":"下面哪些是华为云的立体化运维解决方案的组成部分？","options":[["A","基础设施层运维"],["B","应用层运维"],["C","应用性能分析"],["D","业务分析"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"立体化运维自下而上四层齐全：基础设施层运维（主机与资源）、应用层运维（应用实例与日志）、应用性能分析（调用链与 Apdex）、业务分析（业务指标），四项都属于方案组成，故选 ABCD。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-37","subject":"hcip_cloud","num":37,"pnum":37,"page":9,"type":"single","stem":"使用华为云应用运维服务的日志查询功能分析问题，只能在操作界面上查看应用日志，无法将日志导出到本地查看。","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。日志在界面上做检索查看之外，还支持把查询结果下载导出到本地、并可转储到对象存储做长期归档，「只能在操作界面查看、无法导出到本地」不成立，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-38","subject":"hcip_cloud","num":38,"pnum":38,"page":10,"type":"single","stem":"微服务云应用平台（Service Stage）中的 AOS（应用编排服务）能够一键完成复制的分布式系统的部署。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。AOS 用编排模板把云资源清单与应用拓扑声明化，一次执行即可按依赖顺序拉起整套复杂的分布式系统（题面「复制」应为「复杂」之误），一键部署正是它的定位，故选 A（正确）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-39","subject":"hcip_cloud","num":39,"pnum":39,"page":10,"type":"multi","stem":"软件开发云（DevCloud）中 CICD 流水线可以帮助开发者自动完成以下哪些操作","options":[["A","应用构建"],["B","应用部署"],["C","应用自动化测试"],["D","应用运维和故障恢复"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"CI/CD 流水线覆盖自动构建产出制品、自动化测试验证、部署到目标环境三段，故选 ABC。上线之后的运维与故障恢复属 AOM 等运维域，不在构建部署流水线的职责内，故 D 不选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-40","subject":"hcip_cloud","num":40,"pnum":40,"page":10,"type":"multi","stem":"华为云 PaaS 有哪些针对传统行业 IT 系统上云的解决方案？","options":[["A","应用零修改上云.自动部署和运维"],["B","应用切换云中间件.减少运营和运维的成本"],["C","应用容器化.秒级弹性伸缩、資源利用率更高"],["D","应用微服务化.特性解耦。快速上线"],["E","业务极致创新.基于函数的编程"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"面向传统行业存量 IT 系统上云的是改造代价由低到高的四条路径：应用零修改上云、切换云中间件、应用容器化、应用微服务化，故选 ABCD。E 的基于函数编程面向全新业务的极致创新，不属存量系统上云方案；与问「有哪些 level」的题要区分开。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-41","subject":"hcip_cloud","num":41,"pnum":41,"page":10,"type":"single","stem":"UML 状态图显示一个类的生命周期。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。状态图刻画对象（类的实例）在生命周期内因事件触发而在各状态间迁移，含初始态、终止态与守卫条件，故选 A。注意与顺序图区分：顺序图强调对象之间消息的时间顺序。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-42","subject":"hcip_cloud","num":42,"pnum":42,"page":11,"type":"single","stem":"在 Kubernetes 的 ReplicaSet 中可以设置 pod 的数量.","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）ReplicaSet 的 spec.replicas 就是期望的 Pod 数量，控制器据此把实际副本数调整到该值，所以「可以设置 pod 的数量」是成立的，按 Kubernetes 行为应选「正确」，题给 B 有误。即使原意是副本数应由 Deployment 声明，也不改变该结论，请复核。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-43","subject":"hcip_cloud","num":43,"pnum":43,"page":11,"type":"single","stem":"某房地产商在将线下系统迁移上云时.总结出如下系统改造需求：1）系统和应用平滑改造上云；2）多语言（java、go）混合架构支撑上百种业务；3）天粒度业务快速创新。应对如上需求.哪种华为云 PaaS 解决方案比较合适？","options":[["A","应用 SaaS 化"],["B","应用切换云中间件方案"],["C","应用容器化方案"],["D","应用微服务化方案"]],"answer":["D"],"ans_raw":"D","explain":"上百种业务、多语言混合架构、天粒度快速创新，指向按业务边界拆分、特性解耦后可独立上线的微服务化方案，故选 D。容器化解决的是弹性与资源利用，不解决多语言业务拆分；零修改上云与换中间件更支撑不了快速创新。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-44","subject":"hcip_cloud","num":44,"pnum":44,"page":11,"type":"single","stem":"使用 CSE 微服务框架 SDK 开发的微服务部署到 ServiceStage 如何被其他服务发现调用？","options":[["A","需要开发者自行安装服务中心.提供服务注册和服务发现的服务。"],["B","调用端服务点对点访问被调用端服务。"],["C","直接使用云平台部署的服务中心进行服务的注册和发现。"],["D","利用云平台部署的 Kubernetes DNS 服务进行服务发现。"]],"answer":["C"],"ans_raw":"C","explain":"SDK 内置注册与发现逻辑，应用部署到 ServiceStage 后直接使用云平台已部署的服务中心完成注册和发现，故选 C。A 自建服务中心多余，B 点对点 IP 绕开发现且无法弹性，D 的 Kubernetes DNS 只解析 Service 名，不是 CSE 的服务发现路径。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-45","subject":"hcip_cloud","num":45,"pnum":45,"page":11,"type":"single","stem":"应用在软件开发云（DevCloud）编译构建时使用的 Dockerfile 文件作用是什么？","options":[["A","保存配置参数"],["B","制作应用镜像"],["C","云用户鉴权"],["D","管理项目依赖包"]],"answer":["B"],"ans_raw":"B","explain":"Dockerfile 用 FROM、COPY、RUN 等指令声明基础镜像、要打包的应用文件与启动方式，构建产物就是可交付的应用镜像，故选 B。配置参数靠配置文件/环境变量，鉴权靠 IAM，依赖包靠包管理工具。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-46","subject":"hcip_cloud","num":46,"pnum":46,"page":12,"type":"multi","stem":"以下哪些是华为公有云提供的中间件服务？","options":[["A","DMS：分布式消息服务"],["B","DCS：分布式缓存服务"],["C","DDM：分布式数据库服务"],["D","DRDS：分布式关系型数据库"],["E","CMQ：云消息队列"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"DMS 分布式消息、DCS 分布式缓存、DDM 分布式数据库中间件都是华为公有云的中间件服务，故选 ABC。DRDS 是阿里云的分布式关系型数据库服务，CMQ 是腾讯云的消息队列产品，二者是考厂商产品归属的干扰项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-47","subject":"hcip_cloud","num":47,"pnum":47,"page":12,"type":"multi","stem":"以下哪些属于 CSE 微服务开发框架运行模型中默认提供的处理模块？","options":[["A","服务治理"],["B","负载均衡"],["C","调用链跟踪"],["D","性能统计"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"框架运行模型的处理链默认提供治理（限流、熔断、降级）、负载均衡和调用链跟踪，故选 ABC。性能统计与指标可视化由对接的应用性能管理（APM）承担，不算框架自带的处理模块。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-48","subject":"hcip_cloud","num":48,"pnum":48,"page":12,"type":"multi","stem":"阈值报警通过检测阈值规则中定义的指标设定的上下限.如果达到触发条件。则发送一条警报信息。同时执行自定义的动作。当前华为云上的告警可以通过哪些途径通知运维人员？","options":[["A","邮件"],["B","qq"],["C","短信"],["D","微信"]],"answer":["A","C"],"ans_raw":"AC","explain":"告警经消息通知服务的主题订阅推送，原生支持的通道是邮件和短信，故选 AC。QQ、微信只是聊天工具，未作为华为云告警的通知协议，需要自建转发才能触达。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-49","subject":"hcip_cloud","num":49,"pnum":49,"page":13,"type":"single","stem":"在以下示意图中。有关华为云弹性负载均衡和弹性伸缩服务协调工作的说法正确的是哪项？","options":[["A","弹性伸缩组中的服务配置可以不同"],["B","华为弹性伸缩服务当前页支持容器"],["C","当弹性伸缩服务和负载均衡配合时.伸缩策略就不再起作用了"],["D","此图中的云服务器均向外提供相同的服务"]],"answer":["D"],"ans_raw":"D","explain":"伸缩组按同一模板批量扩出实例并挂到 ELB 后端，组内实例承载相同应用、对外提供相同服务，故选 D。A 与「同模板」矛盾；C 错在伸缩策略照常生效，还能结合负载指标触发；B 的「当前页」文本残缺，也不属该组合要点。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-50","subject":"hcip_cloud","num":50,"pnum":50,"page":13,"type":"single","stem":"下图是 UML 中的哪种图？","options":[["A","类图"],["B","顺序图"],["C","状态图"],["D","用例图"]],"answer":["B"],"ans_raw":"B","explain":"（题干不全）题面所附的图未给出，无法核验。判读方法：顺序图有垂直生命线和按时间自上而下排列的消息箭头；类图是类方框加继承/关联线；状态图是圆角状态框加迁移；用例图是小人加椭圆。图缺失时按给定 B 复习顺序图特征即可。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-51","subject":"hcip_cloud","num":51,"pnum":51,"page":13,"type":"single","stem":"以下哪项是华为云分布式消息 DMS 服务的功能？","options":[["A","Key-Value 数据缓存"],["B","数据库水平扩展"],["C","海量事务交易"],["D","模块异步解耦"]],"answer":["D"],"ans_raw":"D","explain":"DMS 用队列/主题让生产方与消费方不直接依赖、以异步方式传递消息，核心功能是模块异步解耦，故选 D。Key-Value 数据缓存属 DCS，数据库水平扩展属 DDM，海量事务交易属关系型数据库。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-52","subject":"hcip_cloud","num":52,"pnum":53,"page":14,"type":"single","stem":"IOT 行业中设备传输数据量非常小并且通常都是有着固定的时间间隔.这种情况下 CPU 的利用率非常低。为节省资本可采用华为云 PaaS 的哪种解决方案？","options":[["A","Serverless 函数计算平台"],["B","应用微服务化方案"],["C","能力开放 API 网关"],["D","应用 SaaS 化改造方案"]],"answer":["A"],"ans_raw":"A","explain":"数据量小、固定周期、CPU 长期空转的负载最适合 Serverless 函数计算：按调用次数与运行时长计费、无请求时不预留算力，故选 A。微服务化、SaaS 改造仍需常驻实例承担闲置成本，API 网关本身不执行业务逻辑。","note":"第 14 页仅印到选项 A，B/C/D 取自同题第 55 页副本（两处答案一致）","flag":"rechecked","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-53","subject":"hcip_cloud","num":53,"pnum":54,"page":14,"type":"single","stem":"华为云应用性能管理服务的拓扑图中每个箭头连线代表一个调用关系不同颜色代表调用关系的 Apdex 健康程度如下图所示的红色虚线箭头连线表示该调用情况为","options":[["A","请求状态满意"],["B","请求状态一般由于时延导致"],["C","请求状态很差由于时延导致"],["D","请求状态很差.由于错误导致"]],"answer":["C"],"ans_raw":"C","explain":"（题干不全）题面引用的图例未随题给出。可确定的是连线颜色由 Apdex 决定，绿色满意、黄色一般、红色很差，红色只说明该调用状态很差；至于「时延导致」还是「错误导致」取决于图中虚线与实线的图例约定，需按官方拓扑图例复核本题给定的 C。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-54","subject":"hcip_cloud","num":54,"pnum":55,"page":14,"type":"single","stem":"下列哪项不是华为云 CCE 管理的套器的优势？","options":[["A","通过共享 kernel.细粒度资源隔离"],["B","定义了环境无关的标准的交付、部署规范"],["C","利用 Hypervisor 实现对硬件资源更有效的利用"],["D","秒级快速启动和停止"]],"answer":["C"],"ans_raw":"C","explain":"容器不经 Hypervisor，而是共享宿主机内核、靠 namespace 与 Cgroup 做隔离和限额，「利用 Hypervisor 更有效利用硬件资源」是虚拟机/云主机的能力，故选 C。A、B、D 分别对应细粒度隔离降本、环境无关的标准交付规范、秒级启停。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-55","subject":"hcip_cloud","num":55,"pnum":56,"page":15,"type":"single","stem":"微服务的流程与工具、自组织团队、技术实践三者相辅相成.下述哪项不属于流程与工具的范畴？","options":[["A","积极引入外部工具同时不断优化内部工具"],["B","保障持续集成、持续部署流水线的稳定目高效"],["C","通过高度成熟的自动化体系建立可靠且可重复的交付过程"],["D","加强基础设施的构建与管理。加快监控、告警、日志聚合等反馈效率"]],"answer":["C"],"ans_raw":"C","explain":"流程与工具讲的是用什么工具链把流程跑顺：引入并持续优化内外部工具、保障 CI/CD 流水线稳定高效、建设监控告警与日志聚合的快速反馈，A、B、D 属此范畴。C 以高度成熟的自动化体系保证交付过程可靠可重复，是三要素中的技术实践层，故选 C。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-56","subject":"hcip_cloud","num":56,"pnum":57,"page":15,"type":"single","stem":"微服务架构模式下.开发者无法自由选择开发技术来提供 API 服务。","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。微服务各自独立成服务、只通过接口对外交互，每个服务都能按团队需要选用不同语言、框架与存储，技术栈选型自由正是它相对单体的优势，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-57","subject":"hcip_cloud","num":57,"pnum":58,"page":15,"type":"single","stem":"以下哪种华为云中间件服务可解决业务应用的异步消息解耦问题？","options":[["A","DCS：分布式缓存服务"],["B","DMS：分布式消息服务"],["C","DDM：分布式数据库服务"],["D","RDS：关系型数据库服务"]],"answer":["B"],"ans_raw":"B","explain":"异步消息解耦靠消息中间件完成：生产者把请求投给 DMS 的 Topic/Queue 即返回，消费者按自身节奏拉取，两侧无需互相感知，故选 B。DCS 只做 Key-Value 缓存加速，不承载消息流转；DDM 是 RDS 之上的分库分表访问层；RDS 提供持久化关系存储，三者都不能把同步调用拆成异步。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-58","subject":"hcip_cloud","num":58,"pnum":59,"page":15,"type":"single","stem":"应用运维的仪表盘支持展示指标数据和状态数据.对于不同的指标数据根据需要添加不同的图标。如果需要监控变化趋势或多个指标对比可以创建；如果需要了解最新数值可以创建（）。","options":[["A","曲线图；数字图"],["B","数字图；曲线图"],["C","柱状图；饼状图"],["D","柱状图；数字图"]],"answer":["A"],"ans_raw":"A","explain":"要看随时间起伏的变化趋势、或把多个指标叠在同一坐标里比较，只能选横轴为时间的曲线图；只关心当前最新数值时用数字图，它把聚合值放大显示、不保留历史形状，故选 A。柱状图偏分类比较、饼图偏占比构成，都不适合连续趋势与实时读数，别把两类图的用途对调。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-59","subject":"hcip_cloud","num":59,"pnum":60,"page":16,"type":"multi","stem":"在一个 kubernetes 集群中。以下哪些是可以从外部访问的 service 类型？","options":[["A","deport NodePort"],["B","load Balancer"],["C","clouserIP"],["D","namespace"]],"answer":["A","B"],"ans_raw":"AB","explain":"NodePort 在每个节点上开放端口，外部可用节点 IP:端口访问；LoadBalancer 借助 ELB 分配外部 IP 对外暴露，两者均可从集群外进入，故选 AB。ClusterIP 只分配集群内部虚拟 IP，仅能被集群内 Pod 访问；Namespace 是对象的逻辑隔离分组，压根不是 Service 类型。（选项存在录入误写：deport 应为 NodePort、clouserIP 应为 ClusterIP）","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-60","subject":"hcip_cloud","num":60,"pnum":61,"page":16,"type":"single","stem":"在微服务实战指导中。以下示意图中的哪个微服务通过 mesher 接入到系统中？","options":[["A","weathermapweb"],["B","fusionweather"],["C","weather"],["D","forecast"]],"answer":["A"],"ans_raw":"A","explain":"（题干不全）原题依赖未给出的微服务实战架构图，无法据图判定。按原理：Mesher 以 Sidecar 方式为无法植入 SDK 的语言（如 Node.js 前端）代理注册发现与治理流量，实战指导中 weathermapweb 正是前端、只能走 Mesher；weather、forecast、fusionweather 为 Java 微服务，直接用 ServiceComb Java Chassis SDK 接入。据此可推得题库答案 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-61","subject":"hcip_cloud","num":61,"pnum":62,"page":16,"type":"single","stem":"以下哪项不是使用云中间件服务的好处？","options":[["A","开箱即用"],["B","可靠安全"],["C","自动升级和补丁"],["D","使用中间件服务后.企业需要投入大量人力维护中间件软件"]],"answer":["D"],"ans_raw":"D","explain":"云中间件是托管服务：控制台开通即用、SLA 与数据可靠性由平台兜底、版本与补丁由云侧滚动升级、按容量计费无需自建集群，A、B、C 均为其优势。D 说的恰是自建中间件的痛点，使用托管服务后企业不必投入人力维护软件本体，只关注业务侧配置，故选 D。","note":"跨页题：选项 D 位于第 17 页页首并带（答案）标记","flag":"rechecked","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-62","subject":"hcip_cloud","num":62,"pnum":63,"page":17,"type":"single","stem":"应用性能管理（APM）支持非侵入式性能数据采集无需修改业务代码即可轻松接入。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在采集机制：探针基于 JVM 字节码增强，在类加载期把埋点织入方法出入口，不依赖业务代码主动打点，因此无需改一行业务代码、重新打包即可接入。若必须手写埋点，就谈不上非侵入，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-63","subject":"hcip_cloud","num":63,"pnum":64,"page":17,"type":"single","stem":"如图所示华为云 APM 的拓扑图是对应用间调用关系和依赖关系的可视化展示。使用拓扑图能够直观的查看应用的运行状态。下列哪项说法是错误的？（）","options":[["A","拓扑图上每个圆圈代表一个应用。圆圈中的数字“1/1”表示该应用有两个实例、一个正常、一个异常。"],["B","拓扑图上圆圈 Vmall-apigw-service 到圆圈 Vmall-user-service 之间的红线虚线箭头线表示应用 Vmall-apigw-service 调用应用 Vmall-user-service.请求状态很差.由于时延导致"],["C","圆圈的颜色为绿色.表示该应用的状态为健康。"],["D","通过拓扑图可以清晰的查看应用之间的依赖关系。"]],"answer":["A"],"ans_raw":"A","explain":"拓扑图圆圈内的分数，分母是应用实例总数、分子按异常实例数口径统计，1/1 即总共只有 1 个实例且该实例异常；“两个实例、一正常一异常”应显示为 1/2，故 A 说法错误、入选。B 的连线颜色表调用质量（红为差，多由时延或错误率劣化触发）、C 绿为健康、D 拓扑即调用依赖关系可视化，均与官方定义一致。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-64","subject":"hcip_cloud","num":64,"pnum":65,"page":17,"type":"single","stem":"PaaS 分为Apaas（Application PaaS 应用 PaaS）和Gpaas（General PaaS。通用 paas）。Gpaas 的能力范围覆盖：编排部署、监控运维、容器引擎、微服务引擎、软件仓库、中间件、函数服务等。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据看服务对象：gpaaS 面向开发者提供构建与运行应用所需的通用平台能力，容器引擎、微服务引擎、软件仓库、中间件、函数编排与监控运维都落在这一层；aPaaS 面向业务场景做应用组装与低代码搭建。题干列举的七项能力全属 gpaaS 范畴，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-65","subject":"hcip_cloud","num":65,"pnum":66,"page":17,"type":"single","stem":"以下关于 UML 状态图的说法哪项是正确的？（）","options":[["A","状态图显示不同类的迁移关系"],["B","状态图中的状态可按时间先后顺序排列"],["C","状态的改变。由内外部事件触发"],["D","我们常说的流程图就是状态图"]],"answer":["C"],"ans_raw":"C","explain":"状态图刻画一个对象（或构件）在其生命周期内的状态与迁移，触发迁移的正是事件——既有外部消息、定时器信号，也有内部条件满足，故 C 正确。A 混淆了类图，类间关系不由状态图表达；B 把状态当成线性时间轴，忽略状态图可循环、可分支、可有并发子区域；D 与流程图混淆，流程图表达算法步骤而非对象状态机。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-66","subject":"hcip_cloud","num":66,"pnum":67,"page":18,"type":"single","stem":"如下哪个说法不是主流公有云的特性？（）","options":[["A","夏盖 IaaS,Paas、SaaS00%"],["B","支持按需付费 00%"],["C","只能通过管理控制台页面申请资源"],["D","主流公有云还提供大量的云解决方案"]],"answer":["C"],"ans_raw":"C","explain":"主流公有云都提供 OpenAPI、SDK、CLI，并支持 Terraform、CloudFormation 类 IaC 与自动化编排批量开通，控制台只是其中一种入口。C 把入口说成唯一途径，用了“只能”这一绝对限定，因此不是公有云特性、故选 C。A 覆盖 IaaS/PaaS/SaaS 全栈、B 按需付费、D 提供云解决方案，都是公认特征。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-67","subject":"hcip_cloud","num":67,"pnum":68,"page":18,"type":"multi","stem":"Kubernetes 主要包括以下哪些功能？（）","options":[["A","使用 Docker 对应用程南打包、实例化、运行"],["B","以集群的方式运行、管理跨节点的奢器"],["C","解决 Docker 跨节点奢器之间的通讯问题"],["D","实现对虚拟机的有效管理"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"K8s 以容器为最小调度单元：镜像由 Docker 等运行时打包，K8s 负责把容器实例化到合适节点并运行；它跨节点统一管理集群内容器；通过 CNI 插件与 Service 解决跨节点容器互通，故选 ABC。D 错在对象错位，K8s 编排的是容器不是虚拟机，生命周期与节点资源交付不归它管。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-68","subject":"hcip_cloud","num":68,"pnum":69,"page":18,"type":"multi","stem":"华为云分布式消息 DMS 服务可提供哪些数据访问接口？（）","options":[["A","HTTP Restful Apl"],["B","TCP SDK"],["C","Kafka SDK"],["D","sql 接口"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"DMS 侧业务程序按各引擎原生协议接入：Kafka 实例用 Kafka SDK，RabbitMQ、RocketMQ 实例用对应协议 SDK，同时提供 REST 风格的接口与控制台 API 做实例、Topic 管理与部分消息操作，故选 ABC。消息不是二维表，没有 SQL 查询语义，SQL 接口属 RDS、DDS、DWS 等数据库，排除 D。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-69","subject":"hcip_cloud","num":69,"pnum":70,"page":18,"type":"single","stem":"以下哪项不是华为云分布式消息 DMS 服务的关键特性？（）","options":[["A","灵活队列类型：提供普通队列、FIFO 队列、Kafka 队列"],["B","支持消息过滤、消息回溯、消息重投、广播消息等丰富的消息能力"],["C","百亿级消息堆积"],["D","提供热点数据缓存"]],"answer":["D"],"ans_raw":"D","explain":"DMS 的关键特性集中在队列形态（普通、FIFO 等）、消息语义（过滤、回溯、重投、广播）与海量堆积能力，A、B、C 均成立。D 热点数据缓存是 DCS 的定位——靠内存读写加速热数据，消息队列不充当缓存层，故选 D。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-70","subject":"hcip_cloud","num":70,"pnum":71,"page":19,"type":"single","stem":"在华为云应用运维的拓扑图上.不同的颜色代表该实例的健康程度。颜色由 Apdex 值决定。Apdex 值越接近 1 表示应用越健康。若一个应用实例未被其他应用调用.则其颜色为（）","options":[["A","绿色"],["B","灰色"],["C","红色"],["D","黄色"]],"answer":["B"],"ans_raw":"B","explain":"拓扑图取色自 Apdex（满意样本占比加可容忍样本的一半，越接近 1 越健康），绿、黄、红分别对应健康、亚健康、异常；没有跨应用调用就没有事务样本，Apdex 无法计算，此时探针把实例画成灰色以区别于健康度判定，故选 B。灰色不代表故障，别误读成红色。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-71","subject":"hcip_cloud","num":71,"pnum":72,"page":19,"type":"single","stem":"华为容器云不支持有状态应用。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。K8s 提供 StatefulSet 处理稳定网络标识与有序部署，配合 PVC 动态挂载 EVS 云硬盘、Headless Service 稳定域名，CCE 支持有状态工作负载；CCI 与调度侧也能匹配持久化存储。题面把容器云等同无状态，故选 B 即判定该说法错误。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-72","subject":"hcip_cloud","num":72,"pnum":73,"page":19,"type":"multi","stem":"云原生应用的关键点有哪些（）","options":[["A","DevOps"],["B","持续交付"],["C","自动运维"],["D","微服务"],["E","虚拟机"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"云原生应用的关键点是微服务（架构形态）、DevOps（研发协作流程）、持续交付（自动发布实践），再叠加容器化载体，故选 ABD。C 自动运维是平台运维侧目标、不是构建云原生应用的关键要素；E 虚拟机属 IaaS 资源形态，与以容器为运行单元的容器原生理念相悖。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-73","subject":"hcip_cloud","num":73,"pnum":74,"page":20,"type":"single","stem":"某企业自身服务能力已发展成熟.为进一步提升企业在业内影响力。吸引新兴合作伙伴。增强企业竞争力。打算以标准 API 的形式将企业内部服务能力开放给第三方开发情况下可以采用华为云 PaaS 的哪种解决方案？（）","options":[["A","应用器化方案"],["B","应用微服务化方案"],["C","能力开放 API 网关"],["D","应用 SaaS 化改造方案"]],"answer":["C"],"ans_raw":"C","explain":"关键词是“以标准 API 形式把内部能力开放给第三方开发者”，正是 APIG 的用途：把服务封装成 API 发布到门户，集中做认证鉴权、限流、计量计费与版本管理，故选 C。容器化解决运行环境，微服务化解决内部拆分，SaaS 化改造面向产品形态，三者都不承担对外能力开放的职责。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-74","subject":"hcip_cloud","num":74,"pnum":75,"page":20,"type":"multi","stem":"微服务架构是一种架构模式下列哪些是它所提倡的？（）","options":[["A","小且专注于做一件事"],["B","独立的进程也即进程隔离"],["C","轻量级的通信机制"],["D","松耦合、独立部署"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"（存疑）按 Fowler 对微服务的定义，四项皆为其主张：单一职责的小型服务、独立进程隔离、HTTP/REST 或消息等轻量通信、服务间松耦合并可独立部署，D 恰是微服务区别于单体的核心卖点，被写成“不提倡”并不成立，故本题应为 ABCD。题库给出的 ABC 漏选 D。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-75","subject":"hcip_cloud","num":75,"pnum":76,"page":20,"type":"multi","stem":"华为云 CCE 云容器引擎能够给使用 CCE 的游戏厂商带来哪些价值？","options":[["A","一站式部署和运维"],["B","高可用业务不中断"],["C","灵活的弹性伸缩策略"],["D","可定制化的 DevOps 能力"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"游戏业务峰值波动大、版本更新频繁、对停服敏感：CCE 提供编排模板与控制台实现一站式部署运维，多副本加 ELB 摘除故障实例保障高可用，HPA/CronHPA 应对开服与活动洪峰，并可对接 SWR、流水线与 AOM 构建定制化 DevOps，四项皆为其价值，故选 ABCD。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-76","subject":"hcip_cloud","num":76,"pnum":77,"page":20,"type":"single","stem":"华为 CCE 页面创建应用时可以选择创建多个实例。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在工作负载定义本身：Deployment、StatefulSet 等对象的 spec.replicas 就是副本数，CCE 创建向导里有“实例总数”输入框，一次即可拉起多个 Pod 并由 Service 负载均衡；有状态负载同样能多副本。因此可选多实例，选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-77","subject":"hcip_cloud","num":77,"pnum":78,"page":21,"type":"single","stem":"华为云容器引擎 CCE 服务中用户不能对老版本的集群进行升级。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。CCE 提供集群升级：在集群信息页发起，按版本路径逐级升级控制面与节点池，升级前预检查、可分批滚动以保留业务连续性，老版本集群并非只能重建。故该说法不成立，选 B 即判定为错误。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-78","subject":"hcip_cloud","num":78,"pnum":79,"page":21,"type":"single","stem":"华为云应用性能管理服务通过在应用所在节点上安装采集代理来完成应用性能数据采集的。采集代理是基于业界 Pinpoint 开源项目通过 JVM 字节码增强技术实现非侵入式方式采集应用指标的.APM 不支持下列哪种技术栈开发的应用？（）","options":[["A","JAVA"],["B","C++"],["C","Spring"],["D","Tomcat"]],"answer":["B"],"ans_raw":"B","explain":"APM 探针靠 JVM 字节码增强在类加载时织入埋点，只有运行在 JVM 上的技术栈才具备这一条件：Java 本体、Spring/Spring Boot 应用、Tomcat 等容器都在支持范围。C++ 编译为本机代码、无字节码层可增强，需要 APM 当前不提供的 native 探针，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-79","subject":"hcip_cloud","num":79,"pnum":80,"page":21,"type":"single","stem":"微服务引擎提供的一系列能力中。以下哪项是与微服务发现相关的？（）","options":[["A","注册中心"],["B","配置中心"],["C","治理中心"],["D","服务监控"]],"answer":["A"],"ans_raw":"A","explain":"微服务发现＝实例地址的动态登记与查询：服务启动向注册中心上报实例，消费方按服务名拉取地址列表并做客户端负载均衡，注册中心还承担健康剔除，故选 A。配置中心只管外部化配置下发，治理中心做限流熔断路由等策略，服务监控只观测调用链与指标，均不负责服务发现。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-80","subject":"hcip_cloud","num":80,"pnum":81,"page":22,"type":"single","stem":"华为云分布式缓存 DCS 服务是为应用系统提供 Key-Value 缓存服务的数据库服务。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在数据模型与协议：DCS 兼容 Redis 与 Memcached，提供 GET/SET、Hash、ZSet 等以键取值的操作，用途是给应用做热点数据缓存加速，符合 Key-Value 缓存服务描述，故选 A。须留意 DCS 不处理关系查询与事务 SQL，不要把它与 RDS、DDM 归到一类。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-81","subject":"hcip_cloud","num":81,"pnum":82,"page":22,"type":"multi","stem":"下列哪些服务属于微服务云应用平台（Service Stage）的子服务？（）","options":[["A","AOS（应用编排）"],["B","CSE（微服务引擎）"],["C","APM（应用性能管理）"],["D","ECS（弹性云服务器）"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"ServiceStage 是应用全生命周期平台，把 AOS 模板编排、CSE 微服务治理、APM 性能分析等 PaaS 子服务整合到统一入口，故选 ABC。ECS 是 IaaS 层的计算资源，只作为 ServiceStage 部署所依赖的底层资源，并不属于该平台自身提供的子服务，别按“跑在 ECS 上”就误选 D。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-82","subject":"hcip_cloud","num":82,"pnum":83,"page":22,"type":"multi","stem":"Gartner 认为微服务在未来将成为主流请问哪几项是微服务架构的核心目标？（）","options":[["A","敏捷开发（development agility）"],["B","灵活部署（deployment flexibility）"],["C","精准弹性（precise scalability）"],["D","在线追踪（Online Request Tracing）"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"（存疑）Gartner 归纳的微服务三大核心目标是敏捷开发、灵活部署、精准弹性，即让开发独立、发布按服务粒度、扩容只针对瓶颈服务，ABC 成立。但在线追踪是微服务为支撑可运维性引入的关键技术能力，华为官方培训教材中把它与前三项同列为核心目标，按现行教材口径应为 ABCD，题库漏选 D。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-83","subject":"hcip_cloud","num":83,"pnum":84,"page":22,"type":"multi","stem":"华为云生态包括以下哪些内容？（）","options":[["A","合作伙伴"],["B","云社区"],["C","云市场"],["D","培训与认证"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"华为云生态由对内协同与对外赋能两条线组成：合作伙伴体系（Huawei Cloud Partner Network）负责联营与方案共建，云社区承载技术分享与开发者互动，云市场让第三方 SaaS 与镜像直接售卖分发，培训与认证（HCIA/HCIP/HCIE）输出人才，四项皆属生态内容，故选 ABCD。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-84","subject":"hcip_cloud","num":84,"pnum":85,"page":23,"type":"multi","stem":"以下哪些是使用云中间件构建分布式云化应用后可实现的功能？（）","options":[["A","动静分离：动态页面的流量和静态页面的流量进行分离"],["B","可准确预估系统性能和奢重"],["C","系统解耦"],["D","数据库分库分表"],["E","开放兼容、可扩展性强"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"这套中间件组合各自兑现一项能力：ELB/OBS/CDN 承载静态资源实现动静分离；DMS 消息把同步调用改异步完成系统解耦；DDM 分库分表支撑海量交易并让容量、性能随节点数线性预估；接入层与引擎兼容开源协议保证开放可扩展，五项全选，故选 ABCDE。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-85","subject":"hcip_cloud","num":85,"pnum":86,"page":23,"type":"multi","stem":"华为云包括以下哪些种类的服务？（）","options":[["A","IaaS"],["B","PaaS"],["C","SaaS"],["D","解决方案服务"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"华为云把服务按责任边界划成三层：IaaS 供计算存储网络，PaaS 供数据库、中间件、容器等平台能力，SaaS 供开箱即用的软件（企业邮箱、WeLink 等），故选 ABC。D 解决方案服务是跨多种云服务的场景化组合交付形态，属售卖与方案维度，不在这三层分类之内，属最易误选的一项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-86","subject":"hcip_cloud","num":86,"pnum":87,"page":23,"type":"single","stem":"裸金属器直接运行于华为高性能物理服务器上。无任何虚拟化性能损失.可获得和物理机同等的性能。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在是否分层：BMS 把整台物理服务器直接交付租户，没有 Hypervisor 与客户机抢占 CPU、没有虚拟化网络与存储开销，性能与自建物理机等价，因此该说法成立、选 A。若机型上运行 KVM 或 Xen 才存在虚拟化损耗，ECS 就属此类。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-87","subject":"hcip_cloud","num":87,"pnum":88,"page":23,"type":"multi","stem":"下面关于微服务云应用平台（Servicestage）的特性描述.哪些是正确的？（）","options":[["A","资源准备快。异构资源混合编排.自助申请。实施发放"],["B","特性开发快。多语言微服务框架兼容主流开源社区"],["C","应用上线快。图形化编排一键式部署"],["D","故障定位快。非侵入式采集端到端健康状态监控"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"ServiceStage 对外表述即“四快”：AOS 模板把异构资源混合编排、自助申请快速发放；CSE 兼容 ServiceComb、Spring Cloud 等主流框架加速特性开发；图形化拖拽编排配合一键部署加速上线；APM 经探针做端到端调用链与健康监控加速故障定位，四项描述与官方一致，故选 ABCD。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-88","subject":"hcip_cloud","num":88,"pnum":89,"page":24,"type":"single","stem":"在微服务实战指导中以下示意图中的哪个微服务可以使用灰度发布？（C）","options":[["A","weathermapweb"],["B","fusionweather"],["C","weather"],["D","forecast"]],"answer":["C"],"ans_raw":"C","explain":"（题干不全）原题依赖未给出的微服务实战架构图，无法据图作答。按原理：灰度发布要求服务在注册中心按版本或 tag 上报实例，治理中心依据 Header 等请求特征路由到新实例，实战指导中为 weather 准备了 v1、v2 两个版本实例，前端经 Mesher 接入，因此题库给 C。需强调四个微服务只要具备版本化注册信息，技术上都可灰度。","note":"","flag":"labeled-填空题","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-89","subject":"hcip_cloud","num":89,"pnum":91,"page":24,"type":"multi","stem":"云原生应用相对传统应用的优势有哪些？（）","options":[["A","高性能"],["B","DevOps 快速迭代"],["C","容量的弹性伸缩"],["D","服务秒级恢复"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"云原生相对传统应用的三项优势：DevOps 打通开发与发布实现快速迭代，HPA/CronHPA 让副本随负载自动增减，单实例故障由探针与控制器秒级重建并摘除流量，故选 BCD。A 高性能不成立——容器多一层内核隔离与虚拟网络，微服务把本地调用换成跨进程网络调用，单机性能通常不及精调的单体；云原生赢在弹性与迭代速度，而非绝对吞吐。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-90","subject":"hcip_cloud","num":90,"pnum":92,"page":25,"type":"multi","stem":"微服务架构将面临多维度的挑战. 下面哪些属于微服务架构需要面对的挑战？（）","options":[["A","故障概率增加、监控跟踪困难.调用频率高、调用链长.跨虚拟机、VLAN 通信不可控因素增加。"],["B","便于实现自动化测试.测试用例清晰、外部依赖清晰.易于打桩（API 预定义）。"],["C","数据不再集中管理.分散到各个微服务.常规事务管理无法跨域服务边界。"],["D","可以根据服务需要自由选择组件.不必担心依赖冲突.微服务自己管理自己的数据。"]],"answer":["A","C"],"ans_raw":"AC","explain":"A、C 描述的是难题：调用链跨节点、跨子网拉长，故障概率上升、监控与全链路跟踪变难；数据随服务分散到各自库，常规事务管理器无法跨越服务边界，一致性要靠 Saga、TCC 等补偿方案，故选 AC。B“便于自动化测试、依赖清晰易打桩”与 D“自由选型、不必担心依赖冲突”都是收益而非挑战，且 D 本身站不住——多服务依赖同版本库时冲突依旧存在。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-91","subject":"hcip_cloud","num":91,"pnum":93,"page":25,"type":"multi","stem":"微服务架构将面临哪些挑战？（）","options":[["A","分布式系统.复杂性高"],["B","分区数据库架构.数据一致性难以保证"],["C","功能涉及多个模块.不便于测试"],["D","交付周期不可避免的延长"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"微服务把单体拆成跨进程的分布式系统，网络分区、部分失败与数据一致性成为难题；存储按服务边界分区，跨服务查询与事务难以强一致；一个功能贯穿多个服务，构造与联调复杂度上升，故选 ABC。D 说法相反，微服务的目的正是以小粒度独立发布缩短交付周期，不是延长。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-92","subject":"hcip_cloud","num":92,"pnum":95,"page":26,"type":"multi","stem":"以下哪项是华为云分布式数据库 DDM 服务的功能？（）","options":[["A","数据库分布式扩展"],["B","热点数据缓存"],["C","海量数据迁移"],["D","海量数据交易"]],"answer":["A","D"],"ans_raw":"AD","explain":"DDM 取掉 RDS 单机容量与并发瓶颈：对业务暴露标准 MySQL 协议端点，把库表水平拆分到多个 RDS 实例，并用数据节点组管住分片拓扑，故选 AD 即分布式扩展与承载海量数据交易。B 热点缓存属 DCS 内存能力，C 海量数据迁移由 DRS、UGS 等工具完成，DDM 只做分库分表路由，不搬数据。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-93","subject":"hcip_cloud","num":93,"pnum":96,"page":26,"type":"single","stem":"ICAgent 是 APM 的采集代理.运行在应用所在的弹性云服务器上.用于实时采集拓扑和调用链等监控数据。下面哪些说法是不正确的？（）","options":[["A","通过 JVM 字节码技术实现非侵入式数据采集.用户无需修改业务代码"],["B","通过 ServiceStage 上线的应用可以自动完成采集探针的部署"],["C","支持对 C 语言开发的应用的数据采集"],["D","每个采集探针的资源开销极小.不会对业务造成影响"]],"answer":["C"],"ans_raw":"C","explain":"ICAgent 是 ECS 上的统一探针进程，Java 进程由字节码增强完成无侵入采集，经 ServiceStage 上线的应用可自动注入探针，且刻意控制 CPU 与内存开销，A、B、D 正确。探针依赖 JVM 类加载机制，对 C 这类编译为本机代码的程序无从增强，C 说法不成立，按题干“选不正确项”故选 C。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-94","subject":"hcip_cloud","num":94,"pnum":97,"page":26,"type":"single","stem":"下面哪项是 Kubernetes 中用于持久化存储的组件？（）","options":[["A","api-server"],["B","etcd"],["C","kubelet"],["D","event-controller"]],"answer":["B"],"ans_raw":"B","explain":"集群状态的落地持久化由 etcd 完成，它是分布式的 Key-Value 存储，保存全部对象的期望与实况，各组件只经 API Server 读写它、本身不落盘，故选 B。API Server 只做认证校验与 REST 转发、kubelet 管本机容器生命周期、事件控制器只处理 Event 对象，三者都不做持久化。（严格说业务 Pod 的持久卷 PV 属另一话题，本题问集群自身状态存储）","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-95","subject":"hcip_cloud","num":95,"pnum":98,"page":26,"type":"single","stem":"在 kubernetes 集群中 service 的内部访问是通过什么实现的？（）","options":[["A","nodePort"],["B","loadBalancer"],["C","clusterIP"],["D","namespace"]],"answer":["C"],"ans_raw":"C","explain":"ClusterIP 从 Service 网段分配一个虚拟 IP，由 kube-proxy 在节点上写 iptables/IPVS 规则，把它负载到后端 Pod，只在集群内部可达，故选 C。NodePort 与 LoadBalancer 都是对集群外暴露的手段，各自内部仍依赖 ClusterIP；Namespace 只用于资源分组与隔离，不承载流量。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-96","subject":"hcip_cloud","num":96,"pnum":99,"page":27,"type":"single","stem":"用户必须在业务代码中手动埋点.才能让华为云应用运维服务来采集用户应用的各项性能信息。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。判据在采集位置：Java 应用由探针在类加载时做字节码增强，埋点由探针自动生成，业务代码一行不改；非 Java 应用也能通过 Mesher Sidecar 或 OpenTelemetry 标准上报接入。只有需要自定义业务事务时才主动调 API 补充埋点，“必须手动埋点”不成立，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-97","subject":"hcip_cloud","num":97,"pnum":100,"page":27,"type":"multi","stem":"微服务云应用平台(serviceStage)的应用运维能够提供下面哪些运维能力？（）","options":[["A","调用链分析"],["B","节点资源监控"],["C","告警"],["D","日志分析"],["E","弹性伸缩"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"运维能力看它管什么：APM 提供调用链分析，AOM/CCE 提供实例与节点资源监控，告警规则触发 SMN 通知，LTS 负责日志采集与检索，故选 ABCD。弹性伸缩属于应用部署与伸缩配置环节，是“部署/容量管理”动作而非运维观测手段，且伸缩策略本身在 AS 侧定义，故不选 E。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-98","subject":"hcip_cloud","num":98,"pnum":101,"page":27,"type":"single","stem":"使用 CES 微服务框架 SDK 开发微服务时，必须要自己引入外部 web 服务器托管服务运行。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。CES 微服务框架 SDK 内置 REST 容器（如 Jetty/Undertow）与契约优先的代码生成，服务定义后由框架自己起监听端口并注册到服务中心，不必再外置 Tomcat 之类 Web 服务器。这题与“传统 WAR 必须部署进 Tomcat”的习惯相反，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-99","subject":"hcip_cloud","num":99,"pnum":102,"page":27,"type":"single","stem":"在 ServiceStage 应用运维界面创建一个弹性伸缩组，下面哪项不是应用实例的弹性伸缩策略？（）","options":[["A","告警触发"],["B","定时触发"],["C","周期触发"],["D","手动触发"]],"answer":["D"],"ans_raw":"D","explain":"伸缩组的触发条件三类：告警触发按 CPU、内存等指标阈值扩缩，定时触发在指定时刻执行一次，周期触发按每天或每周重复的时间窗执行，故选 D 即“手动触发”并不存在。真要临时改容量，直接调整实例数即可，不属策略；别把“手动调整”误解成策略里的第四种触发方式。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-100","subject":"hcip_cloud","num":100,"pnum":103,"page":27,"type":"multi","stem":"以下哪些是华为云 APM 的应用场景？（）","options":[["A","使用模板一键式将应用部署到云上"],["B","透过 apdex 数值来剖析事务状态"],["C","通过拓扑图来掌握应用健康状况"],["D","通过调用链来追踪问题根因"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"APM 是观测类产品，能力落在三处：Apdex 量化事务健康度便于剖析，拓扑图呈现应用间调用与依赖以便看整体健康，调用链还原单次请求在各服务的耗时并定根因，故选 BCD。A 按模板一键部署属 AOS、CCE 或 FunctionGraph 的能力，与性能管理无关，最易因同处 ServiceStage 门户而误选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-101","subject":"hcip_cloud","num":101,"pnum":104,"page":28,"type":"single","stem":"华为云应用性能管理服务使用字节码增强技术实现非入侵式采集用户应用的性能指标数据，用户在华为云上部署了一个 C 语言开发的应用，也可以用华为云 APM 服务来分析其性能管理服务来分析其性能问题。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。判据在“字节码”这一前提：字节码增强只能作用在运行于 JVM 的程序上，C 语言编译为机器码、不存在字节码可供织入，APM 不提供 native 探针，故 C 应用无法用该方式分析，题干推论不成立、选 B。可对比 Go、Python 应用，它们须经 Mesher Sidecar 或 OpenTelemetry 上报才纳入分析。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-102","subject":"hcip_cloud","num":102,"pnum":105,"page":28,"type":"single","stem":"TP99 时延即满足百分之九十九的网络请求所需要的最低耗时。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。TP99 把时延样本升序排列后取第 99 百分位，含义是 99% 的请求在此耗时之内完成；既然 99% 的样本都不超过它，它自然是满足这 99% 请求所需的最小耗时，“最低耗时”这一措辞正是百分位定义本身，故选 A。另注意它只描述分布位置，与保障服务稳定性的 SLA 不是同一概念。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-103","subject":"hcip_cloud","num":103,"pnum":106,"page":28,"type":"multi","stem":"CSE 提供了一系列配套的开发工具，包含： （）","options":[["A","本地/云上工程"],["B","代码/文档自动生成"],["C","微服务流水线"],["D","本地/远程调试"],["E","测试管理"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"ServiceComb 把脚手架与服务治理一体化工具链放在 CSE 周边：本地工程与云上工程两种初始化方式，契约优先的代码与文档生成，微服务流水线串起构建部署，本地与远程调试，测试用例管理，五项皆属配套工具，故选 ABCDE。易漏的是代码/文档自动生成与测试管理，两者常被当成 IDE 自带能力而非 CSE 配套。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-104","subject":"hcip_cloud","num":104,"pnum":107,"page":28,"type":"single","stem":"在华为云上部署的分布式为服务架构的应用，用传统的运维方式，去云服务器上下载日志来定位 bug，也是很方便快捷的。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。判据在分布式定位成本：一个请求横跨多个服务与实例，故障点未必在日志所在的机器上，逐台登录、下载再人工串联既慢又易漏；容器实例随时重建、日志随之丢失，调用时间戳跨节点还难以对齐。正确做法是 APM 调用链加 LTS 集中日志，故选 B 即判定原说法错误。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-105","subject":"hcip_cloud","num":105,"pnum":108,"page":28,"type":"single","stem":"微服务引擎提供了微服务之间的灰度发布，支持按照 Request 中某个字段(例如 Header)的值进行匹配。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据看路由能力：CSE 治理中心的灰度规则可取请求的 Header、Query 参数、Cookie 或调用方服务名等特征做匹配，命中后只把该部分流量导向打 tag 的新版本实例，其余仍走稳定版本，因此按 Header 取值灰度成立、选 A。它与按流量百分比的灰度是两种不同维度，别混为一谈。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-106","subject":"hcip_cloud","num":106,"pnum":109,"page":28,"type":"single","stem":"微服务架构下的微服务天然支持 DevOps，微服务与 DevOps 相辅相成。DevOps 要求业务组件的开发、测试和运维由一个团队负责(two pizza team)，快速迭代、持续交付。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在“谁对交付负责”：DevOps 要求开发、测试、运维由同一个全功能小团队端到端负责（two-pizza team），配合自动化流水线实现小步快跑、持续交付，而微服务的独立可部署性正是这套协作模式的前提，二者互相成就，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-107","subject":"hcip_cloud","num":107,"pnum":110,"page":28,"type":"single","stem":"如果从零开始开发一个基于 CSE Java SDK 的微服务，推荐使用哪种方式创建微服务？（）","options":[["A","云上工程"],["B","构建管理"],["C","流水线"],["D","本地工程"]],"answer":["A"],"ans_raw":"A","explain":"云上工程（ServiceStage/CodeArts 在线 IDE）预置 Java Chassis 模板与 CSE 连接配置，浏览器里即可生成工程、编译调试并直接部署到 CSE，省去本地搭环境、配依赖与打通访问的环节，适合从零起步，故选 A。本地工程面向已有 IDE 与私服环境；构建管理与流水线属 CI/CD 环节，不是创建微服务的方式。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-108","subject":"hcip_cloud","num":108,"pnum":111,"page":29,"type":"single","stem":"微服务是以不断提高交付效率、缩短交付周期为核心。基于云原生的方式，对架构优化的结果。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据看动机是否成立：微服务把功能切成可独立发布的小服务，配合容器与流水线让每次变更小步上线、影响面局部化，目标正是提高交付效率、缩短交付周期，且它是依托云原生能力（容器、编排、服务治理）对架构做的优化，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-109","subject":"hcip_cloud","num":109,"pnum":112,"page":29,"type":"multi","stem":"华为云容器引擎支持哪些层面的亲和性和反亲和性？（）","options":[["A","应用"],["B","集群"],["C","节点"],["D","网络"]],"answer":["A","C"],"ans_raw":"AC","explain":"CCE 的亲和性配置分两层：应用层用 Pod 间亲和/反亲和（affinity/anti-affinity）让实例分散到不同节点或拓扑域、或与同组服务同置；节点层用节点亲和与节点选择器按标签把实例定向到特定 ECS 机型、AZ，故选 AC。集群维度靠 zone、region 标签与多集群管理体现，不单设亲和层；网络层无亲和机制，VPC、Subnet 不做 Pod 放置约束。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-110","subject":"hcip_cloud","num":110,"pnum":113,"page":29,"type":"multi","stem":"容器编排工具包括？（）","options":[["A","Kubernetes"],["B","Marathon"],["C","Neutron"],["D","Horizon"]],"answer":["A","B"],"ans_raw":"AB","explain":"K8s 与 Marathon 都工作在容器编排层，负责把应用实例调度到集群节点、维持副本数、做健康检查与滚动升级，故选 AB。Neutron 是 OpenStack 的网络即服务组件，只虚拟网络拓扑；Horizon 是 OpenStack 的 Web 管理门户，属 UI 而非调度器。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-111","subject":"hcip_cloud","num":111,"pnum":114,"page":29,"type":"single","stem":"将平台作为服务的云计算服务类型是？（）","options":[["A","IaaS"],["B","以上都不是"],["C","SaaS"],["D","PaaS"]],"answer":["D"],"ans_raw":"D","explain":"按三层定义划分职责即可判断：IaaS 交付计算、存储、网络等基础设施；PaaS 把“平台”本身当服务交付，管运行时、中间件与部署编排；SaaS 交付可直接使用的软件。题面“将平台作为服务”即 Platform as a Service，故选 D。C 的 SaaS 交付的是成品应用，易与平台层混淆。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-112","subject":"hcip_cloud","num":112,"pnum":115,"page":29,"type":"multi","stem":"华为 CCE 云容器引擎可以创建哪些类型的集群？（）","options":[["A","AIX 集群"],["B","虚拟机集群"],["C","裸金属集群"],["D","Windows 集群"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"CCE 集群的工作节点可由 ECS 虚拟机或 BMS 裸金属服务器承载，并支持 Windows 容器集群，故选 BCD。AIX 是 IBM 小型机上的 Unix 操作系统，不在 CCE 节点形态之内，为最易误加的一项。记法：节点底座无非虚拟机或裸金属，AIX 与二者无关。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-113","subject":"hcip_cloud","num":113,"pnum":116,"page":29,"type":"single","stem":"Kubelet 是一个位于集群 master 节点的管理组件。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"Kubelet 是节点代理，运行在每个 Node（含 master）上，按 PodSpec 负责本机容器的创建、健康检查与生命周期，属节点组件而非 master 管理组件，故选 B。master 侧的管理组件是 kube-apiserver、scheduler、controller-manager 等，别把节点侧与主控侧组件混为一谈。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-114","subject":"hcip_cloud","num":114,"pnum":117,"page":30,"type":"single","stem":"在 Kubernetes 中静态 POD 需要 api server 介入。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"静态 Pod 由 kubelet 直接读取节点本地 manifest 目录创建并管理，不经 apiserver、不写 etcd，主要用于自托管控制面组件，故不需要 apiserver 介入、选 B。apiserver 对静态 Pod 只读可见、无法经它下发或编辑，这正是它与普通 Pod 的关键差别。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-115","subject":"hcip_cloud","num":115,"pnum":118,"page":30,"type":"single","stem":"Kubernetes 中，Kubectl 是与集群的哪个组件进行交互的？（）","options":[["A","etcd"],["B","evevt-controller"],["C","kubelet"],["D","api-server"]],"answer":["D"],"ans_raw":"D","explain":"kubectl 把 YAML 或命令行请求转成 REST 调用发给 kube-apiserver，集群内所有资源的增删改查都统一经 apiserver 处理，再由它读写后端 etcd，故选 D。etcd 只是键值存储、不直接对外提供接口，kubelet 是节点代理、event-controller 负责事件，三者都不是 kubectl 的对接入口，故排除。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-116","subject":"hcip_cloud","num":116,"pnum":119,"page":30,"type":"multi","stem":"使用华为云分布式消息 DMS 服务时，在 Kafka 队列创建完成后，需要取得哪些信息才能完成客户接入？（）","options":[["A","客户端证书"],["B","接入点信息"],["C","AS/SK"],["D","消费者信息"]],"answer":["A","B"],"ans_raw":"AB","explain":"客户端接入 Kafka 需拿到 broker 接入点地址（IP/域名加端口）才能建连，启用 SSL 安全协议时还须下载客户端证书做认证，故选 AB。AK/SK 用于调用云服务 API 管理资源，Kafka 客户端本身不用它；消费者信息属业务侧运行概念，非接入前提，最易误选。","note":"答案 AB","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-117","subject":"hcip_cloud","num":117,"pnum":120,"page":30,"type":"single","stem":"以下哪个中间件服务可解决业务应用的热点数据缓存问题？（）","options":[["A","DMS:分布式消息服务"],["B","DCS:分布式缓存服务"],["C","RDS:关系数据库服务"],["D","DDM:分布式数据库服务"]],"answer":["B"],"ans_raw":"B","explain":"DCS 分布式缓存服务兼容 Redis/Memcached，专职把热点数据放内存做高速读写、加速访问，故选 B。DMS 是消息队列做异步解耦，RDS 是持久化关系库，DDM 是数据库分库分表中间件，三者都不承担内存缓存职责，别把缓存与消息/数据库混用。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-118","subject":"hcip_cloud","num":118,"pnum":121,"page":30,"type":"single","stem":"当业务需要一个高可用、高可靠性，但非大容量、高并发的数据缓存时，应该为应用选择以下哪种类型的华为云分布式缓存 DCS 服务？（）","options":[["A","主备"],["B","单机"],["C","集群"],["D","以上都不对"]],"answer":["A"],"ans_raw":"A","explain":"主备实例一主一备、故障自动切换，保证高可用高可靠，容量与并发适中，正好匹配不需要大容量高并发的场景，故选 A。单机无备份、不满足高可用；集群才面向大容量高并发，与题设相反；故不选 B、C，也不选 D。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-119","subject":"hcip_cloud","num":119,"pnum":122,"page":30,"type":"single","stem":"企业如果自己开发或直接使用开源中间件，则需要企业自主解决硬件故障、软件安装部署、中间件软件 bug 和安全修复等问题，需要企业投入大量人力。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在责任边界：自建或直接用开源中间件时，硬件故障处理、安装部署、软件 bug 与安全补丁修复都要企业自行承担，确需大量人力，这正是云托管中间件要替客户化解的负担，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-120","subject":"hcip_cloud","num":120,"pnum":123,"page":30,"type":"multi","stem":"企业应用零改造上云方案可以带来哪些收益？（）","options":[["A","提高资源利用率"],["B","滚动部署，灰度发布"],["C","自动化部署，效率高，错误率低"],["D","自动化监控运维服务"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"零改造上云靠平台托管能力兑现收益：滚动部署与灰度发布(B)、自动化部署提效降错(C)、自动化监控运维(D)，且不改代码即可享受。最易误选的 A 提高资源利用率通常要容器化、弹性伸缩等改造才显著，直接平移反难提升利用率，故不选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-121","subject":"hcip_cloud","num":121,"pnum":124,"page":31,"type":"single","stem":"中间件可帮助用户灵活、高校地开发和集成复杂的应用软件。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在中间件定义：它位于应用与操作系统/网络之间，封装通信、事务、数据访问等通用能力，帮助用户灵活、高效地开发和集成复杂应用，符合公认表述（题干高校应为高效笔误），故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-122","subject":"hcip_cloud","num":122,"pnum":125,"page":31,"type":"single","stem":"当业务需要一个高可用、高可靠性，同时又是大容量、高并发的数据缓存，此时应用应该选择以下哪种类型的华为云分布式缓存 DCS 服务？（）","options":[["A","主备"],["B","以上都不对"],["C","单机"],["D","集群"]],"answer":["D"],"ans_raw":"D","explain":"集群实例由多分片加副本组成，既保证高可用高可靠，又能水平扩展承载大容量、高并发，故选 D。主备只有高可用但容量并发有限、单机两者都不满足，恰好对应上一题的非大并发场景；故不选 A、C，也不必选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-123","subject":"hcip_cloud","num":123,"pnum":126,"page":31,"type":"multi","stem":"应用切换中间件方案主要应对哪些挑战？（）","options":[["A","业务手工部署，效率低，错误率高"],["B","企业自运维成本高"],["C","性能差，扩容能力不足"],["D","开源版本高可用能力不足"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"切换到云中间件解决的是中间件自身痛点：企业自运维成本高(B)、性能与扩容能力不足(C)、开源版高可用弱(D)。A 描述的是业务应用手工部署效率低的问题，属应用编排/部署环节，不是中间件方案要应对的挑战，为最易误选的一项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-124","subject":"hcip_cloud","num":124,"pnum":127,"page":31,"type":"multi","stem":"云架构师的能力模型包括哪些维度？（）","options":[["A","系统优化"],["B","运行维护"],["C","规划设计"],["D","部署实施"],["E","需求分析"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"华为云架构师能力模型覆盖需求分析、规划设计、部署实施、运行维护、系统优化五个维度，贯穿上云全生命周期，故选 ABCDE。可记为分析—设计—实施—运维—优化的闭环，五项缺一即不完整。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-125","subject":"hcip_cloud","num":125,"pnum":128,"page":31,"type":"multi","stem":"从应用开发部署的视角看，云架构设计包括以下哪些领域？（）","options":[["A","可扩展性和自动缩放设计"],["B","松耦合和无状态设计"],["C","安全的设计"],["D","系统失效的容错设计"],["E","API 接口设计"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"从开发部署视角，云架构设计四大领域为可扩展与自动缩放、松耦合与无状态、安全、系统失效的容错，故选 ABCD。E 的 API 接口设计是具体开发活动，不属这四个设计原则领域，为最易多加的一项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-126","subject":"hcip_cloud","num":126,"pnum":129,"page":32,"type":"single","stem":"下面关于 SOA 和 ESB 的说法，哪个是不争取的？（）","options":[["A","SPA 服务可用不同语言开发"],["B","ESB 是 SOA 理念的一种企业级实现"],["C","当用 ESB 连接企业内部的基于 web 的服务和外部的非 web 服务时，需要把 web 服务重新开发成非 web 服务"],["D","ESB 既有商用产品，也可以企业自研"]],"answer":["C"],"ans_raw":"C","explain":"题干选不正确者。ESB 的价值正是做协议与服务转换适配，能同时对接 Web 与非 Web 服务，无需把 Web 服务重写，故 C 说法错误、入选。SOA 服务可用不同语言开发(A)、ESB 是 SOA 的企业级实现(B)、可商用可自研(D)均成立。（SPA 应为 SOA、争取应为正确，属录入误写）","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-127","subject":"hcip_cloud","num":127,"pnum":130,"page":32,"type":"single","stem":"DevOps 的兴起有众多驱动因素，其中云计算属于哪个方面的驱动因素？（）","options":[["A","业务需求"],["B","工程基础"],["C","能力需求"],["D","技术基础"]],"answer":["D"],"ans_raw":"D","explain":"DevOps 兴起的驱动分多层：云计算、容器、微服务等属技术基础，故选 D。敏捷与精益属工程/方法论基础，快速交付与市场竞争压力属业务需求，能力需求偏组织与人才侧，均非云计算所在层面。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-128","subject":"hcip_cloud","num":128,"pnum":131,"page":32,"type":"single","stem":"应用编排服务(AOS)能完成应用资源编排和应用设计。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"应用编排服务 AOS 提供图形化应用模型设计，并基于模板把应用所需 ECS、EVS、VPC、ELB 等资源自动编排部署，故能完成应用资源编排和应用设计，判对、选 A。它面向的是资源与应用的编排建模，而非应用内业务代码本身。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-129","subject":"hcip_cloud","num":129,"pnum":132,"page":32,"type":"multi","stem":"关于无状态应用和有状态应用的区别，下面哪些说法是正确的？（）","options":[["A","有状态应用需要记住发起请求的具体用户"],["B","有状态应用可以通过代码改造获得更好的扩展性"],["C","无状态应用比起有状态应用具有更高的性能"],["D","无状态应用可以较方便地部署在容器里"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"有状态应用保存客户端上下文/session，需记住具体用户(A)；无状态不维护会话、性能更高(C)，也更容易容器化和水平扩展(D)。最易误选的 B 表述反了：要改造成无状态才能获得更好扩展性，有状态本身扩展性差。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-130","subject":"hcip_cloud","num":130,"pnum":133,"page":33,"type":"multi","stem":"架构师的工作实践包括以下哪些方面？（）","options":[["A","以项目实施阶段为重点，贯穿整个产品开发周期"],["B","以战略问题为导向，关注战术问题"],["C","以高层次设计为主，参与功能模块的设计"],["D","以全局为主导，指导局部实施"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"架构师实践为战略导向兼顾战术(B)、以高层次设计为主并适度参与功能模块设计(C)、以全局为主导指导局部实施(D)。A 错在重点放在项目实施阶段——架构关注设计决策与全生命周期，而非聚焦实施阶段，故不选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-131","subject":"hcip_cloud","num":131,"pnum":134,"page":33,"type":"single","stem":"在应用改造上云过程中可以使用 DDM 中间件来代替原应用中的 Redis 服务。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。DDM 是分布式数据库中间件，作用是在多个 MySQL 实例上做水平拆分与读写分离，本身不提供内存缓存，无法替代应用里的 Redis；要替代 Redis 应选兼容其协议的 DCS 分布式缓存服务，故选 B 判错。把 DDM 误当成缓存层是常见的概念错位。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-132","subject":"hcip_cloud","num":132,"pnum":135,"page":33,"type":"single","stem":"某票务网站进行大促销时，由于瞬间访问量巨大，网站容易瘫痪。为了应对流量洪峰，以下哪种微服务治理方法能够有效应对该场景，防止系统过载崩溃？（）","options":[["A","限流"],["B","负载均衡"],["C","熔断"]],"answer":["A"],"ans_raw":"A","explain":"限流对入口请求速率设阈值，主动挡掉超出系统承载的洪峰流量，直接防止过载崩溃，故选 A。负载均衡只是把请求均摊到各实例、并不限制总量；熔断针对下游故障时快速失败以止损，二者都不解决自身被瞬时大流量压垮的问题。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-133","subject":"hcip_cloud","num":133,"pnum":136,"page":33,"type":"multi","stem":"假如你在华为云上部署了一个电商网站，为了惠及老客户，准备搞一个为期一天的大甩卖，那么运维人员应该提前在华为云上做好哪些准备？（）","options":[["A","对网站的关键应用性能指标设置阈值告警，告警自动通知运维人员"],["B","将例行运维需要查看的指标添加到仪表盘中，以便实时掌握全局"],["C","使用华为云的 Cloud Eye 提前演练一下网站的高访问量服务能力"],["D","提前准备资源，设置弹性伸缩组，在促销过程中随资源使用量上升及时扩容"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"大促前的合理运维准备：对关键性能指标设阈值告警并通知(A)、把例行指标聚成仪表盘实时掌握全局(B)、提前配弹性伸缩组随负载上升扩容(D)。最易误选的 C 站不住——Cloud Eye 是监控告警服务，不做高并发压测/演练，压测应使用性能测试服务。","note":"","flag":"option-D-completes-on-p034","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-134","subject":"hcip_cloud","num":134,"pnum":137,"page":34,"type":"judge","stem":"APM 非侵入式数据采集的探针技术是被动式监控，不消耗 CPU 和内存。（错误）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。判据在采集开销：非侵入式探针靠 JVM 字节码增强在方法出入口织入埋点、在进程内持续采集，虽无需改代码，但必然占用少量 CPU 与内存，不消耗的说法过于绝对，故选 B。非侵入指不改业务代码，不等于零开销。","note":"","flag":"labeled-填空题","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-135","subject":"hcip_cloud","num":135,"pnum":138,"page":34,"type":"judge","stem":"UML 类图部署表示类之间的动态关系（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）按标准 UML，类图属结构/静态图，表达类及属性方法与类间关联、泛化、依赖等静态关系，动态交互由时序、协作等交互图刻画。因此类图表示动态关系应判错、应为 B，题库给 A 存疑；且题干中部署一字疑似录入串行，请一并复核。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-136","subject":"hcip_cloud","num":136,"pnum":139,"page":34,"type":"judge","stem":"SOA 用于企业内部业务系统的架构设计，ESB 主要用于企业间业务系统交互。（）","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。SOA 是架构理念、ESB 是其实现总线，二者既能做企业内部系统集成，也能支撑跨企业/跨系统交互，不能把 SOA 限定为内部、把 ESB 限定为企业间。题干人为割裂两者用途，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-137","subject":"hcip_cloud","num":137,"pnum":140,"page":34,"type":"judge","stem":"华为公有云和私有云都用了 FusionSphere 的方案。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在底层虚拟化：FusionSphere 是华为自研的虚拟化与云操作系统，向上支撑云资源池的管理与调度。无论公有云底座，还是私有云场景下的 FusionSphere OpenStack，都构建在这套虚拟化方案之上，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-138","subject":"hcip_cloud","num":138,"pnum":141,"page":34,"type":"multi","stem":"下列描述与容器镜像服务 SWR 有关的是（）","options":[["A","高性能，自研高性能容器网络，秒级自动弹性伸缩"],["B","镜像管理。。。"],["C","多平台部署，支持CCE\\SERVICESTAGE\\SWR 用户的部署调用"],["D","安全可靠，镜像仓库多租隔离"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"SWR 是容器镜像托管服务：镜像管理(B)、对接 CCE/ServiceStage/SWR 多平台部署调用(C)、镜像仓库多租户隔离、安全可靠(D)。A 的自研高性能容器网络与秒级弹性伸缩属 CCE 集群能力，与镜像服务无关，为最易误选项。（B 原文被省略号截断，但含义可辨为镜像管理）","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-139","subject":"hcip_cloud","num":139,"pnum":142,"page":34,"type":"multi","stem":"以下哪些是 DCS 的定位？（）","options":[["A","可有效提升热点数据的访问速度"],["B","可支持强一致性事务"],["C","可大幅降低数据库压力"],["D","为应用系统提供key-value 数据缓存"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"DCS 定位为 key-value 内存缓存(D)，加速热点数据读(A)、卸载后端数据库压力(C)。最易误选的 B 不成立：缓存不保证强一致性事务，一致性是数据库/事务语义，缓存为性能通常牺牲强一致，勿把它当事务型存储。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-140","subject":"hcip_cloud","num":140,"pnum":143,"page":35,"type":"multi","stem":"以下哪些是 DDM 服务的关键特性？（）","options":[["A","兼容 SQL 语法"],["B","可承受 PB 机数据量，百万级并发量"],["C","业务不中断，自动完成水平炒粉、平滑扩容"],["D","集群高可用，秒级故障自动恢复"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"DDM 关键特性四项俱全：兼容 SQL 语法(A)、支撑 PB 级数据量与百万级并发(B)、业务不中断自动水平拆分与平滑扩容(C)、集群高可用秒级故障恢复(D)，四项均为其特性，故选 ABCD。题干机数据、水平炒粉为录入误写，应为 PB 级数据、水平拆分。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-141","subject":"hcip_cloud","num":141,"pnum":144,"page":35,"type":"single","stem":"docker 中查看正在运行的容器的命令是什么？（）","options":[["A","docker images"],["B","docker images"],["C","docker run"],["D","docker ps"]],"answer":["D"],"ans_raw":"D","explain":"docker ps 用于列出当前正在运行的容器，加 -a 参数才连带显示已停止的，故选 D。docker images 列出的是本地镜像而非容器，docker run 则是创建并启动新容器的动作。需注意 A、B 两项文本重复录入（都写成 docker images），属题目录入串行，但不影响正确项 D 的判断。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-142","subject":"hcip_cloud","num":142,"pnum":145,"page":35,"type":"single","stem":"以下哪项是 CCE 部署应用的正确步骤？（）","options":[["A","应用访问设置，容器设置，应用基本信息设置，高级设置"],["B","应用基本信息设置，容器设置，应用访问设置，高级设置"],["C","应用基本信息设置，应用访问设置，容器设置，高级设置"],["D","容器设置，应用访问设置，应用基本信息设置，高级设置"]],"answer":["B"],"ans_raw":"B","explain":"CCE 通过创建向导部署应用，顺序为先填应用基本信息（名称、副本数等）、再做容器设置（镜像与规格）、然后应用访问设置（Service 对外暴露）、最后高级设置（健康检查、扩缩容等），与 B 一致。其余项把容器设置或访问设置顺序排错。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-143","subject":"hcip_cloud","num":143,"pnum":146,"page":35,"type":"judge","stem":"微服务引擎提供的自动负载均衡机制支持的策略包括：顺序、随机本地、粘滞、基于实例负载等。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在负载均衡策略集合：ServiceComb/CSE 的客户端负载均衡内置多种策略，包括顺序轮询 RoundRobin、随机、本地优先、会话粘滞 SessionSticky，以及基于实例负载/响应权重的调度等，题面列举的顺序、随机本地、粘滞、基于实例负载都在其中，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-144","subject":"hcip_cloud","num":144,"pnum":147,"page":35,"type":"single","stem":"以下哪项不属于 CSE 支持的编程模型？（）","options":[["A","JAX-RS"],["B","gRPC"],["C","POJO"],["D","SpringMVC"]],"answer":["B"],"ans_raw":"B","explain":"CSE 底层的 ServiceComb 原生支持的编程模型有 POJO、SpringMVC、JAX-RS 三种，开发者可按这几种方式声明并提供微服务(A/C/D 均属其中)。gRPC 是一种独立的通用 RPC 框架，并非 ServiceComb 定义的接入编程模型，故选 B 作为不属于的一项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-145","subject":"hcip_cloud","num":145,"pnum":148,"page":36,"type":"single","stem":"0.3<Apdex<0.75,用户体验（）","options":[["A","无法确定"],["B","较差"],["C","一般"],["D","较好"]],"answer":["C"],"ans_raw":"C","explain":"（存疑）Apdex 取 0~1、越接近 1 体验越好，业界与华为常用分档中约 0.5~0.75 记为一般、0.3~0.5 记为较差。题给区间 0.3<Apdex<0.75 同时跨过较差与一般两段，答案 C 一般只对应上半段，数值边界因表而异，请复核具体分档表。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-146","subject":"hcip_cloud","num":146,"pnum":149,"page":36,"type":"multi","stem":"下面哪些是业界的中间件产品？（）","options":[["A","IBM Message Queue"],["B","Redis"],["C","Apache Tomcat"],["D","Kafka"],["E","Oracle WEBLOGIC"],["F","Ignite"]],"answer":["A","B","C","D","E","F"],"ans_raw":"ABCDEF","explain":"六项都属业界中间件产品：IBM MQ、Kafka 是消息中间件(A/D)，Redis、Ignite 是内存缓存/数据网格类(B/F)，Apache Tomcat 是 Web 容器、Oracle WebLogic 是 Java EE 应用服务器(C/E)。广义上这些位于操作系统与应用之间、提供通用能力的软件都归中间件，故选 ABCDEF，无一排除。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-147","subject":"hcip_cloud","num":147,"pnum":150,"page":36,"type":"single","stem":"下面哪个命令不属于 dockerfile 命令范畴？（）","options":[["A","FROM"],["B","CD"],["C","COPY"],["D","MAINATNER"]],"answer":["B"],"ans_raw":"B","explain":"Dockerfile 的合法指令包括 FROM 指定基础镜像、COPY 把文件拷入镜像、MAINTAINER 声明维护者（现虽弃用但历史上属 Dockerfile 指令）(A/C/D)。而 CD 只是构建时运行的 shell 命令、并非 Dockerfile 关键字，故选 B。（D 项 MAINATNER 为 MAINTAINER 的录入误写）","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-148","subject":"hcip_cloud","num":148,"pnum":151,"page":36,"type":"multi","stem":"在 POJO 模式下，消费者调用服务提供者时需要制定哪些信息？（）","options":[["A","instanceId"],["B","schemaId"],["C","operationId"],["D","microserviceName"]],"answer":["B","D"],"ans_raw":"BD","explain":"POJO 模式下消费者通过 @RpcReference 指定目标服务的 microserviceName 与 schemaId，框架据此在注册中心查实例并生成代理发起调用，故选 B、D。instanceId、operationId 由框架运行时路由与解析，不需调用方手工指定，为易误选项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-149","subject":"hcip_cloud","num":149,"pnum":152,"page":36,"type":"judge","stem":"DevOps 是指提供一系列的工具链，用来实现自动化的持续交付。（）","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在落地形态：DevOps 通过覆盖开发到运维的工具链（代码库、CI、制品仓库、自动部署、监控）实现持续集成与自动化持续交付，符合课程定义，故选 A。DevOps 也含协作文化，本句只强调工具链自动化层面，不算错。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-150","subject":"hcip_cloud","num":150,"pnum":1,"page":36,"type":"judge","stem":"华为的 PaaS 层应用分为：GPaaS 和 APaaS","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在两层面向的对象不同：华为把 PaaS 分为 GPaaS 与 APaaS——GPaaS 是通用平台即服务，向开发者提供容器、中间件、数据、微服务等通用底座能力；APaaS 是应用平台即服务，偏向业务应用的组装、托管与低代码搭建。这一二分法成立，故选 A。","note":"","flag":"options-on-p037","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-151","subject":"hcip_cloud","num":151,"pnum":2,"page":37,"type":"judge","stem":"SOA 的架构通过引入 ESB 企业服务总线的概念，将应用模块化构建成为独立的单元提供服务","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在服务化组织方式：SOA 把应用功能封装为松耦合、可复用的独立服务单元对外提供，ESB 作为企业服务总线承担这些服务间的路由、编排与协议适配，描述与 SOA/ESB 定位一致，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-152","subject":"hcip_cloud","num":152,"pnum":3,"page":37,"type":"multi","stem":"一般的 web 应用逻辑上分为哪三层？","options":[["A","接入层"],["B","业务逻辑层"],["C","数据访问层"],["D","持久化层"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"一般 Web 应用逻辑上分三层：接入/表现层(A)负责与用户交互、承接请求入口，业务逻辑层(B)承载核心处理，数据访问层(C)封装对数据库的读写。D 持久化层通常被包含在数据访问层之下、不单列为经典三层之一，属最易多加的一项，故不选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-153","subject":"hcip_cloud","num":153,"pnum":4,"page":37,"type":"multi","stem":"微服务有哪些优点？","options":[["A","可以使用不同的技术栈来构建服务"],["B","协议轻量化，可使用 HTTP 协议通信"],["C","可以灵活扩展架构"],["D","微服务是银弹，适合各种业务场景"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"微服务优点：各服务可独立选技术栈(A)、以 HTTP/REST 等轻量协议通信(B)、按服务粒度灵活扩展(C)。D 称微服务是银弹、适合一切场景，违背 Fowler 关于微服务引入分布式复杂度代价的论断，为最易误选项，故不选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-154","subject":"hcip_cloud","num":154,"pnum":5,"page":37,"type":"multi","stem":"云架构设计的一般原则是：","options":[["A","考虑系统失效的容错设计"],["B","应用使用松耦合和无状态设计"],["C","可扩展和自动缩放设计"],["D","考虑将安全因素贯穿到设计原则中"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"云架构设计四原则：系统失效的容错设计(A)、松耦合与无状态设计(B)、可扩展与自动缩放设计(C)、安全因素贯穿设计(D)，故选 ABCD。与 125 题同源，此处未把 API 接口设计列为设计原则。","note":"","flag":"option-D-on-p038","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-155","subject":"hcip_cloud","num":155,"pnum":6,"page":38,"type":"multi","stem":"以下哪些是中间件的用途？","options":[["A","支持超大规模应用"],["B","支持海量访问"],["C","支持海量数据"],["D","模块异步解耦"],["E","热点数据缓存"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"中间件的典型用途涵盖五项：支撑超大规模应用(A)、承受海量访问(B)、处理海量数据(C)，消息类中间件实现模块间异步解耦(D)，缓存类中间件做热点数据加速(E)。这五项分别对应不同中间件的定位，均属其用途，故选 ABCDE，无一排除。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-156","subject":"hcip_cloud","num":156,"pnum":8,"page":38,"type":"multi","stem":"以下哪些是 DCS 服务的关键特性","options":[["A","灵活规格"],["B","兼容开源"],["C","弹性扩容"],["D","数据可靠"],["E","自主运维"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"DCS 关键特性五项俱全：灵活规格，可选单机/主备/集群形态(A)；兼容 Redis、Memcached 开源协议(B)；支持弹性扩容(C)；靠多副本与持久化备份保障数据可靠(D)；控制台提供自助备份、重启、参数调整等自主运维能力(E)。故选 ABCDE。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-157","subject":"hcip_cloud","num":157,"pnum":9,"page":38,"type":"single","stem":"当业务需要一个高可用、高可靠性的数据缓存，但不需要高规格的数据缓存时，此时应用应该选择以下哪种类型的 DCS 服务？","options":[["A","单机"],["B","主备"],["C","集群"]],"answer":["B"],"ans_raw":"B","explain":"主备实例一主一备、故障自动切换，提供高可用高可靠，规格适中，正好匹配不需高规格的缓存场景，故选 B。单机无备份不满足高可用；集群面向高规格大容量高并发，与题设相反，均排除。","note":"","flag":"options-B-C-on-p039","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-158","subject":"hcip_cloud","num":158,"pnum":10,"page":39,"type":"multi","stem":"以下哪些是 DDM 服务的关键特性？","options":[["A","业务不中断，自动完成水平拆分、平滑扩容。"],["B","可承受 PB 级数据量，百万级并发量、十倍于单机数据库连接。"],["C","集群高可用，秒级故障自动恢复。"],["D","兼容 MySQL 协议"],["E","兼容 Oracle 协议。"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"DDM 特性：不中断自动水平拆分与平滑扩容(A)、PB 级数据加百万并发加多倍于单机连接(B)、集群高可用秒级故障恢复(C)、兼容 MySQL 协议(D)。最易误选的 E 不成立：DDM 面向 MySQL 做分布式拆分，不兼容 Oracle 协议，故不选 E。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-159","subject":"hcip_cloud","num":159,"pnum":11,"page":39,"type":"judge","stem":"华为是容器开源社区主要贡献者和容器生态领导者，是 CNCF 基金会的初创会员、白金会员，Kubernetes 社区贡献国内第一，全球第三，同时也是国内首发 Windows 容器和基因容器服务 GCS 的厂家。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。此为华为对其容器生态地位的官方/教材口径：CNCF 白金会员、开源社区主要贡献者、K8s 社区贡献排名居前、率先推出 Windows 容器与面向基因组学的 GCS 容器服务，与教材表述一致，故选 A。具体排名数字属宣传口径，按现行资料复核即可。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-160","subject":"hcip_cloud","num":160,"pnum":12,"page":39,"type":"judge","stem":"华为云企业集成平台 ROMA 命名寓意“条条大路通罗马”，它能够连接企业IT 系统、数据、消息、API、设备、云服务，提供统一的应用与数据集成平台。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在 ROMA 定位：其命名寓意条条大路通罗马，作为企业集成平台/总线，打通 IT 系统、数据、消息、API、设备与云服务，提供统一的应用与数据集成，与官方定义吻合，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-161","subject":"hcip_cloud","num":161,"pnum":13,"page":39,"type":"judge","stem":"区块链是一种万能的技术，可替代数据库，替代 Internet。华为区块链服务（Blockchain Service，BCS），是面向企业及开发者的高性能、高可用和高安全的区块链技术平台服务，适用于数据交易、身份认证、新能源、车联网、供应链溯源等场景。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。前半句称区块链万能、可替代数据库与 Internet 明显夸大——区块链只适合多方互信、不可篡改记账的特定场景，通用存储仍靠数据库、传输仍靠网络。虽后半段对 BCS 的定义与场景描述无误，但整句因夸大判定不成立，故选 B。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-162","subject":"hcip_cloud","num":162,"pnum":14,"page":39,"type":"judge","stem":"华为云容器启动速度快、资源占用小、运行效率高等优势，快速扩容、从容应对突发性大流量冲击，从根本上避免了“官宣”式宕机。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在容器形态优势：容器轻量、启动快、资源占用小，配合弹性伸缩可快速扩容扛住突发大流量，是华为对容器价值的描述，快速扩容从容应对官宣式流量洪峰、避免宕机的结论与其口径一致，故选 A。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-163","subject":"hcip_cloud","num":163,"pnum":15,"page":40,"type":"single","stem":"现今各行业数字化转型面临全方位集成挑战，华为 ROMA 集成平台能够支撑“ABCD”全面集成，其中的“B”指的是？","options":[["A","Devices：跨设备集成，设备到设备、OT 和 IT 间的融合"],["B","Application：跨应用集成，应用到应用间、数据、消息、API、流程集成"],["C","Business：跨企业业务集成，跨企业数据交换"],["D","Clouds：跨云集成，公有云到私有云、多云之间的协同"]],"answer":["C"],"ans_raw":"C","explain":"ROMA 的 ABCD 指 A=Application（跨应用集成）、B=Business（跨企业业务集成）、C=Cloud（跨云集成）、D=Device（跨设备集成）。故字母 B 对应跨企业业务集成，即选项 C 的文字。易错点在于选项字母与缩写首字母错位，别按字母 B 直接选 B 项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-164","subject":"hcip_cloud","num":164,"pnum":16,"page":40,"type":"single","stem":"区块链的价值是在互相不信任的组织之间建立信任，降低交易成本，提升交易效率，促进互信。下列关于区块链描述有误的是？","options":[["A","区块链特点：分布式账本，通过多方共识写入账本，不可篡改，可溯源，公开透明"],["B","区块链价值：促进信任，降低交易成本，提升效率"],["C","华为云区块链平台 BCS 具有开放、易用、高效、安全等特点"],["D","区块链是一种万能的技术，可替代数据库，替代 Internet"]],"answer":["D"],"ans_raw":"D","explain":"本题选描述有误者。D 称区块链万能、可替代数据库和 Internet，属明显夸大，区块链适合多方互信场景而非通用替代，故选 D。A 的分布式账本、不可篡改、可溯源等特点，B 的促进信任降本增效之价值，C 的 BCS 开放易用高效安全之特性，均为正确表述。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-165","subject":"hcip_cloud","num":165,"pnum":17,"page":40,"type":"single","stem":"容器技术是企业云战略转型的关键，同时也是云原生（Cloud Native）的核心，下列哪项不属于容器的三大好处？","options":[["A","资源利用率提升"],["B","秒级弹性"],["C","环境一致性，简化交付"],["D","复杂性增加"]],"answer":["D"],"ans_raw":"D","explain":"容器三大好处为提升资源利用率(A)、秒级弹性伸缩(B)、环境一致性并简化交付(C)。D 复杂性增加是使用容器与编排带来的代价/挑战，并非好处，故属不属于三大好处的答案。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-166","subject":"hcip_cloud","num":166,"pnum":18,"page":40,"type":"single","stem":"在 HUAWEI CONNECT 2018 大会上，华为正式发布华为云智能边缘平台（Intelligent EdgeFabric, IEF）和Atlas 500 智能小站，提供从 AI 芯片、智能硬件到边缘云服务的全栈能力。下列不属于其典型应用场景的是？","options":[["A","安平监控场景。通过在边缘侧的视频预分析，实现园区、住宅、商超等视屏监控场景实时感知安全事件、监控联动"],["B","工业视觉场景。云端已训练的视觉模型，在边缘侧部署，实现产品实时预测，提升检测效率，提高产品质量"],["C","工业制造预测性维护。设备预测性维护是工业 IoT 的典型场景，边缘端可以及时对大量数据进行预处理，通过边缘模型预测，提升设备运维效率，降低设备非计划停机时间"],["D","异地容灾。通过云专线将用户本地数据中心与华为云的 VPC 互联，配合 VPC 跨 AZ 部署，使得用户的数据和服务备份到不同地域，达到异地容灾的目的"]],"answer":["D"],"ans_raw":"D","explain":"IEF 智能边缘平台加 Atlas 500 的典型边缘场景是安防/视频智能(A)、工业视觉(B)、设备预测性维护(C)，共同点是把云侧模型下沉到边缘做实时推理。D 异地容灾属云专线与多 AZ 的网络可靠性方案，与智能边缘无关，为不属于项。","note":"","flag":"option-D-on-p041","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-167","subject":"hcip_cloud","num":167,"pnum":19,"page":41,"type":"multi","stem":"2018 年“双十一”走到第十个年头，已经演变成了一场所有电商平台的全民狂欢。请问下列哪些服务能够应用于电商“促销”、“抢购”场景？","options":[["A","云容器引擎 CCE：灵活的弹性伸缩策略，以应对多变的突发浪涌。"],["B","微服务引擎 CSE：支持微服务接口级 SLA 指标监控和治理（负载均衡、自动容错、服务降级、服务限流），保障应用运行不断服。"],["C","应用性能管理 APM：提供从端到云应用性能追踪能力，通过应用全景拓扑，实时监测、快速故障诊断。"],["D","云性能测试 CPTS：一站式性能测试解决方案，电商抢购真实场景模拟，提前发现系统瓶颈。"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项分别覆盖促销抢购的不同环节：CCE 按策略秒级扩缩副本，扛住突发浪涌；CSE 在接口层做限流、降级、熔断与负载均衡，保证不断服；APM 用全景拓扑和调用链实时定位性能瓶颈；CPTS 在活动前用真实抢购模型压测，提前暴露短板。易漏的是 D，压测属事前预防，同样是该场景的关键能力。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-168","subject":"hcip_cloud","num":168,"pnum":20,"page":41,"type":"multi","stem":"ServiceStage 是一站式全栈云原生应用开发与管理平台，ServiceStage 的下列哪些优势能够支撑打造最强云原生 PaaS 服务？","options":[["A","容器：最强 AI 容器平台，完善的混合云/多云解决方案（集群联邦），K8s 开源社区领导者"],["B","微服务：架构服务化，敏捷 DevOps"],["C","开发流水线：帮助企业快速搭建应用 Alpha、Beta、Gamma、生产环境"],["D","APM/AOM：全链路、实时监控、AIOps"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"ServiceStage 的四块支柱即此四项：容器（CCE/CCI，集群联邦支撑混合云多云）、微服务（架构服务化、敏捷 DevOps）、开发流水线（按 Alpha、Beta、Gamma、生产逐级发布）、APM/AOM（全链路、实时监控、AIOps）。易错在 C：流水线不止跑构建，还要拉起并串联多套环境。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-169","subject":"hcip_cloud","num":169,"pnum":21,"page":41,"type":"multi","stem":"下列属于微服务(Microservice)特征的是？","options":[["A","小：粒度小，且专注一件事情"],["B","独：单独的进程"],["C","轻：轻量级通信机制，HTTP/REST 接口"],["D","松：松耦合、可独立部署"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项合起来正是微服务的定义式描述：粒度小、只做一件事；每个服务独立进程运行、可单独伸缩；用 HTTP/REST 等轻量协议通信；服务之间松耦合、能独立部署上线。无干扰项，反向特征才属 SOA，即重量级总线、集中协议与统一发布。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-170","subject":"hcip_cloud","num":170,"pnum":22,"page":41,"type":"multi","stem":"华为云 PaaS 坚持公司在开源领域的主张“源于开源，高于开源，回馈开源”，基于云原生技术持续创新，助力繁荣生态。下列属于 PaaS 在开源领域的贡献的是？","options":[["A","容器领域：CNCF 初创会员、白金会员，Kubernetes 社区贡献国内第一，全球第三"],["B","微服务领域：自研微服务框架 ServiceComb，为业内首个 Apache 微服务顶级项目"],["C","区块链领域:2016 年即加入 Hyperledger 社区，Fabric 和 STL 的 Maintainer，亚洲唯一"],["D","Kubernetes 生态：针对基因测序与边缘场景的行业难题，开源了基于容器技术的一站式基因测序计算框架 KubeGene 与基于 Kubernetes 架构平台的管理框架 KubeEdge"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项均为华为公开的开源贡献：容器领域是 CNCF 初创会员、白金会员，Kubernetes 社区贡献国内领先；自研 ServiceComb 是业内首个 Apache 微服务顶级项目；2016 年加入 Hyperledger 并任 Maintainer；K8s 生态开源基因测序框架 KubeGene 与边缘框架 KubeEdge。易错在 C，区块链常被误认为与 PaaS 无关；C 中 STL 疑为 IOTA 之误。","note":"","flag":"options-on-p042","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-171","subject":"hcip_cloud","num":171,"pnum":23,"page":42,"type":"judge","stem":".华为的 PaaS 层应用分为：GPaaS 和 APaaS","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。华为把 PaaS 层分为 GPaaS 与 APaaS：前者提供与业务无关的通用平台能力，如容器引擎、微服务引擎、中间件、函数、编排部署与监控运维；后者提供面向具体业务的应用使能。判据看能力是否与特定应用逻辑绑定，通用运行时归 GPaaS，业务使能归 APaaS。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-172","subject":"hcip_cloud","num":172,"pnum":24,"page":42,"type":"judge","stem":"SOA 的架构通过引入 ESB 企业服务总线的概念，将应用模块化构建成为独立的单元提供服务","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。SOA 的标志性做法正是以 ESB 企业服务总线为中枢，把应用按业务能力拆成可独立提供服务的模块，由总线完成协议转换、路由与编排。注意与微服务的区别：SOA 依赖集中式总线，微服务倾向去中心化的薄通信层，题干描述与 SOA 一致，判定成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-173","subject":"hcip_cloud","num":173,"pnum":28,"page":43,"type":"multi","stem":"以下华为云服务哪些不是 PaaS 的范畴？","options":[["A","DevCloud"],["B","ECS"],["C","云桌面"],["D","ServiceStage"]],"answer":["B","C"],"ans_raw":"BC","explain":"ECS 交付弹性计算，属 IaaS；云桌面交付的是桌面实例，同样在 IaaS/DaaS 范畴，二者都不是 PaaS，故选 BC。DevCloud 软件开发云与 ServiceStage 面向应用开发与运行治理，属 PaaS。判据：直接把算力、桌面交给用户的是 IaaS，支撑应用构建与治理的才是 PaaS。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-174","subject":"hcip_cloud","num":174,"pnum":29,"page":43,"type":"multi","stem":"下哪些服务是企业内部能力通过 API 向外界开放？","options":[["A","Google 地图"],["B","salesforce.com"],["C","气象局的天气数据"],["D","股市实时和历史信息"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"Google 地图、气象局的天气数据、股市行情都是把自身沉淀的业务能力封装成 API 对外开放的典型，故选 ACD。salesforce.com 本身以 SaaS 形态交付软件产品，用户订阅的是应用而非调用其内部能力，B 属层级混淆，也是最常见的误选项，容易把云端提供的服务等同于能力开放。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-175","subject":"hcip_cloud","num":175,"pnum":30,"page":43,"type":"judge","stem":"应用性能管理（APM）支持非侵入式性能数据采集，可以无需修改业务代码即可轻松接入。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。APM 靠挂载 Agent 做字节码增强来采集事务与调用链数据，业务源代码不需要修改即可接入。判据在于“非侵入”指不改代码，仍然需要引入探针与少量配置；若题干改说必须改造业务代码才能接入，则应判错。","note":"","flag":"options-on-p044","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-176","subject":"hcip_cloud","num":176,"pnum":31,"page":44,"type":"judge","stem":"PaaS 分为 APaaS（Application PaaS，应用 PaaS）和 GPaaS（General PaaS，通用 PaaS）。GPaaS 的能力范围覆盖：编排部署、监控运维、容器引擎、微服务引擎、软件仓库、中间件、函数服务等。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。前半句 GPaaS 与 APaaS 的划分正确，后半句的能力清单也确属 GPaaS：编排部署、监控运维、容器引擎、微服务引擎、软件仓库、中间件、函数服务都与具体业务逻辑无关，是通用运行时能力；APaaS 才是应用使能层，两句互不矛盾。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-177","subject":"hcip_cloud","num":177,"pnum":32,"page":44,"type":"single","stem":"某专门作小微财务系统的软件开发商，虽然有着大体量的用户，但由于当前运营模式主要以卖 license 为主，因此需要给分散在全国各地的客户分别配置对应的运维人员，这就造成了大量运维成本的浪费。该企业想改变这种商业模式，可采用哪种解决方案？","options":[["A","用云中间件改造软件架构，提升效率"],["B","软件 SaaS 化"],["C","应用微服务化方案"],["D","使用 Serverless 函数计算平台"]],"answer":["B"],"ans_raw":"B","explain":"痛点源于 license 售卖带来的每客户一套部署与驻场运维，解法是软件 SaaS 化：一套多租户实例集中部署、按订阅收费，运维投入不再随客户数线性增长，故选 B。A 中间件改造与 C 微服务化只优化架构，不改收费与交付模式；D Serverless 是运行形态，同样不解决授权分发问题。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-178","subject":"hcip_cloud","num":178,"pnum":33,"page":44,"type":"multi","stem":"NIST（National Institute of Standards and Technology，美国国家标准与技术研究院）将 PaaS 概括为面向应用的核心平台，从功能定义和核心价值上来看，PaaS 具有哪些特性？","options":[["A","提供标准化的编程框架和服务来使能持续开发、集成"],["B","底层资源无感知的应用自动化运维（包括配置、升级、伸缩等等）"],["C","包括计算服务、存储服务和网络服务等"],["D","自动化获取云资源进行应用部署"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"NIST 把 PaaS 定位为面向应用的核心平台，A 的标准化编程框架与服务支撑持续开发集成、B 的底层资源无感知自动化运维（配置、升级、伸缩）、D 的自动化获取资源部署应用都属其特性。C 列举计算、存储、网络服务，是 IaaS 的资源范畴，层级错置，故排除。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-179","subject":"hcip_cloud","num":179,"pnum":34,"page":45,"type":"multi","stem":"业务使用容器后能带来哪些好处？","options":[["A","适合敏捷扩缩容场景"],["B","缩短应用上线时间"],["C","降低了应用部署成本"],["D","为业务提高了安全性"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"镜像一次构建到处运行、启动以秒计，因此适合敏捷扩缩容（A）、缩短上线时间（B）、靠提高部署密度摊薄部署成本（C）。D 不成立：容器共享宿主机内核，隔离强度弱于虚拟机，还需额外做镜像扫描、运行时防护与权限收紧，用容器并不自动等于更安全。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-180","subject":"hcip_cloud","num":180,"pnum":35,"page":45,"type":"judge","stem":"分布式系统具有透明性、扩展性、并发性和开放性的特点。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。这四项都能由分布式系统的定义直接推出：透明性指位置、迁移、访问对用户隐藏，扩展性指加节点即扩容，并发性指多节点同时处理共享数据，开放性指标准接口与互操作。判据是有无被偷换成单机特征，题干四项均无此问题。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-181","subject":"hcip_cloud","num":181,"pnum":36,"page":45,"type":"single","stem":"下列不属于华为云 PaaS 中间件服务的是？","options":[["A","DMS"],["B","DCS"],["C","RDS"],["D","DDM"]],"answer":["C"],"ans_raw":"C","explain":"华为云把 DMS（消息）、DCS（缓存）、DDM（分布式数据库中间件）归入中间件类目，而 RDS 交付的是关系型数据库实例，属独立的云服务分类，故选 C。易错在 D：DDM 名称带“数据库”，但它只做分片路由与访问代理，定位仍是中间件而非数据库本身。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-182","subject":"hcip_cloud","num":182,"pnum":37,"page":45,"type":"judge","stem":"华为云中间件 DCS 可以满足用户高读写性能及快速数据访问的业务诉求，但对主流缓存引擎（Redis、Memcached、Ignite）兼容性不够。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。DCS 的卖点恰恰是对主流缓存引擎的兼容：提供 Redis、Memcached 等社区版本并保持协议兼容，应用几乎不改代码即可接入，“兼容性不够”与产品定位相反。高读写性能、快速数据访问这半句成立，题目把后半句写反，判错依据即在此。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-183","subject":"hcip_cloud","num":183,"pnum":38,"page":45,"type":"single","stem":"下列哪些场景属于 DCS 典型应用场景？","options":[["A","社交应用的事件缓存"],["B","用户登录信息"],["C","静态页面"],["D","推送通知"]],"answer":["B"],"ans_raw":"B","explain":"DCS 是内存级高速读写，用户登录信息与 session 缓存正是典型场景，故选 B。静态页面应由对象存储加 CDN 分发；推送通知走消息通道；社交应用的事件类数据以消息流方式处理，属 DMS 场景，A 是最易误选的干扰项，看清“事件”二字即知不是缓存。","note":"","flag":"options-B-D-on-p046","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-184","subject":"hcip_cloud","num":184,"pnum":39,"page":46,"type":"multi","stem":"下列哪些场景属于 DMS 典型应用场景？","options":[["A","处理用户上传任务"],["B","报告生成"],["C","日志传输"],["D","推送通知"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"DMS 用消息队列做异步解耦与削峰：用户上传任务入队由后台消费（A）、报告生成等耗时作业异步化（B）、日志与指标的传输管道（C）、推送通知的分发缓冲（D）皆为其场景。判断依据是任务能否用“生产—消费”模型异步化，四项都符合，无干扰项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-185","subject":"hcip_cloud","num":185,"pnum":40,"page":46,"type":"judge","stem":"DDM 作为 RDS 后端的分布式数据库访问服务，通过读写分离和数据分片的技术可以承受 PB 级数据量、百万级并发量，十倍于单机数据库连接数。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。层次关系写反：DDM 位于应用与 RDS 之间，作为统一访问入口按分片规则把 SQL 路由到后端多个 RDS 实例，是前端中间件而非“RDS 后端”的服务。读写分离、数据分片以及海量数据与高并发的能力表述本身成立，本题错点只在架构位置。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-186","subject":"hcip_cloud","num":186,"pnum":41,"page":46,"type":"multi","stem":"下列哪些场景属于 DDM 典型应用场景？","options":[["A","社交网站好友关系数据"],["B","社交应用的聊天数据"],["C","互联网用户信息"],["D","短信验证码"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"DDM 面向需要分库分表的海量关系型数据：好友关系、聊天数据、互联网用户信息按维度水平拆分后落在多个 RDS 实例，正是其场景，故选 ABC。D 是最易误选项：短信验证码生命周期短、要求极低时延与自动过期，属 DCS 缓存场景，不需要分布式数据库。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-187","subject":"hcip_cloud","num":187,"pnum":42,"page":46,"type":"judge","stem":"在应用改造上云过程中可以使用 DDM 中间件来代替原应用中的 Redis 服务。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。DDM 兼容 MySQL 协议，替代的是自建分库分表方案，后端仍接关系型数据库；Redis 是键值缓存，对应替代服务是 DCS。判据看协议与数据模型：应用调用的是 Redis 接口，迁到 DDM 根本无法运行，两者不在同一层。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-188","subject":"hcip_cloud","num":188,"pnum":43,"page":47,"type":"judge","stem":"使用云服务中间件改造应用，都需要改动大量代码，改造成本非常高。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。“都需要改动大量代码”过于绝对：DCS 兼容 Redis、Memcached 协议，通常只替换连接地址与鉴权；DDM 兼容 MySQL 协议，改造集中在少数受限 SQL；只有 DMS 需替换消息收发接口。改造量取决于云服务与原实现的协议兼容度，不能一概而论。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-189","subject":"hcip_cloud","num":189,"pnum":44,"page":47,"type":"judge","stem":"自建组件与使用云服务对比，云服务更加易用、可靠并且免维护。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。托管云服务把部署、扩容、备份恢复、故障切换与补丁升级交给平台，用户免去自建高可用设计与日常值守，可靠性由多副本和服务等级协议兜底。判据是运维责任边界：自建要承担全部环节，用云服务只保留应用层运维。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-190","subject":"hcip_cloud","num":190,"pnum":45,"page":47,"type":"single","stem":"以下哪种华为云中间件服务可解决业务应用的异步消息解耦问题？","options":[["A","RDS： 关系数据库服务"],["B","DDM： 分布式数据库服务"],["C","DMS： 分布式消息服务"],["D","DCS： 分布式缓存服务"]],"answer":["C"],"ans_raw":"C","explain":"异步解耦是消息中间件的职责，DMS 提供 Kafka、RabbitMQ 等实例，生产方投递后立即返回，消费方按自身节奏处理，两侧互不感知，故选 C。RDS 与 DDM 解决数据持久化与分片访问，DCS 只做内存缓存，三者都不具备可靠投递语义，无法替代队列。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-191","subject":"hcip_cloud","num":191,"pnum":46,"page":47,"type":"multi","stem":"以下哪些属于华为 DCS 服务的关键特性？","options":[["A","标准规格：支持单机、主备两种模式"],["B","弹性扩容：一键弹性扩容，对业务透明，业务无感知"],["C","数据可靠：数据持久化和备份恢复确保数据高可靠"],["D","自主运维：预提供大量监控指标，支持自定义监控阈值和告警策略"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"BCD 均为 DCS 关键特性：一键弹性扩容对业务透明无感知，数据持久化与备份恢复保证可靠，预置大量监控指标并支持自定义阈值与告警。A 错在把规格说成只有单机与主备两种：实际还提供集群实例与读写分离等形态，属以偏概全，选型时看形态是否被截小。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-192","subject":"hcip_cloud","num":192,"pnum":47,"page":47,"type":"judge","stem":"一台 ECS 虚机只能运行一个容器。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。ECS 只是一台虚拟机，装上 Docker 引擎后即可运行多个相互隔离的容器，它们共享宿主内核；K8s 节点乃至 CCE 节点上更是同时运行多个 Pod 的容器。判据是容器为进程级隔离而非整机绑定，可运行数量受资源限制，不存在一台一个的约束。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-193","subject":"hcip_cloud","num":193,"pnum":48,"page":48,"type":"single","stem":"以下关于 Kubernetes 的描述错误的有？","options":[["A","Kubernetes 是 Google 开源的容器集群管理系统，构建在 Docker 技术之上"],["B","Kubernetes 无法管理容器的生命周期"],["C","Kubernetes 提供跨节点服务发现和负载均衡"],["D","Kubernetes 的自我修复机制使得容器集群总是运行在用户期望的状态"]],"answer":["B"],"ans_raw":"B","explain":"选 B：管理容器生命周期（创建、拉起、重启、驱逐、销毁）正是 Kubernetes 作为编排系统的核心职责，配合自愈与水平扩缩，“无法管理”与事实相反。A 属早期表述，当前运行时已不限于 Docker；C 的跨节点服务发现与负载均衡、D 的自我修复均正确。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-194","subject":"hcip_cloud","num":194,"pnum":49,"page":48,"type":"judge","stem":"华为 CCE 云容器引擎目前只支持华为 FusionSphere 和开源 OpenStack。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。公有云形态的 CCE 节点由华为云 ECS 与裸金属 BMS 提供，与底层虚拟化平台解耦，并不限于 FusionSphere 和开源 OpenStack；后者只是私有云、混合云场景下的可选底座。判据落在“只支持”这一绝对限定，托管服务不存在这种绑定关系。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-195","subject":"hcip_cloud","num":195,"pnum":50,"page":48,"type":"multi","stem":"以下哪些是华为 CCE 云容器引擎的关键特性？","options":[["A","应用全栈建模"],["B","资源属性描述"],["C","资源调度算法"],["D","跨 IaaS 层资源管理"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"个人觉得是 ABCD 关键特性：1、应用全栈建模：基于全栈模型获得应用实例间的关联关系；2、资源属性描述：在资源上进行多维度标签描述，比如标明使用目的；3、资源调度算法：依据应用实例间的关系，确定采用亲和性或是反亲和性进行部署，并将应用实例部署到标签匹配的资源上，保证应用在分布式部署后依然具有高性能，并满足 SLA 要求。4、跨 I 层资源管理：支持 FusionSphere, OpenStack, Vmware, ...","note":"","flag":"checkboxes-mark-ACD-but-red-note-says-ABCD","source":"HCIP-Cloud Service题库.pdf","ex_src":"题源"},{"id":"hcip_cloud-196","subject":"hcip_cloud","num":196,"pnum":51,"page":48,"type":"judge","stem":"裸金属私有集群应用场景下对比虚拟机集群，容器部署密度提升显著。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。裸金属节点没有 hypervisor 与客户机操作系统这两层开销，也不受嵌套虚拟化限制，CPU 与内存可直接留给容器，单节点能规划更多 Pod，部署密度和性能明显优于虚拟机集群。判据是收益来自省去虚拟化损耗，而非凭空增加资源规格。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-197","subject":"hcip_cloud","num":197,"pnum":52,"page":48,"type":"multi","stem":"以下哪些属于华为 CCE 的应用场景？","options":[["A","有状态容器应用"],["B","无状态容器应用"],["C","DevOps 持续交付"],["D","自动化运维和高可用"]],"answer":[],"ans_raw":"","explain":"","note":"题源该题未标注答案：选项块为纯文本，无勾选状态也无答案行","flag":"rechecked","source":"HCIP-Cloud Service题库.pdf","ex_src":""},{"id":"hcip_cloud-198","subject":"hcip_cloud","num":198,"pnum":53,"page":49,"type":"judge","stem":"Docker 的资源限制使用的是 Linux 的 Cgroup 特性。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。Docker 对 CPU、内存、IO 的配额与统计由 Linux cgroups 实现，namespace 负责视图隔离，二者共同构成容器的轻量隔离。判据是分工：限制资源用 cgroup，隔离可见性用 namespace，若题干把资源限制归给 namespace 即为错。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-199","subject":"hcip_cloud","num":199,"pnum":54,"page":49,"type":"judge","stem":"华为容器云引擎支持有状态容器应用和无状态容器应用。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。CCE 用 Deployment 等负载运行无状态应用，用 StatefulSet 配合持久卷（PVC、StorageClass 挂载 EVS、SFS 等存储）运行有状态应用，并提供稳定网络标识与有序部署升级，两类负载都受支持，判据在于有无持久卷与稳定标识能力。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-200","subject":"hcip_cloud","num":200,"pnum":55,"page":49,"type":"single","stem":"以下哪个不属于华为 CCE 为有状态容器提供的服务优势？","options":[["A","数据持久化存储"],["B","支持一种存储类型"],["C","多个实例可共享存储"],["D","容器实例故障或迁移时，数据不丢失"]],"answer":["B"],"ans_raw":"B","explain":"B 不成立：CCE 为有状态容器提供多种存储类型而非一种，可通过 PV/PVC 挂载 EVS 云硬盘、SFS 共享文件系统等后端。A 数据持久化、C 多实例共享存储、D 实例故障或迁移后数据不丢失，都是持久卷随实例漂移带来的优势，与“只支持一种”直接矛盾。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-201","subject":"hcip_cloud","num":201,"pnum":56,"page":49,"type":"single","stem":"发布基于 Docker 的容器应用，包含应用构建、配置信息的部件是什么？","options":[["A","Docker image"],["B","Docker registry"],["C","Dockerfile"],["D","Docker Hub"]],"answer":["C"],"ans_raw":"C","explain":"Dockerfile 用文本指令记录基础镜像、构建步骤以及端口、环境变量等运行配置，docker build 依它产出镜像，因此承载构建与配置信息的部件是 C。镜像（A）是构建结果，registry 与 Docker Hub（B、D）只负责存储和分发，都不描述构建过程。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-202","subject":"hcip_cloud","num":202,"pnum":57,"page":50,"type":"multi","stem":"以下哪些属于云容器引擎适用的场景？","options":[["A","传统 IT 架构渐进式转型的场景"],["B","业务负荷有明显波动的场景"],["C","降低资源成本的场景"],["D","提升业务上线效率的场景"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都是 CCE 的典型场景：以容器为切入点渐进改造传统 IT 架构（A）；负荷波动时按策略自动扩缩（B）；提高资源利用率从而摊薄成本（C）；镜像加编排加快发布节奏、提升上线效率（D）。易漏 A，容器不只用于新建系统，也可与虚机应用并存分期迁移。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-203","subject":"hcip_cloud","num":203,"pnum":58,"page":50,"type":"judge","stem":"华为微服务引擎 CSE 的功能包括微服务运维生命周期管理。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。CSE 的功能项是服务注册与发现、配置管理、治理规则与监控，面向已经运行的服务；“生命周期管理”是 ServiceStage 平台层的目标表述，且运维只是其中一个阶段。把“运维生命周期管理”列为 CSE 功能，范围与层级双重错置，故判错。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-204","subject":"hcip_cloud","num":204,"pnum":59,"page":50,"type":"multi","stem":"华为微服务引擎 CSE 的主要模块有哪些？","options":[["A","微服务管理中心"],["B","一致性管理"],["C","API Gateway"],["D","服务配置中心"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"CSE 由微服务管理中心（注册与元数据）、一致性管理（一致性哈希路由与负载均衡）、服务配置中心三部分构成，故选 ABD。C 的 API Gateway 是华为云独立的 API 网关产品，属南北向流量入口，不在 CSE 模块清单内；它常与微服务搭配，因此最易误选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-205","subject":"hcip_cloud","num":205,"pnum":60,"page":50,"type":"judge","stem":"Service Mesh 支持将遗留系统或其他语言微服务接入分布式环境，对业务代码零侵入，并支持多种开发语言。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。Service Mesh 把治理逻辑下沉到 sidecar 代理，由数据面承担通信、路由与可观测，业务代码无需引入框架 SDK，因而零侵入并天然支持多语言，遗留系统只要暴露服务端口即可接入分布式环境。判据：若说需改造代码或仅限单一语言即为错。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-206","subject":"hcip_cloud","num":206,"pnum":61,"page":50,"type":"single","stem":"下述哪项是微服务引擎 CSE 的目标？","options":[["A","微服务开发生命周期管理"],["B","微服务全生命周期管理"],["C","微服务上线生命周期管理"],["D","微服务运维生命周期管理"]],"answer":["B"],"ans_raw":"B","explain":"CSE 面向微服务从开发、部署、治理到监控运维的完整过程，目标是全生命周期管理，故选 B。A 只覆盖开发、C 只覆盖上线、D 只覆盖运维，都只是生命周期中的一段，属以偏概全。判据即范围完整性，另需注意它与 203 的区别：目标不等于功能清单。","note":"","flag":"options-B-D-on-p051","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-207","subject":"hcip_cloud","num":207,"pnum":62,"page":51,"type":"single","stem":"某票务网站进行大促销时，由于瞬间访问量巨大，网站容易瘫痪。为了应对流量洪峰，以下哪种微服务治理方法能够有效对应该场景，防止系统过载崩溃？","options":[["A","限流"],["B","负载均衡"],["C","熔断"],["D","容灾"]],"answer":["A"],"ans_raw":"A","explain":"洪峰要守住的是入口请求速率，限流按阈值拒绝或排队超出部分，防止线程与连接被打满，故选 A。负载均衡只是把请求分摊到既有实例，总容量不足时无效；熔断针对下游故障快速失败、防雪崩，不解决上游过载；容灾是地域级故障切换，与瞬时高流量无关。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-208","subject":"hcip_cloud","num":208,"pnum":63,"page":51,"type":"multi","stem":"微服务引擎 CSE 支持的部署方式有哪些？","options":[["A","手动部署"],["B","自动部署到第三方云平台"],["C","流水线式一键部署"],["D","基于 AOS 应用编排部署"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"CSE 侧提供的部署方式包括手动部署、流水线式一键部署和基于 AOS 模板的应用编排部署，故选 ACD。B 不成立：引擎与治理面部署在华为云，产品不提供把微服务自动部署到第三方云平台的能力，跨云需自行迁移，别与混合云、多云协同的管理能力混为一谈。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-209","subject":"hcip_cloud","num":209,"pnum":64,"page":51,"type":"multi","stem":"微服务架构将面临哪些挑战？","options":[["A","交付周期不可避免的延长"],["B","分布式系统，复杂性高"],["C","分区数据库架构，数据一致性难以保证"],["D","服务间关联增多，运维复杂度增加"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"微服务引入的挑战是分布式系统复杂性高（B）、分区数据库下数据一致性难以保证（C）、服务间关联增多导致调用链与运维复杂度上升（D）。A 说反了：小团队独立开发与并行发布的价值主张正是缩短交付周期，把它写成挑战即为干扰项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-210","subject":"hcip_cloud","num":210,"pnum":65,"page":51,"type":"single","stem":"在华为云应用运维的拓扑图上，不同的颜色代表该实例的健康程度，颜色由Apdex 值决定。如果实例颜色是灰色，它代表什么？","options":[["A","该实例正常"],["B","该实例未被其它应用调用"],["C","该实例亚健康"],["D","该服务所有实例都有故障"]],"answer":["B"],"ans_raw":"B","explain":"拓扑图颜色由 Apdex 值映射健康度，没有调用数据就无法计算该评分，因此显示灰色，选 B。正常与亚健康都要有有效评分才有颜色（A、C 不成立）；实例故障会表现为偏红的差评级别，而非灰色（D 不成立）。判据：灰是缺数据，红才是出问题。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-211","subject":"hcip_cloud","num":211,"pnum":66,"page":52,"type":"multi","stem":"华为云立体化运维的目标是全方位掌控系统的运行状态，并快速的响应各类问题，具体体现在以下哪些方面？","options":[["A","只关注 PaaS 层应用的运行状态"],["B","监控 IaaS 层"],["C","掌握 PaaS 上部署的应用的运行状态，支持故障及性能问题的追踪"],["D","度量分析用户端到端的体验"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"立体化运维强调自下而上打通：监控 IaaS 资源层（B）、掌握 PaaS 上应用运行状态并追踪故障与性能问题（C）、度量分析端到端用户体验（D）。A 的“只关注 PaaS 层”把范围收缩到单层，恰与“立体化”矛盾，因日常操作集中在应用层而最易误选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-212","subject":"hcip_cloud","num":212,"pnum":67,"page":52,"type":"judge","stem":"使用华为云应用运维服务的日志功能，运维人员无需登录集群中的节点上去下载日志，可以在线查看并精确搜索日志来定位问题。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。日志由采集 Agent 统一上报、集中存储，控制台可按关键字、时间、实例过滤检索并查看上下文，运维无需登录集群节点下载日志。判据是“采集—集中存储—在线检索”这条链路；若说必须登录节点或只能看实时输出即为错。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-213","subject":"hcip_cloud","num":213,"pnum":68,"page":52,"type":"judge","stem":"APM 非侵入式数据采集的探针技术是被动式监控，不消耗 CPU 和内存。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。非侵入指的是不改业务源代码，Agent 仍需注入进程并做字节码增强，采集与上报必然消耗 CPU 与内存，只是开销可控。被动式监控的说法可接受，但“不消耗 CPU 和内存”绝对化，判据在于探针运行在业务进程内就要占用资源。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-214","subject":"hcip_cloud","num":214,"pnum":69,"page":52,"type":"single","stem":"在华为云应用运维的拓扑图上，如下图箭头部分所示，圆圈被分为三段，但三段的长短不一样，这是什么含义？","options":[["A","监控到三个故障"],["B","有三个 Tomcat 实例，但实例间的负载不均衡"],["C","该微服务被调用了三次"],["D","该服务所有实例都有故障，故障数不同"]],"answer":["B"],"ans_raw":"B","explain":"（题干不全）题目依赖未提供的拓扑图截图，也未给出图例说明，仅凭文字无法确认圆圈分段的官方含义。按华为云 APM 拓扑图的一般图例，一个服务圆圈被分成段数不等的几段，表示其下多个实例及各自承接的调用量占比，长短不一即负载不均衡，与 B 对应。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-215","subject":"hcip_cloud","num":215,"pnum":71,"page":53,"type":"multi","stem":"以下哪些是华为云 APM(应用性能管理服务)的应用场景？","options":[["A","透过 Apdex 数值来剖析事务状态"],["B","通过拓扑图来掌握应用健康状况"],["C","通过调用链来追踪问题根因"],["D","使用模板来一键式将应用部署到云上"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"ABC 是 APM 的场景：用 Apdex 数值剖析事务状态与用户满意度、用拓扑图掌握应用与依赖的健康状况、用调用链追踪慢调用与故障根因。D 属部署能力，由 AOS 模板或 ServiceStage 流水线完成，APM 只观测不部署，是易混干扰项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-216","subject":"hcip_cloud","num":216,"pnum":72,"page":54,"type":"judge","stem":"单体应用可以使用中间件。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。中间件如 DCS 缓存、DMS 消息、RDS 数据库都是独立部署的基础能力，任何架构风格都能接入，单体应用同样用它们做削峰、缓存与持久化。判据：是否使用中间件与架构拆分粒度无关，微服务只是让治理更细，并非使用中间件的前提。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-217","subject":"hcip_cloud","num":217,"pnum":73,"page":54,"type":"judge","stem":"基于应用编排服务（AOS）可以实现应用的自动化运维。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。AOS 的职能是应用编排与自动化部署，用模板定义资源拓扑并按依赖顺序一次拉起环境，属“建”的能力；自动化运维指运行期的监控、告警、日志与故障处理，由 AOM、APM 等承担。判据在部署与运维的分工，别因资源自动创建就判成自动化运维。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-218","subject":"hcip_cloud","num":218,"pnum":74,"page":54,"type":"judge","stem":"在 Kubernetes 中一个 Pod 可以包含多个容器。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。Pod 是 Kubernetes 的最小调度单位，可以由多个共享网络命名空间与存储卷的容器组成，典型形态是主容器加日志收集或代理 sidecar。判据：同 Pod 内容器可通过 localhost 互访、被一起调度到同一节点，若说只能有一个容器即为错。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-219","subject":"hcip_cloud","num":219,"pnum":75,"page":54,"type":"judge","stem":"应用向云原生（CloudNative）模式演进，微服务是 CloudNative 的事实标准。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。云原生通常概括为微服务、容器、DevOps 与持续交付四要素，其中微服务是应用拆分与独立发布的架构基础，容器和 K8s 提供运行底座，业界演进普遍以微服务作为落地标准。判据：若只容器化而不做服务拆分，仍无法独立迭代，该表述因此成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-220","subject":"hcip_cloud","num":220,"pnum":76,"page":54,"type":"judge","stem":"使用华为云应用运维服务的日志查询功能分析问题，只能在操作界面上查看应用日志，无法将日志导出到本地查看。","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。日志在线检索的同时支持下载导出到本地，也可转储到对象存储做长期归档再用本地工具分析。判据在于日志已被集中存储，天然具备导出与转储能力，“只能看不能导出”与实际功能相反，这类“只能”限定通常即为错点。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-221","subject":"hcip_cloud","num":221,"pnum":77,"page":54,"type":"judge","stem":"微服务云应用平台（ServiceStage）中的 AOS（应用编排服务）能够一键式完成复杂的分布式系统的部署。","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。AOS 用模板描述云资源与部署拓扑，自动创建资源并按依赖顺序编排各组件，一次提交即可拉起整套多节点分布式系统。判据：一键式指的是编排自动化，不涉及运行期故障自愈；若题干把这能力说成自动化运维，则应判错（参见 217）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-222","subject":"hcip_cloud","num":222,"pnum":79,"page":55,"type":"single","stem":"以下哪项服务不属于华为云 PaaS 服务？","options":[["A","微服务云应用平台 ServiceStage"],["B","弹性云服务器 ECS"],["C","云容器引擎 CCE"],["D","云性能测试服务 CPTS"]],"answer":["B"],"ans_raw":"B","explain":"ECS 交付的是虚拟机算力，属 IaaS 计算服务，不在 PaaS 范畴，故选 B。ServiceStage 提供应用平台、CCE 提供容器编排、CPTS 提供性能测试，都面向应用的构建、运行与治理。判据是交付对象：给资源的是 IaaS，给应用支撑能力的是 PaaS。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-223","subject":"hcip_cloud","num":223,"pnum":80,"page":55,"type":"single","stem":"当业务不需要缓存的高可用性，并且希望较低成本时，此时应该为应用选择以下哪种类型的华为云分布式缓存 DCS 服务？","options":[["A","单机"],["B","主备"],["C","集群"],["D","以上都不对"]],"answer":["A"],"ans_raw":"A","explain":"单机模式只有一份数据、无副本与故障自动切换，成本最低，适合缓存内容可随时回源重建、不追求高可用的场景，故选 A。主备与集群都以副本或多分片换可用性，费用相应更高（B、C）；D 不成立，单机确为可选规格形态之一，判据是可用性与成本的取舍。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-224","subject":"hcip_cloud","num":224,"pnum":81,"page":55,"type":"single","stem":"华为云分布式数据库中间件 DDM 服务是作为（）前置的分布式数据访问服务。","options":[["A","DCS"],["B","DMS"],["C","RDS"],["D","Oracle"]],"answer":["C"],"ans_raw":"C","explain":"DDM（分布式数据库中间件）的定位就是 RDS 的前置访问层：应用只连 DDM，由它把 SQL 按分片规则路由到后端多个 RDS 实例，分库分表与读写分离对应用透明，故选 C。DCS 是缓存、DMS 是消息队列，都不提供 SQL 接入语义；Oracle 不在 DDM 后端支持的数据库范围内。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-225","subject":"hcip_cloud","num":225,"pnum":84,"page":56,"type":"single","stem":"如果从零开始开发一个基于华为 CSE Java SDK 的微服务，推荐使用哪种方式创建微服务？","options":[["A","本地开发后迁移到云"],["B","流水线"],["C","云上工程"],["D","Service Mesher 方式"]],"answer":["C"],"ans_raw":"C","explain":"从零开发并要接入华为云服务中心时，推荐在 CSE 侧创建云上工程：脚手架自带 Java SDK 依赖、注册中心地址与鉴权配置，下载即可编译运行，故选 C。本地开发后再迁移需自行补齐这些配置；流水线只负责构建部署、不生成工程；Service Mesher 面向存量与多语言服务的零侵入接入，不是新建工程的手段。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-226","subject":"hcip_cloud","num":226,"pnum":88,"page":57,"type":"multi","stem":"华为 CCE 为有状态容器提供的服务的优势是？","options":[["A","数据持久化存储"],["B","多实例数据共享"],["C","支持一种存储类型"],["D","容器实例故障或迁移时，数据不丢失"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"有状态容器的关键在存储：CCE 通过 PV/PVC 挂载 EVS、OBS、SFS 等实现数据持久化（A），多个实例可挂同一存储卷支撑数据共享（B），容器重建或节点迁移后数据仍在（D）。C 与事实相反——支持的存储类型是多种而非一种，这正是排除它的依据。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-227","subject":"hcip_cloud","num":227,"pnum":90,"page":58,"type":"multi","stem":"下面哪些是华为云的立体化运维解决方案的组成部分？","options":[["A","基础设施层运维"],["B","应用层运维"],["C","应用性能管理"],["D","业务分析"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"立体化运维按层次打通：基础设施层用主机与资源监控掌握 ECS、节点水位（A）；应用层用 AOM 管日志、指标与告警（B）；APM 负责调用链与性能剖析（C）；业务分析把技术指标映射到业务指标（D）。四层齐备才称“立体”，任一缺失都退化为单点监控，故全选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-228","subject":"hcip_cloud","num":228,"pnum":109,"page":62,"type":"multi","stem":"CCE 优势包括？","options":[["A","多样的生态接入"],["B","增强的商用化特性"],["C","完全开放的原生平台"],["D","高性能基础设施"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"此四项即 CCE 对外列举的优势：完全开放的原生平台，兼容社区 Kubernetes API 不锁定；高性能基础设施，含裸金属与容器网络；增强的商用化特性，即托管带来的可靠性、安全与运维增强；多样的生态接入，如镜像仓库、编排模板与工具链。故全选，最易漏 B，它恰是自建集群的补集。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-229","subject":"hcip_cloud","num":229,"pnum":110,"page":62,"type":"multi","stem":"CCE 适用的场景包括？","options":[["A","传统 IT 架构渐进式转型的场景"],["B","提升业务上线效率的场景"],["C","业务负荷有明显波动的场景"],["D","降低资源成本的场景"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都能对应到容器的一项核心能力：以容器为切入点与传统应用并存、分期迁移，支撑渐进转型（A）；镜像加编排缩短发布节奏（B）；按策略自动扩缩副本应对波动负载（C）；提升部署密度与复用率从而降本（D）。故全选，易漏 A，容器不只用于新建系统。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-230","subject":"hcip_cloud","num":230,"pnum":111,"page":63,"type":"judge","stem":"华为容器云支持节点亲和、反亲和，支持应用的亲和、反亲和。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据是 CCE 沿用并增强 Kubernetes 的调度语义：节点层面有 nodeAffinity 与节点反亲和，决定 Pod 能落到哪些节点；应用层面有 Pod 亲和与反亲和，决定业务实例彼此聚集还是打散。两类亲和与反亲和同时具备，题干成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-231","subject":"hcip_cloud","num":231,"pnum":112,"page":63,"type":"single","stem":"下列哪项不是容器的优势","options":[["A","通过共享 kernel，细粒度资源隔离"],["B","定义了环境无关的标准的交付、部署规范"],["C","利用 Hypervisor 实现对硬件资源更有效的利用"],["D","秒级快速启动和停止"]],"answer":["C"],"ans_raw":"C","explain":"容器共享宿主机内核，靠 namespace 隔离、cgroup 限额，并不经过 Hypervisor；用 Hypervisor 提升硬件利用率是虚拟机的机制，故选 C 作为“非容器优势”。A 共享内核与细粒度隔离、B 标准化交付部署规范、D 秒级启停，都是容器的公认优势。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-232","subject":"hcip_cloud","num":232,"pnum":113,"page":63,"type":"multi","stem":"容器编排工具包括？","options":[["A","Marathon"],["B","Kubernetes"],["C","Neutron"],["D","Horizon"]],"answer":["A","B"],"ans_raw":"AB","explain":"Marathon（Mesos 上的容器编排框架）与 Kubernetes 都负责多容器的部署、调度与自愈，故选 AB。Neutron 是 OpenStack 的网络组件，Horizon 是 OpenStack 的 Web 控制台，二者同属云基础设施而不编排容器，是最易混淆的一项——它们与容器生态无关。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-233","subject":"hcip_cloud","num":233,"pnum":1,"page":64,"type":"multi","stem":"微服务云应用平台（ServiceStage），可以完成以下哪些功能？","options":[["A","容器应用需要自己在 ServiceStage 上搭建容器管理平台，比如需自己搭建 kubernetes 管理 docker 容器应用"],["B","创建应用依赖计算资源"],["C","在线可视化升级应用"],["D","使用 AOS 模板自动化应用编排"],["E","查看应用各项指标"]],"answer":["A","C","D","E"],"ans_raw":"ACDE","explain":"（存疑）A 与 ServiceStage 现行行为不符：容器应用可直接对接托管的 CCE 集群，并不需要用户自行搭建 Kubernetes 管理平台，把它列为“可完成的功能”不成立。B 创建应用依赖的计算资源、C 在线可视化升级、D 用 AOS 模板编排、E 查看应用指标均为其能力，按官方口径应为 BCDE，建议复核。","note":"我认为应该是ABCDE","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-234","subject":"hcip_cloud","num":234,"pnum":2,"page":65,"type":"judge","stem":"微服务云应用平台（ServiceStage）中的 AOS（应用编排服务）能够一键式完成复杂的分布式系统的部署。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在于“模板加自动化编排”：AOS 用声明式模板描述 ECS、网络、中间件等资源及其依赖关系与创建顺序，一次提交即按序建好整套拓扑并自动配置，因而能一键部署复杂分布式系统，而不是靠人工逐个购买资源拼装。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-235","subject":"hcip_cloud","num":235,"pnum":4,"page":65,"type":"judge","stem":"TP99 时延即满足百分之九十九的网络请求所需要的最低耗时。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"对。TP99 是第 99 百分位耗时，含义是 99% 的请求耗时都不超过它，反过来即“能覆盖 99% 请求所需的最低耗时门槛”，题干与此一致，故选 B（本题 B 才是“正确”）。别混淆两点：TP99 不是平均值，也不是最大值，它允许 1% 的请求超出。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-236","subject":"hcip_cloud","num":236,"pnum":5,"page":65,"type":"single","stem":"在华为云应用运维的拓扑图上，不同的颜色代表该实例的健康程度，颜色由Apdex 值决定，Apdex 值越接近 1，表示应用越健康，若一个应用实例未被其它应用调用，则其颜色为：","options":[["A","灰色"],["B","黄色"],["C","绿色"],["D","红色"]],"answer":["A"],"ans_raw":"A","explain":"拓扑图配色由 Apdex 决定，而 Apdex 需要被调用的响应时间样本；实例未被其它应用调用就没有样本，Apdex 无法计算，此时以灰色表示“无数据”，故选 A。黄、绿、红分别对应已算出的分档（一般、健康、较差），未被调用的实例不可能落到这三色上。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-237","subject":"hcip_cloud","num":237,"pnum":6,"page":66,"type":"single","stem":"Apdex 全称是 Application Performance Index。是由 Apdex 联盟开发的用于评估应用性能的工业标准。Apdex 标准从用户的角度出发，将对应用响应时间的表现转为用户对于应用性能的范围为 0-1 的满意度评价。若 0.3<=Apdex<=0.75，以下说法哪个正确？","options":[["A","用户体验较差"],["B","无法确定用户体验好坏"],["C","用户体验一般"],["D","用户体验较满意"]],"answer":["C"],"ans_raw":"C","explain":"APM 按 Apdex 分档评估体验：越接近 1 越满意，0.3 到 0.75 落在中间档即“一般”，低于 0.3 为较差，故选 C。A 把下界区间当成了本档；B 不成立——Apdex 本身就是把响应时间折算成 0 到 1 的可比较满意度值，存在即能判定好坏。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-238","subject":"hcip_cloud","num":238,"pnum":7,"page":66,"type":"multi","stem":"以下哪些是华为云 APM（应用性能管理服务）的应用场景？","options":[["A","通过调用链来追踪问题根因"],["B","透过 Apdex 数值来剖析事物状态"],["C","通过拓扑图来掌握应用健康状况"],["D","使用模板来一键式将应用部署到云上"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"APM 只做观测不做交付：拓扑图掌握应用健康状况（C）、调用链追踪问题根因（A）、Apdex 量化体验与事务状态（B），三项均属其场景，故选 ABC。D 的一键部署属 AOS 与 ServiceStage 的编排能力，是最常见的张冠李戴项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-239","subject":"hcip_cloud","num":239,"pnum":8,"page":66,"type":"judge","stem":"华为云应用性能管理服务使用字节码增强技术实现非侵入式采集用户应用的性能指标数据，用户在华为云上部署了一个 C 语言开发的应用，也可以用华为云应用性能管理服务来分析其性能问题。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）字节码增强依赖 JVM 里存在字节码，这一手段只对 Java 应用成立，题干前半句对、后半句推不出。C 语言编译为机器码、没有字节码可增强，无法用同一探针做代码级链路分析，需自行上报数据或改用其它观测方式，按此判据应选 B（错误），建议复核。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-240","subject":"hcip_cloud","num":240,"pnum":9,"page":66,"type":"single","stem":"如图所示，华为云APM的拓扑图是对应用间调用关系和依赖关系的可视化展示。使用拓扑图能够直观地查看应用的运行状态。下列哪项说法是错误的？","options":[["A","拓扑图上每个圆圈代表一个应用，圆圈中的数字“1/1”表示该应用有两个实例、一个正常、一个异常。"],["B","圆圈的颜色为绿色，表示该应用的状态为健康。"],["C","拓扑图上圆圈Vmall-apigw-service到圆圈Vmall-user-service之间的红色虚线箭头线表示应用Vmall-apigw-service调用应用Vmall-user-service请求状态很差，由于时延导致。"]],"answer":["A"],"ans_raw":"A","explain":"（题干不全）题图未给出，连线颜色与圆圈数字无法核对。仅就选项文本可判：拓扑图圆圈中的“1/1”是“正常实例数/总实例数”，表示单实例且正常，并非“两个实例一正常一异常”，故 A 说法错误、为本题答案。B 绿色表示健康符合配色；C 究竟是时延还是错误率所致须看图中调用详情。","note":"屏幕翻拍题：原图只拍到 3 个选项（缺 D），答案按单选按钮判读","flag":"rechecked","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-241","subject":"hcip_cloud","num":241,"pnum":10,"page":67,"type":"single","stem":"华为云APM的事务表示一个从“用户请求 > webserver > DB > webserver > 用户请求”的完整过程，通常表现为一个 HTTP 请求。现实生活中，电商应用中一次商品的查询就是一个事务，如下图中一个应用运维的事务页面，哪些说法是错误的？","options":[["A","点击动作列的图标可以跳转至拓扑图"],["B","事务“用户注册”的Apdex值为0.5，最可能的原因是该事务整体时延太长"],["C","事务“购买商品”的Apdex值为0.72，最可能的原因是该事务整体时延太长"],["D","只有“查询商品”这个事务的状态为健康"]],"answer":["C"],"ans_raw":"C","explain":"（题干不全）事务清单的数值与状态列来自截图，缺图无法定答。可用方法论：Apdex 高于 0.75 记为健康，0.3 到 0.75 为一般，低于 0.3 为较差；数值偏低既可能因整体时延超出容忍度，也可能由慢调用或失败请求拉低，单凭一个 Apdex 数不能断言“整体时延太长”。请对照原图逐项核对后再判。","note":"屏幕翻拍题：答案按唯一填充的单选按钮判读","flag":"rechecked","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-242","subject":"hcip_cloud","num":242,"pnum":11,"page":68,"type":"single","stem":"应用运维的仪表盘支持展示指标数据和状态数据，对于不同的指标数据根据需要添加不同的图标，如果需要监控变化趋势或多个指标对比。可创建（）：如果需要了解最新数值，可创建（）","options":[["A","柱状图：饼状图"],["B","数字图：曲线图"],["C","曲线图：教字图"],["D","柱状图：数字图"]],"answer":["D"],"ans_raw":"D","explain":"（存疑）AOM 仪表盘中用于观察变化趋势并支持多指标对比的是曲线图，展示最新数值的是数字图，故第一空应为曲线图，即选项 C（“教字图”为“数字图”的识别缺字）。柱状图擅长分档与区间比较、难以呈现时间趋势，给定 D 的第一空不成立，建议复核。","note":"答案应该是C","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-243","subject":"hcip_cloud","num":243,"pnum":12,"page":68,"type":"single","stem":"以下哪项为 CSE 微服务开发框架为支持开发者使用 SpringlVC 风格开发微服务而提供的注解？","options":[["A","RestScheme"],["B","RestTempl ate"],["C","RestController-"],["D","RpeSchema"]],"answer":["A"],"ans_raw":"A","explain":"CSE/ServiceComb 为 REST（Spring MVC 风格）编程模型提供的契约注解是 @RestSchema（选项 A 的 RestScheme 为识别缺字），标注在 POJO 上声明服务契约，故选 A。RestTemplate 是 Spring 的 HTTP 客户端类而非注解；@RpcSchema 属 RPC 高性能风格；@RestController 是 Spring 原生注解，不是 CSE 专门提供的。","note":"应该是RestSchema","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-244","subject":"hcip_cloud","num":244,"pnum":13,"page":68,"type":"single","stem":"在微服务实战指导中，以下示意图中的哪个微服务可以使用灰度发布？","options":[["A","weather"],["B","forecast"],["C","weathermapweb"],["D","fusionweather"]],"answer":["A"],"ans_raw":"A","explain":"（题干不全）能否灰度取决于示意图中各组件的实例数与流量入口，图未给出，不宜凭组件名猜测。判据：组件须无状态、多实例部署，且流量经 ELB 或服务中心治理路由，才具备新旧版本按比例分流、逐步放量的条件。请对照原图确认哪个组件被标注为多实例并接入负载均衡。","note":"","flag":"screenshot-question; radio-marked option weather","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-245","subject":"hcip_cloud","num":245,"pnum":14,"page":70,"type":"single","stem":"微服务实战指导中，本地启动服务前需要配置什么信息以使微服务成功注册到华为云上的服务中心？","options":[["A","配置中心地址"],["B","handler"],["C","监控中心地址"],["D","AK/SK 等认证信息"]],"answer":["D"],"ans_raw":"D","explain":"服务中心开启鉴权后，本地进程必须以租户身份注册，需要配置 AK/SK 等认证信息（连同注册中心地址、project 等），否则注册请求被拒绝，故选 D。配置中心地址只影响配置下发，不是注册前提；handler 是过滤器链配置；监控中心地址只关系到指标上报，与注册无关。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-246","subject":"hcip_cloud","num":246,"pnum":15,"page":70,"type":"single","stem":"随着互联网业务的极速增长，应用架构也随之不断变迁，请问以下哪种在应用架构的变迁中未提及？","options":[["A","SOA 架构"],["B","单体架构"],["C","微服务架构"],["D","原子架构"]],"answer":["D"],"ans_raw":"D","explain":"应用架构演进主线是单体架构、SOA 架构、微服务架构三段，故选 D 原子架构，它不是被承认的架构阶段，属生造名词。记忆动因：单体难扩展、SOA 依赖集中式总线过于笨重，微服务以去中心化通信与独立部署解决二者痛点。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-247","subject":"hcip_cloud","num":247,"pnum":17,"page":71,"type":"multi","stem":"微服务引擎 CSE 提供了一系列配套的开发工具，包含下述哪些？","options":[["A","微服务流水线"],["B","本地/云上工程"],["C","测试管理"],["D","本地/远程调试"],["E","代码/文档自动生成"]],"answer":["A","D","E"],"ans_raw":"ADE","explain":"CSE 的配套开发工具聚焦编码与调试：微服务流水线打通构建到部署（A）、本地与远程调试（D）、代码及契约文档自动生成（E）。C 测试管理属 CodeArts 测试服务能力，明显不属 CSE，是最易排除项。B 本地/云上工程通常被归为“创建工程的方式”而非独立工具，本题按列举口径未选，该分界在不同版本文档中有差异，复习时留意。","note":"应该是ABCDE","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-248","subject":"hcip_cloud","num":248,"pnum":18,"page":71,"type":"judge","stem":"Service Mesh 支持将遗留系统或其他语言微服务接入分布式环境，对业务代码零侵入，并支持多种开发语言。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"对（此题选 B 表示“正确”）。判据是治理逻辑的位置：Service Mesh 把它放进与业务同机部署的 sidecar 代理，服务间调用改由代理接管，业务代码不引入框架 SDK，因此遗留系统与其它语言写的服务都能不改代码接入治理网络，多语言与零侵入由此成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-249","subject":"hcip_cloud","num":249,"pnum":19,"page":71,"type":"multi","stem":"Gartner 认为微服务在未来将成为主流，请问哪几项是微服务架构的核心目标？","options":[["A","敏捷开发（devel opment agility）"],["B","灵活部署（deployment flexibility）"],["C","在线追踪（Online Request Tracing）"],["D","精准弹性（precise scalability）"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"Gartner 归纳的微服务三个核心目标是敏捷开发、灵活部署、精准弹性，故选 ABD。C 在线请求追踪属可观测性的具体技术手段，是支撑目标实现的能力而非目标本身。区分口径：目标回答“想要什么”，追踪回答“怎么做到”。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-250","subject":"hcip_cloud","num":250,"pnum":20,"page":72,"type":"single","stem":"微服务开发生命周期管理中，流水线发挥了重要的作用。请问应用开发流水线不支持微服务生命周期哪些环节？","options":[["A","测试"],["B","编码"],["C","部署"],["D","构建"]],"answer":["B"],"ans_raw":"B","explain":"流水线自动化的是编码之后的环节：构建（D）、测试（A）、部署（C），源码在 IDE 中由开发者书写，流水线只拉取提交并驱动后续步骤、不产出代码，故选 B。注意它覆盖编码环节的成果物管理，但编码动作本身不在流水线内。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-251","subject":"hcip_cloud","num":251,"pnum":21,"page":72,"type":"single","stem":"下述哪项是微服务引擎 CSE 的目标？","options":[["A","微服务开发生命周期管理"],["B","微服务上线生命周期管理"],["C","微服务运维生命周期管理"],["D","微服务全生命周期管理"]],"answer":["D"],"ans_raw":"D","explain":"CSE 覆盖微服务从开发、部署、治理到监控运维的完整过程，目标是全生命周期管理，故选 D。A 只取开发、B 只取上线、C 只取运维，均为生命周期的一段，属以偏概全型干扰项。判据就是范围是否完整。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-252","subject":"hcip_cloud","num":252,"pnum":22,"page":72,"type":"multi","stem":"华为云容器引擎支持哪些层面的亲和性与反亲和性？","options":[["A","集群"],["B","节点"],["C","网络"],["D","应用"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四个层面均受支持：集群层面决定工作负载落在哪个集群（多集群与联邦场景），节点层面用节点亲和与反亲和约束落点，应用层面用 Pod 亲和与反亲和控制聚集或打散，网络层面按网络可达性与分布域约束实例，故选 ABCD。易漏 A 与 C，它们只在多集群与网络域场景才显现。","note":"应该是BD","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-253","subject":"hcip_cloud","num":253,"pnum":23,"page":73,"type":"multi","stem":"华为 CCE 云容器引擎可以创建哪些类型的集群？","options":[["A","windows 集群"],["B","虚拟机集群"],["C","AIX 集群"],["D","裸金属集群"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"CCE 可创建基于 ECS 的虚拟机集群（B）、基于裸金属服务器的裸金属集群（D），以及承载 Windows 容器负载的集群（A），故选 ABD。C 的 AIX 是 IBM Power 小型机的专有 Unix，不在华为云容器节点支持的操作系统与处理器架构范围内，故为应选项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-254","subject":"hcip_cloud","num":254,"pnum":24,"page":73,"type":"single","stem":"Kubernetes 中创建、调度、管理的最小单元是什么？","options":[["A","Node"],["B","Pod"],["C","Service"],["D","deployment"]],"answer":["B"],"ans_raw":"B","explain":"Kubernetes 创建、调度与托管的最小单元是 Pod，一个 Pod 内的多个容器共享网络与存储、被一起调度到同一节点，故选 B。Node 是承载 Pod 的机器，Service 提供访问入口与负载均衡，Deployment 管理 Pod 副本数，三者粒度都比 Pod 高一级。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-255","subject":"hcip_cloud","num":255,"pnum":25,"page":73,"type":"single","stem":"下面哪个命令不属于 docker 镜像生命周期的管理范畴？","options":[["A","docker comit"],["B","docker save"],["C","docker exec"],["D","docker build"]],"answer":["C"],"ans_raw":"C","explain":"docker exec 是在已运行的容器内执行命令，属容器运行时操作，不在镜像生命周期管理之内，故选 C。build 产出镜像、commit 由容器固化出新镜像、save 把镜像导出为文件，再加 push/pull/tag/rmi 才构成镜像的构建—分发—清理链条。选项 A 的 comit 即 commit 的识别缺字。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-256","subject":"hcip_cloud","num":256,"pnum":26,"page":73,"type":"single","stem":"docoker 的资源限制使用的是 linux 的以下哪种特性？","options":[["A","namespace"],["B","SELinux"],["C","Cgrou"],["D","aufs"]],"answer":["C"],"ans_raw":"C","explain":"CPU、内存、IO 的配额限制由 Linux cgroup 实现，故选 C（选项 Cgrou 为 cgroup 缺字）。namespace 负责可见性隔离、不设限额；aufs 是镜像分层的联合文件系统；SELinux 属强制访问控制与安全加固。成对记：限制靠 cgroup，隔离靠 namespace。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-257","subject":"hcip_cloud","num":257,"pnum":27,"page":74,"type":"single","stem":"下列哪一种不是访问容器应用的方式？","options":[["A","ELB"],["B","Node Port"],["C","Service"],["D","yPC"]],"answer":["B"],"ans_raw":"B","explain":"（题干不全/存疑）D 选项文本残缺，yPC 疑为 VPC，需原卷核对。就现有信息题给 B 不成立：NodePort 是 Kubernetes 与 CCE 明确支持的暴露方式，在每个节点开端口供外部访问；Service 与 ELB 同样是访问途径。若 D 为 VPC，它只是内部网络隔离、不构成应用访问入口，则本题答案应为 D，建议复核。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-258","subject":"hcip_cloud","num":258,"pnum":28,"page":74,"type":"single","stem":"下面哪项是 CCE 裸金属集群所依赖的 1aasi 算服务？","options":[["A","BIS"],["B","ECS"],["C","EvS"],["D","VPC"]],"answer":["A"],"ans_raw":"A","explain":"（题干不全）题干“laasi 算服务”应为“IaaS 计算服务”，选项 A 的 BIS 应为 BMS、C 的 EvS 应为 EVS，修正后答案 A 成立：裸金属容器集群直接跑在 BMS 裸金属服务器上，容器落在物理机、无需虚拟化层。ECS 是虚拟机集群所依赖的计算服务；EVS 是块存储、VPC 是网络，都不是计算服务。","note":"考题中是BMS","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-259","subject":"hcip_cloud","num":259,"pnum":29,"page":74,"type":"single","stem":"docoker 的资源隔离使用的是 1inux 的以下哪种特性？","options":[["A","Cgroup"],["B","SELinux"],["C","aufs"],["D","namespace"]],"answer":["D"],"ans_raw":"D","explain":"隔离靠 namespace：它让容器只看到自己的进程号、网络栈、挂载点、主机名与用户视图，彼此互不可见，故选 D。cgroup 管的是资源配额而非视图隐藏；aufs 承担镜像分层；SELinux 提供安全策略与访问控制，不负责把容器与宿主机其它进程隔开。与上一题合记：限制-cgroup、隔离-namespace。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-260","subject":"hcip_cloud","num":260,"pnum":30,"page":75,"type":"multi","stem":"在使用华为云分布式缓存 DCS 服务的过程前，需要进行以下哪些因素的评估？","options":[["A","数据的备份及持久化要求"],["B","数据的关系型库表设计"],["C","数据的规模及并发要求"],["D","数据的迁移方案，"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"评估点为持久化与备份要求（A，决定实例形态与备份策略）、数据规模与并发（C，决定规格与分片数）、迁移方案（D，存量数据与流量切换）。B 也成立，但口径要说清：DCS 是 Key-Value 存储、没有库表模型，需要设计的是缓存与后端 RDS 之间的数据映射关系，不是 Redis 自身的 schema。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-261","subject":"hcip_cloud","num":261,"pnum":31,"page":75,"type":"multi","stem":"下面哪些是业界的中间件产品？","options":[["A","Ignite"],["B","Apache Tomcat"],["C","oracle RebLogic"],["D","Kafka"],["E","Redis"],["F","IBM Message Queue"]],"answer":["A","B","C","D","E","F"],"ans_raw":"ABCDEF","explain":"六项都在中间件范畴：Ignite 是内存数据网格，Tomcat 是 Web 容器，WebLogic（选项 RebLogic 为识别缺字）是 Oracle 应用服务器，Kafka 与 IBM MQ 是消息队列，Redis 是缓存。界定标准是“位于操作系统与应用之间、提供消息、缓存、容器、事务等通用能力”，据此全选，无干扰项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-262","subject":"hcip_cloud","num":262,"pnum":32,"page":75,"type":"multi","stem":"以下哪些是华为云分布式缓存 DCS 服务的关键特性？","options":[["A","弹性扩容"],["B","即开即用"],["C","兼容开源"],["D","无忧运维"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项均为 DCS 关键特性：控制台购买即可用、免自建部署（B）；规格与分片可按需弹性扩展（A）；协议与 Redis 开源生态兼容、客户端基本不改（C）；监控、告警、备份与升级由服务托管（D）。故 ABCD，易漏 B——即开即用常被当成通用云特性而忽略它也是 DCS 卖点。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-263","subject":"hcip_cloud","num":263,"pnum":33,"page":76,"type":"single","stem":"以下哪项是华为云分布式消息 DMS 服务的功能？","options":[["A","数据库水平扩展"],["B","Key-Value 数据缓存"],["C","海量事务交易"],["D","模块异步解耦"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）DMS 是分布式消息服务，提供 Kafka、RabbitMQ 等实例，靠生产—消费模型让模块异步解耦、削峰填谷，功能应选 D。题给 B 的 Key-Value 数据缓存是 DMS 的兄弟服务 DCS 的职责，消息队列不承担缓存语义；A 数据库水平扩展属 DDM，C 海量事务交易偏数据库场景。建议复核本题。","note":"答案应该是D","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-264","subject":"hcip_cloud","num":264,"pnum":33,"page":76,"type":"multi","stem":"以下哪些是华为公有云提供的中间件服务？","options":[["A","CMQ：云消息队列"],["B","DRDS：分布式关系型数据库"],["C","DDM：分布式数据库服务"],["D","DCS：分布式缓存服务"],["E","DMS：分布式消息服务"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"（存疑）CMQ 是腾讯云的消息队列产品名，DRDS 是阿里云分布式关系型数据库产品名，两者都不在华为云目录中；华为云对应产品是 DMS（消息队列）、DDM（分布式数据库中间件），加上 DCS（缓存）才是本域中间件清单，故按产品命名应为 CDE。题给 ABCDE 把友商产品算入，建议复核。","note":"这个答案不对，应该是CDE","flag":"printed-number-duplicate-33","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-265","subject":"hcip_cloud","num":265,"pnum":35,"page":76,"type":"judge","stem":"华为云分布式数据库中间件 DDM 服务可实现透明读写分离。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。DDM 作为 SQL 代理会解析语句语义，写操作发往主实例、读操作按权重分发到只读实例，应用仍只连一个地址、不改代码，因此读写分离对上层透明。判据在“是否需应用自己选库”：若题干要求为读与写分别配置数据源，透明性即不成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-266","subject":"hcip_cloud","num":266,"pnum":36,"page":77,"type":"multi","stem":"以下哪项是华为云分布式消息 DD1 服务的功能？","options":[["A","海量数据迁移"],["B","海量数据交易"],["C","数据库分布式扩展"],["D","热点数据缓存"]],"answer":["A","C"],"ans_raw":"AC","explain":"（题干不全）题干“分布式消息 DD1”有误，从选项看应为分布式数据库中间件 DDM。其两项核心功能是 A 与 C：提供迁移能力把自建 MySQL 数据搬到拆分后的实例，并用分库分表让数据库层横向扩展。D 热点数据缓存属 DCS；B 海量数据交易描述的是数据库本体承载能力，不是中间件功能。","note":"这题不对，应该是分布式数据库中间件DDM, 答案是BC","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-267","subject":"hcip_cloud","num":267,"pnum":37,"page":77,"type":"judge","stem":"华为云分布式数据库中间件 D1 服务高度兼容 SL 语法，基于 MySL 的应用系统可轻松上云。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"对（本题 B 才是“正确”；题干 D1、SL、MySL 分别为 DDM、SQL、MySQL 的识别缺字）。判据在协议兼容度：DDM 兼容 MySQL 语法与协议，原有 SQL 语句基本照写，改造集中在少数受限语法与分片键设计，应用只需把连接指向 DDM，无需重写访问层。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-268","subject":"hcip_cloud","num":268,"pnum":38,"page":77,"type":"multi","stem":"使用华为云分布式消息 DMS 服务时，在 Kafka 队列创建完成后，需要取得哪些信息才能完成客户端接入？","options":[["A","消费者信息"],["B","客户端证书"],["C","AS/SK"],["D","接入点信息"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"接入 Kafka 实例需要三样：接入点地址（broker 的域名与端口，D）、用于 TLS 与鉴权的客户端证书（B），以及 AK/SK 身份凭据（C），故选 BCD。A 不成立：消费组与消费者由客户端启动时自行创建与提交位点，不属于队列建好后要“取得”的信息。","note":"答案应该是BD","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-269","subject":"hcip_cloud","num":269,"pnum":39,"page":78,"type":"multi","stem":"以下哪些是华为云分布式数据库中间件 DDM 服务服务的关键特性？","options":[["A","兼容 SOL 语法"],["B","业务不中断，自动完成水平拆分、平滑扩容"],["C","集群高可用，秒级故障自动恢复"],["D","可承受 PB 级数据量，百万级并发量、十倍于单机数据库连接"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都是 DDM 的关键特性：兼容 SQL 语法、应用少改（A，选项 SOL 为 SQL 缺字）；水平拆分与扩容在线完成、业务不中断（B）；代理层集群化部署并秒级故障切换（C）；靠多分片聚合支撑 PB 级数据量与远超单机的并发连接（D）。故全选，判据是每条都落在“中间件层能力”而非后端数据库本身。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-270","subject":"hcip_cloud","num":270,"pnum":40,"page":78,"type":"single","stem":"以下哪项服务不属于华为云 Paas 服务？","options":[["A","弹性云服务器 Es0"],["B","云容器引擎 CCE"],["C","云性能测试服务 CPTS"],["D","微服务云应用平台 Servicestage"]],"answer":["A"],"ans_raw":"A","explain":"ECS 是弹性云服务器，交付的是算力实例，属 IaaS，故选 A。CCE 容器引擎、ServiceStage 微服务应用平台、CPTS 性能测试服务都面向应用的构建与运行治理，属 PaaS。判据：直接给用户裸资源的是 IaaS，提供运行时与开发运维能力的是 PaaS。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-271","subject":"hcip_cloud","num":271,"pnum":41,"page":78,"type":"judge","stem":"裸金属容器直接运行于华为高性能物理服务器上、无任何虚拟化性能损失，可获得和物理机同等的性能。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。裸金属容器跑在物理服务器上，没有 Hypervisor 与客户机内核这两层损耗，CPU、内存与 IO 直通给容器，性能与独占物理机相当。判据是收益来源：省下的是虚拟化开销，而不是凭空增加规格，也不会突破物理机本身的能力上限。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-272","subject":"hcip_cloud","num":272,"pnum":42,"page":78,"type":"single","stem":"IOT 行业中，设备传输数据量非常小，并且通常都是有着固定的时间间隔，这种情况下 CFU 的利用率非常低，为节省资本，可采用华为 Pas 的哪种解决方案？","options":[["A","能力开放 API 网关"],["B","应用微服务化方案"],["C","应用 Saas 化改造方案"],["D","Serverless 函数计算平台"]],"answer":["D"],"ans_raw":"D","explain":"设备上报数据量小且周期固定，长期空跑的 CPU 就是浪费，Serverless 函数计算按调用触发、按执行计费、无流量不占资源，最贴合该场景，故选 D。API 网关只管接口开放与流控；微服务化与 SaaS 化改造都要常驻进程或集群，同样需要为空闲容量付费，都不解决利用率低的问题。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-273","subject":"hcip_cloud","num":273,"pnum":43,"page":79,"type":"multi","stem":"计算下列描述与容器镜像服务（SwR）有关的是？","options":[["A","多平台对接部署。支持云容器引擎（CCE）、微服务云应用平台（Servilestage）、函数服务（funcitons age）、容器镜像服务（）用户的部署调用"],["B","安全可靠。镜像仓库多租隔离；安全扫描；数据高可靠（三份备份）"],["C","高性能。自研高性能容器网络，秒级自动弹性伸缩，支持高性能裸全属容器私有集群"],["D","镜像管理。对接华为 MarketPlace，管理客户购买的收费镜像"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项均为 SWR 的产品特性：多平台对接，CCE、ServiceStage、FunctionGraph 等可直接调用镜像部署（A）；安全可靠，租户隔离、镜像安全扫描与数据冗余（B）；高性能，依托容器网络与裸金属私有集群、秒级弹性（C）；镜像管理，对接云商店纳管客户购买的收费镜像（D）。故全选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-274","subject":"hcip_cloud","num":274,"pnum":44,"page":79,"type":"single","stem":"下列关于企业级微服务管理平台 Cs 功能的描述，哪项是错误的？","options":[["A","一系列配套的微服务开发工具，包括代码生成、契约编辑、本地和远程调试。"],["B","对新建微服务提供多语言的 SDK，对已有应用提供低成本的改造接入能力。"],["C","一站式的微服务管理，包括服务注册、配置、治理、监控仪表盘、事务一致性管理"],["D","为企业提供应用快速打包/部署、自动化运维等 Docker 容器全生命周期管理能力"]],"answer":["D"],"ans_raw":"D","explain":"CSE 的交付物是微服务治理与开发支撑：配套开发工具与契约编辑（A）、多语言 SDK 与存量应用低成本接入（B）、注册发现、配置、治理、监控与事务一致性的一站式管理（C）。D 的 Docker 容器全生命周期托管属 CCE 与 ServiceStage，CSE 不编排容器、不建镜像，故 D 为错误描述。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-275","subject":"hcip_cloud","num":275,"pnum":45,"page":80,"type":"multi","stem":"微服务架构较传统单体架构，可以解决以下哪些问题？","options":[["A","可伸缩性差"],["B","交付周期长"],["C","新人培养时间长"],["D","代码质量差"],["E","应用维护成本高"]],"answer":["A","B","C","E"],"ans_raw":"ABCE","explain":"微服务把系统拆成可独立部署的小服务，各自按瓶颈扩缩（A）、并行交付缩短上线周期（B）、单个服务规模小便于新人上手（C）、职责边界清晰降低维护改动成本（E），故选 ABCE。D 代码质量差靠规范、评审与工具保障，拆分本身既不改善也不保证质量，属最易误选项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-276","subject":"hcip_cloud","num":276,"pnum":46,"page":80,"type":"judge","stem":"公有云收费，私有云不收费","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）“私有云不收费”不成立：私有云要么向厂商采购软件许可与集成服务，要么自建并承担硬件、运维人力与升级成本，费用只是从按量付费变为一次性投入加持续运维，并非不收费。按成本模型应判此说法错误，即选 A，题给 B（正确）建议复核。","note":"答案应该是A 本题在题库另一处（第99页）答案为A，两处不一致","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-277","subject":"hcip_cloud","num":277,"pnum":47,"page":80,"type":"judge","stem":"U 类图不能表示类之间的动态关系","options":[["A","错误"],["B","正确"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）类图是静态结构视图，描述类、属性、操作及泛化、实现、关联、聚合、组合、依赖等静态关系；运行期对象间的消息传递与时序由顺序图、通信图、状态图、活动图表达。据此“类图不能表示动态关系”的说法成立，应选 B（正确），题给 A 建议复核。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-278","subject":"hcip_cloud","num":278,"pnum":48,"page":80,"type":"multi","stem":"ESB（Enterprise Service Bus）的主要功能包括以下哪些？","options":[["A","服务通讯的身份验证和授权"],["B","对各个服务之间消息进行监控与路由"],["C","支撑数据转换与映射"],["D","消息与事件查询与排序"],["E","解决各个服务组件之间的通讯故障"]],"answer":["B","C","D","E"],"ans_raw":"BCDE","explain":"ESB 是服务间通信的中枢：对服务间消息做监控与路由（B）、做协议与格式的数据转换映射（C）、消息与事件的查询排序（D），并以总线方式屏蔽组件差异、降低点对点互联造成的故障面（E），故选 BCDE。A 的身份验证与授权属 API 网关的南北向入口职责，虽与微服务常搭配，却最易误选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-279","subject":"hcip_cloud","num":279,"pnum":49,"page":81,"type":"judge","stem":"M 给架构师提供了一个画图规范，只需用一张图就可以准确的描述一个系统的架构。","options":[["A","错误"],["B","正确"]],"answer":["A"],"ans_raw":"A","explain":"判据落在「一张图」上：无论题干主语是哪种建模规范（此处疑为识别残缺，应为 UML），系统架构都要从结构、行为、部署、运行时等多个视角分别表达，即 4+1 视图那类多视图方法，单一图必然漏掉关键约束，故判错误（A）。前半句「提供画图规范」成立，后半句过度。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-280","subject":"hcip_cloud","num":280,"pnum":50,"page":81,"type":"multi","stem":"华为云生态包括以下哪些内容？","options":[["A","云市场"],["B","合作伙伴"],["C","云社区"],["D","培训与认证"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项共同构成华为云生态：合作伙伴体系提供联合方案与分销能力，云市场承载第三方软件、API 等商品的交易与分发，云社区沉淀开发者交流与内容，培训与认证（HCIA/HCIP/HCIE）输出能力标准与人才，故选 ABCD。易漏选的是云市场，常被误当作纯售卖渠道而不算生态。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-281","subject":"hcip_cloud","num":281,"pnum":53,"page":82,"type":"single","stem":"常用 TCP/IP 协议中，哪个是有状态（stateful）的？","options":[["A","FTP"],["B","HTTP"],["C","UDP"],["D","IP"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）FTP 是应用层有状态协议：控制连接与数据连接分离，服务端要记住登录态、当前目录、传输模式与被动协商结果，防火墙必须做状态检测加 FTP ALG 才能放行，故按协议特性应选 A。题给 B 不成立，HTTP 在定义上就是无状态协议，会话靠 Cookie/Session 由应用自行补齐；UDP、IP 均为无连接。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-282","subject":"hcip_cloud","num":282,"pnum":54,"page":82,"type":"multi","stem":"微服务云应用平台（ServiceStage），可以完成以下哪些功能？","options":[["A","创建应用依赖计算资源"],["B","使用 AOS 模板自动化应用编排"],["C","查看应用各项指标"],["D","在线可视化升级应用"],["E","容器应用需要自己在 Servvi ceStage 上搭建容器管理平台，比如需自己搭建 kubernetes 管理 docker 容器应用"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"（存疑）ServiceStage 能创建应用所依赖的计算资源、用 AOS 模板做自动化编排、查看应用各项指标、在线可视化升级应用，A、B、C、D 都成立。E 错在要自建容器平台：ServiceStage 直接对接云容器引擎 CCE 与 SWR，Kubernetes 集群由 CCE 承载，用户不必自建。按此口径答案应为 ABCD。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-283","subject":"hcip_cloud","num":283,"pnum":55,"page":83,"type":"multi","stem":"软件开发云（DevCloud）中 CI/CD 流水线可以帮助开发者自动完成以下哪些操作","options":[["A","应用构建"],["B","应用自动化测试"],["C","应用运维和故障恢复"],["D","应用部署"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"CI/CD 流水线自动化的是从代码到发布的环节：构建编译打包产出制品（A）、自动化测试验证质量（B）、部署到目标环境（D），故选 ABD。C 的应用运维与故障恢复属上线后的运维域，由监控、告警、弹性伸缩等承担，不在流水线职责内，误选源于把持续交付等同于持续运维。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-284","subject":"hcip_cloud","num":284,"pnum":56,"page":83,"type":"single","stem":"应用在软件开发云（DevCloud）编译构建时，使用的 Dockerfile 文件作用是什么？","options":[["A","制作应用镜像"],["B","云用户鉴权"],["C","管理项目依赖包"],["D","保存配置参数"]],"answer":["C"],"ans_raw":"C","explain":"（存疑）Dockerfile 是镜像构建的描述文件，用 FROM、COPY、RUN 等指令逐层声明基础镜像、文件与启动方式，作用就是制作应用镜像，应为 A。C 的依赖包管理由 pom.xml、package.json 这类构建清单负责；D 保存配置参数靠配置文件；B 鉴权由 IAM 与 AK/SK 完成，都与 Dockerfile 无关。","note":"答案应该是A","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-285","subject":"hcip_cloud","num":285,"pnum":57,"page":83,"type":"judge","stem":"华为云应用性能管理服务使用字节码增强技术实现非侵入式采集用户应用的性能指标数据，用户在华为云上部署了一个 C 语言开发的应用，也可以用华为云应用性能管理服务来分析其性能问题。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）判据在采集技术与语言的匹配性：字节码增强只能作用于运行在 JVM 上的字节码，C 语言编译成机器码，没有可增强的字节码，无法用该探针非侵入接入，故应判错误（A）。本卷相邻两题也认定 APM 不支持 C/C++，题干两个分句自相矛盾。分析 C 应用性能需系统级性能剖析或代码埋点。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-286","subject":"hcip_cloud","num":286,"pnum":59,"page":84,"type":"single","stem":"ICAgent 是 APM 的采集代理，运行在应用所在的弹性云服务器上，用于实时采集拓扑和调用链等监控数据，下面哪种说法是不正确的？","options":[["A","通过 JVM 字节码技术实现非侵入式数据采集，用户无需修改业务代码"],["B","通过 Servicestage 上线的应用可以自动完成采集探针的部署"],["C","每个采集探针的资源开销极小，不会对业务造成影响"],["D","支持对 C 语言开发的应用的数据采集"]],"answer":["D"],"ans_raw":"D","explain":"APM 探针 ICAgent 基于 JVM 字节码增强，面向 Java 技术栈及 Tomcat、Spring 这类 JVM 上的运行环境采集拓扑与调用链；C 语言没有 JVM 与字节码，无法以此方式采集，D 说法不成立，即为答案。A 非侵入、B 经 ServiceStage 上线自动注入探针、C 探针资源开销小，均符合其设计。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-287","subject":"hcip_cloud","num":287,"pnum":60,"page":84,"type":"multi","stem":"以下哪些是华为云 APM（应用性能管理服务）的应用场景？","options":[["A","透过 Apdex 数值来剖析事务状态"],["B","使用模板来一键式将应用部署到云上"],["C","通过调用链来追踪问题根因"],["D","通过拓扑图来掌握应用健康状况"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"APM 定位是应用可观测：Apdex 分值量化事务满意度（A）、调用链逐跳定位慢调用与异常根因（C）、拓扑图反映应用及依赖的健康状况（D），故选 ACD。B 用模板一键部署应用属应用编排服务 AOS 的交付能力，与性能管理无关，是本题最强干扰项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-288","subject":"hcip_cloud","num":288,"pnum":61,"page":84,"type":"multi","stem":"假如你在华为云上部署了一个电商网站，为了惠及老客户，准备搞一个为期一天的大甩卖，那么运维人员应该提前在华为云上做好哪些准备？","options":[["A","使用华为云的压测服务（CPTS）提前演练一下网站的高访问量服务能力"],["B","将例行运维需要查看的指标添加到仪表盘中，以便实时掌握全局"],["C","对网站的关键应用性能指标设置阈值告警，告警自动通知运维人员"],["D","提前准备资源。设置弹性伸缩组，在促销过程中随资源使用量上升及时扩容"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"（存疑）大促前的准备四项皆合理：用 CPTS 压测提前验证高并发承载能力（A）、把例行运维指标聚成仪表盘实时掌握全局（B）、对关键性能指标设阈值告警自动通知（C）、预置资源并用弹性伸缩随负载及时扩容（D）。题给 BCD 排除了 A，但压测正是容量评估与扩容参数确定的前提，按实践应为 ABCD。","note":"跨页题：题干在第 84 页末，选项与「答案：BCD」在第 85 页","flag":"rechecked","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-289","subject":"hcip_cloud","num":289,"pnum":62,"page":85,"type":"multi","stem":"阀值报警通过检测阀值规则中定义的指标设定的上下限，如果达到触发条件，则发送一条警报信息，同时执行自定义的动作，当前华为云上的告警可以通过哪些途径通知运维人员？","options":[["A","短信"],["B","邮件"],["C","微信"],["D","QQ"]],"answer":["A","B"],"ans_raw":"AB","explain":"华为云告警通知走云监控与 SMN 主题，官方触达渠道是短信和邮件（主题还可把事件推送到函数、HTTP/HTTPS 订阅端），故选 AB。微信、QQ 属第三方社交工具，平台不提供官方直连接口，需要自建机器人中转，不算告警通知途径。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-290","subject":"hcip_cloud","num":290,"pnum":63,"page":85,"type":"single","stem":"华为云应用性能管理服务通过在应用所在节点上安装采集代理来完成应用性能数据采集的。采集代理是基于业界 Pinpoint 开源项目，通过 JVM 字节码增强技术实现非侵入方式采集应用指标的。APM 不支持下列哪种技术栈开发的应用？","options":[["A","JAVA"],["B","Tomcat"],["C","C++"],["D","Spring"]],"answer":["C"],"ans_raw":"C","explain":"APM 探针靠 JVM 字节码增强实现，能覆盖 Java 应用以及 Tomcat、Spring 这类运行在 JVM 上的容器与框架；C/C++ 编译为本地机器码，无字节码可增强，因此不支持，答案 C。易错点是以为 Tomcat、Spring 不是语言就该排除，实际它们是探针适配的 Java 运行环境。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-291","subject":"hcip_cloud","num":291,"pnum":64,"page":86,"type":"multi","stem":"华为云立体化运维的目标是全方位掌控系统的运行状态，并快速的响应各类问题，具体体现在以下哪些方面？","options":[["A","监控 IaaS 层资源的运行状态"],["B","只关注 Paas 层应用的运行状态"],["C","掌握 Paas 上部署的应用的运行状态，支持故障及性能问题的追踪，方便运维人员定位"],["D","管理用户的体验保障，实时监控业务运行是否正常"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"立体化运维要求自下而上全栈可见并快速响应：A 覆盖 IaaS 层资源运行状态监控，C 覆盖 PaaS 上应用的运行状态与故障、性能问题追踪定位，D 覆盖业务与用户体验的实时保障，三层贯通才成立，故选 ACD。B 的「只关注 PaaS」与全方位目标直接冲突，错在排他限定。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-292","subject":"hcip_cloud","num":292,"pnum":65,"page":86,"type":"multi","stem":"下述哪项属于微服务自组织团队的范畴？","options":[["A","不断识别交付中的瓶颈，采用精益的方式快速验证和优化，小步快跑"],["B","You Build it，You Run it 小团队，完成服务的分析、开发、测试、部署和运维"],["C","组织团队设计、开发、测试等角色分工明确、各司其职"],["D","康威定律-产品或系统的设计（架构）受到其生产组织自身沟通结构的制约"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"自组织团队讲的是团队如何自治交付服务：A 用精益方式持续识别交付瓶颈、小步快跑验证优化，B 全功能小团队对服务从分析到运维全程负责（You build it, you run it），D 康威定律说明组织沟通结构制约系统架构，属团队组织维度，故选 ABD。C 角色分工明确、各司其职是职能筒仓式组织，正是自组织要打破的对象。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-293","subject":"hcip_cloud","num":293,"pnum":66,"page":87,"type":"single","stem":"在微服务实战指导中，以下示意图中的哪个微服务可以使用灰度发布?","options":[["A","forecast"],["B","weathermapweb"],["C","weather"],["D","fusionweather"]],"answer":["C"],"ans_raw":"C","explain":"（题干不全）本题依赖题干所指的那张微服务实战示意图，图未随题给出，无法据图判断哪个服务具备灰度发布条件，不做猜测。可记的判据：该服务需已注册到服务中心、同时部署新旧两个版本实例且调用方可按版本分流，入口前端类与图中未做多版本部署的服务不满足。","note":"","flag":"image-question","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-294","subject":"hcip_cloud","num":294,"pnum":67,"page":87,"type":"single","stem":"以下哪项不属于 CSE 微服务开发框架支持的编程模型？","options":[["A","gRPC"],["B","POJO"],["C","JAX-RS"],["D","SpringMVC"]],"answer":["B"],"ans_raw":"B","explain":"CSE 的开发框架（ServiceComb 系 SDK）对外提供 REST 风格的 JAX-RS 与 Spring MVC 编程模型，跨语言与高性能场景走 gRPC，三者都自带服务契约、路由与注册语义，故选 B。POJO 只是普通 Java 对象的形态，不是一种服务编程模型命名。易错点：服务实现类可以写得很朴素，容易把它误当成官方编程模型。","note":"答案应该是A 本题在题库另一处（第88页）答案为，两处不一致","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-295","subject":"hcip_cloud","num":295,"pnum":69,"page":88,"type":"single","stem":"下述哪项是微服务引擎 CSE 的目标？","options":[["A","微服务运维生命周期管理"],["B","微服务上线生命周期管理"],["C","微服务开发生命周期管理"],["D","微服务全生命周期管理"]],"answer":["D"],"ans_raw":"D","explain":"CSE 的目标是微服务全生命周期管理：开发期给多语言 SDK、契约与开发工具，上线期做服务注册发现与配置下发、灰度发布，运维期给治理（限流熔断降级）与监控大盘，三段全覆盖故选 D。A 运维、B 上线、C 开发都只截取一个阶段，属片面表述。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-296","subject":"hcip_cloud","num":296,"pnum":70,"page":88,"type":"single","stem":"微服务实战指导中，本地启动服务前需要配置什么信息以使微服务成功注册到华为云上的服务中心？","options":[["A","监控中心地址"],["B","配置中心地址"],["C","AK/SK 等认证信息"],["D","handl er"]],"answer":["C"],"ans_raw":"C","explain":"本地进程要把实例注册到云端服务中心，等于跨公网访问受保护的服务注册接口，必须提供 AK/SK 等认证信息，否则鉴权不通过、注册失败，故选 C。监控中心、配置中心地址影响的是指标上报与动态配置，不决定能否注册；D 选项文本因识别出现空格（handler），也不是注册前提。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-297","subject":"hcip_cloud","num":297,"pnum":71,"page":89,"type":"judge","stem":"微服务的范围包括自组织团队、技术实践、流程与工具，三者相辅相成，互相促进与发展。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"判据在于微服务不只是拆分粒度或技术选型：组织层面要自组织团队，工程层面要技术实践（服务拆分、契约优先、自动化），流程工具层面要 DevOps 与 CI/CD，三者互为前提、共同演进，题干的三要素划分与相互关系符合这口径，故选正确（B）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-298","subject":"hcip_cloud","num":298,"pnum":72,"page":89,"type":"judge","stem":"应用向云原生（CloudNative）模式演进，微服务是 CloudNative 的事实标准。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"判据是云原生的构成要素：容器作为运行载体、微服务作为架构形态、DevOps 与持续交付作为实践流程共同组成云原生，其中架构形态这一环已被微服务风格占据，主流平台也按微服务拆分与治理，故「微服务是 CloudNative 的事实标准」成立，判正确。易错点是只认容器为标准而否定架构形态。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-299","subject":"hcip_cloud","num":299,"pnum":74,"page":89,"type":"multi","stem":"微服务架构将面临多维度的挑战，下面哪些属于微服务架构需要面对的挑战？","options":[["A","故障概率增加、监控跟踪困难，调用频率高、调用链长，跨虚拟机、VLAN 通信不可控因素增加。"],["B","可以根据服务需要自由选择组件，不必担心依赖冲突，微服务自己管理自己的数据。"],["C","数据不再集中管理，分散到各个微服务，常规事务管理无法跨越服务边界。"],["D","便于实现自动化测试，测试用例清晰、外部依赖清晰，易于打桩（API 预定义）。"]],"answer":["A","C"],"ans_raw":"AC","explain":"挑战要看被变差的一面：A 服务与调用链数量暴增，故障概率上升、跨虚拟机与 VLAN 通信不可控，监控跟踪难度陡增；C 数据随服务去中心化、由各服务自管，常规事务无法跨越服务边界，需要最终一致性方案，两者是真挑战，故选 AC。B 的「不必担心依赖冲突」本身说法错，D 讲的是打桩与测试便利，属收益。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-300","subject":"hcip_cloud","num":300,"pnum":75,"page":90,"type":"judge","stem":"微服务引擎提供的自动负载均衡机制支持的策略包括：顺序、随机本地、粘滞、基于实例负载等。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"判据看 CSE 客户端负载均衡的可配置策略族：顺序/轮询、随机、本地（同可用区、同区域优先）、会话粘滞以及基于实例负载的策略都在支持范围，且由框架自动完成、无须自建路由，故题干正确（B）。别把「自动」误读成必须靠服务端或 ELB 来做。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-301","subject":"hcip_cloud","num":301,"pnum":76,"page":90,"type":"judge","stem":"微服务引擎提供了一系列开箱即用的微服务治理能力，如自动容错、服务障级、服务限流和自动容灾。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"判据在治理能力的开箱即用程度：CSE 控制台配置策略即生效，提供自动容错（超时、重试、熔断）、服务降级（题干「障级」应为降级之误）、服务限流以及跨可用区的自动容灾，均在治理范围内，故题干正确（A）。易疑点是这些能力需要 SDK 或网格接入配合，但无需自行引入额外组件。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-302","subject":"hcip_cloud","num":302,"pnum":77,"page":90,"type":"judge","stem":"华为云容器引擎 CCE 服务中用户不能对老版本的集群进行升级。","options":[["A","错误"],["B","正确"]],"answer":["A"],"ans_raw":"A","explain":"判据是 CCE 的集群升级能力：老版本集群可以在控制台升级到当前支持的目标版本，通常先升级控制面、再按批次升级节点，并有升级前检查与预案，所以「不能升级」判错误（A）。易混点：不支持任意跨大版本直升、也不支持升到已下线的历史版本，这与完全不能升级是两回事。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-303","subject":"hcip_cloud","num":303,"pnum":78,"page":90,"type":"judge","stem":"kubelet 是一个位于集群 master 节点的管理组件。","options":[["A","错误"],["B","正确"]],"answer":["A"],"ans_raw":"A","explain":"判据看组件运行位置：kubelet 运行在集群的每一个 node 上，负责解析 PodSpec、调用容器运行时拉起并维持 Pod 内容器、上报节点与容器状态；master 侧的管理组件是 API Server、调度器、控制器管理器等，故把 kubelet 说成 master 管理组件是错的，判错误（A）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-304","subject":"hcip_cloud","num":304,"pnum":79,"page":91,"type":"multi","stem":"在一个 kubernetes 集群中，以下哪些是可以从外部访问的 service 的类型？","options":[["A","namespace"],["B","1oadBal ancer"],["C","clusterIP"],["D","nodePort"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"（存疑）能从集群外访问的是 LoadBalancer（对接 ELB 对外暴露）与 NodePort（在每个节点开放端口映射），ExternalName 也可从集群外解析但未列入选项；ClusterIP 只是集群内虚拟 IP，仅在集群内流量中可达，外部访问要靠 Ingress 等另加机制。故答案应为 BD，题给 BCD 把 clusterIP 计入不成立。namespace 是隔离对象，不是 service 类型。","note":"答案应该是BD","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-305","subject":"hcip_cloud","num":305,"pnum":80,"page":91,"type":"judge","stem":"docker 镜像不分层。","options":[["A","错误"],["B","正确"]],"answer":["A"],"ans_raw":"A","explain":"判据是镜像的组织方式：Docker 镜像由一组只读层叠加、用联合文件系统合并成统一视图，容器启动时在最上层加可写层，分层带来层复用与构建缓存。「不分层」与该机制直接矛盾，判错误（A）。易混点：镜像导出为单个 tar 包，不等于内部没有分层结构。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-306","subject":"hcip_cloud","num":306,"pnum":81,"page":91,"type":"multi","stem":"容器编排工具包括？","options":[["A","Marathon"],["B","Kubernetes"],["C","Horizon"],["D","Neutron"]],"answer":["A","B"],"ans_raw":"AB","explain":"Marathon 是 Mesos 上的容器与长时服务编排框架，Kubernetes 是主流容器编排系统，两者都做调度、编排与自愈，故选 AB。C Horizon 是 OpenStack 的控制台界面，D Neutron 是 OpenStack 的网络组件，均与容器编排无关，误选是把云平台组件当成了编排器。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-307","subject":"hcip_cloud","num":307,"pnum":82,"page":91,"type":"multi","stem":"华为 CCE 云容器引擎优势包括？","options":[["A","多样的生态接入"],["B","高性能基础设施"],["C","增强的商用化特性"],["D","完全开放的原生平台"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"CCE 的优势主张正是这四点：完全开放、兼容原生 Kubernetes 生态；以 ECS/BMS 与自研容器网络构成高性能基础设施；补齐多可用区、企业级权限、日志监控等商用化特性；生态上可对接镜像、应用平台与服务网格等多样接入，故选 ABCD。别因「完全开放」看似与商用矛盾而漏选。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-308","subject":"hcip_cloud","num":308,"pnum":83,"page":92,"type":"multi","stem":"华为 CCE 云容器引擎可以创建哪些类型的集群？","options":[["A","裸金属集群"],["B","虚拟机集群"],["C","A1X 集群"],["D","windows 集群"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"CCE 支持以 ECS 虚拟机为节点的集群、以 BMS 裸金属服务器为节点的集群，以及承载 Windows 容器工作负载的集群，故选 ABD。C 的「A1X 集群」不是 CCE 的集群类型（此处文本疑为图像识别残缺）；GPU、AI 类算力是以节点规格形式提供，不构成独立集群类型。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-309","subject":"hcip_cloud","num":309,"pnum":84,"page":92,"type":"multi","stem":"以下哪些是华为 CCE 云容器引擎适用的场景？","options":[["A","业务负荷有明显波动的场景"],["B","降低资源成本的场景"],["C","传统 IT 架构可以稳定支撑业务的场景"],["D","提升业务上线效率的场景"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"容器化的价值点即 CCE 的适用场景：负荷有明显波动可靠弹性伸缩按需扩缩（A）、靠提升密度与混合部署降低资源成本（B）、靠镜像一次构建多处运行提高上线效率（D）。C 的读法是把传统 IT 能稳定支撑的业务也纳入渐进式改造，收益仍落在效率与成本上，按题给口径入选；此项逻辑上较牵强，复习时把握 A、B、D 更稳。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-310","subject":"hcip_cloud","num":310,"pnum":85,"page":92,"type":"judge","stem":"华为云容器引擎 CCE 服务中高可用集群和普通集群的区别是高可用集群一般包含多个 node。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）高可用集群与普通集群的差别在控制面而非工作节点：高可用规格提供多个 master 节点与多数派元数据存储，避免管理面单点；普通集群只有单个 master。worker 数量与是否高可用无关，任何规格都能有多台 node，故题干判据错误，应判「错误」。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-311","subject":"hcip_cloud","num":311,"pnum":86,"page":93,"type":"judge","stem":"在 Kubernetes 的 Replicaset 中可以设置 Pod 的数量","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"判据看 ReplicaSet 的期望副本数字段：它声明要维持的 Pod 数量，控制器据此对比实际状态做多删少补，数量可直接修改，也可由上层 Deployment 间接设定，所以「可以设置 Pod 的数量」成立，判正确（B）。易混：自动调副本是 HPA 的职责，但手工声明副本数正是 ReplicaSet 的基本用法。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-312","subject":"hcip_cloud","num":312,"pnum":87,"page":93,"type":"multi","stem":"以下哪些是华为云分布式缓存 DCS 服务的关键特性？","options":[["A","无忧运维"],["B","兼容开源"],["C","弹性扩容"],["D","即开即用"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都是 DCS 的关键特性：即开即用（分钟级开通实例）、兼容开源（Redis、Memcached 协议与常用命令）、弹性扩容（规格与实例数可变）、无忧运维（免安装部署，监控告警与补丁升级由服务承担），故选 ABCD。易漏的是无忧运维，容易以为缓存仍需自己维护。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-313","subject":"hcip_cloud","num":313,"pnum":88,"page":93,"type":"single","stem":"以下哪项不是华为云分布式消息 DMS 服务的关键特性？","options":[["A","提供热点数据缓存"],["B","灵活队列类型：提供普通队列、FIFO 队列、Kafka 队列"],["C","支持消息过滤、消息回溯，消息重投、广播消息等丰富的消息能力"],["D","百亿级消息堆积"]],"answer":["A"],"ans_raw":"A","explain":"DMS 是消息与队列服务，能力集中在队列类型（普通、FIFO、Kafka）、消息过滤/回溯/重投/广播等丰富消息语义、大规模消息堆积上，B、C、D 都是其特性。A 的热点数据缓存属 DCS 的定位，与消息语义无关，故 A 不是 DMS 特性，即本题答案。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-314","subject":"hcip_cloud","num":314,"pnum":89,"page":93,"type":"multi","stem":"下面哪些是典型的中间件的用途？","options":[["A","分布式数据库中间件：支持海量数据"],["B","负载均衡：支持海量访问"],["C","消息队列：模块异步解耦"],["D","缓存数据库：热点数据缓存"],["E","安全服务：应用 WAF 安全"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"中间件的经典用途四条齐全：分布式数据库中间件分库分表支撑海量数据，负载均衡支撑海量访问，消息队列实现模块异步解耦，缓存数据库承担热点数据访问，故选 ABCD。E 的 WAF 属安全防护服务，是应用防护能力而非中间件分层，是最容易误带进来的一项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-315","subject":"hcip_cloud","num":315,"pnum":90,"page":94,"type":"judge","stem":"企业如果自己开发或直接使用开源中间件，则需要企业自主解决硬件故障、软件安装部署、中间件软件 bug 和安全修复等问题，需要企业大量人力。","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"判据是责任边界：自建或直接使用开源中间件时，硬件故障处置、安装部署、软件 bug 修复与安全补丁、高可用与扩容全部由企业自行承担，需要专职人力；云中间件把这些工作托管给服务方，用户只需配置与使用。题干陈述这一成本事实，判正确（A）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-316","subject":"hcip_cloud","num":316,"pnum":91,"page":94,"type":"multi","stem":"在使用华为云分布式缓存 DCs 服务的过程前，需要进行以下哪些因素的评估？","options":[["A","数据的迁移方案"],["B","数据的关系型库表设计"],["C","数据的规模及并发要求"],["D","数据的备份及持久化要求"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"（存疑）DCS 是键值缓存，规划时要评估数据规模与并发要求（C，决定实例规格与分片数）、能否接受数据丢失及备份与持久化策略（D）、自建缓存上云的迁移方案（A），答案应为 ACD。B 的关系型库表设计属 RDS 建模范畴，与缓存实例选型无关，题给 ABC 把 B 计入、反而漏掉 D，不成立。","note":"答案应该是ABCD","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-317","subject":"hcip_cloud","num":317,"pnum":92,"page":94,"type":"multi","stem":"以下哪些是使用云中间件构建分布式云化应用后可实现的功能？","options":[["A","开放兼容、可扩展性强"],["B","动静分离：动态页面的流量和静态页面的流量进行分离"],["C","数据库分库分表"],["D","系统解耦"],["E","可准确预估系统性能和容量"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"云中间件支撑分布式云化应用可实现：开放兼容且可水平扩展（A）、配合负载均衡与对象存储/CDN 做动静流量分离（B）、由 DDM 完成分库分表（C）、由消息队列实现系统解耦（D），故选 ABCD。E 错在「准确预估」，分布式系统受热点数据、依赖抖动与突发流量影响，只能靠压测做容量评估，无法精确预估。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-318","subject":"hcip_cloud","num":318,"pnum":93,"page":95,"type":"multi","stem":"使用华为云分布式消息 DMS 服务时，在 Kafka 队列创建完成后，需要取得哪些信息才能完成客户端接入？","options":[["A","客户端证书"],["B","AS/SK"],["C","接入点信息"],["D","消费者信息"]],"answer":["A","B"],"ans_raw":"AB","explain":"（存疑）Kafka 客户端接入实例，必需的是接入点信息（broker 地址与端口，即 C）以及采用 SSL 认证时下载的客户端证书（A），故应为 AC。AK/SK 用于调用管理类 API，不参与 Kafka 协议数据面的认证；消费者信息属消费端自身逻辑，不需从服务端获取。题给 AB 混淆了管理面与数据面。","note":"答案应该是AC","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-319","subject":"hcip_cloud","num":319,"pnum":94,"page":95,"type":"judge","stem":"中间件可帮助用户灵活、高效地开发和集成复杂的应用软件","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"判据在中间件的定义职能：它位于操作系统、数据库与应用之间，把连接管理、事务、消息、缓存、并发与扩展性等公共能力封装成可复用服务，让开发者专注业务逻辑，从而更灵活高效地开发和集成复杂应用。题干与这一定位一致，判正确（A）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-320","subject":"hcip_cloud","num":320,"pnum":95,"page":95,"type":"multi","stem":"以下哪些是华为云分布式数据库中间件 DDM 服务服务的关键特性？","options":[["A","业务不中断，自动完成水平拆分、平滑扩容"],["B","兼容 SQL 语法"],["C","可承受 PB 级数据量，百万级并发量、十倍于单机数据库连接"],["D","集群高可用，秒级故障自动恢复"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"DDM 的四个关键特性：水平拆分与平滑扩容在线完成、业务不中断（A）、兼容 MySQL 语法与协议使应用近乎零改造（B）、多实例集群支撑海量数据与远高于单机的连接并发（C）、集群多节点部署、故障自动切换快速恢复（D），故选 ABCD。注意 C 的量级是产品宣传口径，实际取决于分片数与后端 RDS 规格。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-321","subject":"hcip_cloud","num":321,"pnum":96,"page":95,"type":"single","stem":"以下哪项是华为云分布式缓存 DCS 服务的功能？","options":[["A","模块间异步解耦"],["B","数据库水平扩展"],["C","Key-Value 数据缓存"],["D","海量事务交易"]],"answer":["C"],"ans_raw":"C","explain":"DCS 是分布式缓存服务，对外提供键值结构数据的内存存取，答案 C。A 模块间异步解耦靠 DMS 消息队列，B 数据库水平扩展是 DDM 的分库分表，D 海量事务交易由 RDS/DDM 这类数据库承担，都不属缓存服务的功能表述。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-322","subject":"hcip_cloud","num":322,"pnum":97,"page":96,"type":"single","stem":"某游戏平台面临两大挑战：一方面，日常业务峰值负荷下平台利用率低于 30%（即一半时间利用率低于 10%），造成了资源的极大浪费；另一方面，当前手工升级方式效率低下，升级过程平均要花费两个多小时。这种情况下，可以采用华为云 PaaS 哪种解决方案？","options":[["A","应用零改造上云方案"],["B","应用切换云中间件方案"],["C","应用容器化方案"],["D","应用 Saas 化"]],"answer":["C"],"ans_raw":"C","explain":"两个痛点同时指向容器化：峰值下利用率仍低、多数时间空闲，说明需要细粒度隔离与秒级弹性伸缩来提密度降成本，容器正是前提；手工升级两小时说明需要不可变交付物，用镜像灰度或一键回滚替代手工替换。选 C。A 零改造上云不解决弹性与发布效率，B 换中间件与利用率无关，D SaaS 化面向租户而非自建平台。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-323","subject":"hcip_cloud","num":323,"pnum":98,"page":96,"type":"multi","stem":"下列描述与容器镜像服务（SWR）有关的是？","options":[["A","镜像管理。对接华为 MarketPlace，管理客户购买的收费镜像。"],["B","多平台对接部署。支持云容器引擎（CCE）、微服务云应用平台（ServiceStage）、函数服务（FunctionStage）、容器镜像服务（SMR）用户的部署调用。"],["C","高性能。自研高性能容器网络，秒级自动弹性伸缩，支持高性能裸金属容器私有集群。"],["D","安全可靠。镜像仓库多租隔高：安全扫描：效据高可靠（三份备份）。"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"SWR 负责镜像的存储与分发：对接华为云 Marketplace 管理客户购买的收费镜像（A）、为 CCE、ServiceStage、FunctionGraph 等提供部署时的镜像来源（B）、以多租户隔离、镜像安全扫描和三份备份保障安全可靠（D），故选 ABD。C 的高性能容器网络、秒级弹性与裸金属容器私有集群是 CCE 的能力，为最强干扰项。B、D 文本有识别错字，应为 FunctionGraph、SWR、多租户隔离、数据高可靠。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-324","subject":"hcip_cloud","num":324,"pnum":99,"page":97,"type":"judge","stem":"通过函数服务（FunctionStage），只需编写业务函数代码并设置运行的条件，无需配置和管理服务器等基础设施，函数以弹性、免运维、高可靠的方式运行。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"判据是 Serverless 的责任划分：用户只写业务函数代码并设置运行条件（触发器、定时或上游事件），不配置与管理服务器，运行环境与扩缩容由平台托管，确实表现为弹性、免运维、高可靠，与题干一致，判正确（B）。名称应为函数工作流 FunctionGraph，题面写作 FunctionStage，不影响结论。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-325","subject":"hcip_cloud","num":325,"pnum":100,"page":97,"type":"multi","stem":"微服务架构较传统单体架构，可以解决以下哪些问题？","options":[["A","新人培养时间长"],["B","代码质量差"],["C","可伸缩性差"],["D","交付周期长"],["E","应用维护成本高"]],"answer":["A","C","D","E"],"ans_raw":"ACDE","explain":"微服务对单体的改善集中在交付与运维：服务边界小、新人只需吃透一块（A）、可按瓶颈单独伸缩解决可伸缩性差（C）、小服务独立部署并行交付缩短周期（D）、影响面收敛降低维护成本（E），故选 ACDE。B 代码质量取决于规范、评审与测试，拆分反而引入分布式复杂度，不会自动变好。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-326","subject":"hcip_cloud","num":326,"pnum":101,"page":97,"type":"single","stem":"下列关于企业级微服务管理平台 CSE 功能的描述，哪项是错误的？","options":[["A","为企业提供应用快速打包/部署、自动化运维等 Docker 容器全生命周期管理能力。"],["B","一站式的微服务管理，包括服务注册、配置、治理、监控仪表盘、事务一致性管理。"],["C","对新建微服务提供多语言的 SDK，对已有应用提供低成本的改造接入能力。"],["D","一系列配套的微服务开发工具，包括代码生成、契约编辑、本地和远程调试。"]],"answer":["D"],"ans_raw":"D","explain":"（存疑）A 所说的应用快速打包部署、自动化运维以及 Docker 容器全生命周期管理，是云容器引擎 CCE 的能力定位，并非 CSE 的功能，本身就是错误描述，应选 A。B 的一站式微服务管理（注册发现、配置、治理、监控、事务一致性）、C 多语言 SDK 与低成本改造接入、D 配套开发工具（契约编辑、代码生成、本地与远程调试）都是 CSE 的真实能力，属正确描述，题给 D 不成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-327","subject":"hcip_cloud","num":327,"pnum":102,"page":98,"type":"multi","stem":"业务使用容器后能带来哪些好处？","options":[["A","适合敏捷扩缩容场景"],["B","降低企业成本"],["C","提升代码开发质量"],["D","提高交付效率"],["E","为业务提高了安全性"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"容器的收益在交付与资源两面：秒级启停适合敏捷扩缩容（A）、细粒度隔离与混部提升利用率从而降本（B）、标准镜像一次构建多处运行提高交付效率（D），故选 ABD。C 代码质量与运行时形态无关；E 不成立，容器共享宿主内核、逃逸面增加，安全性要靠镜像扫描与运行时策略另行保障。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-328","subject":"hcip_cloud","num":328,"pnum":103,"page":98,"type":"judge","stem":"基于应用编排服务（AOS）可以实现应用的自动化运维。","options":[["A","错误"],["B","正确"]],"answer":["B"],"ans_raw":"B","explain":"判据看 AOS 的职责范围：它用模板声明云资源清单与应用拓扑，一次执行按依赖顺序拉起，并可与弹性伸缩、监控等能力联动，把重复的资源创建与配置从手工变为流程化，属应用自动化运维范畴，判正确（B）。严格说它偏交付编排，故障自愈仍要靠运维服务，但这不否定题干的自动化结论。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-329","subject":"hcip_cloud","num":329,"pnum":104,"page":98,"type":"single","stem":"以下哪项服务不属于华为云 Paas 服务？","options":[["A","微服务云应用平台 ServiceStage"],["B","云性能测试服务 CPTS"],["C","弹性云服务器 ECS"],["D","云容器引擎 CCE"]],"answer":["C"],"ans_raw":"C","explain":"ECS 交付的是虚拟机形态的计算资源，操作系统之上的运行时与应用仍由用户自己维护，属 IaaS，答案 C。ServiceStage 提供应用编排与运行平台、CCE 提供容器运行平台、CPTS 提供压测能力平台，三者都是给应用托管运行环境的 PaaS。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-330","subject":"hcip_cloud","num":330,"pnum":105,"page":99,"type":"multi","stem":"下面哪些是常用容灾架构模式？","options":[["A","备份复原"],["B","冷待机"],["C","多活模式"],["D","异地恢复"],["E","暖待机"]],"answer":["A","B","C","E"],"ans_raw":"ABCE","explain":"常用容灾架构模式按站点就绪程度与 RTO/RPO 递进排布：备份复原、冷待机、暖待机、多活模式，四级覆盖从数据级到业务级的取舍，故选 ABCE。D 异地恢复描述的是恢复动作发生的地点维度，与备份复原、待机重复，不是一种独立的架构层级，是最易误加的一项。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-331","subject":"hcip_cloud","num":331,"pnum":107,"page":99,"type":"single","stem":"（图片题：题干为考试界面截图中的 UML 图，截图内未见文字题干）","options":[["A","顺序图"],["B","状态图"],["C","类图"],["D","用例图"]],"answer":["A"],"ans_raw":"A","explain":"截图内为带 fill in info、submit、add course(张三,软件架构)、are you open?、add（张三）等消息箭头的图；选项为单选按钮，顺序图 前的圆点为选中状态。","note":"","flag":"image-stem","source":"HCIP-Cloud Service题库.pdf","ex_src":"题源"},{"id":"hcip_cloud-332","subject":"hcip_cloud","num":332,"pnum":108,"page":99,"type":"judge","stem":"SOA 用于企业内部业务系统的架构设计，ESB 主要用于企业间业务系统交互。","options":[["A","错误"],["B","正确"]],"answer":["A"],"ans_raw":"A","explain":"判据是 SOA 与 ESB 的层级关系：ESB 是 SOA 在落地时的集成总线，主要解决企业内异构系统之间的服务编排、协议与数据转换；跨企业、对外的服务交互通常经 API 开放能力与网关完成，而不是把内部总线暴露出去。题干把两者的适用范围说反，判错误（A）。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-333","subject":"hcip_cloud","num":333,"pnum":109,"page":100,"type":"multi","stem":"云架构师的能力模型包括哪些维度？","options":[["A","系统优化"],["B","需求分析"],["C","运行维护"],["D","规划设计"],["E","部署实施"]],"answer":["A","B","C","D","E"],"ans_raw":"ABCDE","explain":"云架构师能力模型沿交付链路展开为五个维度：需求分析把业务目标转为功能与非功能约束，规划设计给出架构与选型，部署实施完成落地迁移，运行维护保障可用与可观测，系统优化持续调优降本，五者构成闭环，故选 ABCDE。易漏的是系统优化，容易被当成纯运维工作。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-334","subject":"hcip_cloud","num":334,"pnum":110,"page":100,"type":"judge","stem":"UML 给架构师提供了一个画图规范，只需用一张图就可以准确的描述一个系统的架构。","options":[["A","错误"],["B","正确"]],"answer":["A"],"ans_raw":"A","explain":"判据仍是「一张图」：UML 提供用例图、类图、组件图、部署图、序列图等多种图形，恰恰说明没有哪一种图能同时表达结构、行为、部署与运行时；系统架构需要逻辑、开发、进程、物理加场景的多视图协作。前半句规范表述成立，后半句被夸大，判错误（A）。与 279 题同一判据。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-335","subject":"hcip_cloud","num":335,"pnum":111,"page":100,"type":"multi","stem":"华为云包括以下哪些种类的服务？","options":[["A","laas"],["B","Paas"],["C","解决方案服务"],["D","Saas"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"华为云按服务供给层次分为 IaaS（弹性云服务器、云硬盘、虚拟私有云）、PaaS（RDS、CCE、DCS 等）与 SaaS（开箱即用的应用类服务），故选 ABD。C 的解决方案是把多个服务按行业场景组合成的参考架构与商品包，不与这三个层次并列，属分类维度的偷换。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-336","subject":"hcip_cloud","num":336,"pnum":112,"page":101,"type":"single","stem":"云服务器级别的高可用设计关键要用到哪些云服务？","options":[["A","云硬盘备份（VBS）和对象存储服务（OBS）"],["B","云专线（DC）和弹性文件服务（SFS）。"],["C","弹性负载均衡（ELB）和弹性伸缩服务（AS）"],["D","云监控（Cloud Eye）和云容器（CCE）"]],"answer":["C"],"ans_raw":"C","explain":"云服务器级高可用靠多实例加流量分发实现：ELB 把请求分发到多台 ECS 并用健康检查剔除故障实例，AS 按策略维持实例数、故障时替换与扩容，两者配合才消除单点，故选 C。A 的 VBS/OBS 属数据备份，恢复期间服务仍不可用；B 的专线与 SFS 是网络接入与共享存储；D 的 Cloud Eye 只观测、CCE 是容器平台，均不承担实例级切换。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-337","subject":"hcip_cloud","num":337,"pnum":113,"page":101,"type":"multi","stem":"关于无状态应用和有状态应用的区别，下面哪些说法是正确的？","options":[["A","有状态应用可以通过代码改造获得更好的扩展性"],["B","无状态应用比起有状态应用具有更高的性能"],["C","无状态应用可以较方便地部署在容器里"],["D","有状态应用需要记住发起请求的具体用户"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都符合状态性差异：A 有状态应用经代码改造把会话与数据外置到缓存或数据库后即可水平扩展；B 无状态免去会话保持与状态同步开销、扩容不必做粘性路由，通常更易获得高吞吐；C 无状态容器可随时销毁重建，天然适配容器；D 有状态应用必须记住发起请求的用户上下文。B 略有争议，性能取决于实现，此处按无额外状态开销的口径成立。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"id":"hcip_cloud-338","subject":"hcip_cloud","num":338,"pnum":114,"page":101,"type":"single","stem":"关于单体应用，下面哪个说法是不正确的？","options":[["A","单体应用由于是一个部署包，部署起来比较容易。"],["B","单体应用没有向外发布的 API。"],["C","单体应用可以是经典的 web 三层逻辑架构。"],["D","传统 J2EE 应用往往是单体应用。"]],"answer":["B"],"ans_raw":"B","explain":"不正确的说法是 B：单体应用照样可以通过 HTTP/REST、WebService 等方式对外发布 API，接口是否存在与是否为单体无关，区别只在于所有功能被打包在一个部署单元内。A 单一包部署确实简单、C 表示层/业务层/数据层的经典 Web 三层可以在一个应用内、D 传统 J2EE 的 WAR/EAR 应用多为单体，三项均符合单体特征。","note":"","flag":"","source":"HCIP-Cloud Service题库.pdf","ex_src":"编写"},{"num":1,"stem":"可以列出所有数据库角色的是？","type":"single","options":[["A","\\du"],["B","dr"],["C","\\d"]],"answer":["A"],"ans_raw":"A","explain":"psql 元命令 \\du 专门列出所有数据库角色及其属性与成员关系，故选 A。易错点：\\d 列的是当前 schema 下的表/视图/序列等关系对象，看不到角色；dr 不是合法元命令，缺了前导反斜杠。记法：末尾字母即对象，u 指 user。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-1","note":"","flag":"","pnum":1,"ex_src":"编写"},{"num":2,"stem":"现有分区表 t 定义语句如下 CREATE TABLE t ( col1 integer NOT NULL, col2 character varying(60) ) PARTITION BY RANGE (col1) ( PARTITION P1 VALUES LESS THAN(5000), PARTITION P2 VALUES LESS THAN(10000), PARTITION P3 VALUES LESS THAN(15000) ); 现执行插入语句: INSERT INTO t VALUES(20000); 以下选项哪个是正确的执行结果？","type":"single","options":[["A","插入失败，原因是无法匹配到合适的分区"],["B","插入失败，原因是语法错误"],["C","插入成功，插入行位于自动新建的分区中"],["D","插入成功，插入的行位于分区 P3"]],"answer":["A"],"ans_raw":"A","explain":"RANGE 分区要求插入行的分区键值落在某个已定义分区的范围内，本例 20000 超过最大上界 15000 且表没有 DEFAULT 分区，故匹配不到分区而报错。易错点：分区不会因插入自动新建，INSERT 语句本身语法合法，落在 P3 需要该值确在 P3 区间内。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-2","note":"","flag":"","pnum":2,"ex_src":"编写"},{"num":3,"stem":"以下哪个选项为字符处理函数？","type":"single","options":[["A","Ipad"],["B","bitand"],["C","age"],["D","path"]],"answer":["A"],"ans_raw":"A","explain":"lpad 把字符串左侧填充到指定长度，属字符处理函数，故选 A。bitand 是按位与的数值函数，age 是时间函数（返回时间间隔），path 用于图路径类数据，三者都不做字符处理。题面 Ipad 只是 lpad 首字母的大小写显示差异。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-3","note":"","flag":"","pnum":3,"ex_src":"编写"},{"num":4,"stem":"如果将分区 sdd2 开机自动挂载到/mnt/file 目录下，管理员需将对应配置写入到以下哪个 配置文件中?","type":"single","options":[["A","/etc/fstab.conf"],["B","/etc/fstba.conf"],["C","/etc/fstab"],["D","/etc/fstba"]],"answer":[],"ans_raw":"","explain":"","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-4","note":"题源该题未标注答案：该题在原文里没有答案行","flag":"","pnum":4,"ex_src":""},{"num":5,"stem":"以下哪个选项不能用于 shell 循环语句的流程控制?","type":"single","options":[["A","go"],["B","for"],["C","while"],["D","until"]],"answer":["A"],"ans_raw":"A","explain":"shell 的循环结构只有 for、while、until（以及 select），配合 if/case 与 break/continue 完成流程控制，bash 语法里根本没有 go，故选 A。go 是 Go 语言的关键字与协程概念，与 shell 无关。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-5","note":"","flag":"","pnum":5,"ex_src":"编写"},{"num":6,"stem":"以下哪个选项不属于 linux 进程的特性?","type":"single","options":[["A","并发性"],["B","动态性"],["C","连续性"],["D","独立性"]],"answer":["C"],"ans_raw":"C","explain":"Linux 进程的四大特性是并发性、动态性、独立性和异步性：进程被反复创建消亡、交替处于就绪等待执行状态，执行序可中断，故不是连续推进的，选 C 连续性。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-6","note":"","flag":"","pnum":6,"ex_src":"编写"},{"num":7,"stem":"以下哪个选项是 openSSH 服务的默认端口?","type":"single","options":[["A","20"],["B","22"],["C","23"],["D","21"]],"answer":["B"],"ans_raw":"B","explain":"sshd 默认监听 22/tcp，这是 openSSH 服务的约定端口，故选 B。21 是 FTP 控制端口，20 是 FTP 主动模式的数据端口，23 是 telnet，都与 SSH 无关。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-7","note":"","flag":"","pnum":7,"ex_src":"编写"},{"num":8,"stem":"当 openEuler 系统 CPU 占用较高时，管理员可通过 top 命令和以下哪个命令配合使用， 来定位由于 wa 高导致的故障点?","type":"single","options":[["A","ps aux"],["B","sar"],["C","iotop"],["D","free"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）top 里 wa 高说明 CPU 在等 IO，要把责任定位到具体进程就得看每个进程的磁盘读写量，这正是 iotop 的用途，按原理应选 C。ps aux 只给进程的 CPU/内存快照与命令行，看不出谁在压 IO；sar 是历史统计、free 只看内存。此题答案建议复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-8","note":"","flag":"","pnum":8,"ex_src":"编写"},{"num":9,"stem":"在 openEuler 中，在应用程序启动后，可通过以下哪个命令来设置对应进程的优先级?","type":"single","options":[["A","priority"],["B","setpri"],["C","renice"],["D","nice"]],"answer":["C"],"ans_raw":"C","explain":"renice 作用于已经在运行的进程，按 PID 修改其 nice 值，故选 C。nice 是在启动命令前为新程序设定优先级，priority、setpri 不是 Linux 命令。判据看时机：进程已起用 renice，起进程用 nice。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-9","note":"","flag":"","pnum":9,"ex_src":"编写"},{"num":10,"stem":"以下哪个目录或文件的存在可以决定 openEuler 的系统引导方式?","type":"single","options":[["A","/boot/efi/EFI/openEuler/"],["B","/etc/default/grub"],["C","/etc/grub2"],["D","/sys/firmware/efi"]],"answer":["A"],"ans_raw":"A","explain":"UEFI 要从 ESP 上加载 .efi 文件，/boot/efi/EFI/openEuler/ 下有 shim、grubx64.efi 就说明系统按 UEFI 引导，该目录不存在则是 Legacy BIOS，故选 A。易错点：/sys/firmware/efi 只是内核运行期暴露的 sysfs 节点，用来判断当前是否 UEFI 启动，并不决定引导方式。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-10","note":"","flag":"","pnum":10,"ex_src":"编写"},{"num":11,"stem":"以下哪个命令可用于查看当前 shell 的后台任务?","type":"single","options":[["A","cat"],["B","jobs"],["C","vim"],["D","bg"]],"answer":["B"],"ans_raw":"B","explain":"jobs 列出当前 shell 的作业清单及前台/后台/停止状态，故选 B。bg 只是把停止的作业放到后台继续跑，不输出清单；cat、vim 与作业控制无关。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-11","note":"","flag":"","pnum":11,"ex_src":"编写"},{"num":12,"stem":"以下哪个选项不属于 openEuler 默认的 SSH 服务中必要组成部分?","type":"single","options":[["A","openssh-askpass"],["B","openssh-server"],["C","openssh"],["D","openssh-clients"]],"answer":["A"],"ans_raw":"A","explain":"openEuler 的 SSH 服务由 openssh（公共库与文件）、openssh-server（sshd 守护进程）、openssh-clients（ssh/scp/sftp）三部分构成，缺任一都不能对外提供 SSH，故选 A。openssh-askpass 只在图形环境弹窗输口令时才用到，属可选组件。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-12","note":"","flag":"","pnum":12,"ex_src":"编写"},{"num":13,"stem":"以下哪一项是 openEuler 在系统启动过程中的第一步?","type":"single","options":[["A","硬件自检"],["B","启动内核"],["C","系统引导"],["D","初始化系统"]],"answer":["A"],"ans_raw":"A","explain":"上电后固件先做 POST 硬件自检，确认 CPU、内存、显卡等设备可用，之后才依次进入系统引导、启动内核、初始化系统（systemd），故选 A。顺序记：自检、引导、内核、初始化。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-13","note":"","flag":"","pnum":13,"ex_src":"编写"},{"num":14,"stem":"以下哪个选项不属于 SSH 客户端工具?","type":"single","options":[["A","sftp"],["B","scp"],["C","rsync"],["D","ssh"]],"answer":["D"],"ans_raw":"D","explain":"（存疑）ssh 本身就是 SSH 客户端命令，说它不属于 SSH 客户端工具显然不成立；sftp、scp 同由 openssh-clients 提供，而 rsync 是独立的同步工具，只是可以借 ssh 作传输通道，按题意应选 C。请复核该题答案。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-14","note":"","flag":"","pnum":14,"ex_src":"编写"},{"num":15,"stem":"以下关于定时任务描述的选项中，哪个是正确的?","type":"single","options":[["A","可以用 at 命今设置"],["B","可以用 job 命令设置"],["C","无法使用 kll 命令杀死"],["D","可以用 crontab 命今设置"]],"answer":["D"],"ans_raw":"D","explain":"周期性定时任务由 crond 读取 crontab 设置，可按分钟到年多级调度，故选 D。at 只能安排在某个时刻执行一次的一次性任务，与题面定时（周期）任务的语义不同；job 不是调度命令，定时任务进程同样可被 kill 终止。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-15","note":"","flag":"","pnum":15,"ex_src":"编写"},{"num":16,"stem":"以下对 openGauss 数据库的全密态等值查询能力描述正确的是?","type":"single","options":[["A","数据在传输、存储和计算等阶段均是密文形式，无法解密"],["B","数据在存储时加密，在计算时由应用提供动态密钥解密后进行"],["C","数据在存储和计算时加密，在向客户端返回时解密"],["D","数据在存储时加加密，在计算时解密"]],"answer":["B"],"ans_raw":"B","explain":"全密态下数据以密文存放在库中，查询所需密钥由应用侧掌握并在会话中提供，参与运算的是该密钥下的加密值，明文只在应用侧还原，故选 B。A 的无法解密不成立（持钥者可解），C 把解密放到返回环节，D 只描述存储加密，属 TDE 而非全密态。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-16","note":"","flag":"","pnum":16,"ex_src":"编写"},{"num":17,"stem":"以下哪个工具用来让用户了解 openGauss 的负载情况?","type":"single","options":[["A","gs_collector"],["B","gs_checkperf"],["C","gs_checkos"],["D","gs_check"]],"answer":["B"],"ans_raw":"B","explain":"gs_checkperf 采集并检查数据库的性能与负载指标，用来让用户了解 openGauss 的负载情况，故选 B。gs_checkos 检查操作系统配置是否达标，gs_collector 收集日志与诊断信息，gs_check 做安装部署前环境检查，都不反映负载。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-17","note":"","flag":"","pnum":17,"ex_src":"编写"},{"num":18,"stem":"以下对 openGauss 数据库逻辑复制的特点描述正确的是?","type":"single","options":[["A","支持双主部署、将二进制日志转换为逻辑 SQL 和表级别复制"],["B","将二进制日志转换为逻辑 SQL 和支持表级别复制"],["C","支持双主部署和将二进制日志转换为逻辑 SQL 语句"],["D","支持双主部署和表级别复制"]],"answer":["B"],"ans_raw":"B","explain":"openGauss 逻辑复制把 XLOG 二进制日志解析为逻辑 SQL 在订阅端回放，复制粒度可细到表，故选 B。双主部署不在该能力范围内，凡含双主的 A、C、D 都因此不成立。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-18","note":"","flag":"","pnum":18,"ex_src":"编写"},{"num":19,"stem":"客户端连接工具 Data Studio 通过哪种驱动与 openGauss 数据库进行通信?","type":"single","options":[["A","Psycopg"],["B","ODBC"],["C","JDBC"],["D","Libpq"]],"answer":["C"],"ans_raw":"C","explain":"Data Studio 是基于 Java/Eclipse 的图形客户端，通过 JDBC 驱动与 openGauss 通信，故选 C。Libpq 是 C 语言接口、Psycopg 是 Python 接口、ODBC 走通用驱动管理器，都不是 Data Studio 的通信方式。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-19","note":"","flag":"","pnum":19,"ex_src":"编写"},{"num":20,"stem":"openGauss 采用的是什么开源协议?","type":"single","options":[["A","BSD License"],["B","GNU General Public License"],["C","Mulan PSL"],["D","MIT License"]],"answer":["C"],"ans_raw":"C","explain":"openGauss 以木兰开源许可证 Mulan PSL v2 发布，故选 C。BSD、MIT 属宽松许可，GNU GPL 属 copyleft 许可，均非 openGauss 采用的协议。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-20","note":"","flag":"","pnum":20,"ex_src":"编写"},{"num":21,"stem":"openGauss WDR snapshot 默认多长时间执行一次?","type":"single","options":[["A","60 分钟"],["B","360 分钟"],["C","120 分钟"],["D","30 分钟"]],"answer":["A"],"ans_raw":"A","explain":"WDR 依赖后台按固定周期自动抓取的快照，默认周期为 60 分钟，故选 A。30/120/360 分钟是把快照周期与保留、清理类周期混成干扰项；采集周期与保留时长可由 WDR 相关参数调整。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-21","note":"","flag":"","pnum":21,"ex_src":"编写"},{"num":22,"stem":"openGauss 安装前需要使用哪个工具检查环境是否符合安装?","type":"single","options":[["A","gs_check"],["B","gs_collector"],["C","gs_checkos"],["D","gs_checkperf"]],"answer":["C"],"ans_raw":"C","explain":"安装前用 gs_checkos 对操作系统配置、内核参数、依赖软件包等做环境预检查，故选 C。gs_check 面向安装部署后的集群检查，gs_checkperf 看性能负载，gs_collector 收集诊断信息，都不用于判断环境是否符合安装要求。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-22","note":"","flag":"","pnum":22,"ex_src":"编写"},{"num":23,"stem":"下列关于数据库事务 ACID 特性的说法不正确的是?","type":"single","options":[["A","D 指的是持久性，即事务成功后即使发生机器断电，也可以恢复到事务成功后的状态"],["B","A 指的是原子性，即事务中所有操作要么全部成功，要么全部失败"],["C","C 指的是一致性，即系统的状态只能是事务前的状态，或者事务成功后的状态，而不会出 现任何不一致的中间状态"],["D","l 指的是可用性，即数据库系统要为数据库执行提供尽可能高的可用性，确保大部分事务 可以成功的执行"]],"answer":["D"],"ans_raw":"D","explain":"ACID 里的 I 指隔离性，即并发事务互不干扰，而不是可用性，故选 D。A 持久性靠重做日志在断电后恢复到提交状态、B 原子性要么全成要么全败、C 一致性指只存在事务前或事务后状态，三项表述都对。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-23","note":"","flag":"","pnum":23,"ex_src":"编写"},{"num":24,"stem":"以下对 openGauss 三权分立说法正确的是?","type":"single","options":[["A","数据库的读写操作和管理操作由不同的角色或用户执行"],["B","数据库实例、数据库和表空间之间的职责清晰地分离"],["C","数据库管理、数据安全和数据库审计日志查看与管理的职责被分配给不同的角色或用户 D. 数据库管理员(DBA)、应用程序开发人和系统管理员各自拥有同样的权限和责任"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）三权分立是把数据库系统管理、安全管理（授权与策略）、审计管理（审计日志查看维护）三类职责分给不同角色，即选项 C 的表述；题给 A 说的是读写与管理分离，不是该特性的定义，正确项应为 C。另注：本题选项文本把 D 的内容并进了 C，题面串行，建议一并核对。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-24","note":"","flag":"","pnum":24,"ex_src":"编写"},{"num":25,"stem":"当在 openGauss 中创建或更新用户账户时，哪个选项可以提高账户的安全性?","type":"single","options":[["A","设置简单密码"],["B","允许任何 IP 地址登录"],["C","关闭密码策略检查"],["D","启用 SSL/TLS 加密连接"]],"answer":["D"],"ans_raw":"D","explain":"启用 SSL/TLS 加密连接让口令与数据在链路上不被明文窃听，故选 D。简单密码、允许任意 IP 登录、关闭密码策略检查都会削弱账户安全，与提高安全性的要求正好相反。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-25","note":"","flag":"","pnum":25,"ex_src":"编写"},{"num":26,"stem":"以下哪些是 iSulad 有那些特点?","type":"multi","options":[["A","巧"],["B","快"],["C","轻"],["D","灵"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"iSulad 定位轻量级容器引擎：代码与内存占用小即轻、巧，守护进程常驻、容器创建启动快即快，支持 CRI/gRPC 且 OCI 运行时可插拔即灵，四字特点都成立，故选 ABCD，本项无排除项。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-26","note":"","flag":"","pnum":26,"ex_src":"编写"},{"num":27,"stem":"在安装 openEuler 时，当进入安装界面后，可对以下哪些选项进行设置?","type":"multi","options":[["A","网络和主机名"],["B","软件选择"],["C","时间日期"],["D","用户环境变量"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"（存疑）进入安装界面后可设置时间与日期、软件选择、网络和主机名，另有安装目标盘、Root 口令、用户创建等，A、B、C 成立；用户环境变量是装完后由 shell 配置文件（profile 之类）负责的事，安装程序并不提供该项设置，故合理答案应为 ABC，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-27","note":"","flag":"","pnum":27,"ex_src":"编写"},{"num":28,"stem":"以下关于 openEuler 内置变量的描述中，哪些选项是正确的?","type":"multi","options":[["A","$n 表示 shell 程序(或过程)的第 n 个位置参数值，n=1..9"],["B","$*表示 shell 程序所有的位置参数组成的字符串"],["C","$#表示 shel 程序的位置参数个数"],["D","$0 表示 shell 所有参数"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"$n 取第 n 个位置参数、$* 把所有位置参数并成一个字符串、$# 是位置参数个数，A、B、C 均正确，故选 ABC。$0 表示脚本自身的名字而不是全部参数，D 错；真正表示全部参数的展开是 $* 与 $@。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-28","note":"","flag":"","pnum":28,"ex_src":"编写"},{"num":29,"stem":"以下关于 chgrp 命令的描述中，哪些选项是错误的?","type":"multi","options":[["A","指定在创建文件时进行权限掩码的预设"],["B","用于修改文件的所有者"],["C","用于对文件或目录的所属群组进行更改"],["D","用于配置文件权限"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"chgrp 的职责只有一个：修改文件或目录的所属组，C 是它的正确描述故不选。权限掩码的预设归 umask、改所有者归 chown、配置权限归 chmod，A、B、D 都不属于 chgrp，正是题目要的错误项。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-29","note":"","flag":"","pnum":29,"ex_src":"编写"},{"num":30,"stem":"以下哪些选项是 openEuler 支持的本地文件系统类型?","type":"multi","options":[["A","btrfs"],["B","ext4"],["C","nfs"],["D","xfs"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"btrfs、ext4、xfs 都是本地文件系统，openEuler 内核与配套 mkfs 工具链支持，故选 A、B、D。nfs 是网络文件系统，要挂载远端导出目录，不属本地类型。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-30","note":"","flag":"","pnum":30,"ex_src":"编写"},{"num":31,"stem":"以下哪些命令无法将分区/dev/hdb6 格式化?","type":"multi","options":[["A","mount t ext4 /dev/hdb6"],["B","format -t ext4 /dev/hdb6"],["C","mkfs -t ext4 /dev/hdb6"],["D","makefile -t ext4 /dev/hdb6"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"格式化分区只能用 mkfs（mkfs -t ext4 或 mkfs.ext4），C 确实能完成，故无法格式化的答案是 A、B、D：mount 是挂载而非格式化，format 不是 Linux 命令，makefile 是构建相关文件/工具名，均无格式化能力。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-31","note":"","flag":"","pnum":31,"ex_src":"编写"},{"num":32,"stem":"以下哪些选项属于命令 systemctl 的功能?","type":"multi","options":[["A","启动、重启、停止服务"],["B","重启、关闭系统"],["C","设置服务为开机启动"],["D","收集操作系统串口信息"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"systemctl 统一管理 unit：start/restart/stop 控制服务（A）、reboot/poweroff 控制整机（B）、enable 设置开机自启（C），故选 ABC。收集串口等硬件信息由 dmesg、journalctl 等负责，不是 systemctl 的功能，D 错。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-32","note":"","flag":"","pnum":32,"ex_src":"编写"},{"num":33,"stem":"以下哪些选项属于 SSH 客户端的配置文件?","type":"multi","options":[["A","/etc/ssh/ssh_config"],["B","~/.ssh/config"],["C","/etc/ssh/ssh_config.d/openeuler.conf"],["D","/etc/ssh/sshd_config"]],"answer":["A","B"],"ans_raw":"AB","explain":"SSH 客户端读全局 /etc/ssh/ssh_config 与用户级 ~/.ssh/config 两份配置，故选 AB。最易误选的是 /etc/ssh/sshd_config，它是服务端 sshd 的配置必须排除；ssh_config.d 下的片段要靠 Include 引入，属打包细节，不是 openEuler 默认安装的客户端主配置。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-33","note":"","flag":"","pnum":33,"ex_src":"编写"},{"num":34,"stem":"以下哪些选项中的命令功能描述是正确的?","type":"multi","options":[["A","cat /etc/fstab 可用于直看内存使用情况"],["B","lscpu 命令可用于查看 CPU 型号、数量、频率"],["C","cat /etc/os-release 可用于查看系统版本"],["D","Iscpi 命今可用于查看系统硬件信息"]],"answer":["B","C"],"ans_raw":"BC","explain":"lscpu 给出 CPU 型号、核数、频率等信息（B），/etc/os-release 记录发行版名称与版本（C），故选 BC。/etc/fstab 是挂载表，看内存要用 free 或 /proc/meminfo，A 错；D 的 Iscpi 疑为 iscsi 类命令的录入讹误，与查看硬件信息无关（该用 lshw、dmidecode 等）。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-34","note":"","flag":"","pnum":34,"ex_src":"编写"},{"num":35,"stem":"在计算机系统中，数据以二进制信息单元 0/1 形式表示","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"计算机内部一切信息（数值、字符、编码后的图形）都以二进制位的 0/1 形式存储与运算，这是冯诺依曼体系的基础，故判正确（A）。判据是硬件只有两种稳定电平，编码只是在其上约定含义。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-35","note":"","flag":"","pnum":35,"ex_src":"编写"},{"num":36,"stem":"关于 openGauss 数据库辅助线程，请判断以下哪些描述是正确的?","type":"multi","options":[["A","Pagewriter 用于将脏页数据拷贝至双写区域并落盘"],["B","AutoVacuum 主要用于统计信息，包括对象、sql、会话、锁等，存储到 pgstat.stat 文件中"],["C","Walwriter 负责将已提交的事务永久记录写入预写日志文件中"],["D","Checkpointer 用于周期性检查点，将数据脏页刷新到感盘，确保数据库一致"]],"answer":["A","B"],"ans_raw":"AB","explain":"（存疑）按 openGauss 线程职责，Pagewriter 负责脏页刷新并配合双写落盘，A 成立；Walwriter 负责把已提交事务的 XLOG 写入预写日志文件，C 成立。统计信息由独立统计线程收集并写入 pgstat 文件，AutoVacuum 主要回收死元组、防止事务 ID 回卷，B 属张冠李戴。所给 AB 应为 AC，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-36","note":"","flag":"","pnum":36,"ex_src":"编写"},{"num":37,"stem":"在 openGauss 全密态数据库中，哪些方式可以创建一个加密表?","type":"multi","options":[["A","使用 pg_dump 命今备份已有的加密表，并指定加密算法和密钥"],["B","使用 CREATE TABLESPACE 语句，指定加密算法和密钢"],["C","使用 ALTER TABLE 语句，指定加密算法和密钥"],["D","使用 CREATE TABLE 语句，指定加感算法和击调"]],"answer":["C","D"],"ans_raw":"CD","explain":"全密态的加密是列级属性：建表时在 CREATE TABLE 的列上指定加密算法与密钥，或用 ALTER TABLE 增改该列并指定，故选 C、D。pg_dump 只是导出还原既有对象的手段，CREATE TABLESPACE 管的是存储位置，都无法定义列加密。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-37","note":"","flag":"","pnum":37,"ex_src":"编写"},{"num":38,"stem":"openEuler 系统运维的愿景是: 构筑基础软件运维平台，打通智能运维”最后一公里”，逐 步实现系统运维自治.","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"该句正是 openEuler 运维给出的愿景定位：以基础软件运维平台为底座，用智能运维打通最后一公里，最终走向系统运维自治，故判正确（A）。判据是平台、智能、自治三个要素齐备，若改成以人工排障为最终目标则为错误。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-38","note":"","flag":"","pnum":38,"ex_src":"编写"},{"num":39,"stem":"iSulad 的社区主线实现的桥网络是基于 CNI 插件实现的.","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"iSulad 社区主线不自建网络栈，容器网络通过 CNI 插件配置实现，桥接网络用的就是 CNI 的 bridge 插件，故判正确（A）。判据是 iSulad 定位为轻量的 OCI/CRI 引擎，网络能力交由 CNI 生态完成。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-39","note":"","flag":"","pnum":39,"ex_src":"编写"},{"num":40,"stem":"关于 openGauss 表设计，以下哪些说法是正确的?","type":"multi","options":[["A","尽量通过聚展/局部聚族实现热数据的连续存储，将随机/O 转换为连续 I/O"],["B","对于频繁更新的 astore 表，需要制定较小的填充因子"],["C","规划好表结构设计，避免添加字段、修改李段类型或长度"],["D","COMMENT 只是注释，没有必要添加"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"聚集与局部聚簇让热数据物理连续，把随机 I/O 转为连续 I/O（A）；astore 表频繁更新要用较小填充因子，给页面预留更新空间以减少行迁移（B）；提前规划表结构可避免加字段、改类型这类重操作（C），故选 ABC。COMMENT 属数据字典内容，影响可维护性，D 错。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-40","note":"","flag":"","pnum":40,"ex_src":"编写"},{"num":41,"stem":"Data Studio 是一个集成开发环境，下列选项哪些属于 Data Studio 的特性?","type":"multi","options":[["A","执行 SQL 语句/脚本"],["B","编辑和执行 PL/SQL 语句"],["C","创建和管理数据库对象"],["D","查看 WDR 报告"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"Data Studio 作为图形化集成开发环境，可执行 SQL 语句与脚本、编辑并运行 PL/SQL、创建管理表视图等数据库对象，故选 ABC。WDR 报告由数据库侧快照与报告生成机制产出，属服务端诊断能力，不是 Data Studio 的特性。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-41","note":"","flag":"","pnum":41,"ex_src":"编写"},{"num":42,"stem":"openEuler 可以采用光盘，U 盘，虚拟光驱的方式来安装。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"openEuler 可用光盘、写入镜像的 U 盘、虚拟机挂载 ISO 的虚拟光驱三类介质安装，此外还支持网络等方式，故判正确（A）。判据是介质只要提供引导与软件仓库即可，与载体形态无关。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-42","note":"","flag":"","pnum":42,"ex_src":"编写"},{"num":43,"stem":"华为鲲鹏 920 处理器只支持 A32 指令集，不支持 A64 指令集.","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）鲲鹏 920 是 ARMv8 架构的 64 位服务器处理器，配套运行的是 aarch64 系统，A64（AArch64）正是其主要执行状态，只支持 A32、不支持 A64 把关系说反了，应为错误（B）。A32 只是可选的 32 位执行状态。请核对答案。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-43","note":"","flag":"","pnum":43,"ex_src":"编写"},{"num":45,"stem":"PG_ATTRIBUTE 存储的是表字段信息","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"pg_attribute 以每列一行记录表或视图的字段信息（列名、类型、长度、可否为空、attnum 等），故判正确（A）。判据是按 attrelid 关联 pg_class 的字段级元数据；对象级信息在 pg_class，类型定义在 pg_type。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-45","note":"","flag":"","pnum":45,"ex_src":"编写"},{"num":46,"stem":"以下哪些工具可以实现 openGauss 数据库的逻辑备份?","type":"multi","options":[["A","gs_dumpall"],["B","PITR"],["C","gs_dump"],["D","IVM 快照"]],"answer":["A","C"],"ans_raw":"AC","explain":"gs_dump 按库、表导出对象定义与数据，gs_dumpall 导出全部数据库及公共对象，两者都是逻辑备份，故选 A、C。PITR 靠基础备份加 WAL 归档做物理恢复，IVM 快照服务于物化视图增量刷新，均不属逻辑备份。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-46","note":"","flag":"","pnum":46,"ex_src":"编写"},{"num":47,"stem":"以下哪些选项对配置文件/etc/fstab 的描述是错误的?","type":"multi","options":[["A","保存硬件信息"],["B","用于管理文件系统信息"],["C","系统启动后，由系统自动产生"],["D","用于设置命名规则，是否使用可以用 TAB 来命名一个文件"]],"answer":["A","D"],"ans_raw":"AD","explain":"（存疑）/etc/fstab 是管理员手工维护的静态挂载表，记录设备、挂载点、文件系统类型与挂载选项，B 的描述正确。保存硬件信息、系统启动后自动生成、设定文件命名规则这三条都不成立：自动产生的是旧的 mtab（现为 /proc/mounts），故错误项应为 A、C、D，所给 AD 漏了 C，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-47","note":"","flag":"","pnum":47,"ex_src":"编写"},{"num":48,"stem":"哈希分区器根据表的一列，为每个分区指定楼数和余数，将要插入表的记录划分到对应 的分区中，每个分区所持有的行都需要满足条件: 分区键的值除以为其指定的模数将产生为 其指定的余数","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"哈希分区为每个分区指定模数和余数，分区键值按模数取余等于该分区指定余数的行才落入此分区，判正确（A）。判据是模与余的对应关系保证数据均匀打散；需要按边界值划分的是 RANGE 分区，别混淆。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-48","note":"","flag":"","pnum":48,"ex_src":"编写"},{"num":49,"stem":"在 openEuler 系统中，以下哪些选项是 route 命令的正确用法?","type":"multi","options":[["A","route del -net 192.168.0.1 netmask 255.255.255.0"],["B","route"],["C","route print"],["D","route add default gw 192.168.1.1"]],"answer":["B","C"],"ans_raw":"BC","explain":"（存疑）Linux 下 route 的合法用法是：不带参数直接打印路由表、route add default gw 网关 添加默认路由、route del -net 网络 netmask 掩码 删除路由，A、B、D 都成立；route print 是 Windows 的写法，Linux 看路由用 route 或 ip route show。所给 BC 含错项且漏掉正确用法，应为 ABD。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-49","note":"","flag":"","pnum":49,"ex_src":"编写"},{"num":50,"stem":"void foo(float a1, float a2, float b1, float b2, float* A) { A[0] = a1(a1 + b1); A[1] = a2*(a2 + b2); A[2] = a1(a1 + b1); A[3] = a2*(a2 + b2); } 编译后: mov v0.s[1], v1.s[0] mov v2.s[1], v3.s[0] fadd v1.2s, v0.2s, v2.2s fmul v0.2s, v1.2s, v0.2s mov v0.d[1], v0.d(0] str q0.[x0] ret 上述这种优化效果，可以使用哪个选项开启?","type":"multi","options":[["A","-02"],["B","-ftree-vectorize"],["C","-ftree-slpvectorize"],["D","-ftree-loop.vectorize"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"（存疑）题中是无循环的直线计算，向量化后形成 SLP（超字并行）指令，靠 -ftree-vectorize 打开总开关、由 -ftree-slp-vectorize 完成，核心答案应为 C；-ftree-loop-vectorize 针对循环体，本例没有循环，-O2 在多数 GCC 版本并不默认开启自动向量化。所给 ABCD 偏宽，且选项文本有 -02、-ftree-loop.vectorize 等录入讹误，建议复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-50","note":"","flag":"","pnum":50,"ex_src":"编写"},{"num":51,"stem":"在 openEuler 中，共享内存页可以换出到交换区","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"共享内存（tmpfs、SysV shm）的页属于可换出页面，内存紧张时可被回收并写入交换区，故判正确（A）。判据是它不走普通文件的回写路径；相对地，大页 hugetlb 不参与换出，mmap 普通文件的页是写回文件而非 swap。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-51","note":"","flag":"","pnum":51,"ex_src":"编写"},{"num":52,"stem":"以下关于 openGauss 数据库说法正确的是?","type":"multi","options":[["A","CM:运维管理模块:提供集群日常运维、配置管理的管理接口、工具"],["B","openGaus 主备(Datanode):负责存储业务数据(支持行存、列存、内存表存，执行数据查询 任务以及向客户端驱动返回执行结果图"],["C","客户端驱动(Client Drive)小负责接收来自应用的访问请求，并向应用返回执行结果"],["D","OM: 集群管理楼块:提供集群启停、主备切换和状态查询"]],"answer":["A","B"],"ans_raw":"AB","explain":"（存疑）openGauss 中 CM 是 Cluster Manager，负责集群启停、主备切换与状态查询；OM 是运维管理模块，提供日常运维与配置管理的接口工具，题面 A 与 D 把两者定义互换了，均不成立。Datanode 存业务数据并执行查询、Client Drive 收发请求与结果，B、C 正确，故答案应为 BC。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-52","note":"","flag":"","pnum":52,"ex_src":"编写"},{"num":53,"stem":"查看 openGauss 数据库参数有哪些方式?","type":"multi","options":[["A","show 命令"],["B","pg_settings 视图"],["C","gs.guc 工具"],["D","postgresqlconf 配置文件"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"（存疑）查看参数四条途径都可用：show 命令查单个 GUC、pg_settings 视图看运行值与来源、gs_guc 工具读取与设置、直接查看数据目录下 postgresql.conf 的静态配置，故答案应为 ABCD；题给 ABC 漏掉 D，且 C 的写法 gs.guc 应为 gs_guc，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-53","note":"","flag":"","pnum":53,"ex_src":"编写"},{"num":54,"stem":"对于目录类型的文件而言，x 权限表示指定用户可以执行该文件。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）目录的 x 是进入与遍历权限，即可以 cd 进去并访问其下的条目，而目录本身并不能作为程序被执行，按题面执行该文件的文字应为错误（B）。若原句是 x 权限表示可以进入该目录，则 A 才成立，建议据此复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-54","note":"","flag":"","pnum":54,"ex_src":"编写"},{"num":55,"stem":"视图会将数据复制一份到一个表中，并通过这个表控制用户对数据的访问","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）普通视图只保存一条 SELECT 定义，不复制数据，基表变化会即时反映到视图；真正持有数据副本的是物化视图或快照。视图靠限定可见行列来控制数据访问是对的，但会把数据复制一份到表中这一条不成立，应为错误（B）。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-55","note":"","flag":"","pnum":55,"ex_src":"编写"},{"num":56,"stem":"在数据层次模型中，节点可以有一个以上的双亲","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"层次模型用树形结构组织记录，除根节点外每个子节点有且仅有一个双亲，一个节点可以有多个孩子；允许一个节点有多个双亲的是网状模型，故判错误（B）。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-56","note":"","flag":"","pnum":56,"ex_src":"编写"},{"num":57,"stem":"CAP 理论是实现分布式系统所必需遵循的基础理论，只有满足 CAP 基本要需求的系统才 能称为分布式系统","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"CAP 只是刻画分布式存储在一致性、可用性、分区容错性之间必须做取舍的理论框架，用来指导设计，并不构成被称为分布式系统的准入条件；分布式系统的要义是多节点协同与消息传递，故判错误（B）。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-57","note":"","flag":"","pnum":57,"ex_src":"编写"},{"num":58,"stem":"以下哪些情况不支持生成 WDR 报告?","type":"multi","options":[["A","两次 Snapshot 中间有 Drop database"],["B","两次 Snapshot 中闻有 truncate table"],["C","两次 Snapshot 中间有节点重启"],["D","两次 Snapshot 中间有主备导换"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"WDR 报告完全建立在两个 Snapshot 之间的性能采集数据上，所以四种情况都断链：drop database 使快照与该库元数据一并消失；truncate table 会重建文件的 relfilenode，历史表级统计无法与新对象对齐；节点重启使采集线程中断、时间轴不连续；主备倒换后数据来自另一节点，负载视图拼不起来。故选 ABCD，无排除项。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-58","note":"","flag":"","pnum":58,"ex_src":"编写"},{"num":59,"stem":"下列哪些是属于健康检查的场景?","type":"multi","options":[["A","升级前检查"],["B","设置自动 WAL 检查点"],["C","安装 openGauss 前检查"],["D","重要操作前检查"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"（存疑）健康检查的官方用途是安装 openGauss 前、升级前以及重要操作前确认环境与集群健康状态，正确项应为 ACD。B 的设置自动 WAL 检查点是 GUC 参数配置动作，跟检查场景无关；A 的升级前检查反倒是最典型的用途。题给 BCD 含错项又漏 A，应是答案录入错位，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-59","note":"","flag":"","pnum":59,"ex_src":"编写"},{"num":60,"stem":"在 openGauss 数据库架构设计中，使用主备模式跟单机模式比有哪些好处","type":"multi","options":[["A","最大可能丢失的数据的时长 (RPO) 可以控制，系统恢复正常所需要的最大时长 RTO)可以 控制"],["B","可以实现最大可靠性，最大性能和实现最大可用性"],["C","支持多种故障转移切换和切换模式"],["D","可以进行损坏页自动修复"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"主备模式有副本与切换能力：RPO/RTO 成为可配置指标（A）、可靠与可用性提升且备机可分担只读查询（B）、支持自动手动与抢占非抢占等多种切换模式（C），故选 ABC。最易误选的 D：主备提供的是用对端副本重写坏页的修复条件，需运维定位坏页后显式发起，不是无人值守的自动修复，题按此排除；建议对照官方主备特性清单再确认措辞。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-60","note":"","flag":"","pnum":60,"ex_src":"编写"},{"num":61,"stem":"在 openEuler 中，卸载一个软件包可以使用 rpm -e 命令","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"rpm 的卸载子命令就是 -e（等价 --erase），openEuler 沿用 RPM 包体系，故判正确（A）。判据：参数给包名而非 .rpm 文件名，依赖不满足时会拒绝，需 --nodeps 才强制。日常更常用 dnf remove，但它做的是同一件事，不能据此否认 rpm -e 可用。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-61","note":"","flag":"","pnum":61,"ex_src":"编写"},{"num":62,"stem":"openEuler 22.03 LTS 版本的 SELINUX 默认关闭","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"判据看两处：getenforce 的输出与 /etc/selinux/config 里 SELINUX 的取值。openEuler 出厂未启用 SELinux 强制访问控制（不拦截或完全关闭），装数据库等软件无需先手工关策略，需要策略时由管理员改为 enforcing，故按题面判正确（A）。现场被改成 enforcing 属管理员配置，不代表默认状态。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-62","note":"","flag":"","pnum":62,"ex_src":"编写"},{"num":63,"stem":"设备直通技术指将 host 上的物理设备直接星现给一台虚拟机，虚拟机可以直接访问该 设备资源的一种使用方式，当设备克通使用的是 VFIO 方式时，按照点遇的设备类型可以分 为 PCI 直通和 SR-IOV 直通两种类型","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"VFIO 借 IOMMU 把物理功能安全地赋给虚拟机，整块设备交给一台虚机独占即 PCI 直通；把支持 SR-IOV 的设备切成多个 VF 分离直通则是 SR-IOV 直通。分类方式与定义都对，判正确（A）。题中「星现/克通/点遇」是「呈现/直通」的录入讹误，不影响判断。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-63","note":"","flag":"","pnum":63,"ex_src":"编写"},{"num":64,"stem":"StratoVirt 不支持热插拔网卡","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"判据看 VMM 有没有设备热插拔通道：StratoVirt 用 virtio 提供块与网卡设备，并支持运行期动态插拔，「不支持热插拔网卡」不成立，判错误（B）。设备模型精简、可热插的类型数量有限，属于能力受限，与「完全不支持」是两码事，别把限制当缺失。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-64","note":"","flag":"","pnum":64,"ex_src":"编写"},{"num":65,"stem":"iSulad 是否实现 CRI 接口，对接 K8S","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"iSulad 实现了 K8s 的 CRI（容器运行时接口）并对外提供服务，kubelet 可直接把它当节点运行时用，判正确（A）。判据是有没有 CRI 服务端：没有 CRI 就需 docker-shim 之类的中间层才能接 K8s；它的 CRI 通道与自身 CLI 用的接口是两回事。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-65","note":"","flag":"","pnum":65,"ex_src":"编写"},{"num":66,"stem":"openEuler 的内核热升级技术可以用于解决内核的 CVE 和 BUG","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"内核热升级/热补丁的作用对象是正在运行的内核，把修内核态缺陷的补丁在不重启业务的前提下换上，内核 CVE 与 BUG 正是它的目标场景，判正确（A）。判据只看补丁落在哪：内核树内代码可以，用户态程序与第三方驱动不在能力范围（见 67、104 题）。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-66","note":"","flag":"","pnum":66,"ex_src":"编写"},{"num":67,"stem":"openEuler 内核热补丁不支持给第三方驱动打补丁","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"热补丁框架管理的是内核构建体系内的代码，其符号、校验与版本匹配都由内核侧提供；树外的第三方驱动模块不在保障范围内，只能重装模块或重启修复，故判正确（A）。判据是补丁作用域是否在内核树内，能打的才叫热补丁对象。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-67","note":"","flag":"","pnum":67,"ex_src":"编写"},{"num":68,"stem":"openGauss 提供了两种数据类型用于支持全文检索。tsvector 类型表示为文本搜杂优的 文件格式，tsquery 类型表示文本查询","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"tsvector 保存的是文档经解析、分词、词位归一后的「为搜索优化过」的内部表示，tsquery 表达带运算符与权重的查询条件，两者用 @@ 做匹配，判正确（A）。判据是分工：一个是被检索对象的结构化形态，一个是查询表达式。题干「文件格式」应为「格式」，属录入讹误。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-68","note":"","flag":"","pnum":68,"ex_src":"编写"},{"num":69,"stem":"关于认证规则的配置，建议靠前的记录有比较严格的连接参数和比较到的认证方法","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（题干不全）关键形容词被识别丢掉（「比较到的认证方法」），而 pg_hba 按自上而下首条命中生效，靠前的记录理应既限定严格（具体库、用户、地址）又采用更强的认证方式，原文若为「强」则判正确；同库第 130 题写作「弱」，那一句应为错误。请核对原题干再定答案。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-69","note":"","flag":"","pnum":69,"ex_src":"编写"},{"num":70,"stem":"表空间用于管理数据对象，与磁盘上的一个目录对应","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"表空间是逻辑对象，创建时用 LOCATION 指定一个磁盘路径，其下对象的 data file 都落在该目录及子目录中，与磁盘目录一一对应，判正确（A）。判据是物理位置由表空间决定，逻辑名字只是映射；多个表空间也可指向同一父目录下的不同子目录。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-70","note":"","flag":"","pnum":70,"ex_src":"编写"},{"num":71,"stem":"用户创建的定时任务的信息存放在 PG PROC 中","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）pg_proc 存的是函数与过程的定义，pgproc 是共享内存里描述后端进程槽位的内部控制结构，两者都不存放定时任务。openGauss 的作业调度把任务定义、生效时间与执行用户写进作业系统表（pg_job 一类），由后台作业线程按时间触发，故应为错误（B）。请核对答案键。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-71","note":"","flag":"","pnum":71,"ex_src":"编写"},{"num":72,"stem":"DQL 用于对数据库中的数据进行操作，如插入、更新和删除","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"插入、更新、删除这三类改写数据的动作属 DML（数据操作语言），而 DQL 只指用 SELECT 把数据查出来，并不改动库里的内容，把写操作归给 DQL 不成立，判错误（B）。判据看语句动词的归属：改数据归 DML，建、改、删对象结构归 DDL，权限的授予与回收归 DCL，四类语言各管一段，不可互相顶替。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-72","note":"","flag":"","pnum":72,"ex_src":"编写"},{"num":73,"stem":"全连接会返回两个表中满足连接条件的记录，不会返回两个表中不满足连接条件的行","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"全外连接除匹配行外，还会把两侧未匹配的行都保留、对另一侧的列补 NULL，「不满足条件的行不返回」描述的是内连接，判错误（B）。判据是保留与否由连接类型决定：只有 INNER JOIN 两边都不保留非匹配行，外连接至少保留一侧。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-73","note":"","flag":"","pnum":73,"ex_src":"编写"},{"num":74,"stem":"openGauss 的几何操作符<<运算中，SELECT CIRCLE‘((0,0), 1)’ << CIRCLE’(5,0), 1)’;返同法果 为 TRUE","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"圆圈的 << 表示「严格位于左侧」，比较的是两圆在 X 轴上的投影：圆心 (0,0) 半径 1 的圆最右到 x=1，圆心 (5,0) 半径 1 的圆最左到 x=4，1<4 故结果为真，判正确（A）。判据是操作符语义而非圆心大小；两圆 X 区间一旦重叠就返回假。题干括号是录入讹误。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-74","note":"","flag":"","pnum":74,"ex_src":"编写"},{"num":75,"stem":"GaussDB(for openGauss)的分片和副本是针对哪个组件的描述?","type":"single","options":[["A","CM"],["B","CN"],["C","DN"],["D","GTM"]],"answer":["C"],"ans_raw":"C","explain":"分片与副本描述的是存算数据的 DN：数据按分布键切分、每片再以主备多份落在各 DN 上，故选 C。CN 是无状态的接入与规划执行层，不持数据；CM 负责集群启停与故障切换；GTM 提供全局事务快照，三者都谈不上分片和副本。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-75","note":"","flag":"","pnum":75,"ex_src":"编写"},{"num":76,"stem":"openGauss 所提供的全密态等值查询能力是指","type":"single","options":[["A","数据在传输、存储和计算等阶段均是文形式，无法解密"],["B","数据在存储时加密，在计算时解密"],["C","数据在存储和计算时加密，在向客户端返回时解密"],["D","数据在存储时加密，在计算时由应用提供动态密钥解密后进行"]],"answer":["C"],"ans_raw":"C","explain":"（存疑）全密态等值查询的要件是密文存储加上运算由应用侧下发的会话密钥参与，明文只在客户端还原，选项 D 才是这个描述；C 把解密放到向客户端返回的环节，等于承认库内计算之外才由服务端还原，与全密态定义不合。同库第 16 题给的是「应用提供动态密钥」一项，两处口径矛盾，本题应选 D，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-76","note":"","flag":"","pnum":76,"ex_src":"编写"},{"num":77,"stem":"可以列出所有的数据库和描述信息的是","type":"single","options":[["A","\\I"],["B","\\d"],["C","\\s"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）列出所有数据库及其描述信息（编码、属主、访问权限）的元命令是 \\l，带 + 号显示更多描述，故选 A。B 的 \\d 列的是当前 schema 下的表、视图、序列等关系对象，看不到数据库清单；\\s 是历史命令。题给 B 与 psql 实际行为不符，A 项的 \\I 是 \\l 的大小写讹误，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-77","note":"","flag":"","pnum":77,"ex_src":"编写"},{"num":78,"stem":"以下哪个选项中的命令可显示当前正在运行的服务?","type":"single","options":[["A","systemctl list-units -type service"],["B","systemctl list-units -type service -all"],["C","systemctl list-units --type service"],["D","systemctl list-units --type service –all"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）systemctl 用长选项 --type，list-units 默认只列已加载且处于活动中的 unit，因此显示正在运行的服务应选 C。加上 --all 反而把未运行的也一并列出，与「正在运行」相悖；B、D 的 -type、-all 单划线写法不是合法选项，D 还误用破折号。题给 B 应为 C，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-78","note":"","flag":"","pnum":78,"ex_src":"编写"},{"num":79,"stem":"以下哪个选项是 MBR 分区方式支持最大分区容量?","type":"single","options":[["A","2T"],["B","4T"],["C","1T"],["D","3T"]],"answer":["A"],"ans_raw":"A","explain":"MBR 用 32 位扇区计数描述分区，按 512 字节扇区算上限约 2^32×512B = 2TiB，即单分区与单盘都到 2T，故选 A。4T 是把 GPT 的容量层级混进来的干扰项，1T、3T 只是凑数；此外 MBR 只有 4 个主分区条目，超过 2TiB 的盘必须改用 GPT。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-79","note":"","flag":"","pnum":79,"ex_src":"编写"},{"num":80,"stem":"以下哪个选项不属于 iptables 的表?","type":"single","options":[["A","flter"],["B","mangle"],["C","nat"],["D","INPUT"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）iptables 的表是 filter、nat、mangle、raw 再加 security，而 INPUT 是挂在表下面的一条链（chain），不是表，所以「不属于表」的正确项应为 D。题给 A 写作 flter，只是 filter 的录入讹误，它本身确属表，不能算错误项。记法：表管策略归类，链管挂载位置。请复核该题答案。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-80","note":"","flag":"","pnum":80,"ex_src":"编写"},{"num":81,"stem":"在 openEuler 中，以下哪个符号用于创建后台执行进程?","type":"single","options":[["A","&"],["B","@"],["C","|"],["D","$"]],"answer":["A"],"ans_raw":"A","explain":"& 让命令在当前 shell 的作业表里以后台方式运行，随后可用 jobs、bg、fg 管理，故选 A。@ 只是特殊展开前缀（如数组/参数扩展里的 ${a[@]}），| 是管道、把输出接给下一个命令，$ 是变量取值前缀，三者都不会产生后台进程。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-81","note":"","flag":"","pnum":81,"ex_src":"编写"},{"num":82,"stem":"openEuler 管理员需将某文件的组外成员的权限设为只读，组内成员的权限设为读写， 所有者拥有全部权限，以下哪个选项是对应的权限值?","type":"single","options":[["A","467"],["B","476"],["C","764"],["D","674"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）权限数字的位序固定是 所有者-所属组-其他，题中要求所有者全权限 7（rwx）、组内读写 6（rw-）、组外只读 4（r--），对应 764，故选 C。A 的 467 是把三段顺序整体倒写，是最典型的错法，B、D 同样是顺序错配。题给 A 与权限定义不符，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-82","note":"","flag":"","pnum":82,"ex_src":"编写"},{"num":83,"stem":"StratoVirt 支持对接 libvirt 管理虚拟机，也支持对接 iSula 安全容器","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"StratoVirt 只做 VMM，本身不带完整管理面，上层入口可复用：既能被虚机管理框架（如 libvirt 一类的域管理层）拉起并纳管，也能作为 iSula 安全容器的底层运行时承接容器生命周期，判正确（A）。判据是它对外同时具备虚机对接与容器对接两条集成路径，而不是只服务一种场景。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-83","note":"","flag":"","pnum":83,"ex_src":"编写"},{"num":84,"stem":"系统表是 openGauss 存放结构元数据的地方，是数据库系统运行控制信息的来源","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"系统表（pg_class、pg_attribute、pg_type 等）由系统维护，存放表、列、类型、权限等结构元数据，执行计划与运行控制逻辑都从这里取信息，判正确（A）。判据是这些表只能由内核与目录操作改动，用户直接写会被拒绝；业务数据在用户表，不在系统表。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-84","note":"","flag":"","pnum":84,"ex_src":"编写"},{"num":85,"stem":"对于数据库第二范式，说法错误的是","type":"single","options":[["A","一张表存在组合主键时，其他非主键字段可以部分依赖组合键中的某字段"],["B","2NF 要求数据库表中的每个实例或行必领可以被唯一的区分"],["C","2NF 强调的是完全函数依赖"]],"answer":["A"],"ans_raw":"A","explain":"2NF 的定义正是消除非主属性对组合主键的部分依赖，A 说「可以部分依赖组合键中的某字段」与之直接相反，是错误说法，故选 A。C 的完全函数依赖就是 2NF 的核心；B 的「每行必须能被唯一区分」是 1NF 的要求，而 2NF 建立在 1NF 之上，不能算错，这是最易误选的一项。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-85","note":"","flag":"","pnum":85,"ex_src":"编写"},{"num":86,"stem":"以下关于 gs_restore 的说法，错误的是","type":"single","options":[["A","gs_restore 支持导入的文件格式包括自定义归档格式、目录归档格式和 tar 归档格式"],["B","gs_restore 在导入时，允许用户选择需要导入的内容，并支持在数据导入前对等待导入的 内容进行排序"],["C","gs.festore 支持导入到脚本文件，如果未指定身入数据库，则创建包含重建数据库所需的 SQL 语句脚本，并将其写入至文件或者标准输出，"],["D","gs_restore 支持使用-S 只导入模式定义，不导入数据"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）gs_dump 能输出自定义、目录、tar 三种归档，gs_restore 正是读这三类，所以 A 的说法与工具行为一致，判它「错误」依据不足。B 的选择性导入与导入前排序、C 未指定导入库时输出重建用 SQL 脚本、D 的 -s 只导模式定义，都是实际能力，唯一站得住的瑕疵是 D 里 -S 的大小写（应为小写 -s）。答案建议复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-86","note":"","flag":"","pnum":86,"ex_src":"编写"},{"num":87,"stem":"DATE 类型占用几个字节?","type":"single","options":[["A","16"],["B","4"],["C","12"],["D","8"]],"answer":["D"],"ans_raw":"D","explain":"openGauss 为兼容 Oracle 把 DATE 定义为同时含日期与时分秒的类型，按 8 字节存储，故选 D。B 的 4 字节是 PostgreSQL 原生 date（只到日）的宽度，是本题最易误选项；16、12 是把带时区类型或对齐开销凑出来的干扰值。记法：库内 DATE 等同无时区的时间戳。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-87","note":"","flag":"","pnum":87,"ex_src":"编写"},{"num":88,"stem":"在 openEuler 中，以下哪些是页面置换算法","type":"multi","options":[["A","FCFS"],["B","LFU"],["C","LRU"],["D","FIFO"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"页面置换算法要回答「淘汰哪一页」：LFU 看访问频次、LRU 看最久未用、FIFO 看进内存顺序，三者都属置换策略，故选 BCD。最易误选的 A（FCFS 先来先服务）是 CPU/请求调度策略，不参与选淘汰页。内核实际实现是活跃/非活跃链表等对 LRU 的近似，判断类别时仍以算法名为准。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-88","note":"","flag":"","pnum":88,"ex_src":"编写"},{"num":89,"stem":"在 openEuler 中，文件的权限 rwxr-xr-x 分别代表了文件所有者、文件所有者所属组、其 他用户对该文件所拥有的权限","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"rwxr-xr-x 的九位按 所有者-所属组-其他 三段各三位依次读，即属主 rwx、属组 r-x、其他 r-x，判正确（A）。判据是段序固定不变，数字写法 754 表达同一含义；把三段顺序颠倒是最常见错法，参见 82 题的答案键问题。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-89","note":"","flag":"","pnum":89,"ex_src":"编写"},{"num":90,"stem":"处理器缓存是动态随机访问存储器","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"处理器缓存由 SRAM 构成，靠双稳态触发器保持数据、无需刷新，才能跟得上流水线节拍；动态随机访问存储器 DRAM 是主存，要周期刷新、速度层级也低一档，判错误（B）。判据是速度与集成度的取舍：越靠近核心越用 SRAM，容量越大越用 DRAM。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-90","note":"","flag":"","pnum":90,"ex_src":"编写"},{"num":91,"stem":"在 openEuler 中，可以通过 echo $#获取传递给脚本的参数数目","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"$# 展开为位置参数的个数，echo $# 就是打印传给脚本的参数数目，判正确（A）。判据是各符号含义：$* 与 $@ 取全部参数（后者按词加引号），$? 是上一命令的退出码，$0 是脚本自身名字，都不给个数。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-91","note":"","flag":"","pnum":91,"ex_src":"编写"},{"num":92,"stem":"netfilter 通过 filter 表实现数据包过滤功能","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"netfilter 的 filter 表负责「能不能过」的裁决，下有 INPUT、FORWARD、OUTPUT 三条链，包过滤规则就写在这里，判正确（A）。判据是表的分工：filter 管放行与丢弃，nat 管地址改写，mangle 管头部修改与打标记，raw 管连接跟踪豁免。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-92","note":"","flag":"","pnum":92,"ex_src":"编写"},{"num":93,"stem":"netfilter 通过 mangle 表实现数据包修改功能","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"mangle 表按规则改写数据包的头部字段（如 TTL、TOS、给包打 MARK），即数据包修改功能，判正确（A）。判据是别把两类改动混起来：源/目的地址的转换归 nat，是否放行归 filter，只做字段加工的是 mangle。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-93","note":"","flag":"","pnum":93,"ex_src":"编写"},{"num":94,"stem":"用户若不在有效使用期内，需要重新设定账号的有效期","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"账号有效期是角色属性，起止时间在建号或改号语句里设定；当前时间落在有效期之外时登录被直接拒绝，只能由管理员重新指定有效期后恢复使用，判正确（A）。判据是三类机制互相独立：有效期过期、密码过期、账号锁定各有各的处置，改密码或解锁救不了过期。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-94","note":"","flag":"","pnum":94,"ex_src":"编写"},{"num":96,"stem":"在存储字符串时，VARCHAR(n)类型比 CHAR(n)类型更加节省空间","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"CHAR(n) 定长，内容不足用空格补齐并始终按 n 计宽；VARCHAR(n) 只按实际长度存储，另加很少的长度开销，所以在长度普遍小于 n 时更省空间，判正确（A）。判据是补齐成本：若串长总等于 n，varchar 的长度头反而略多占一点，但它不会像 char 那样保留尾部空格。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-96","note":"","flag":"","pnum":96,"ex_src":"编写"},{"num":97,"stem":"修改数据库默认表空间后，不在缺省表空间的表和索引也会受到影响","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）数据库的默认表空间只决定「新建且未显式指定表空间」的对象落盘位置，执行迁移时也只搬动原先位于旧缺省表空间的文件；已经显式建在其他表空间里的表和索引位置不变，不受影响，所以该说法应为错误（B）。题给 A 把影响范围说反了，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-97","note":"","flag":"","pnum":97,"ex_src":"编写"},{"num":98,"stem":"函数 instr(string1,string2,int1,int2)中，第二个 int 表示字符串结束匹配的位置","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"instr 的四个参数依次是原串、目标串、起始搜索位置、要匹配第几次出现，第二个 int 是 occurrence 序号而不是「结束匹配位置」，判错误（B）。判据是省略时从位置 1 开始、取第 1 次出现；instr 没有结束边界入参，需要区间语义得配合 substr、length 使用。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-98","note":"","flag":"","pnum":98,"ex_src":"编写"},{"num":99,"stem":"以下选项哪些是 StratoVirt 的核心架构?","type":"multi","options":[["A","BootLoader"],["B","OCI 兼容接口"],["C","KVM Hypervisor"],["D","MicroVM"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"StratoVirt 的架构三块是面向容器生态的 OCI 兼容接口、基于 KVM 的 Hypervisor 抽象、MicroVM（及标准 VM）的虚机形态，故选 BCD。要排除的 A：BootLoader 只是启动阶段用到的固件或引导环节，不是这个 VMM 自身的模块划分，别把启动流程和架构层次混在一起。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-99","note":"","flag":"","pnum":99,"ex_src":"编写"},{"num":100,"stem":"哈佛结构是将程序指令和数据分开存储的存储器结构","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"哈佛结构把指令存储与数据存储分成两套空间和总线，取指与访存可以并行，判正确（A）。判据是有无独立总线：冯·诺依曼结构指令与数据共用同一存储与通道，取指和数据访问互相争用；现代 CPU 把 L1 拆成 i-cache 与 d-cache，正是哈佛思路的落地。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-100","note":"","flag":"","pnum":100,"ex_src":"编写"},{"num":101,"stem":"在 openEuler 中，虚拟内存管理的实现必须需要相应的硬件支持","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"虚拟内存依赖 MMU 做地址翻译、页表遍历与 TLB 缓存，访问不在场的页时由硬件产生缺页异常交内核补页，没有这些硬件机制就无从实现，判正确（A）。判据是地址翻译是否由硬件完成；纯软件模拟理论上可行，但不是内核走的常规路径。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-101","note":"","flag":"","pnum":101,"ex_src":"编写"},{"num":102,"stem":"在 openEuler 中，页表的作用仅仅是实现逻辑地址到物理地址的映射","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"页表项除物理页号外还有存在位、读写执行等权限位、dirty 与 accessed 位、大页与缓存属性位，缺页处理、内存保护、共享控制和置换依据都来自它，「仅仅是映射」太窄，判错误（B）。判据是越权访问触发的保护错误同样由页表位决定，映射只是其中一项职能。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-102","note":"","flag":"","pnum":102,"ex_src":"编写"},{"num":103,"stem":"iSulad 客户端和服务端通信方式只支持 GRPC","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"gRPC 是 iSulad 客户端与守护进程之间的主通道，但它同时提供 REST/HTTP 风格的接口、CRI 也走独立的服务通道，「只支持 GRPC」把接口面说窄了，判错误（B）。判据是能否用非 gRPC 的调用方接入同一守护进程，答案是可以。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-103","note":"","flag":"","pnum":103,"ex_src":"编写"},{"num":104,"stem":"openEuler 的内核热升级可以用于解决用户态软件的 CVE 和 BUG","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）内核热升级的补丁对象是内核代码，用户态软件自身的 CVE 与 BUG 只能通过升级对应软件包（必要时重启该服务）解决，热补丁改不到进程的地址空间和库实现，应为错误（B）。题给 A 与第 66 题划定的能力边界正好冲突，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-104","note":"","flag":"","pnum":104,"ex_src":"编写"},{"num":105,"stem":"数据库是指长期存储在计算机内、有组织、可共享的大量的数据的集合","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"该句即数据库的标准定义：长期存储在计算机内的、有组织的、可共享的大量数据的集合，并由 DBMS 统一管理，判正确（A）。判据是三个限定词齐备：长期存储（非临时结果）、有组织（结构化描述）、可共享（多用户多用途），缺一个就不完整。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-105","note":"","flag":"","pnum":105,"ex_src":"编写"},{"num":106,"stem":"openGauss 数据库只能采用分布式架构进行部署","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"openGauss 既可集中式单机部署，也可主备或分布式部署，单机是官方给出的小规模与入门形态，「只能分布式」不成立，判错误（B）。判据是同一套内核按部署规划可选形态，架构选择取决于可用性、容量需求，不是产品限制。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-106","note":"","flag":"","pnum":106,"ex_src":"编写"},{"num":107,"stem":"一键式收集工具，根据生产环境中问题的不同，从生产环境中获取不同的的信息，从 而提高问题定位定界的效率","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"一键式收集工具会按问题类型选择采集项：性能类、故障类、备份类、集群状态类场景各取不同日志与诊断数据，避免全量抓取，从而缩短定位定界时间，判正确（A）。判据是它的价值就在「按场景取数」，若不管什么问题都拉同一套数据，就谈不上效率提升。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-107","note":"","flag":"","pnum":107,"ex_src":"编写"},{"num":108,"stem":"设置是否开启虚拟索引功能的参数为 enable_hypo_index","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"虚拟索引只在优化器估算里存在、不建实际索引结构，由 enable_hypo_index 控制是否允许创建与使用，判正确（A）。判据看参数名的语义指向：hypo 即 hypothetical，关闭时创建虚拟索引的接口直接报错，也就无法用它试算索引效果。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-108","note":"","flag":"","pnum":108,"ex_src":"编写"},{"num":109,"stem":"order by 语句默认按照降序对记录进行排序，如果希望按照升序对记录进行排序，需 要使用 asc","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"ORDER BY 省略方向时就是升序，要降序才写 DESC，题干把默认方向说成降序，判错误（B）。判据是默认值方向；另外升序默认 NULLS LAST、降序默认 NULLS FIRST，别把默认方向与空值位置两件事混为一谈（见 110 题）。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-109","note":"","flag":"","pnum":109,"ex_src":"编写"},{"num":110,"stem":"在不指定 NULLS FIRST 和 NULLS LAST 关键字的时候，ASC 默认为 NULLS LAST，DESC 默 认为 NULLS FIRST","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"openGauss 把 NULL 视为大于任何值，所以 ASC 时 NULL 落在末尾（NULLS LAST）、DESC 时落在开头（NULLS FIRST），不写关键字就是这个默认，判正确（A）。判据是 NULL 的大小约定；想让 NULL 始终在最前或最后，需显式加 NULLS FIRST/LAST 覆盖默认。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-110","note":"","flag":"","pnum":110,"ex_src":"编写"},{"num":111,"stem":"为了获 tpcds 频式中 customer_addres 表的统计信息，使用 select relname, relpages, reltuples from pg class where relname = 'tpcds.customer address'可以直查询到结果","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"pg_class 的 relname 只存对象名本身、不含模式前缀，条件写成 'tpcds.customer_address' 匹配不到任何行，直接查是空结果，判错误（B）。判据是模式归属在 relnamespace，正确做法是 relname='customer_address' 并用 relnamespace 或关联 pg_namespace 限定；另外 relpages、reltuples 要有值还得先 ANALYZE。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-111","note":"","flag":"","pnum":111,"ex_src":"编写"},{"num":112,"stem":"A-Tune 支持使用 python2 或 python3 运行代码","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"判据看运行依赖：A-Tune 的引擎与采集脚本没有绑定单一解释器主版本，Python 2 与 Python 3 环境都能启动，openEuler 上只有 python3 也照样可用，故判正确（A）。若题干改成「必须使用 python2」或「只能用 python3」，则为错误。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-112","note":"","flag":"","pnum":112,"ex_src":"编写"},{"num":113,"stem":"在为 openEuler 创建新用户时，以下哪个选项可以为新增用户指定家目录","type":"single","options":[["A","-u"],["B","-c"],["C","-d"],["D","-p"]],"answer":["C"],"ans_raw":"C","explain":"useradd 的 -d 指定 home directory，建号时把家目录写成给定路径，故选 C。易错点集中在其余三项：-u 是 UID，-c 是 GECOS 备注字段，-p 接受的是已经加密好的口令串（明文填入反而会把密文当密码存），都与家目录无关。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-113","note":"","flag":"","pnum":113,"ex_src":"编写"},{"num":114,"stem":"Linux 文件权限由四部分组成，以下哪一项是第三部分所表示的权限?","type":"single","options":[["A","其他用户的权限"],["B","文件所有者的权限"],["C","文件类型"],["D","文件所有者所在组的权限"]],"answer":["D"],"ans_raw":"D","explain":"ls -l 的十个字符按 文件类型 + 属主 + 属组 + 其他 四段来读，第三段（第 4 到 6 位）表示文件所有者所在组的权限，故选 D。易错点是段数从第 1 位起算：这样 A 是第四段、B 是第二段、C 是第 1 位的类型位，都不是第三段。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-114","note":"","flag":"","pnum":114,"ex_src":"编写"},{"num":115,"stem":"商店想根据商品价格对商品信息表进行分区，哪种分区表最符合使用场景?","type":"single","options":[["A","间隔分区表"],["B","列表分区表"],["C","范围分区表"]],"answer":["C"],"ans_raw":"C","explain":"商品价格是连续取值的数值区间，按 0-100、100-500 这类边界划分最贴合，用 RANGE 范围分区，故选 C。列表分区要求分区键是离散、可枚举的具体值，价格不适用；间隔分区按固定步长自动生成分区，主要面向时间列的滚动归档场景，与价格档位这种人为边界不符。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-115","note":"","flag":"","pnum":115,"ex_src":"编写"},{"num":116,"stem":"数据库的逻辑操作符中，以下哪个操作符运算优先级最低","type":"single","options":[["A","NOT"],["B","OR"],["C","AND"]],"answer":["B"],"ans_raw":"B","explain":"逻辑操作符的优先级是 NOT 高于 AND、AND 高于 OR，最低的是 OR，故选 B。混合条件里先算 NOT 再算 AND 最后算 OR，要改变求值顺序必须加括号，按书写顺序从左到右算是最常见的错因；A 的 NOT 恰恰是最高优先级。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-116","note":"","flag":"","pnum":116,"ex_src":"编写"},{"num":117,"stem":"下列哪个选项表示依赖该 Data Source 的对象存在，则该 Data Source 无法删除","type":"single","options":[["A","RESTRICT"],["B","CASCADE"],["C","src_name"],["D","IF EXISTS"]],"answer":["A"],"ans_raw":"A","explain":"RESTRICT 的语义就是「仍有对象依赖它时拒绝删除并报错」，正好对应题面，故选 A。CASCADE 反其道而行，会连依赖对象一起删掉；src_name 只是数据源的名称参数，不涉及删除策略；IF EXISTS 只决定对象本身不存在时要不要报错，与依赖无关。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-117","note":"","flag":"","pnum":117,"ex_src":"编写"},{"num":118,"stem":"以下哪个类型用来存储变长大对象二进制数据","type":"single","options":[["A","BLOB"],["B","RAW"],["C","CLOB"],["D","BYTE"]],"answer":["A"],"ans_raw":"A","explain":"BLOB 是变长二进制大对象类型，图片、音视频、文件字节流这类非文本内容存它，故选 A。易错项是 RAW：它同样是变长二进制，但定位是普通列而非大对象，容量层级与访问方式不同；CLOB 是字符大对象，BYTE 是单字节整型，都不能存大对象二进制数据。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-118","note":"","flag":"","pnum":118,"ex_src":"编写"},{"num":119,"stem":"删除学生表中学生年龄小于 15 或者学生 id 小于 20 的学生的全部信息，下面 SQL 语句 正确的是?","type":"single","options":[["A","DELETE FROM students ON age<15 OR id<20"],["B","DELETE FROM students WHERE age<15 OR id<20"],["C","DELETE * FROM students WHERE age<15 OR id<20"],["D","DELET FROM students ON age<15 OR id<20:"]],"answer":["B"],"ans_raw":"B","explain":"删除行要用 DELETE FROM 表 WHERE 条件，「或」用 OR 连接两个条件，故选 B。A、D 把条件写在 ON 后面，DELETE 语句没有这种形式，必须用 WHERE；C 的 DELETE * 混进了 SELECT 的星号写法，语法非法；D 还把 DELETE 拼成 DELET 并多出行尾符号。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-119","note":"","flag":"","pnum":119,"ex_src":"编写"},{"num":120,"stem":"以下哪个判断语句的使用方式是错误的?","type":"single","options":[["A","[-w $file]用来判断以变量$file 的值为名称的文件是否存在并可写"],["B","[-f $file]用来名称为$file 的目录是否存在"],["C","[-x $file]用来判断以变量$file 的值为名称的文件是否存在并可执行"],["D","[-r $file]用来判断以变量$file 的值为名称的又件是否存在并可读"]],"answer":["B"],"ans_raw":"B","explain":"-f 的语义是「存在并且是普通文件」，用它判目录恒为假，判断目录该用 -d，所以 B 的用法错误，故选 B。A、C、D 与 -w（可写）、-x（可执行）、-r（可读）的实际含义一致，都是 test 的文件测试算子，只是判定的动作不同。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-120","note":"","flag":"","pnum":120,"ex_src":"编写"},{"num":121,"stem":"以下哪些因素，保证了 openEuler 内核热升级前后，网络链接的平稳恢复?","type":"multi","options":[["A","设置防火墙规则，使被升级的内核处于\"静默”状态，避免发出 reset 包。"],["B","通过网络发送通知，告诉相关的通信终端，当前内核将开始热升级"],["C","保证整个升级，状态恢复过程足够快，避免触发相关通信终端的超时机制"],["D","通过网络发送通知，告诉相关的通信终端，当前内核已经结束热升级"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）本题是多选却只给 B，且该说法不成立：内核热升级不会向通信对端发「开始/结束」通知，TCP 对端也不感知，B、D 都没有对应机制。真正让连接平稳恢复的是 A（用防火墙规则让被替换的内核静默、不再回 reset 包）与 C（切换与状态恢复过程足够快，避开对端重传与超时），应为 AC，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-121","note":"","flag":"","pnum":121,"ex_src":"编写"},{"num":122,"stem":"在 openEuler 中，SLAB 分配器可以分配小块内存来减少页内碎片","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"伙伴系统按 2 的幂次页来分配，内核里大量几十字节的结构体若各占一页会浪费页内空间；SLAB 在页之上按对象大小切缓存并复用，正为解决小块分配的页内碎片，判正确（A）。判据是分配粒度：页级归伙伴，页内小对象归 SLAB/SLUB，它还顺带提供初始化与缓存复用。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-122","note":"","flag":"","pnum":122,"ex_src":"编写"},{"num":123,"stem":"在 openEuler 中全局变量是效率最高的进程间通讯方式","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"进程各有独立地址空间，所谓「全局变量」只在本进程内可见，跨进程根本读不到，连通讯都谈不上，判错误（B）。判据是必须经内核提供共享通道：共享内存因省去用户态之间的数据拷贝通常最快，管道、消息队列、socket 都要复制数据。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-123","note":"","flag":"","pnum":123,"ex_src":"编写"},{"num":124,"stem":"AArch64 外理器架构的硬件辅助虚拟化技术是 VT-x","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"VT-x 是 Intel x86 平台的硬件虚拟化扩展；AArch64 的硬件辅助虚拟化由 ARM 虚拟化扩展提供，即 EL2 异常等级与 stage-2 地址翻译，判错误（B）。判据是架构与特性名的对应：AMD 对应 AMD-V，Intel 对应 VT-x，ARM 看 EL2，跨架构套用即为错。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-124","note":"","flag":"","pnum":124,"ex_src":"编写"},{"num":125,"stem":"iSulad 支持 OCIruntime 吗","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"iSulad 按 OCI 规范实现容器运行时接口，镜像格式与容器行为遵循 OCI，运行时可插拔（如 runc、kata 等），判正确（A）。判据是它的定位就是轻量的 OCI 引擎：容器语义不绑死某一实现，才能既接 CRI 又接自有 CLI 与 REST 接口。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-125","note":"","flag":"","pnum":125,"ex_src":"编写"},{"num":126,"stem":"使用 A-Tune 可以对应用运行的时间数据进行采集，如 mysql 的启动时间数据、nginx 发送 1000 条指令需要的时间等","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"A-Tune 的采集层除系统 CPU、内存、IO 指标外，也采集应用运行过程中的耗时类时序数据（服务启动耗时、请求处理时长等），并用这些时间数据做场景识别与调优评价，判正确（A）。判据是可调优对象是否包含应用运行时行为；mysql、nginx 只是举例，不构成类型限制。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-126","note":"","flag":"","pnum":126,"ex_src":"编写"},{"num":127,"stem":"A-Tune 上游社区地址为 https://github.com/openeuler/A-Tune.git","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"判据是仓库归属：openEuler 项目的上游代码仓在 openEuler 社区自己的托管组织下，A-Tune 的提交、issue、发布都走那里，GitHub 侧只是镜像，把 github.com 地址说成上游不成立，判错误（B）。核对方法很简单：看哪个仓库接受贡献与版本发布，镜像仓只被动同步。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-127","note":"","flag":"","pnum":127,"ex_src":"编写"},{"num":128,"stem":"openEuler 内核热补需要重启内核","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"热补丁的设计目标就是在系统持续运行的前提下替换有缺陷的内核代码，不需要重启内核或机器，判错误（B）。判据是「热」字的作用域：凡是需要重启才能生效的修复属常规升级，不在热补丁能力内；热补只对运行中的内核生效，也正因为如此它才免去重启。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-128","note":"","flag":"","pnum":128,"ex_src":"编写"},{"num":129,"stem":"DBMS 的主要目的是提供一种可以方便，高效地存取数据库信息的途径","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"DBMS 是位于操作系统与应用之间的数据管理软件层，其目的正是提供方便、高效存取数据库数据的途径，同时负责安全性、完整性与并发控制，判正确（A）。判据是职责边界：数据的物理组织与访问路径由它管理，业务逻辑仍由应用承担。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-129","note":"","flag":"","pnum":129,"ex_src":"编写"},{"num":130,"stem":"关于认证规则的配置建议靠前的记录有比较严格的连接参数和比较弱的认证方法","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）pg_hba 按自上而下取首条命中规则生效，所以靠前的记录既要连接参数严格（限定具体库、用户、地址），也要采用更强的认证方法；把弱方法（例如无需口令）放在前面，宽松匹配会先放行后续连接，安全性反而更差。故该说法应为错误（B），题给 A 与第 69 题口径冲突，请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-130","note":"","flag":"","pnum":130,"ex_src":"编写"},{"num":131,"stem":"在删除一个表空间之前，表空间里面不能有任何数据库对象，否则会报错","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"（存疑）DROP TABLESPACE 不会连带清理其中的对象：表空间里仍有表、索引等对象，或被某个数据库用作默认表空间时，语句直接报错，必须先把对象迁走或删空才能删除，题干说法成立，应为正确（A）。对比第 137 题的 DROP SCHEMA，差别就在表空间没有 CASCADE 可用。题给 B 请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-131","note":"","flag":"","pnum":131,"ex_src":"编写"},{"num":132,"stem":"在 openGauss 在操作与维护阶段，应严禁修改数据目录下文件名和权限","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"数据目录下的文件名、目录结构与权限由内核按固定约定读写，改名会让实例找不到文件，放宽权限会使内核拒绝启动，还可能连带破坏主备复制与备份恢复，运维阶段必须禁止此类手工改动，判正确（A）。判据是这些属性属系统内部约定而非可调项，需要调整只走官方工具与参数。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-132","note":"","flag":"","pnum":132,"ex_src":"编写"},{"num":133,"stem":"gs_dumpall 工具由操作系统用户 omm 执行","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"gs_dumpall 要读取所有数据库的对象定义与公共元数据（角色、表空间等），并按 openGauss 的运维口径以数据库管理操作系统用户 omm 身份执行，判正确（A）。判据是权限来源：omm 既有数据库侧的超级用户身份，也能访问数据目录与工具本身；换成普通 OS 用户往往连文件都读不到。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-133","note":"","flag":"","pnum":133,"ex_src":"编写"},{"num":134,"stem":"全密态数据库让云数据库借助全密态能力更好的遵守个人隐私保护方面的法律法规","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"全密态让数据在库内始终保持密文、密钥由数据所有者掌握，数据库管理者与运维人员看不到明文，敏感个人信息因此获得技术层面的保护，有助于满足隐私保护类法规要求，判正确（A）。判据是信任边界是否收紧：服务商只做计算不做解密，正是这类法规所要求的措施之一。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-134","note":"","flag":"","pnum":134,"ex_src":"编写"},{"num":135,"stem":"ANALYZE 支持的表类型只有行存表","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"ANALYZE 为代价模型收集表与列的统计信息，行存表和列存表都支持，列存还会按列采样，「只有行存」不成立，判错误（B）。判据是统计信息服务于优化器选计划，与数据的存储形态无关；把两者绑在一起是对 ANALYZE 适用范围的误读。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-135","note":"","flag":"","pnum":135,"ex_src":"编写"},{"num":136,"stem":"左连接会把左边的表中没有记录的字段位置填上 NULL","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"左外连接保留左表全部行，补 NULL 的是右表来源的那些列，而不是给左表自己的列填空，判错误（B）。判据是「被保留表之外的另一侧」才补 NULL；若左表某列本身就是 NULL，那是数据取值，与连接行为无关，右外连接同理方向相反。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-136","note":"","flag":"","pnum":136,"ex_src":"编写"},{"num":137,"stem":"tpcds 模式中存在表 customer，不能成功删除 tpcds 模式是","type":"single","options":[["A","drop schema tpcds"],["B","drop schema tpcds cascade"],["C","drop table tpcds.customer; drop schema tpcds"]],"answer":["A"],"ans_raw":"A","explain":"drop schema 不带 CASCADE 时，模式内还有表等对象就直接报错，所以 A 不能成功删除 tpcds，选 A。B 加 cascade 会连同其中的表一并删除，能成功；C 先把 tpcds.customer 删掉再删模式，此时模式已空，同样能成功。易错点是把 C 当成多余步骤而漏选。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-137","note":"","flag":"","pnum":137,"ex_src":"编写"},{"num":138,"stem":"要求只把两个表中所有满足连接条件的数据记录返回，应该使用如下哪种连接","type":"single","options":[["A","内连接"],["B","右外连接"],["C","全外连接"],["D","左外连接"]],"answer":["A"],"ans_raw":"A","explain":"只返回两表中都满足连接条件的行，正是内连接的定义，故选 A。左外连接会额外保留左表未匹配行、右外连接保留右表未匹配行、全外连接两侧都保留，未匹配处对侧列补 NULL，多出的这些行都不符合「只返回满足条件」的要求。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-138","note":"","flag":"","pnum":138,"ex_src":"编写"},{"num":139,"stem":"StratoVirt 支持哪些硬件架构","type":"single","options":[["A","aarch64"],["B","x86"],["C","sw_64"],["D","riscv"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）A 项 aarch64 确实支持，但作为单选并不严谨：StratoVirt 当前同时支持 aarch64 与 x86_64 两类架构，社区还在扩展其他指令集，按现行能力 A、B 都成立，只有 sw_64 不在其支持清单内。判据应看官方架构支持列表，本题建议改成多选或复核答案键。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-139","note":"","flag":"","pnum":139,"ex_src":"编写"},{"num":140,"stem":"Samba 服务器只能充当文件共享服务器","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"Samba 除了文件共享还提供打印机共享，可作 NetBIOS/SMB 客户端访问远端共享，还能承担 Active Directory 域控制器或域成员角色，「只能充当文件共享服务器」把能力说窄了，判错误（B）。判据是进程分工：smbd 提供文件与打印服务，nmbd 负责名称解析与浏览，加上 AD DC 能力，功能不止一项。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-140","note":"","flag":"","pnum":140,"ex_src":"编写"},{"num":141,"stem":"广播地址是指到达网段上所有主机的地址","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"广播地址是主机位全部为 1 的地址，发往它的数据链路层帧会被同一网段内所有主机接收并交给上层判断，判正确（A）。判据是广播范围等于广播域：路由器不会把链路层广播转发到别的网段；主机位全 0 的那个地址是网络地址，不是广播地址。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-141","note":"","flag":"","pnum":141,"ex_src":"编写"},{"num":142,"stem":"在 openEuler 中，当进程运行遇到 I/O 等待时，进程状态会由运行态切换到就绪态","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"（存疑）进程遇到 I/O 等待时是让出 CPU 进入阻塞（等待）态，等事件完成才被置为就绪、再参与调度；就绪态的含义是已具备运行条件、只差 CPU，不是差 I/O，应为错误（B）。判据看它还缺什么：缺事件是阻塞，缺 CPU 才是就绪。题给 A 请复核。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-142","note":"","flag":"","pnum":142,"ex_src":"编写"},{"num":143,"stem":"StratoVirt 最大支持 512 个 CPU","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"StratoVirt 定位为轻量级 VMM 与安全容器运行时，单虚机的 vCPU 规格上限远小于 512，这种数百核的单机规格属传统虚拟化与裸金属扩容的目标场景，判错误（B）。判据是设计取向而非具体数字：上限随版本与机型定义，复习时抓住「小规格、快速启动」即可，不必记数值。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-143","note":"","flag":"","pnum":143,"ex_src":"编写"},{"num":144,"stem":"A-Tune 采集模块 (A-Tune-Collector)可以作为信息采集工具单独部署和使用","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"A-Tune-Collector 只负责按场景配置采集系统与应用的 KPI 并落盘或上报，是独立进程、由配置文件驱动，可单独部署当信息采集工具用，不绑定调优引擎，判正确（A）。判据是模块边界：采集与决策分离，决策与下发由引擎完成，采集侧本身可独立运行。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-144","note":"","flag":"","pnum":144,"ex_src":"编写"},{"num":145,"stem":"同一个 LIBC 库，在不同进程地址空间中，一定都占据相同的地址段","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"共享库以位置无关代码编译，加载基址由内核按 ASLR 随机化，同一份 libc 在不同进程的地址空间里映射段通常各不相同，「一定相同」不成立，判错误（B）。判据是只有关闭 ASLR 或使用非位置相关的加载方式时地址才固定；地址不同并不浪费内存，文件页仍是共享物理页的。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-145","note":"","flag":"","pnum":145,"ex_src":"编写"},{"num":146,"stem":"用户可以借助 openEuler Devkit 下具套件完成软件迁移","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"正确","explain":"openEuler DevKit 是迁移与开发辅助套件，可分析软件的依赖与兼容性、提示架构差异并给出移植建议，用来支撑从其他发行版或 x86 向 aarch64 的软件迁移，判正确（A）。判据是工具定位：它做的是迁移分析与构建辅助，迁移结果仍需回归测试验证。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-146","note":"","flag":"","pnum":146,"ex_src":"编写"},{"num":147,"stem":"创建新用户时，需要限制用户的有效开始时间，不需要限制有效结束时间","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"有效期是起止两个时间点组成的区间：只设开始时间而不设结束时间，等于账号永久可用，权限无法按期回收，正确做法是起止都限制，判错误（B）。判据是生命周期管理要能自动到期收敛访问权，缺结束时间就失去到期这一环，与第 94 题的过期重设是同一机制的两端。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-147","note":"","flag":"","pnum":147,"ex_src":"编写"},{"num":148,"stem":"SMALLINT 类型占用 1 字节","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"错误","explain":"SMALLINT 是 2 字节短整型，取值范围 -32768 到 32767，不是 1 字节，判错误（B）。判据是按位宽排布：1 字节的是单字节整型（TINYINT 一类，需类型支持），SMALLINT 2 字节、INT4 4 字节、BIGINT 8 字节，把类型名与字节数错配是本题的失分点。","source":"ICT大赛-计算赛道（最新省赛题库）.pdf","subject":"ict_calc","id":"ict_calc-148","note":"","flag":"","pnum":148,"ex_src":"编写"},{"num":1,"stem":"以下关于华为RAID2.0+技术，描述正确的是：","type":"multi","options":[["A","硬盘域中每个存储层的硬盘类型相同"],["B","硬盘的空间被划分成固定大小的块"],["C","用户可以为存储池（storage pool）中的每一个存储层分别设置“RAID 策略”"],["D","grain 作为数据迁移的最小粒度和构成Thin LUN 的基本单位"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"OceanStor 存储系统会将 Chunk Group（CKG）切分为更小的 Extent。Extent 作为数据迁移的最小粒度和构成Thin LUN 的基本单位，默认为 4MB。对于 Thin LUN 或文件系统， 会在 Extent 上再进行更细粒度的划分（Grain），并以 Grain 为单位映射到Thin LUN、文件系统。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-1","note":"","flag":"","pnum":1,"ex_src":"题源"},{"num":2,"stem":"以下哪些选项不是FC SAN 环境中必须的组件：","type":"multi","options":[["A","存储设备"],["B","FC 交换机"],["C","FC HBA"],["D","Windows 操作系统"]],"answer":["B","D"],"ans_raw":"BD","explain":"选 B、D。FC SAN 的必备三要素是主机侧 FC HBA、FC 链路与存储设备，A、C 属于必须有。FC 交换机只在组 Fabric 时用到，主机与存储点对点直连时并不需要它；Windows 更不是前提，Linux、AIX 等系统同样能接入 FC SAN，操作系统与 SAN 是否成立无关。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-2","note":"题源原解析（排版截断）：“当主机与存储点对点时不需要 FC 交换机。”","flag":"","pnum":2,"ex_src":"编写"},{"num":3,"stem":"SmartThin 是华为OceanStor V3 存储系统提供的一项按需分配存储资源的存储空间管理技术，基于虚拟化技术，SmartThin 减少了物理存储资源的部署，最大限度的提高了存储空间的利用率。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。SmartThin 即精简配置，靠存储虚拟化先给出逻辑容量、只在主机真正写入的块上分配物理空间，因此能减少初期落盘的物理盘数，并把空间利用率按实际用量提上去。判据落在「按需分配」：只要不是预先分配全部空间，题干中减少部署、提高利用率两项表述就都成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-3","note":"","flag":"","pnum":3,"ex_src":"编写"},{"num":4,"stem":"以下关于华为RAID 2.0+技术中的硬盘域的描述，错误的是：","type":"single","options":[["A","一个硬盘域是一组硬盘"],["B","一个硬盘只能属于一个硬盘域"],["C","OceanStor V3 存储系统可以创建一个或多个硬盘域"],["D","硬盘域中，硬盘的类型是相同，硬盘的大小和转速需要保持一致"]],"answer":["D"],"ans_raw":"D","explain":"在一个硬盘域中，同种类型的硬盘构成一个存储层，每个存储层内部再按一定的规则划分为 Disk Group，没有要求硬盘的大小和转速需要保持一致。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-4","note":"","flag":"","pnum":4,"ex_src":"题源"},{"num":5,"stem":"云计算的商业模式有：","type":"multi","options":[["A","IaaS"],["B","PaaS"],["C","SaaS"],["D","MaaS"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"选 ABC。云计算的商业模式即三种服务模型：IaaS 交付算力、存储、网络等基础设施，PaaS 交付开发与运行平台，SaaS 交付可直接使用的应用。D 的 MaaS 是把模型当服务售卖的叫法，随 AI 服务出现，不属于该体系下云计算的商业划分。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-5","note":"","flag":"","pnum":5,"ex_src":"编写"},{"num":6,"stem":"华为OceanStor V3 SmartTier 特性可用于将数据放置到指定的磁盘类型上。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。SmartTier 按数据访问热度在高性能层与容量层之间搬移数据，而哪些盘构成高优先层、哪些构成低优先层由管理员指定，所以配置上确实能把数据引导到指定磁盘类型上。判据：冷热判定归 SmartTier，磁盘类型到层的映射归配置，两半合起来才支撑该说法。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-6","note":"","flag":"","pnum":6,"ex_src":"编写"},{"num":7,"stem":"下面关于CIFS 和 NFS 共享，描述不正确的是：","type":"multi","options":[["A","CIFS 是一个基于网络共享的协议，对网络传输的可靠性有较高的要求，所以通常采用 TCP 协议进行传输"],["B","CIFS 的一个缺点是Windows 客户端必须安装专业的软件"],["C","NFS 是一个无状态的协议，而 CIFS 是一个有状态的协议，NFS 可以从链路故障中自动恢复，而 CIFS 不能"],["D","无论CIFS 或NFS 协议，都需要客户端进行文件格式转换"]],"answer":["B","D"],"ans_raw":"BD","explain":"题干选不正确的，故 B、D。B 错在 Windows 原生自带 SMB/CIFS 客户端，不需要装专业软件；D 错在文件语义与格式转换由 NAS 设备侧的文件系统完成，客户端不做格式转换。A、C 是正确表述：CIFS 依赖 TCP 保证可靠传输，且为有状态协议，链路故障后不能像无状态的 NFS 那样自动恢复。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-7","note":"","flag":"","pnum":7,"ex_src":"编写"},{"num":8,"stem":"某银行将上线一套业务系统，对性能和安全性要求都非常高，数据库采用了 Oracle 数据库，并计划将 Oracle 数据库部署到某存储系统中，那么，在为该 Oracle 数据库创建 RAID 组时，最优RAID 策略应该是：","type":"single","options":[["A","RAID 1"],["B","RAID 5"],["C","RAID 6"],["D","RAID 10"]],"answer":["D"],"ans_raw":"D","explain":"选 D。Oracle 核心库以小块随机 IO 为主，同时对性能与可用性要求都高，RAID 10 先镜像后条带，没有校验的读-改-写惩罚，随机写最好，且同一镜像对坏掉一盘仍可读写。A 的 RAID 1 可用容量只有一半、扩展不便；B、C 的 RAID 5/6 靠校验冗余，写性能受损且重建窗口长。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-8","note":"","flag":"","pnum":8,"ex_src":"编写"},{"num":9,"stem":"SCSI 协议不仅可以用于主机与磁盘通信，也可以用于主机和物理带库、光盘等的通信。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。SCSI 定义的是主机（initiator）与目标设备（target）之间的命令与数据交互，逻辑单元后面挂什么介质并不受限，磁盘、物理带库、光盘都以 SCSI 设备身份被主机访问。判据：协议约束的是命令集而不是介质类型，因此题干列举的两类用途并列成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-9","note":"","flag":"","pnum":9,"ex_src":"编写"},{"num":10,"stem":"在华为 OceanStor V3 存储系统中，某客户计划部署一套业务系统，数据库采用的是 Oracle 数据，平均数据块的大小为 16KB，在使用 SmartTier 特性时，以下数据迁移粒度，最优的是：","type":"single","options":[["A","512KB"],["B","4MB"],["C","32MB"],["D","64MB"]],"answer":["A"],"ans_raw":"A","explain":"选 A。迁移粒度是 SmartTier 统计热度与搬移数据的最小单位，粒度越小分层越贴合热点，元数据与后台带宽开销越大。Oracle 平均块仅 16KB、以小块随机 IO 为主，取候选中最小的 512KB 才能把热块从冷块里分离出来；4MB/32MB/64MB 更适合大块顺序型业务，此处会把大量冷块一并搬动。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-10","note":"","flag":"","pnum":10,"ex_src":"编写"},{"num":11,"stem":"下边哪一种方法可以实现 RTO 最优？","type":"single","options":[["A","磁盘-磁盘"],["B","磁盘-磁盘-磁带"],["C","远程复制"],["D","虚拟带库"]],"answer":["C"],"ans_raw":"C","explain":"选 C。RTO 是业务从中断到恢复运行的耗时。远程复制在灾备端常存一份与生产端基本同步的副本卷，接管时把主机指向副本即可，不需要回拷数据，耗时最短。A、B、D 都属备份体系：磁盘-磁盘-磁带与虚拟带库要从带库或备份盘还原数据，磁盘-磁盘也须先做数据回写，恢复耗时以小时计。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-11","note":"","flag":"","pnum":11,"ex_src":"编写"},{"num":12,"stem":"在华为 OceanStor V3 中，Thick LUN 向存储系统申请空间的单位是什么？","type":"single","options":[["A","grain"],["B","chunk"],["C","stripe"],["D","extent"]],"answer":["D"],"ans_raw":"D","explain":"若干 Extent 组成了卷（Volume），卷（Volume）对外体现为主机访问的 LUN（这里的 LUN 为 Thick LUN）。在处理用户的读写请求以及进行数据迁移时，LUN 向存储系统申请空间、释放空间、迁移数据都是以 Extent 为单位进行。例如：用户在创建 LUN 时，可以指定容量从某一个存储层中获得，此时 LUN 由指定的某一个存储层上的 Extent 组成。在用户的业务开始运行后，存储系统会根据用户设定的迁移策略，对访问频繁的数据以及较少被访 问的数据在存储层之间进行迁移（此功能需要购买 SmartTier License）。此时 LUN 上的数据就会以 Extent 为单位分布到存储池的各个存储层上。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-12","note":"","flag":"","pnum":12,"ex_src":"题源"},{"num":13,"stem":"互联网行业产生的数据大部分是结构化数据，这部分数据约占数据总量的 80%。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。判据在数据类型而不是比例数字：互联网行业产生的数据以视频、图片、日志、文档等非结构化数据为主，占绝大部分，结构化数据只占较小份额。题干把主体说成结构化数据，方向正好反了，所以即便比例口径如何调整也不改变结论。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-13","note":"题源原解析（排版截断）：“互联网行业产生的数据大部分是非结构化数据。”","flag":"","pnum":13,"ex_src":"编写"},{"num":14,"stem":"以下两个关于云计算的描述， 描述 1、云计算的一种部署模型是将一台大型物理服务器划分为多个小型虚拟机； 描述 2、云计算的一种部署模型是将多个小型物理服务器聚合成一台大型主机。","type":"single","options":[["A","描述 1 和描述 2 均正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 和描述 2 均错误"]],"answer":["A"],"ans_raw":"A","explain":"选 A。描述 1 是服务器虚拟化路线，把一台大型物理机切分成多台小型虚拟机；描述 2 是分布式/集群路线，把大量小型物理机聚合成一台逻辑上的大主机（横向扩展的计算与存储集群）。两者方向相反但都是云计算的部署形态，判据是资源被「拆分」还是被「聚合」，与对错无关。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-14","note":"","flag":"","pnum":14,"ex_src":"编写"},{"num":15,"stem":"多路径软件只能用于 IP-SAN 中。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"在中低端 SAN/NAS 融合存储架构双控中也需要；FC SAN 也需要。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-15","note":"","flag":"","pnum":15,"ex_src":"题源"},{"num":16,"stem":"关于DAS 的特点，以下描述正确的是：","type":"multi","options":[["A","可以连接到主机的端口数目有限"],["B","维护内部的DAS 时，系统需要下电"],["C","如果存储空间紧张的 DAS 可以共享存储资源过剩的 DAS 剩余空间"],["D","多个主机连接DAS 时，可以提供不同服务等级的服务"]],"answer":["A","B"],"ans_raw":"AB","explain":"选 A、B。DAS 经主机总线连接，可扩展的通道与端口数受主机侧限制；它与主机一体，维护内置磁盘通常要让系统下电。C 恰是 DAS 的短板——设备之间没有共享通道，富余空间给不了别的 DAS；D 是 SAN 或专业存储的能力，DAS 无法为多主机提供不同服务等级的存储。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-16","note":"","flag":"","pnum":16,"ex_src":"编写"},{"num":17,"stem":"在基于 RAID2.0+的华为 OceanStor V3 中，当用户创建文件系统时，系统会先自动创建对应 LUN，并在 LUN 上生成文件系统。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。OceanStor V3 的 RAID2.0+ 体系里，LUN 是需要管理员先规划并手工创建的资源（选定存储池、容量与属性），之后才能在其上创建文件系统；创建文件系统不会反向自动补建对应 LUN。题干把顺序说成系统先自动建 LUN，与实际配置流程不符。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-17","note":"题源原解析（排版截断）：“LUN 需要先手工创建”","flag":"","pnum":17,"ex_src":"编写"},{"num":18,"stem":"某公司属于银行、金融领域，业务数据量大，安全性要求高，请问该公司适合哪种 RAID 级别？","type":"single","options":[["A","RAID 0"],["B","RAID 1"],["C","RAID 5"],["D","RAID 10"]],"answer":["D"],"ans_raw":"D","explain":"选 D。银行金融业务数据量大、可靠性与性能要求高，随机小块 IO 多，RAID 10 无校验回写、重建只需镜像复制、单对镜像故障不中断，最合适。A 的 RAID 0 没有冗余，坏盘即丢数据；B 的 RAID 1 容量利用率仅 50%、不易扩展；C 的 RAID 5 有读-改-写惩罚，重建期风险高。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-18","note":"","flag":"","pnum":18,"ex_src":"编写"},{"num":19,"stem":"当硬盘出现坏道或坏块时，使用哪种重构方式？","type":"single","options":[["A","全盘重构"],["B","局部重构"],["C","恢复重构"],["D","本地重构"]],"answer":["B"],"ans_raw":"B","explain":"选 B。坏道、坏块只损坏盘上的局部区域，重构时按冗余信息重新生成这些区段的数据并写到健康位置即可，属局部重构。干扰项：全盘重构针对整盘失效或换盘后的整体回补；恢复重构针对盘短暂离线期间由热备顶替、上线后把新写数据回补原盘；本地重构不是 RAID 的重构分类。判据是故障范围。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-19","note":"","flag":"","pnum":19,"ex_src":"编写"},{"num":20,"stem":"以下关于快照技术，描述错误的是？","type":"single","options":[["A","回滚文件系统快照时，必须取消对源文件系统的共享挂载"],["B","同一个文件系统打开多个快照后，回滚到其中一个快照，回滚完成后，将删除目标快照创建时间点之后的所有快照"],["C","手动为某个文件系统创建快照时，超过产品规格的限制将不能为该文件系统创建新 的快照"],["D","为文件系统创建定时快照时，存储系统自动删除最早创建的快照，自动生成新的快 照"]],"answer":["D"],"ans_raw":"D","explain":"选 D。定时快照数量达到产品规格上限时，存储系统不会自动删掉最早的快照来腾位置，新快照会创建失败，需要靠保留策略或人工清理，故该项描述错。A、B、C 描述的都是快照的实际行为：回滚文件系统快照前要取消对源文件系统的共享挂载，回滚后目标时间点之后的快照被删除，手动快照超出规格上限即禁止再建。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-20","note":"","flag":"","pnum":20,"ex_src":"编写"},{"num":21,"stem":"对于机械磁盘的随机访问来说，对于完成一个 IO 所用时间影响最大的是：","type":"single","options":[["A","寻道时间"],["B","旋转时延"],["C","数据传送时间"]],"answer":["A"],"ans_raw":"A","explain":"选 A。随机访问时磁头要在不同磁道之间移动，寻道时间在单次 IO 耗时中占比最大，是机械盘随机性能的决定项。B 的旋转时延受转速限制、量级远小于寻道；C 的数据传送时间只在连续大块 IO 时才成为主要开销。这也正是没有寻道的 SSD 在小块随机 IO 上远超机械盘的原因。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-21","note":"","flag":"","pnum":21,"ex_src":"编写"},{"num":22,"stem":"InfiniBand 接口在华为OceanStor V3 统一存储中用于前端主机接口，可灵活支持直连及交换机多种组网方式。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。OceanStor V3 统一存储的前端主机业务接口是 FC、GE/10GE（承载 iSCSI 与 CIFS/NFS 等文件业务）等，控制器上并不提供 InfiniBand 主机接口，也就谈不上 IB 的直连或交换机组网。判据是「该接口能否作为控制器上对外连主机的业务口」，IB 不在 V3 的主机接口清单内。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-22","note":"","flag":"","pnum":22,"ex_src":"编写"},{"num":23,"stem":"以下关于 NAS 解决方案的描述，哪些是正确的？","type":"multi","options":[["A","NAS 通过文件级的数据访问和共享提供存储资源"],["B","可通过 FC 网络对外提供共享"],["C","主要使用CIFS 和 NFS 协议"],["D","NAS 客户端和 NAS 存储设备间采用 IP 网络互连"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"选 A、C、D。NAS 以文件为单位提供访问与共享，对外使用 CIFS 与 NFS 协议，客户端与设备之间通过 IP 网络互连。最易误选 B：FC 承载的是 SAN 的块业务，NAS 对客户端提供的是 IP 上的文件共享，不经 FC 网络对外共享；统一存储上的 FC 端口服务的是块（SAN）场景。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-23","note":"","flag":"","pnum":23,"ex_src":"编写"},{"num":24,"stem":"硬盘域支持在线添加硬盘，存储池支持在线扩容。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。硬盘域是在线管理的资源容器，可在线加入新硬盘；新盘的 Chunk 被切分打散成 Extent 纳入池后，存储池容量随之增长，扩容过程不改变已有 LUN 与条带的映射关系，业务无须中断。判据落在「在线」：加盘与扩池都不需要停机重建，因此两项表述同时成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-24","note":"","flag":"","pnum":24,"ex_src":"编写"},{"num":25,"stem":"以下哪项操作属于数据中心存储中的每日维护项目？","type":"single","options":[["A","查看并处理告警"],["B","巡检存储设备"],["C","检查机房环境"],["D","检查机架内部环境"]],"answer":["A"],"ans_raw":"A","explain":"选 A。每日维护以不停机、无须进入现场的手段为主，通过 DeviceManager 查看并处理告警，能第一时间发现硬盘、链路、电源类异常，属日常项。B 巡检存储设备、C 检查机房环境、D 检查机架内部环境都要按计划进入现场并接触设备，归周期（周/月）维护项目，不是每日必做。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-25","note":"","flag":"","pnum":25,"ex_src":"编写"},{"num":26,"stem":"描述 1：HyperMirror 一个 LUN 故障，主机业务不中断，HyperClone 主 LUN 故障，主机业务中断。 描述 2：HyperMirror 支持双副本，HyperClone 最大支持 1 主 LUN：16 从 LUN 模式。","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 错误，描述 2 错误"]],"answer":["B"],"ans_raw":"B","explain":"HyperMirror（卷镜像）：通过为本地 LUN 或第三方存储系统的 LUN 提供两个镜像物理副本，持续对 LUN 进行冗余备份保护，从而提高LUN 的可靠性，降低容灾风险和运维成本。HyperClone（克隆）能够在不中断主机业务的情况下实现 LUN 级别的完整备份，可用 于数据备份与恢复、应用测试与数据分析等场景。HyperClone 最大支持 1 主：8 从 LUN 模式。知识点来源于 HCNA-Storage V3.0 版教材和官方产品文档。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-26","note":"","flag":"","pnum":26,"ex_src":"题源"},{"num":27,"stem":"下列对于 SAN 和 NAS 描述正确的是：","type":"multi","options":[["A","SAN 更多的是用在数据库这种场景，来存储这种结构化的数据"],["B","现在 NAS 是面向非结构化数据的存储，比如很多部门员工用于关键办公文档共享和集中存储的共享文件服务器。"],["C","DAS、NAS 和 SAN 都是外部存储，因此可以轻松实现存储资源共享。"],["D","NAS 特点是把服务器的文件系统放在了存储器里，这样服务器需要透过网络就可以来共享数据。"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"选 A、B、D。A、B 按数据类型划分：SAN 提供块级存储，多用于数据库这类结构化数据；NAS 以文件为单位，适合办公文档等非结构化共享。D 说清 NAS 的实现方式——文件系统内置在存储设备里，客户端经 NFS/CIFS 走网络共享。C 错在把 DAS 也说成能轻松共享，DAS 直挂单一主机，共享性比较差，三者的共享能力并不相同。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-27","note":"题源原解析（排版截断）：“DAS 共享性比较差。”","flag":"","pnum":27,"ex_src":"编写"},{"num":28,"stem":"灾备系统关注的要素主要是？","type":"multi","options":[["A","备份窗口"],["B","RTO"],["C","RPO"],["D","备份容量"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"选 A、B、C。灾备体系的核心要素是 RTO（业务恢复耗时）与 RPO（可容忍的数据丢失量），再加上约束策略排布的备份窗口（可用于完成备份的时间段）。D 的备份容量只是资源规模参数，属于容量规划，用来核算介质与许可，不用于衡量灾备系统的恢复能力。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-28","note":"","flag":"","pnum":28,"ex_src":"编写"},{"num":29,"stem":"从原理、性能、成本、共享性、应用场景比较 NAS 存储和 SAN 存储，下列哪些描述是正确的？","type":"multi","options":[["A","NAS 性能高于 SAN，成本也高于 SAN"],["B","SAN 主要适用于文件共享的场景，共享更方便"],["C","NAS 是带有文件系统的存储设备，通过网络共享文件，相当于网络中的一台主机"],["D","SAN 是高速光纤连接的磁盘网络，给主机提供磁盘资源，自身没有文件系统，相当于网络中的一块硬盘"]],"answer":["C","D"],"ans_raw":"CD","explain":"选 C、D。NAS 自带文件系统、按文件通过网络共享，相当于网络中的一台主机；SAN 是高速光纤互连的磁盘网络，只向主机提供块设备、自身不带文件系统，相当于网络中的一块硬盘。A 说反：NAS 走 IP 且要处理文件语义，性能一般低于 SAN，成本也更省；B 也反了，方便的文件共享正是 NAS 的场景。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-29","note":"","flag":"","pnum":29,"ex_src":"编写"},{"num":30,"stem":"HA（High Availability，高可用性）是指提供在本地系统单个组件故障情况下，能继续访问应用的能力。某数据中心，一年中，宕机时间是一个小时，那么该数据中心的 HA 是多少？","type":"single","options":[["A","0.99999"],["B","0.9998858"],["C","0.999999"],["D","0.998934"]],"answer":["B"],"ans_raw":"B","explain":"HA=1-（宕机时间/（宕机时间+运行时间）） 4 个 9: 0.9999 52.56 分钟/年 5 个 9: 0.99999 5.265 分钟/年 6 个 9：0.999999 31 秒/年","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-30","note":"","flag":"","pnum":30,"ex_src":"题源"},{"num":31,"stem":"在备份系统中，需要备份的数据必须经过介质服务器才会存储到备份介质中。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。备份体系中备份服务器负责策略与调度，介质服务器负责把数据真正写入和读出备份介质，因此按架构定义，被备份的数据都要经介质服务器才落到带库或备份盘。判据在分工：LAN-free、client-free 优化的是数据是否流经业务主机和 LAN，介质服务器对备份介质的读写控制权并不被绕过。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-31","note":"","flag":"","pnum":31,"ex_src":"编写"},{"num":32,"stem":"镜像阵列或者 RAID 阵列中发生故障的磁盘上的所有用户数据和校验数据的重新生成的过程被称为：","type":"single","options":[["A","重计算"],["B","重构"],["C","热备份"],["D","恢复"]],"answer":["B"],"ans_raw":"B","explain":"选 B。用阵列内剩余成员盘的数据与校验重新算出故障盘的全部内容并写入替代盘，这一过程称重构（rebuild）。A 的重计算只指校验运算这一步、不含写回；C 的热备（盘/空间）是重构的目标介质而非过程；D 的恢复泛指数据找回或业务回切，不等于阵列内部的数据再生。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-32","note":"","flag":"","pnum":32,"ex_src":"编写"},{"num":33,"stem":"由于地震，某企业 11 月 11 日 16:00 时 IT 系统宕机导致业务停顿，到当天 23:00 时 IT 系统恢复运行，可以恢复到当天 12:00 时的数据，那么本次的 RTO 和RPO 分别是多少？","type":"single","options":[["A","RTO=4 小时，RPO=7 小时"],["B","RTO=7 小时，RPO=4 小时"],["C","RTO=2 小时，RPO=4 小时"],["D","RTO=7 小时，RPO=3 小时"]],"answer":["B"],"ans_raw":"B","explain":"选 B。RTO 从业务中断算到恢复运行：16:00 到当天 23:00 为 7 小时；RPO 是中断时刻与能够恢复到的数据时刻之差：16:00 与当天 12:00 之间为 4 小时。判据是两条都从 16:00 这个中断点起算，RTO 往后量到恢复时刻，RPO 往前量到可用数据点；拿 23:00 去减 12:00 算 RPO 是最常见的错法。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-33","note":"","flag":"","pnum":33,"ex_src":"编写"},{"num":34,"stem":"某公司需要做一份备份策略，该公司的备份数据量小，希望在短时间内备份并且最大限度的节省存储空间。你建议使用哪种类型的备份？","type":"single","options":[["A","完全备份"],["B","累积增量式备份"],["C","差异增量式备份"]],"answer":["C"],"ans_raw":"C","explain":"累积增量式备份：每周一次全备份，本周其余每天备份与上次备份的差异部分。差异增量式备份：每周一次全备份，本周其余每天备份与全备份的差异部分。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-34","note":"","flag":"","pnum":34,"ex_src":"题源"},{"num":35,"stem":"FC SAN 的组网方式有？","type":"multi","options":[["A","直连"],["B","单交换"],["C","双交换"],["D","仲裁环"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"选 A、B、C。FC SAN 按冗余程度分三种组网：主机与控制器光纤对拷、没有交换机的直连；只有一台交换机的单交换；两套独立 fabric 的双交换。D 的仲裁环（FC-AL）是早期磁盘接口上的环路拓扑，不属于 FC SAN 的组网方式，现网交换机工作在交换式 fabric 模式下。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-35","note":"","flag":"","pnum":35,"ex_src":"编写"},{"num":36,"stem":"某银行需要保证数据安全性，并用来传输大块的数据库。请问该银行适合哪种存储网络架构？","type":"single","options":[["A","IP SAN"],["B","FC SAN"],["C","DAS"],["D","NAS"]],"answer":["B"],"ans_raw":"B","explain":"选 B。FC SAN 是专用块网络，链路独占、无损、低时延，与大块数据库传输的吞吐需求匹配，且与业务 IP 网络物理隔离，安全性高。A 的 IP SAN 跑在会丢包的以太网上、要靠 TCP 保可靠；C 的 DAS 无法共享、扩展性差；D 的 NAS 面向文件共享，数据库直接挂文件系统不如块设备安全高效。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-36","note":"","flag":"","pnum":36,"ex_src":"编写"},{"num":37,"stem":"某公司员工小王，作为该公司存储系统的管理员。当他用两套 OceanStor5500 V3 做容灾方案时，只需要其中一台 OceanStor5500 V3 配置数据远程复制软件。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。远程复制是两端阵列协同工作的特性，生产阵列与灾备阵列都要具备并启用该特性、各自取得许可，只有一侧有复制能力就无法建立复制关系与一致性组。判据：任何阵列间复制都需要主备两侧控制器共同参与，不存在只在单台配置软件即可成形的方案。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-37","note":"","flag":"","pnum":37,"ex_src":"编写"},{"num":38,"stem":"某公司用户可通过一款管理软件自动将与其相连的存储设备告警上报到华为服务支持中心。请问，此用户使用的是哪款软件？","type":"single","options":[["A","DeviceManager"],["B","CLI 管理界面"],["C","Toolkit"],["D","eService"]],"answer":["D"],"ans_raw":"D","explain":"选 D。eService 是华为企业设备的告警自动上报与远程维护通道，设备侧接入后可把告警与诊断信息自动送达到华为服务支持中心。A 的 DeviceManager 与 B 的 CLI 只承担本地/远程设备管理，不具备向厂商上报的能力；C 的 Toolkit 是主机侧与巡检工具箱，服务对象是管理员自己。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-38","note":"","flag":"","pnum":38,"ex_src":"编写"},{"num":39,"stem":"Windows 拷贝程序在将本地文件拷贝到文件系统时，华为OceanStor V3 存储系统的文件系统块大小是默认的，这样保证了存储空间的充分利用。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。文件系统块大小在创建文件系统时确定并保持不变，Windows 的拷贝动作不会自动调整它；当块大于实际文件（尤其大量小文件）时，每个文件仍要占用整块，反而浪费空间。判据：块大小要按业务的平均文件大小手工设置，默认值并不等于空间利用最优，题干结论不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-39","note":"","flag":"","pnum":39,"ex_src":"编写"},{"num":40,"stem":"华为 OceanStor V3 系列产品中的 SmartCache 特性，只能提升读性能，不能提升写性能。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"SmartCache 特性通过将读热点数据拷贝至 SmartCache 池中，提高存储系统中读热点 数据的访问效率。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-40","note":"","flag":"","pnum":40,"ex_src":"题源"},{"num":41,"stem":"根据备份数据量的变化，备份的类型可分为：","type":"multi","options":[["A","实时备份"],["B","全量备份"],["C","增量备份"],["D","差量备份"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"选 B、C、D。按每次备份数据量的变化划分：全量备份复制全部数据，增量备份只复制自上一次备份以来的变化，差量备份复制自上一次全量备份以来的变化。A 的实时备份描述的是备份时机与保护的连续性（对应 CDP、复制类技术），不属于按数据量划分的备份类型。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-41","note":"","flag":"","pnum":41,"ex_src":"编写"},{"num":42,"stem":"以下是对 SSD 硬盘与机械硬盘相比的具备的优势，描述正确的是：","type":"multi","options":[["A","无高速旋转部件，性能高"],["B","支持 TCQ/NCQ，一次相应多个 IO 请求"],["C","SSD 盘更适用于对存储容量要求较大的场景使用"],["D","SSD 可用在一些环境较恶劣的场合，如高温高湿，强震等恶劣环境下使用"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"选 A、B、D。SSD 无盘片旋转与磁头寻道机构，随机 IO 时延低、性能高；支持 TCQ/NCQ，可一次接收并乱序优化多条命令；没有机械部件，因而在振动、温度等恶劣环境下比机械盘可靠。最易误选 C：SSD 单位容量成本高、大容量不经济，容量密集型场景应选 SATA 机械盘。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-42","note":"","flag":"","pnum":42,"ex_src":"编写"},{"num":43,"stem":"异步远程复制的同步周期时间限制是多少？","type":"single","options":[["A","1s~144min"],["B","3s~144min"],["C","1s~300min"],["D","3s~300min"]],"answer":["B"],"ans_raw":"B","explain":"（存疑）题源解析给出的范围是 3 秒到 1440 分钟，与 B 选项的 144min 上限对不上，疑为题库漏印一位 0。可以确定的是最小周期为 3 秒而不是 1 秒，故四项中最接近的仍是 B。异步远程复制按设定周期做增量同步，周期越长链路占用越小、RPO 越大，实际配置应以设备支持的范围为准。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-43","note":"题源原解析（排版截断）：“应是 3 秒到 1440 分钟”","flag":"","pnum":43,"ex_src":"编写"},{"num":44,"stem":"在机械磁盘的构成组件中，负责读和写数据的部件是：","type":"single","options":[["A","盘片"],["B","读/写磁头"],["C","磁头臂"],["D","主轴"]],"answer":["B"],"ans_raw":"B","explain":"选 B。读写磁头直接与磁面作用，完成磁化写入与磁阻读取，是唯一承担数据读写的部件。A 盘片只是承载磁记录的介质，本身不读写；C 磁头臂负责带动磁头跨磁道移动，实现寻道；D 主轴带动盘片恒速旋转，只提供角速度。判据：谁改变或感知磁化状态，谁就是读写部件。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-44","note":"","flag":"","pnum":44,"ex_src":"编写"},{"num":45,"stem":"LAN Free 和 Server Free 是备份组网方式中对主机性能影响小的。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"LAN Free 和 Server Free 备份都是基于 SAN 的备份方式。 LAN Free 备份，优点：服务器负载低，优化了数据传输效率；缺点：SAN 布置的费用高昂，设备必须与 SAN 兼容 Server Free 备份，优点：服务器负载最低，大大优化了数据传输效率；缺点：SAN 布置的费用高昂，设备必须与 SAN 兼容，需要第三方设备支持。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-45","note":"","flag":"","pnum":45,"ex_src":"题源"},{"num":46,"stem":"关于数据库级容灾，以下说法错误的是？","type":"single","options":[["A","数据库级的容灾技术，是针对于固定的数据库设计的容灾方案"],["B","数据库级容灾支持广域网，但需要单独的硬件支持"],["C","数据库级容灾主要是通过传输数据日志，并在灾备站点进行重放（Replay）来实现的"],["D","数据库级容灾，在异步方式下会丢失较多数据，至少丢失一个日志文件"]],"answer":["B"],"ans_raw":"B","explain":"选 B。数据库级容灾依赖数据库自身的日志传送与灾备端重放，属软件层面机制，通过广域网链路即可部署，不需要额外的专用硬件，故该说法错。其余三项成立：它面向特定数据库设计（A），靠传日志并重放实现同步（C），异步方式下主库不等待日志落到远端，故障时至少丢失一个日志（D）。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-46","note":"","flag":"","pnum":46,"ex_src":"编写"},{"num":47,"stem":"以下对应RAID 5 和RAID 10 的说法正确的是？","type":"single","options":[["A","RAID 5 的顺序读性能低于 RAID 10"],["B","前端压力足够的情况下，RAID 5 的顺序写性能高于 RAID 10"],["C","RAID 5 的随机读性能低于 RAID 10"],["D","RAID 5 的随机写性能高于 RAID 10"]],"answer":["B"],"ans_raw":"B","explain":"选 B。同等盘数下 RAID 5 有效盘为 N-1，整条带顺序写时冗余写代价约 1/(N-1)，低于 RAID 10 的双份写入，因此前端压力足够时顺序写吞吐更高。A、C 说反：RAID 5 参与读盘的数目更多，顺序读与随机读都不低于 RAID 10；D 错：小块随机写要读-改-写校验，性能明显低于 RAID 10。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-47","note":"","flag":"","pnum":47,"ex_src":"编写"},{"num":48,"stem":"以下关于存储常用协议的描述，正确的是？","type":"single","options":[["A","ATA 协议采用并行接口，只能内置使用，对线缆长度有要求"],["B","SCSI 协议不支持热插拔"],["C","一个 SAS 域可以连接 15 个设备"],["D","FC 协议兼容性好，传输距离长"]],"answer":["A"],"ans_raw":"A","explain":"SCSI 和 SAS 都支持热插拔；一个 SAS 域中，最大可以支持 16384 个设备。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-48","note":"","flag":"","pnum":48,"ex_src":"题源"},{"num":49,"stem":"某小型企业的员工小王在其公司存储系统支持的 Linux 应用服务器上通过 CIFS 协议访问共享的文件。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"Linux 用 NFS 协议；Windows 用CIFS 协议","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-49","note":"","flag":"","pnum":49,"ex_src":"题源"},{"num":50,"stem":"关于数据级、应用级和业务级容灾，以下说法正确的是？","type":"single","options":[["A","关于 RTO，数据级<应用级<业务级"],["B","关于RTO，数据级<业务级<应用级"],["C","关于TCO，数据级<应用级<业务级"],["D","关于TCO，业务级<数据级<应用级"]],"answer":["C"],"ans_raw":"C","explain":"选 C。容灾级别越高，需要冗余的软硬件与流程越多：数据级只复制数据，应用级还要冗余应用与数据库环境，业务级再加全业务链路、值守与自动切换，TCO 依次递增。A、B 的 RTO 关系刚好相反——数据级切换后要重装应用与数据库、耗时最长，业务级可自动接管、RTO 最短。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-50","note":"","flag":"","pnum":50,"ex_src":"编写"},{"num":51,"stem":"从云计算商业模型视角来看，华为网盘属于 PaaS。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"华为网盘属于 SaaS（软件即服务）或 STaaS（存储即服务）。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-51","note":"","flag":"","pnum":51,"ex_src":"题源"},{"num":52,"stem":"某公司客户端服务器资源充足，但是网络资源紧张，适合选择哪种重删策略？","type":"single","options":[["A","文件级重删"],["B","字节级重删"],["C","源端重删"],["D","目标端重删"]],"answer":["C"],"ans_raw":"C","explain":"选 C。瓶颈在网络而非算力，应在客户端即源端先完成重删，只把唯一数据块下发到后端，直接压减传输量。目标端重删要先把全量数据传到存储侧再处理，省不了带宽，D 错；字节级重删属目标端重删的一种粒度，同样不缓解网络压力，B 错；文件级重删只是按整文件去重的粒度概念，与位置无关且删除率低，A 错。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-52","note":"题源原解析（排版截断）：“字节级重删属于目标端重删”","flag":"","pnum":52,"ex_src":"编写"},{"num":53,"stem":"安装了 Linux 操作系统的服务器访问基于 RAID 5 策略组建的磁盘阵列，访问的路径顺序为：","type":"single","options":[["A","文件系统->应用系统->卷->I/O 子系统->RAID 控制器->磁盘"],["B","应用系统->文件系统->卷->I/O 子系统->RAID 控制器->磁盘"],["C","应用系统->文件系统-> I/O 子系统->卷-> RAID 控制器->磁盘"],["D","应用系统->文件系统->卷-> RAID 控制器->I/O 子系统->磁盘"]],"answer":["C"],"ans_raw":"C","explain":"选 C。路径自上而下：应用系统发起读写，文件系统负责组织目录与文件，请求进入操作系统的 I/O 子系统，再落到由物理盘聚合成的卷，最后由 RAID 控制器按 RAID5 的条带与校验定位磁盘，次序是先 I/O 子系统、后卷。A 把文件系统排在应用之前，层次倒置；B、D 都把卷排在 I/O 子系统之前，D 还将 RAID 控制器置于 I/O 子系统之前。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-53","note":"题源原解析（排版截断）：“先 IO 子系统再卷。”","flag":"","pnum":53,"ex_src":"编写"},{"num":54,"stem":"主机层容灾投入较少，兼容性较好。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。主机层容灾在操作系统或虚拟化层用软件做卷复制，不必为阵列特性、网关或智能交换机追加投资，投入较少；它工作在主机侧，对下层不同品牌、不同型号的存储都适用，兼容性好。判据是实现位置：软件在主机侧，成本与兼容性优于阵列层方案，代价是占用主机算力、一致性更难保证。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-54","note":"","flag":"","pnum":54,"ex_src":"编写"},{"num":55,"stem":"某企业采用了云主备数据级容灾，在业务规划时，可根据实际需求，在存储上划分两种 LUN：保护 LUN 和未保护 LUN，将需要容灾的 VM 创建在保护 LUN 上，并只对保护 LUN 配置阵列复制，以节省容灾中心存储空间的需求。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。数据级容灾在灾备端占用的容量按被复制的 LUN 计，把必须保障的业务放保护 LUN 做阵列复制、其余 VM 放未保护 LUN 不复制，既满足关键业务的 RPO/RTO 要求，又省下灾备中心容量，该规划方式成立。判据：容灾投入与保护范围成正比，按业务分级保护是常规做法而非漏洞。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-55","note":"","flag":"","pnum":55,"ex_src":"编写"},{"num":56,"stem":"下列选项中，数据中心块存储基础业务配置流程顺序正确的是？ 1、创建映射视图。 2、创建存储池。 3、创建硬盘域。 4、创建 LUN，创建 LUN 组。 5、创建主机组。 6、登录DeviceManager","type":"single","options":[["A","6->2->3->4->5->1"],["B","6->3->2->4->5->1"],["C","3->2->4->5->1->6"],["D","4->5->2->3->1->6"]],"answer":["B"],"ans_raw":"B","explain":"选 B。块存储配置逐级依赖：先登录 DeviceManager，再创建硬盘域聚合物理盘，然后基于硬盘域创建存储池，从池中划分 LUN 并归入 LUN 组，同时创建主机组登记主机，最后用映射视图把 LUN 组、主机组与前端端口关联，即 6→3→2→4→5→1。判据：无池则无 LUN，无 LUN 与主机则无从映射。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-56","note":"","flag":"","pnum":56,"ex_src":"编写"},{"num":57,"stem":"以下关于 LAN-FREE 备份方式的特点，描述不正确的是：","type":"single","options":[["A","备份数据流不占用 LAN 资源"],["B","备份的代理不影响应用服务器的性能"],["C","备份性能通常比 LAN-BASED 方式高"],["D","不影响用户网络性能"]],"answer":["B"],"ans_raw":"B","explain":"选 B。LAN-FREE 的改进点是让备份数据流走专用 SAN 而不挤占办公 LAN，A、D 因此成立；走高速 SAN 通道后备份性能通常高于 LAN-BASED，C 也成立。但备份代理软件仍需部署在应用服务器上，会占用其 CPU、内存与磁盘 IO，对应用性能是有影响的，B 的说法正好说反。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-57","note":"题源原解析（排版截断）：“备份的代理会影响应用服务器的性能。”","flag":"","pnum":57,"ex_src":"编写"},{"num":58,"stem":"描述 1：Windows 在挂载同一 IP 地址（域名或机器名）的CIFS 共享时，同一个用户可以同时挂载一个或多个共享，但是不能使用不同的用户挂载相同或不同的共享。 描述 2：Windows 在挂载同一 IP 地址（域名或机器名）的 Homedir 共享时，不能使用多个用户挂载多个共享。","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 错误，描述 2 错误"]],"answer":["A"],"ans_raw":"A","explain":"选 A。两条描述受同一条 Windows 规则约束：到同一 IP（域名或机器名）只维持一套会话凭据，因此同一用户可以挂载该服务器上的一或多个 CIFS 共享，但不能再用另一个用户身份挂同一目标上的共享；Homedir 按用户目录映射，同一目标上同样不允许多用户挂多个共享。判据是凭据个数，不是共享个数。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-58","note":"","flag":"","pnum":58,"ex_src":"编写"},{"num":59,"stem":"如下对于重构的描述，哪项是不正确的？","type":"single","options":[["A","RAID 0,1,3,5,6 和 10 支持重构"],["B","重构不一定需要热备盘"],["C","重构对 RAID 性能有影响"],["D","重构不会中断RAID 业务"]],"answer":["A"],"ans_raw":"A","explain":"选 A。RAID 0 没有镜像或校验等任何冗余信息，盘故障后数据无法重新生成，根本不支持重构，故该项描述不正确。B 对：重构可写到更换后的替代盘，不必预留热备盘；C 对：重构期间要读全部成员盘并写回，前台性能受影响；D 对：重构在后台进行，阵列以降级状态继续对外提供服务。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-59","note":"","flag":"","pnum":59,"ex_src":"编写"},{"num":60,"stem":"双交换机网络设计广泛应用于FC SAN 环境中，以下关于双交换机网络冗余设计的描述， 哪些是正确的？","type":"multi","options":[["A","在 SAN 环境中部署两台 FC 交换机交叉连接到存储设备的两个控制器"],["B","每个主机需要 2 个可用的 FC 端口，并将两个端口连接到不同的交换机"],["C","交换机上需要通信的主机端口和存储设备端口必须在同一个 zone"],["D","虽然存在多条路径，但双交换机网络只支持链路冗余，不支持负载均衡"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"选 A、B、C。双交换机冗余靠两台交换机分别连接两个控制器形成独立 fabric（A），主机用两个可用 FC 口跨交换机接入（B），需要互通的主机端口与存储端口必须划入同一个 zone 才能互相可见（C）。最易误选 D：多路径软件可在两套 fabric 上按策略分担 IO，链路冗余与负载均衡同时具备。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-60","note":"","flag":"","pnum":60,"ex_src":"编写"},{"num":61,"stem":"数据中心是为了接入、承载服务器的业务而建设的基础设施。按照业务可以将数据中心分为：","type":"multi","options":[["A","云数据中心"],["B","企业数据中心"],["C","运营商数据中心"],["D","互联网数据中心"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"选 B、C、D。按接入和承载的业务主体划分，数据中心分为企业数据中心、运营商数据中心、互联网数据中心三类。A 的云数据中心是按技术形态与建设模式描述的数据中心演进阶段（资源虚拟化、池化交付），与「按业务」不属于同一分类维度，故不选。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-61","note":"","flag":"","pnum":61,"ex_src":"编写"},{"num":62,"stem":"在使用 RAID2.0+技术的华为存储系统中，一个硬盘域只能包含一种类型的硬盘。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。一个硬盘域可以同时纳入 SAS、SATA、SSD 等不同类型硬盘，盘被统一切分为 Chunk 后再按类型归入各自的存储池；要求同类型的是存储池/性能层，一个池只放一种盘。判据：硬盘域允许混合盘类型，正是 SmartTier 能划出高优先层与容量层的资源前提。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-62","note":"","flag":"","pnum":62,"ex_src":"编写"},{"num":63,"stem":"一个设备只能有一个 WWPN，但是可以有多个WWNN。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。关系说反了：一个 FC 节点（设备）只有一个全局唯一的 WWNN，用于标识节点本身；而它的每个 N_Port 各有独立的 WWPN，端口多的设备就有多个 WWPN。判据：WWPN 标识端口、WWNN 标识节点，个数由端口数决定，成立的是「一个 WWNN、可多个 WWPN」。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-63","note":"","flag":"","pnum":63,"ex_src":"编写"},{"num":64,"stem":"以下属于云计算的关键特征的是：","type":"multi","options":[["A","用户可以按需自助服务"],["B","用户使用的资源池与资源池的确切地理位置无关"],["C","可以迅速、弹性地为用户提供能力，如计算能力、存储能力等。"],["D","根据用户实际使用情况收费"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"选 ABCD。四项分别是按需自助服务、资源池化且使用者与资源所在物理位置无关、能够迅速弹性地提供算力与存储等能力、按实际用量计量收费，再加上泛在网络接入即云计算的关键特征。判据：这些描述的都是交付与计量方式，与底层用哪种虚拟化实现无关，因此都算特征。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-64","note":"","flag":"","pnum":64,"ex_src":"编写"},{"num":65,"stem":"RAID2.0+的一个 CKG 里的两个 CK 能来自同一个硬盘。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"CKG 是由来自于同一个 DG 内不同硬盘的 CK 按照 RAID 算法组成的逻辑存储单元，是存储池从硬盘域上分配资源的最小单位。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-65","note":"","flag":"","pnum":65,"ex_src":"题源"},{"num":66,"stem":"下列关于 NAS 的描述错误的是？","type":"multi","options":[["A","NAS 设备可以使用集群技术用于故障切换"],["B","NAS 提供一个控制台集中管理，可以有效地管理文件系统"],["C","不允许 NAS 同时被多个客户端访问"],["D","一个客户端不可同时连接多个 NAS 设备"]],"answer":["C","D"],"ans_raw":"CD","explain":"选 C、D。题干要挑错误描述：NAS 的核心价值就是多客户端并发访问与共享文件（C 错），一个客户端也可以同时连接多台 NAS 设备上的共享（D 错）。A、B 属 NAS 的正常能力：可用集群技术做故障切换保障连续性，并有集中控制台统一管理文件系统、共享与权限。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-66","note":"","flag":"","pnum":66,"ex_src":"编写"},{"num":67,"stem":"以下不属于备份类型的是？","type":"single","options":[["A","完全备份"],["B","累计增量式备份"],["C","差异增量备份"],["D","实时备份"]],"answer":["D"],"ans_raw":"D","explain":"选 D。完全备份、累计增量式备份、差异增量备份都是按备份数据量划分的标准类型：累计增量以上一次全量为参照，差异增量固定从上一次完全备份起算变化量。D 的实时备份讲的是保护时机与数据连续性，属 CDP 或复制类技术，不在备份类型的分类之中。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-67","note":"","flag":"","pnum":67,"ex_src":"编写"},{"num":68,"stem":"描述 1：FC 协议和 FCoE 协议的运行环境不同，运行通道不同，协议栈相同。描述 2：FCoE 只能跑在 10GE 上，解决了 FC 传输距离短和 IP 网络的掉包问题。","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 错误，描述 2 错误"]],"answer":["A"],"ans_raw":"A","explain":"选 A。FCoE 只是把 FC 帧封装进以太网帧，运行环境与传输通道都变了（光纤换成无损以太网），FC 协议栈原封不动沿用；它靠 DCB/PFC 提供无损承载，既缓解 FC 传输距离短的问题，又规避 IP 网络的丢包，两条按教材均判对。补充：本质要求是「无损」而非速率，现网也存在更高速率的承载。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-68","note":"","flag":"","pnum":68,"ex_src":"编写"},{"num":69,"stem":"下面对于 IOPS 的描述错误的是：","type":"single","options":[["A","每秒能进行多少次 IO，每次 IO 根据写入数据的大小，这个值是固定的"],["B","如果在不频繁换道的情况下，每次 IO 写入很大的一块连续数据，则此时每秒所做的 IO 次数是比较低的"],["C","如果磁头频繁换道，每次写入数据比较大的话，此时IOPS 应该是这块磁盘的最低数 值"],["D","如果在不频繁换道的条件下，每次写入最小的数据块，比如 512 字节，那么此时的 IOPS 将是最高值"]],"answer":["A"],"ans_raw":"A","explain":"选 A。IOPS 是每秒完成的 IO 次数，它与 IO 大小、随机还是顺序、磁头是否频繁换道密切相关，同一块盘的数值随负载模型大幅变化，A 说这个值「固定」错。B、C、D 正确刻画了这一关系：不换道加大块则次数低，频繁换道且大块接近最低值，不换道加 512 字节小块接近最高值。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-69","note":"","flag":"","pnum":69,"ex_src":"编写"},{"num":70,"stem":"基于 Windows 系统的服务器要使用OceanStor V3 存储设备提供的存储资源，需要以下的操作步骤： 1、创建硬盘域和存储池 2、创建主机和主机组 3、创建 LUN 和 LUN 组 4、在服务器和存储设备上配置启动器（initiator） 5、连接服务器到存储设备 6、格式化逻辑磁盘 7、安装 initiator 软件到服务器 8、映射 请对以上的步骤进行排序。","type":"single","options":[["A","2->3->1->4->5->6->7->8"],["B","1->2->3->4->5->6->7->8"],["C","2->3->1->4->8->7->5->6"],["D","7->5->1->3->2->4->8->6"]],"answer":["D"],"ans_raw":"D","explain":"选 D。按依赖关系排：先在服务器装 initiator（含多路径）软件，再做物理连接，存储才能识别到发起端；随后存储侧建硬盘域与存储池、建 LUN 与 LUN 组、建主机与主机组登记 initiator，然后做映射，最后主机端扫描磁盘并格式化逻辑盘，即 7→5→1→3→2→4→8→6。判据：映射必须早于格式化。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-70","note":"","flag":"","pnum":70,"ex_src":"编写"},{"num":71,"stem":"当某公司客户需要在设备间完成数据迁移时，可以使用哪些特性来完成？","type":"multi","options":[["A","远程复制"],["B","LUN 拷贝"],["C","SmartMigration"],["D","克隆"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"SmartMigration（LUN 迁移）：能够在不中断主机业务的情况下实现源 LUN 上的业务完整透明的迁移到目标 LUN 上，并在迁移结束后使用目标 LUN 完全替代源 LUN，而用户无感知。HyperReplication（远程复制）：为用户提供了灵活强大的数据复制功能，通过远程复制能够实现数据的远端备份和恢复、持续的业务数据支撑、数据的容灾恢复。包括同步远程复制和异步远程复制。HyperClone（克隆）能够在不中断主机业务的情况下实现 LUN 级别数据的完整备份，可用于数据备份与恢复、应用测试与数据分析等场景。HyperCopy（LUN 拷贝）能够将源 LUN 中的数据拷贝到本地的目标 LUN 或者其他存储上的目标LUN，从而实现数据迁移、分发和备份。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-71","note":"","flag":"","pnum":71,"ex_src":"题源"},{"num":72,"stem":"基于 SAN 网络的数据复制技术是在前端应用服务器与后端存储系统之间的存储区域网络（SAN），加入一层智能型交换机，前端连接服务器主机，后端连接存储设备。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。这正是带外的智能交换机方式数据复制：在应用服务器与存储设备之间的 SAN 中加一层具备复制能力的智能交换机，由它截获 IO 并同时向本端与远端下发，前端仍连主机、后端仍连阵列，主机侧无须装复制软件。判据：复制逻辑位于交换机而非阵列控制器或主机。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-72","note":"","flag":"","pnum":72,"ex_src":"编写"},{"num":73,"stem":"半结构化数据一般是自描述的，数据的结构和内容混在一起，没有明显的区分。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。半结构化数据（HTML、XML、日志等）用标签把结构与内容一起记录，是自描述的，但没有预先定义好的严格模式，结构与内容交织、难以直接映射到二维表，题干表述成立。判据是与另两类的对比：结构化数据模式与内容分离、字段固定，非结构化数据缺少自描述结构。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-73","note":"","flag":"","pnum":73,"ex_src":"编写"},{"num":74,"stem":"描述 1：由几个硬盘组成的 RAID 称之为物理卷。 描述 2：RAID 5 能够提高读写速率，并提供一定程度的数据安全，但是当有单块硬盘故障时，读写性能会大幅度下降。","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 错误，描述 2 错误"]],"answer":["C"],"ans_raw":"C","explain":"RAID 由几块硬盘（物理卷）组成；RAID 可以按照指定容量创建一个或多个逻辑卷，一个逻辑卷对于主机来说就是一块硬盘（物理卷）。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-74","note":"","flag":"","pnum":74,"ex_src":"题源"},{"num":75,"stem":"IP 漂移策略所选择的端口与端口速率无关，只与端口所在位置有关，选择端口的顺序是？ 1、对端控制器相同位置的端口 2、对端控制器其他位置的端口 3、本端控制器的端口","type":"single","options":[["A","1->2->3"],["B","2->1->3"],["C","3->1->2"],["D","2->3->1"]],"answer":["C"],"ans_raw":"C","explain":"选 C。IP 漂移只为保证业务地址不断，端口选择原则是先本端、再对端：优先用本端控制器上仍可工作的端口（3），其次选对端控制器相同位置的端口（1），最后才用对端其他位置端口（2），即 3→1→2。其余三项都把对端排在本端之前，会让流量绕到对端控制器，加重集群互联链路负担并带来非对称路径风险。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-75","note":"题源原解析（排版截断）：“先本端，再对端。”","flag":"","pnum":75,"ex_src":"编写"},{"num":76,"stem":"一个存储系统性能的衡量指标通常是？","type":"multi","options":[["A","IOPS"],["B","带宽"],["C","容量"],["D","时延"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"选 A、B、D。衡量存储性能看三项：IOPS（每秒 IO 次数）、带宽（每秒吞吐的字节数）、时延（单个 IO 的完成耗时）。易错项 C 的容量描述的是能存下多少数据，属规模指标而非性能指标；同一容量档位的设备性能可以相差几个数量级，故不计入性能衡量。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-76","note":"","flag":"","pnum":76,"ex_src":"编写"},{"num":77,"stem":"关于双活、热备、暖备、冷备四种容灾模式的特点，以下说法错误的是？","type":"single","options":[["A","采用冷备模式的数据中心 RTO 时间长，且不可预知"],["B","采用双活模式的数据中心 RTO 时间最短"],["C","当出现数据中心故障造成该业务不可用时，热备和双活模式可以用软件自动切换业务，而暖备模式需要人工干预，冷备模式需要人工强干预"],["D","热备模式需要的软件成本最高"]],"answer":["D"],"ans_raw":"D","explain":"选 D。双活要求两套数据中心同时在线承载业务，还要仲裁与自动接管，许可与建设投入最高；热备只是备端环境常开、数据持续同步，成本低于双活，故 D 说法错。A、B、C 均为四者的正确特征：冷备无现成运行环境，RTO 长且依赖人工恢复、不可预知；双活 RTO 最短；暖备需人工干预，冷备需人工强干预。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-77","note":"","flag":"","pnum":77,"ex_src":"编写"},{"num":78,"stem":"华为OceanStor V3 存储产品使用的多路径负载均衡策略，默认的是？","type":"single","options":[["A","轮询"],["B","最小队列深度"],["C","最小任务"],["D","最小IO 数"]],"answer":["B"],"ans_raw":"B","explain":"选 B。队列深度直接反映一条路径上排队而未完成的请求数，选最浅者能即时避开已经拥塞的链路，比按次序轮流派发的轮询更贴近实时负载，因此 V3 多路径默认采用最小队列深度。A 轮询不感知路径忙闲；C、D 要依赖累计的任务数或 IO 数统计，反应滞后，属需按场景手工指定的策略。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-78","note":"","flag":"","pnum":78,"ex_src":"编写"},{"num":79,"stem":"以下关于数据和信息理解正确的是？","type":"multi","options":[["A","数据是反映客观事物属性的记录，是信息的具体表现形式"],["B","数据是指可以存储和传输的信息"],["C","信息是为了满足用户决策的需要而经过加工处理的数据"],["D","数据是信息和数据冗余之和"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"选 ABCD。数据是反映客观事物属性的记录、是信息的具体表现形式（A），也是可以存储与传输的信息载体（B）；信息是为满足用户决策需要而经加工处理的数据（C）；数据中总含重复或无效部分，故有「数据＝信息＋冗余」的关系（D）。判据：是否经过加工并具备决策价值，用来区分数据与信息。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-79","note":"","flag":"","pnum":79,"ex_src":"编写"},{"num":80,"stem":"关于企业做灾备系统建设的好处和必要性，以下说法错误的是？","type":"single","options":[["A","可以规避重大损失，降低企业风险"],["B","符合政策法规，满足行业监管要求"],["C","可以简化运维工作，规避突发事件冲击"],["D","在自然灾害发生较少的地域可以考虑降低灾备级别"]],"answer":["D"],"ans_raw":"D、","explain":"选 D。灾备级别由业务连续性要求（RPO/RTO）和数据重要性决定，与当地自然灾害频率没有必然关系；灾害少的地区同样会因宕机、误操作、勒索软件丢数据，不能据此降级。A、B 是风险与合规价值。C 也成立，灾备站点可承接备份、开发测试和报表查询，把这部分负载从生产系统移走，运维反而更简单。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-80","note":"","flag":"","pnum":80,"ex_src":"编写"},{"num":81,"stem":"IP 漂移支持在不同类型的接口模块之间进行漂移。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。IP 漂移是把 IP 地址、路由与链路属性整体迁移到对等模块，前提是两端接口类型、速率与链路层封装一致，配置才能原样延续。不同类型接口模块的介质和封装不同，接管后地址与链路状态无法保持一致，故漂移只允许在同类模块之间发生，题干说可以跨类型不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-81","note":"","flag":"","pnum":81,"ex_src":"编写"},{"num":82,"stem":"一个主机连接到交换机的一个端口不能属于多个 zone，而只能被划分到一个 zone 中。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。FC 交换机的 zone 成员是可重叠的集合，同一个物理端口（同一个 WWN）可以先加入一个 zone，再用加入命令把它追加到其他 zone，实际配置中主机端口与多个存储端口分区时经常要跨 zone。因此一个端口只能属于一个 zone 的说法不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-82","note":"","flag":"","pnum":82,"ex_src":"编写"},{"num":83,"stem":"混合云是一种同时使用私有云和公有云的解决方案。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。混合云的判据就是同时使用私有云和公有云两种部署模式，两者各自独立存在，靠专线或 VPN 打通以承载负载溢出与数据流动。题干的表述正是这一定义的最小形式，没有附加错误条件，故判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-83","note":"","flag":"","pnum":83,"ex_src":"编写"},{"num":84,"stem":"设备备份带宽大小应该考虑哪些条件？","type":"multi","options":[["A","初始数据的容量大小"],["B","每天的数量增量"],["C","备份周期"],["D","备份人员"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"选 ABC。带宽估算式是待搬运数据量除以备份窗口：初始容量决定首次全备的峰值带宽，每日增量决定常态带宽，备份周期决定必须在多长时间内传完，三者共同定带宽。D 是最易凭直觉误选的无关项，备份人员属组织分工，与链路上要跑多少字节无关。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-84","note":"","flag":"","pnum":84,"ex_src":"编写"},{"num":85,"stem":"在华为 OceanStor V3 存储系统中，一个 LUN 可以创建多个快照，但是只有一个快照可以处于已激活状态。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"一个 LUN 可以创建多个快照，而且每个快照都可以处于已激活状态。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-85","note":"","flag":"","pnum":85,"ex_src":"题源"},{"num":86,"stem":"使用 NFS 协议时，增加客户端，设置读写权限对性能有影响。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。客户端数量与读写权限在 NFS 里属于访问控制配置，服务端不会把它们放进每笔 I/O 的处理路径反复计算，增加客户端或调整权限不会带来可感知的性能变化。真正影响 NFS 性能的是网络带宽、并发量和同步/异步写模式，题干把配置项当成了性能因素。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-86","note":"","flag":"","pnum":86,"ex_src":"编写"},{"num":87,"stem":"IT 架构云化是由“分离”走向“融合”，其中融合指的是？","type":"single","options":[["A","IT 基础设施的融合"],["B","应用与服务器的融合"],["C","硬件与软件的融合"],["D","多应用共享、开放的“云计算机”"]],"answer":["D"],"ans_raw":"D","explain":"选 D。云化所说的融合，是把计算、存储、网络资源池化后交给多个应用按需共享，对外表现为一台开放、可弹性调度的「云计算机」，核心是共享与开放。A 只讲基础设施合并，C 只讲软硬件关系，B 讲的是应用与服务器绑定，都没有触及多应用共享这一本质。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-87","note":"","flag":"","pnum":87,"ex_src":"编写"},{"num":88,"stem":"如下对 RAID 5 的描述，正确的有哪些？","type":"multi","options":[["A","RAID 5 有固定的校验盘"],["B","RAID 5 采用XOR 算法校验"],["C","RAID 5 使用条带化写入数据"],["D","RAID 5 在数据不丢失的情况下允许最多两块成员盘同时失效"]],"answer":["B","C"],"ans_raw":"BC","explain":"RAID 5 是改进版的RAID 3，使用条带化并计算奇偶校验信息。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-88","note":"","flag":"","pnum":88,"ex_src":"题源"},{"num":89,"stem":"关于 SAN 同步复制的步骤，以下排序正确的是？ （1）、生产存储收到主机写请求。HyperReplication 将该请求记录日志。日志中只记录地址信息，不记录数据内容。 （2）、HyperReplication 等待主 LUN 和从 LUN 的写处理结果都返回。如果都写成功，清除日志；否则保留日志，进入异常断开状态，后继启动同步时重新复制该日志地址对应的数据块。 （3）、将该请求写入主 LUN 和从 LUN。通常情况下 LUN 是回写状态，数据会写入 Cache。 （4）、返回主机写请求处理结果，以写主 LUN 的处理结果为准。","type":"single","options":[["A","（1）（3）（2）（4）"],["B","（1）（2）（3）（4）"],["C","（2）（1）（3）（4）"],["D","（4）（2）（3）（1）"]],"answer":["A"],"ans_raw":"A","explain":"选 A，顺序 1-3-2-4。先把写请求记入日志（只记地址不记数据）以保证一致性，再同时下发主、从 LUN（回写进 Cache），然后等两边写结果都返回才清日志、失败则保留日志进入异常断开，最后按主 LUN 的结果回复主机。B、C 把日志与写入次序颠倒，掉电时找不回未确认的块；D 完全倒序。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-89","note":"","flag":"","pnum":89,"ex_src":"编写"},{"num":90,"stem":"下列存储功能中能够为客户提供数据灾备功能的是：","type":"multi","options":[["A","快照"],["B","Cache 预取"],["C","远程复制"],["D","分级存储"]],"answer":["A","C"],"ans_raw":"AC","explain":"选 AC。灾备的前提是拿到可用副本：快照给出本设备的时间点副本，远程复制给出异地副本，两者共同支撑数据灾备。B 的 Cache 预取只优化读命中，D 的分级存储只把数据在不同性能介质间搬移以降低单位成本，都不产生用于恢复的副本，是最容易被当成数据保护的干扰项。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-90","note":"","flag":"","pnum":90,"ex_src":"编写"},{"num":91,"stem":"以下关于 FC SAN 网络交换技术，哪项是错误的？","type":"single","options":[["A","一种广泛使用，最多支持 127 个设备的技术"],["B","交换机可以提供连接到它的多个节点之间可以同时通信"],["C","一个 zone 的某个节点故障，不会影响其他zone 内的节点服务"],["D","交换机利用 zone 管理网络分区，并提供最佳的互联方式"]],"answer":["A"],"ans_raw":"A","explain":"选 A。FC 按 Domain/Area/Port 三级地址编址，规模由交换机端口数与地址空间决定，所谓最多支持 127 个设备这一上限与 FC 的编址方式无关，属错误说法。B 讲交换机允许多对节点并发通信，C 讲 zone 之间故障隔离，D 讲用 zone 管理网络分区并获得最优互联，都是 FC 交换的正确特性。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-91","note":"","flag":"","pnum":91,"ex_src":"编写"},{"num":92,"stem":"OceanStor 5300 V3 扩展控制器是属于那种技术？","type":"single","options":[["A","Scale-out"],["B","Scale-up"],["C","Scale-in"],["D","Scale-deep"]],"answer":["A"],"ans_raw":"A","explain":"选 A。增加控制器个数属于横向扩展 Scale-out：新控制器以集群方式加入，处理能力、缓存容量和前端带宽随控制器数量成比例增长。B 的 Scale-up 指在单台设备内扩盘柜、扩容量，是纵向提升单机规格；C、D 不是业界也不是华为使用的扩展术语，属生造干扰项。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-92","note":"","flag":"","pnum":92,"ex_src":"编写"},{"num":93,"stem":"数据中心的基础设施有哪些？","type":"multi","options":[["A","消防系统"],["B","供电系统"],["C","机柜系统"],["D","综合布线"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"选 ABCD。数据中心基础设施指支撑 IT 设备运行的物理子系统，包括供电（UPS 与配电）、制冷、机柜与微模块、综合布线、消防以及动环监控，四项全在其中。易错处是漏选 A，把消防当作楼宇配套；它是机房强制配置，属基础设施不可分割的一部分。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-93","note":"","flag":"","pnum":93,"ex_src":"编写"},{"num":94,"stem":"下列选项中，属于狭义存储的是哪个？","type":"single","options":[["A","磁盘"],["B","磁盘阵列"],["C","磁盘柜"],["D","磁带库"]],"answer":["A"],"ans_raw":"A","explain":"选 A。狭义存储只指存储介质本身，即数据的物理载体，如磁盘、磁带；广义存储则把介质连同控制器、冗余与管理软件组织成可用设备。B 磁盘阵列、C 磁盘柜、D 磁带库都带管理与冗余能力，属广义范畴。判据很简单：选项给的是介质还是设备/系统。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-94","note":"","flag":"","pnum":94,"ex_src":"编写"},{"num":95,"stem":"目前容灾存在的挑战有哪些？","type":"multi","options":[["A","容灾建设需要昂贵的投入"],["B","应用多样，管理不便"],["C","IT 系统的云化趋势越来越明显，众多的虚拟机也需要提供保护，目前的容灾建设缺乏统一的管理系统"],["D","数据共享等能力受数据物理位置限制，应用与数据无法分离，无法构建敏捷应用与更好的容灾特性"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"选 ABCD。四项正是容灾建设的经典痛点：异地机房与重复建设导致投入高昂（A），被保护应用类型繁杂、策略难统一（B），云化与虚拟化后虚拟机数量庞大却缺少统一容灾管理平台（C），数据受物理位置约束使应用与数据耦合、切换不敏捷（D），无需取舍。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-95","note":"","flag":"","pnum":95,"ex_src":"编写"},{"num":96,"stem":"某公司使用OLTP 数据库，则该公司的 SmartTier 适合选哪种迁移策略？","type":"single","options":[["A","不迁移"],["B","自动迁移"],["C","向高性能层迁移"],["D","向低性能层迁移"]],"answer":["C"],"ans_raw":"C","explain":"选 C。OLTP 以小 I/O、随机读写为主，时延敏感，属典型热数据，SmartTier 要把高频 Extent 上收到 SSD 高性能层，故迁移策略取向高性能层迁移。B 自动迁移只按访问统计自行决定方向，不体现业务诉求；D 向低性能层迁移适合长期不访问的归档数据；A 不迁移等于关闭特性。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-96","note":"","flag":"","pnum":96,"ex_src":"编写"},{"num":97,"stem":"描述 1：存储系统的控制器之间是有互连线的，假如控制器坏了一个，那么属于它管理的 LUN 的工作控制器就会被切换为可以正常工作的控制器。 描述 2：一个 LUN 的工作控制器和归属控制器必须统一为一个控制器。","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 错误，描述 2 正确"],["C","描述 1 错误，描述 2 错误"],["D","描述 1 正确，描述 2 错误"]],"answer":["D"],"ans_raw":"D","explain":"选 D。描述 1 正确：控制器之间有专用互连链路交换状态与 Cache 数据，一个控制器故障后，其承载 LUN 的工作控制器会切到正常控制器上。描述 2 错误：归属控制器是配置意义上的 owner，工作控制器是当前实际承接 I/O 的控制器，两者本就可以不一致，故障切换与负载均衡正建立在这一点上。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-97","note":"","flag":"","pnum":97,"ex_src":"编写"},{"num":98,"stem":"主机安装多路径软件后，以下哪些描述是正确的？","type":"multi","options":[["A","LUN 自动映射到主机"],["B","协助操作系统通过多条链路访问同一个 LUN，避免逻辑错误"],["C","提高链路可靠性，防止单链路故障，从而避免系统失效"],["D","建立主机和存储设备之间的 SCSI 连接"]],"answer":["B","C"],"ans_raw":"BC","explain":"选 BC。多路径软件把已经存在的多条链路聚合识别为一个逻辑设备，避免同一 LUN 被上层当成多块盘造成数据错乱（B），并在链路故障时切换、正常时做负载分担，从而消除单链路故障（C）。A 错，LUN 必须由存储侧配置主机组与 LUN 组手工映射；D 错，SCSI 会话由 HBA 与 OS initiator 建立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-98","note":"","flag":"","pnum":98,"ex_src":"编写"},{"num":99,"stem":"数据库数据属于结构化数据，音频、视频数据属于非结构化数据，目前存储空间的增长主要来自于非结构化数据的快速增长。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。判据有两层：可用关系表建模的数据库数据属结构化，音频、视频、图片属非结构化，这一划分无误；同时当前存储容量的增量主要来自音视频等非结构化负载，也是行业与教材共识。两个分句都成立且互不矛盾，整句判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-99","note":"","flag":"","pnum":99,"ex_src":"编写"},{"num":100,"stem":"以下对华为 OceanStor V3 存储系统中 NFS 写入模式描述正确的是？","type":"single","options":[["A","同步模式是写入共享的数据想写入缓存，然后再写入磁盘"],["B","异步模式是写入共享的数据立即写入硬盘"],["C","系统默认的是异步写入模式"],["D","系统默认的是同步写入模式"]],"answer":["D"],"ans_raw":"D","explain":"选 D。V3 的 NFS 共享提供同步与异步两种写模式，默认为同步：数据写入磁盘后才向客户端返回写完成，以一致性优先，代价是吞吐较低。A、B 恰好把两种模式对调——先写缓存立即应答的是异步，立即落盘才应答的是同步；C 又把默认值说反，只有 D 成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-100","note":"","flag":"","pnum":100,"ex_src":"编写"},{"num":101,"stem":"关于容灾演练以下说法错误的是？、","type":"single","options":[["A","按照真实的容灾步骤进行演习"],["B","通过容灾熟悉灾难恢复流程，锻炼灾难来临时的业务恢复能力"],["C","通过容灾演习，不能检查业务完整性"],["D","容灾演习是验证，是证明系统可用性最有效的手段"]],"answer":["C"],"ans_raw":"C","explain":"选 C。容灾演练的价值之一，就是切换完成后用数据校验和业务实际访问来确认业务完整性，说不能检查业务完整性与演练目的相反，是错误说法。A 要求按真实容灾步骤执行才有意义，B 强调熟悉流程、锻炼人员，D 指出演练是验证系统可用性最有效的手段，均为正确表述。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-101","note":"","flag":"","pnum":101,"ex_src":"编写"},{"num":102,"stem":"在容灾备份中用到的 RPO 的全称是：","type":"single","options":[["A","Return Purchase Order"],["B","Recover Plan Objective"],["C","Restore Point Objective"],["D","Recovery Point Objective"]],"answer":["D"],"ans_raw":"D","explain":"选 D。RPO 全称 Recovery Point Objective，恢复点目标，衡量故障时允许丢失多长时间窗口的数据。A 的 Return Purchase Order 与容灾无关，B、C 把 Point 换成 Plan、Restore 属拼凑词。记法：RPO 关注丢多少数据（时间点），RTO 是 Recovery Time Objective，关注多久恢复业务。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-102","note":"","flag":"","pnum":102,"ex_src":"编写"},{"num":103,"stem":"下列关于 Quota tree 的描述正确的是？","type":"single","options":[["A","Quota tree 是文件系统下的一级目录"],["B","只能由管理员通过命令行或GUI 管理界面进行创建、删除、重命名等操作，普通用户可以删除空的 Quota tree"],["C","Quota tree 通过协议进行共享时，可以改名和删除"],["D","普通用户可以对 Quota Tree 下的文件个数或者容量进行配额管理"]],"answer":["A"],"ans_raw":"A","explain":"选 A。Quota tree 是文件系统下用来承载配额策略的一级目录，文件数与容量配额都挂在它上面。B 错在允许普通用户删除空的 Quota tree，创建、删除、改名均只有管理员可做；C 错在已通过协议共享的 Quota tree 不能再改名和删除；D 错在配额管理权属于管理员，普通用户无权设定。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-103","note":"","flag":"","pnum":103,"ex_src":"编写"},{"num":104,"stem":"在华为 OceanStor V3 存储系统中，某客户计划部署 3 套系统，一套业务系统，运行 Oracle 数据库，对随机读写性能要求高；一套邮件系统，用于日常邮件处理；一套视频系统，保存长期归档的视频。在分别为各个系统创建 LUN 时，以下关于 SmartTier 策略设置正确的是？","type":"multi","options":[["A","业务系统： 1、初始容量分配：优先从性能层分配 2、数据迁移策略：向低性能层迁移"],["B","邮件系统： 1、初始容量分配：自动分配 2、数据迁移策略：自动迁移"],["C","视频系统： 1、初始容量分配：优先从容量层分配 2、数据迁移策略：自动迁移"],["D","视频系统： 1、初始容量分配：优先从容量层分配 2、数据迁移策略：向低性能层迁移"]],"answer":["B","D"],"ans_raw":"BD","explain":"选 BD。Oracle OLTP 属热数据，初始分配优先性能层，迁移方向也要向高性能层上收，A 写成向低性能层迁移故错。邮件系统负载平稳、冷热变化不明显，自动分配加自动迁移即可，B 对。归档视频访问极少，除优先从容量层分配外还应显式向低性能层迁移，C 的自动迁移方向不确定，D 对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-104","note":"","flag":"","pnum":104,"ex_src":"编写"},{"num":105,"stem":"在存储上部署随机小 IO 为主的数据库业务，应该选择哪种RAID 类型比较恰当？为什么？","type":"single","options":[["A","RAID 10，没有写惩罚"],["B","RAID 5，没有写惩罚"],["C","RAID 10，没有读惩罚"],["D","RAID 5，没有读惩罚"]],"answer":["A"],"ans_raw":"A","explain":"RAID 5 有写惩罚。RAID 10 在随机写入时，不存在写惩罚，性能优势比较明显。没有读惩罚一说。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-105","note":"","flag":"","pnum":105,"ex_src":"题源"},{"num":106,"stem":"CKG 是由硬盘域中不同类型的不同硬盘上的多个 CK 组成。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"OceanStor 存储系统通过随机算法，将每一个存储层的 Chunk（CK）按照用户设置的“RAID”策略来组成Chunk Group（CKG）。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-106","note":"","flag":"","pnum":106,"ex_src":"题源"},{"num":107,"stem":"FCoE 是将FC 中的帧可以封装在无损以太网中传输协议标准，应用于组建存储网络。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。FCoE 的作用就是把 FC 帧封装进以太网帧，在具备 PFC、ETS 等无损保障的以太网（DCB）上承载完整 FC 协议栈，只更换底层物理链路、保留 FC 语义，用于组建统一存取的存储网络。题干要素齐全，关键限定词无损以太网也已给出，故判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-107","note":"","flag":"","pnum":107,"ex_src":"编写"},{"num":108,"stem":"OceanStor 6800 V3 框内本身可以配置四控，也可以只配置成 2 控。如果配置成双控电源和 BBU 全部配满，接口卡、控制器全部配在上面一排。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。判据是框式高端设备的冗余与槽位规则：一个机框支持四控，也允许只装两个控制器构成双控；电源模块与 BBU 按整机冗余规格配满，不因控制器减半而少配；控制器与其接口卡集中在机框上排槽位布置。题干的三处描述都与这套规则一致，没有偷减冗余条件，故判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-108","note":"","flag":"","pnum":108,"ex_src":"编写"},{"num":109,"stem":"物联网是新一代信息技术的重要组成部分，也是“信息化”时代的重要发展阶段。其英文名称是：Internet of Things（IoT）。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。物联网的英文确为 Internet of Things（IoT），指通过感知、网络与计算技术实现物物相连；把它定位为新一代信息技术的重要组成部分、信息化时代的重要发展阶段，也与通用定义一致。两处分句均无错，整句判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-109","note":"","flag":"","pnum":109,"ex_src":"编写"},{"num":110,"stem":"SmartTier 智能数据分级特性需要存储池中存在三种类型的硬盘。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。SmartTier 的最低要求是存储池中存在两种性能差异明显的介质（如 SSD 加 SAS，或 SAS 加 SATA），两个数据分层就足以做冷热 Extent 迁移，并不强制凑齐三种盘。判据是至少两个分层，而非三种硬盘类型，题干把条件说严了。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-110","note":"","flag":"","pnum":110,"ex_src":"编写"},{"num":111,"stem":"RAID2.0+技术的 Extent 是存储池中哪些技术的基本单位？","type":"multi","options":[["A","申请空间"],["B","释放空间"],["C","数据统计"],["D","数据迁移"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"Extent 是在CKG 基础上划分的固定大小的逻辑存储空间，大小可调，是热点数据统 计和迁移的最小单元（数据迁移粒度），也是存储池中申请空间、释放空间的最小单位。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-111","note":"","flag":"","pnum":111,"ex_src":"题源"},{"num":112,"stem":"主机层容灾包括以下哪几种？","type":"multi","options":[["A","应用级"],["B","数据库级"],["C","阵列级"],["D","逻辑卷级"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"选 ABD。主机层容灾在操作系统之内实现数据一致：应用级靠应用自身双写或重放，数据库级靠日志同步与镜像库，逻辑卷级靠卷管理器复制，三者都发生在主机侧。C 阵列级是存储设备用远程复制、双活实现的，属存储层容灾，与主机层分属不同层级，是最易混的一项。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-112","note":"","flag":"","pnum":112,"ex_src":"编写"},{"num":113,"stem":"FC 依赖于专用的 FC 网络，易形成存储孤岛。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。FC 必须配专用 HBA 和 FC 交换机，无法复用现成的 IP 网络，自成一张独立于业务网的专用 fabric，跨厂商互通与统一管理都受限，投资也更高，因而天然容易形成存储孤岛。这是 FC 相对 iSCSI 的固有短板，判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-113","note":"","flag":"","pnum":113,"ex_src":"编写"},{"num":114,"stem":"NAS 设备在通用服务器的基础上对文件服务、存储、检索、文件访问等功能进行了优化。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。NAS 的构造就是通用服务器去掉应用计算、强化文件服务：硬件仍是 CPU、内存与盘，软件层针对文件共享、存储、检索与访问路径做优化，并通过 NFS、CIFS 直接对外提供文件级服务。题干所列四项正是被优化的部分，与定义一致，故判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-114","note":"","flag":"","pnum":114,"ex_src":"编写"},{"num":115,"stem":"如果一个企业在备份数据时，数据流不经过生产服务器，而是通过独立的网络进行传输，这种备份采用的是哪种备份网络？","type":"single","options":[["A","LAN-Base"],["B","LAN-Free"],["C","Server-Free"],["D","NDMP"]],"answer":["C"],"ans_raw":"C","explain":"常见数据备份方式有：LAN 备份、LAN Free 备份和 SAN Server-Free 备份三种。 LAN 备份针对所有存储类型都可以使用， LAN Free 备份和 SAN Server-Free 备份只能针对 SAN 架构的存储。 1、基于 LAN 的数据备份方式 传统备份的数据备份方式需要在每台主机上安装磁带机备份本机系统，采用 LAN 备份策略，在数据量不是很大时候，可采用集中备份。一台中央备份服务器将会安装在 LAN 中，然后将应用服务器和工作站配置为备份服务器的客户端。中央备份服务器接受运行在客户机上的备份代理程序的请求，将数据通过 LAN 传递到它所管理的、与其连接的本地磁带机资源上。这一方式提供了一种集中的、易于管理的备份方案，并通过在网络中共享磁带机资源提高了效率。 2、LAN-Free 数据备份方式 由于数据通过 LAN 传播，当需要备份的数据量较大，备份时间窗口紧张时，网络容易发生堵塞。在 SAN 环境下，可采用存储网络的 LAN-Free 备份，需要备份的服务器通过 SAN 连接到磁带机上，在 LAN-Free 备份客户端软件的触发下，读取需要备份的数据， 通过 SAN 备份到共享的磁带机。这种独立网络不仅可以使 LAN 流量得以转移，而且它的运转所需的 CPU 资源低于 LAN 方式，这是因为光纤通道连接不需要经过服务器的 TCP/IP 栈，而且某些层的错误检查可以由光纤通道内部的硬件完成。在许多解决方案中需要一台主机来管理共享的存储设备以及用于查找和恢复数据的备份数据库。 3、Server-Free 数据备份方式 SAN Server-Free 对需要占用备份主机的 CPU 资源，如果备份过程能够在 SAN 内部完成，而大量数据流无需流过服务器，则可以极大降低备份操作对生产系统的影响。SAN Server-Free 备份就是这样的技术。 1、 LAN-Base 2、LAN-Free 3、Server-Free","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-115","note":"","flag":"","pnum":115,"ex_src":"题源"},{"num":116,"stem":"在由三块盘组成的一个 RAID5 中，如果 10110110 和 11010011 分别同时被写入组成 同一分条的两块数据盘，那么 01100101 将会被写入校验盘。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。RAID5 的校验块是同分条内各数据块逐位异或的结果。10110110 与 11010011 按位异或得 01100101，与题干给出的校验盘内容完全一致，故判对。判据只有一条：校验值等于同分条数据块的异或，与盘序、条带大小无关。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-116","note":"","flag":"","pnum":116,"ex_src":"编写"},{"num":117,"stem":"如下关于预拷贝的描述，哪项是不正确的？","type":"single","options":[["A","预拷贝是将数据从即将失效的成员盘上拷贝至热备盘上的过程"],["B","将要进行预拷贝的数据必须进行计算和重构"],["C","预拷贝很大程度上降低了数据丢失的风险"],["D","预拷贝要求有热备盘"]],"answer":["B"],"ans_raw":"B","explain":"选 B。预拷贝是把判定为即将失效的成员盘上的数据整盘搬到热备盘，属于盘到盘的原样复制，不需要用校验块参与计算重构；需要计算重构的是盘真正失效后的 RAID 重建，B 把两者混为一谈。A 说搬迁方向、C 说缩短二次故障窗口、D 说必须有空闲热备盘承接，均为正确特征。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-117","note":"","flag":"","pnum":117,"ex_src":"编写"},{"num":118,"stem":"某电子商务网站，平时业务量比较稳定，自己购买服务器搭建私有云运营，但到了双十一促销的时候，业务量非常大，就从运营商的公有云租用服务器，来分担节日的高负荷，这种云计算的部署模式属于？","type":"single","options":[["A","公有云"],["B","私有云"],["C","混合云"],["D","社区云"]],"answer":["C"],"ans_raw":"C","explain":"选 C。自建私有云承载日常稳定业务，大促峰值时租用运营商公有云分担高负荷，即负载溢出（cloud bursting），两种云同时存在并协同工作，构成混合云。A、B 只对应单一部署模式，解释不了平时私有、峰值借公有；D 社区云由多个组织共建共享，与题干场景无关。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-118","note":"","flag":"","pnum":118,"ex_src":"编写"},{"num":119,"stem":"在华为 OceanStor V3 存储系统中，控制器之间的镜像通道用的那种协议？","type":"single","options":[["A","IB"],["B","PCI-E"],["C","FCoE"],["D","iSCSI"]],"answer":["B"],"ans_raw":"B","explain":"选 B。控制器之间的镜像通道要承载写 Cache 实时复制，要求高带宽、低时延的专用高速互联，四个选项中只有 PCI-E 属于这一类。C、D 的 FCoE 与 iSCSI 是对外承载主机 I/O 的前端协议，A 的 IB 多用于服务器集群互联而非 V3 控间通道。需注意 V3 不同档次的控间互联实现并不相同（中端也有基于 IP 的扩展互联），本题只在给定选项里取最贴合专用高速通道的一项。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-119","note":"","flag":"","pnum":119,"ex_src":"编写"},{"num":120,"stem":"差量备份备份的数据是相对于上一次全备份之后增加的和修改过的数据。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在基准点：差量（差异）备份始终以最近一次全备份为基准，备份那次全备之后新增和修改过的数据，因而随时间越滚越大；增量备份则以最近一次备份（不论类型）为基准。题干用的正是差量的定义，没有把基准点说错，故判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-120","note":"","flag":"","pnum":120,"ex_src":"编写"},{"num":121,"stem":"以下有两个关于备份的描述，正确的是： 描述 1：灾备方案不需要考虑是备份在磁带还是硬盘上。描述 2：备份计划要考虑到最糟糕的情况。","type":"single","options":[["A","描述 1 和 2 都是对的"],["B","描述 1 是对的，描述 2 是错的"],["C","描述 1 是错的，描述 2 是对的"],["D","描述 1 和 2 都是错的"]],"answer":["C"],"ans_raw":"C","explain":"选 C。描述 1 错误：备份落磁带还是硬盘，直接决定备份窗口、恢复速度、介质寿命与成本，是灾备方案必须做的选型，不能不考虑。描述 2 正确：备份计划要按最坏情况设计，例如整盘或整站点故障后，需要在恢复窗口内用一次全备加其后各次备份把数据全部还原。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-121","note":"","flag":"","pnum":121,"ex_src":"编写"},{"num":122,"stem":"关于 OceanStor V3 的 LUN 重删，以下描述错误的是？","type":"single","options":[["A","重删功能和 SmartCache 一起使用，可加速提升性能"],["B","接管的异构阵列 LUN 支持块级重删"],["C","重删和远程复制不能在同一 LUN 上共存"],["D","在创建 LUN 的时候选择了重删的 LUN，不能还原到没有做重删的状态"]],"answer":["B"],"ans_raw":"B","explain":"在文件系统开启 SmartCache 的前提下，重删使用文件系统的 SmartCache 加速指纹的比对，以提高系统重删处理性能。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-122","note":"","flag":"","pnum":122,"ex_src":"题源"},{"num":123,"stem":"使用 CIFS 协议访问共享，当共享名称和用户名一致时，访问的共享顺序是：","type":"single","options":[["A","先查询CIFS 共享，如果没有查询到匹配的共享信息，再查询 Homedir 共享"],["B","查询CIFS 共享，如果没有查询到，则返回失败"],["C","先查询 Homedir 共享，如果没有查询到匹配的共享信息，再查询 CIFS 共享"],["D","查询 Homedir 共享，如果没有查询到，则返回失败"]],"answer":["C"],"ans_raw":"C","explain":"选 C。OceanStor 的 CIFS 共享匹配规则是先用共享名去匹配按用户名保留映射的 Homedir 共享，命中即返回该用户的家目录；未命中再按管理员显式创建的 CIFS 共享名查找。A 把优先级颠倒，会让同名用户取不到自己的家目录；B、D 只查一种就报错，缺少回退逻辑。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-123","note":"","flag":"","pnum":123,"ex_src":"编写"},{"num":124,"stem":"一个可靠的 ICT 基础架构，要避免出现设备的单点故障，甚至是人员的单点问题。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。单点不止指硬件。设备层要靠双控、双链路、双电源、冗余盘消除单点；组织层若只有一人掌握配置、口令和恢复流程，同样构成单点，此人不可用就等于业务不可恢复。题干用甚至把冗余范围从设备推到人员，属高可用架构的完整要求，故判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-124","note":"","flag":"","pnum":124,"ex_src":"编写"},{"num":125,"stem":"在华为 OceanStor V3 存储系统中，关于映射快照 LUN 的描述以下哪项是正确的？","type":"single","options":[["A","映射给主机的快照 LUN 只能读，不能写"],["B","激活的快照 LUN 可以映射给主机读写"],["C","快照 LUN 只能映射给与原始 LUN 相同的主机"],["D","所有选项的描述都是对的"]],"answer":["B"],"ans_raw":"B","explain":"选 B。快照 LUN 在未激活时是只读的时间点视图，用于防止任何人破坏这份历史数据；执行激活后它变成可写卷，供测试、备份、分析使用，此时可以正常映射给主机读写。A 忽略了激活这一状态，C 错在快照 LUN 并非只能给源 LUN 的同一主机，D 随之不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-125","note":"","flag":"","pnum":125,"ex_src":"编写"},{"num":126,"stem":"根据容灾效果可以将容灾等级分为：","type":"multi","options":[["A","数据级容灾"],["B","平台级容灾"],["C","应用级容灾"],["D","业务级容灾"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"选 ACD。按容灾效果由低到高分为数据级（只保证有异地数据副本）、应用级（关键应用可切换接管）、业务级（整体业务连续性与流程恢复）三档。B 平台级不属于这一分级体系，容易因为平台听起来比数据更高一档而误选，但该口径下并无此层级。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-126","note":"","flag":"","pnum":126,"ex_src":"编写"},{"num":127,"stem":"以下关于 LAN-BASED 备份方式的特点，描述不正确的是：","type":"single","options":[["A","指令流经过 LAN 网络，数据流不经过 LAN 网络"],["B","备份的代理会影响应用服务器的性能"],["C","备份数据基于 LAN，影响网络性能"],["D","需要单独维护备份业务，增加管理和维护的难度"]],"answer":["A"],"ans_raw":"A","explain":"选 A。LAN-Base 的特征恰恰相反：备份指令流与数据流都走 LAN，数据要从应用服务器经局域网送到备份设备，因此才带来 B 的代理开销、C 的网络拥塞、D 的独立维护负担。A 把数据流不过 LAN 安在 LAN-Base 头上，那是 LAN-Free 走 SAN 传数据的定义，故 A 描述不正确。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-127","note":"","flag":"","pnum":127,"ex_src":"编写"},{"num":128,"stem":"LAN-Base 组网中业务流和数据流都走 LAN 网络，占用较大的带宽。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。判据看数据走向：LAN-Base 组网把备份设备接在局域网内，备份与恢复的数据流同日常业务流复用同一张 LAN，因此占用较大带宽并可能冲击业务，题干与此一致。若改成数据走 SAN、LAN 上只跑指令流，那是 LAN-Free，应按错判。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-128","note":"","flag":"","pnum":128,"ex_src":"编写"},{"num":129,"stem":"某公司员工小王在公司存储系统中做了以下操作：9:00 对 LUN A 做了快照并进行激活，10:00 对快照 LUN 和源 LUN 的数据全部进行了修改，11:00 对快照进行回滚。 以下说明正确的是？","type":"multi","options":[["A","COW 写前拷贝空间中的数据是 9:00 LUN A 的数据"],["B","COW 写前拷贝空间中的数据是 10:00 LUN A 的数据"],["C","源 LUN 的数据是 10:00 修改后的数据"],["D","快照回滚后，源 LUN 的数据变成 10:00 修改后的快照 LUN 的数据"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"选 ACD。COW 在写源 LUN 之前把即将被覆盖的旧块拷入快照空间，保存的是 9:00 快照时刻的数据，A 对；10:00 的新内容留在源 LUN 而不进 COW 区，B 错。源 LUN 被 10:00 改写后其数据就是修改后的数据，C 对。快照激活后对快照 LUN 的修改记录在快照侧，回滚把这份 10:00 修改后的内容写回源 LUN，D 对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-129","note":"","flag":"","pnum":129,"ex_src":"编写"},{"num":130,"stem":"Thick LUN 和Thin LUN 的转换时通过什么技术实现的？","type":"single","options":[["A","克隆"],["B","LUN 迁移"],["C","LUN 拷贝"],["D","卷镜像"]],"answer":["A"],"ans_raw":"A","explain":"选 A。厚薄 LUN 的属性不能在原地直接改，实现转换要新建一个分配类型不同的目标 LUN 再把数据落进去，教材把这一路径归给克隆：克隆产生的从 LUN 可独立指定精简或厚配置。易误选的 B 是 LUN 迁移（SmartMigration），其主用途是把数据在存储池或设备之间换位置、做搬迁与负载均衡；C 的 LUN 拷贝侧重阵列间搬数据，D 的卷镜像只增加冗余副本，都不以转换分配类型为目的。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-130","note":"","flag":"","pnum":130,"ex_src":"编写"},{"num":131,"stem":"在使用 RAID2.0+技术的华为存储系统中，关于 Thick LUN 和Thin LUN 的区别，以下哪项描述是正确的？","type":"multi","options":[["A","Thick LUN 创建时分配存储容量"],["B","Thin LUN 创建时默认不分配存储容量，有数据写入时才分配存储容量"],["C","Thin LUN 比 Thick LUN 更灵活，在大 IO 顺序读写时性能更好"],["D","Thin LUN 使整个存储空间利用率更高"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"一个 LUN 可以创建为 Thick LUN 和Thin LUN。Thick LUN 将预先从存储池中分配存 储容量，即使Thick LUN 上没有存储任何用户数据。而Thin LUN 不会预先从存储池中分配存储容量，只有当用户数据写入 Thin LUN，才会从存储池中分配实际的存储容量。 顺序读：由于 thin LUN 是按照用户的实际需求动态分配存储资源，空间分配在时间上存在不连续性，因此会影响到其映射到磁盘上的空间连续性。而 thick LUN 在创建时，系统通过自动资源配置技术从存储资源中一次性为其分配存储资源，最大限度上保证了其映射到磁盘上的空间连续性。对于机械磁盘顺序读取效率更高，因此顺序读时，thick LUN 性能优于 thin LUN。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-131","note":"","flag":"","pnum":131,"ex_src":"题源"},{"num":132,"stem":"大数据的特征有以下哪几项？","type":"multi","options":[["A","一次写入，多次修改"],["B","数据的价值不确定"],["C","容量大，增长速度快"],["D","保存时间长"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"选 BCD。大数据在写入模型上是一次写入、多次读取，数据基本不做原地修改，以保证分布式一致与并发访问，A 把读写成修改故错。B 对应价值密度低、需分析才显价值；C 对应 Volume 与 Velocity；D 对应长期留存以支撑回溯与挖掘，均为其典型特征。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-132","note":"","flag":"","pnum":132,"ex_src":"编写"},{"num":133,"stem":"下列关于 DAS 的描述，错误的是？","type":"single","options":[["A","DAS 是指将存储设备通过 SCSI 线缆或光纤通道直接连接到服务器上"],["B","DAS 方式数据依然是分散的，不同的应用各有一套存储设备。管理分散，无法集中"],["C","服务器与存储设备直接连接的方式导致出现新的应用需求时，只能为新增的服务器单独配置存储设备，造成重复投资"],["D","DAS 方式的存储空间可以充分利用，不同的应用服务器可以共享的存储设备，充分利用闲置的存储空间"]],"answer":["D"],"ans_raw":"D","explain":"选 D。DAS 把存储用 SCSI 线缆或光纤通道直连单台服务器，设备与主机绑定，其他应用看不到也用不了它的空闲空间，所以不可能共享存储设备、盘活闲置容量，D 描述的其实是 SAN/NAS 的优点，为错误说法。A 是定义，B 讲数据分散、管理难集中，C 讲新应用只能另配一套造成重复投资。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-133","note":"","flag":"","pnum":133,"ex_src":"编写"},{"num":134,"stem":"下列的备份介质中，单位容量的价格从低到高的顺序是：","type":"single","options":[["A","磁带，CD/DVD，SSD，虚拟带库"],["B","CD/DVD，磁带，虚拟带库，SSD"],["C","磁带，CD/DVD，虚拟带库，SSD"],["D","CD/DVD，SSD，磁带，虚拟带库"]],"answer":["C"],"ans_raw":"C","explain":"选 C。磁带单盒容量大、摊薄后每 GB 成本最低；CD/DVD 每 GB 高于磁带但仍是廉价介质；虚拟带库本质是基于磁盘阵列加备份软件的设备，成本高于光盘；SSD 每 GB 最贵，故顺序为磁带、CD/DVD、虚拟带库、SSD。易错是选 B，把 CD/DVD 当最便宜，忽略了单盒容量太小、按容量摊算反而更贵。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-134","note":"","flag":"","pnum":134,"ex_src":"编写"},{"num":135,"stem":"在华为 OceanStor V3 存储系统中，关于文件级 HyperSnap 特性数据恢复的描述，哪些是正确的？","type":"multi","options":[["A","可以恢复单个文件"],["B","可以恢复发生逻辑错误的原始文件"],["C","可以恢复误删除的原始文件"],["D","可以恢复发生物理故障的文件系统上的文件"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"选 ABC。文件级 HyperSnap 允许从快照中按需还原单个文件，不必整卷回滚（A）；误删除的文件，以及被覆盖、篡改造成逻辑错误的原始文件，都能用时间点副本找回（B、C）。D 不成立：快照只记录时间点、不提供数据冗余，盘片或硬件物理故障要靠 RAID、复制与备份兜底。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-135","note":"","flag":"","pnum":135,"ex_src":"编写"},{"num":136,"stem":"在传统 RAID 组中，当有一定数量的硬盘失效后整个 RAID 组能够防止数据丢失，并且数据恢复进程尚未启动，这个状态是？","type":"single","options":[["A","正常工作"],["B","降级"],["C","失效"],["D","重构"]],"answer":["B"],"ans_raw":"B","explain":"选 B。失效盘数仍在 RAID 冗余能力之内、数据不丢但保护度下降，且重建尚未开始，这一带病工作状态就是降级。A 正常指没有任何盘失效；C 失效指超出冗余能力、数据已不可用；D 重构指已经开始重算或搬移数据到新盘，题干明确恢复进程尚未启动，正是排除 D 的依据。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-136","note":"","flag":"","pnum":136,"ex_src":"编写"},{"num":137,"stem":"磁盘读写的时候都是以扇区为最小寻址单位的，可以往某个扇区的前半部分写入一段数据，再往另一个扇区写入一段数据。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。前半句对、后半句错，整句判错。扇区是磁盘最小寻址与读写单位，一次操作以整扇区为粒度，不能只写半个扇区再另写一个扇区；若上层下发不足一扇区的数据，设备必须读出整扇区、改写后再写回。文件系统引入簇与分区对齐，正是为了避免这种半扇区操作。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-137","note":"","flag":"","pnum":137,"ex_src":"编写"},{"num":138,"stem":"描述 1：SAN 存储的文件系统部署在存储端，NAS 存储的文件系统在主机端。描述 2：动态分级存储可以实现数据在不同性能的存储介质之间迁移","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 错误，描述 2 错误"]],"answer":["C"],"ans_raw":"C","explain":"选 C。描述 1 说反了：SAN 对主机提供的是块设备，文件系统建在主机端的操作系统上；NAS 直接输出文件级服务，文件系统在其存储端。描述 2 正确，动态分级存储按访问热度在 SSD、SAS、SATA 等不同性能介质之间迁移数据。故为描述 1 错、描述 2 正确。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-138","note":"","flag":"","pnum":138,"ex_src":"编写"},{"num":139,"stem":"下列关于 OceanStor V3 特性错误的有？","type":"single","options":[["A","克隆提供物理全拷贝，可增量拷贝"],["B","克隆不支持跨引擎 LUN 克隆，主从 LUN 必须在同一个引擎下"],["C","LUN 拷贝可以支持阵列内、阵列间（包含同构和异构）的数据备份和迁移"],["D","LUN 拷贝支持增量 LUN 拷贝，并且 LUN 拷贝要离线进行"]],"answer":["D"],"ans_raw":"D","explain":"选 D。D 错在必须离线这一限定：LUN 拷贝采用全量加增量的异步方式，拷贝过程中源 LUN 仍可继续读写，只在最后切换收口时短暂暂停，离线不是它的前提。A 正确，克隆先做物理全拷贝再增量同步；B 正确，克隆是引擎内特性，主从 LUN 须在同一引擎下；C 正确，覆盖阵列内与同构、异构阵列间。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-139","note":"","flag":"","pnum":139,"ex_src":"编写"},{"num":140,"stem":"如果同城灾备中心故障了，那么级联组网方式的生产中心就会失去所有的备份站点。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。级联（链式）组网的数据流是生产中心到同城、再由同城到异地，同城站点是异地上行的唯一复制源，它故障即切断整条链路，生产中心不再有任何可用备份站点接收更新，故判对。平行组网因生产中心同时向两地复制，才会剩下另一条独立路径，这是两种组网的关键差异。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-140","note":"","flag":"","pnum":140,"ex_src":"编写"},{"num":141,"stem":"OceanStor V3 系列存储只能单独支持 iSCSI 或 FC 主机链接，不能同时支持两种主机链接组网方式。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。V3 的前端接口卡可按需混插，同一套系统既能提供 FC 链路也能提供 iSCSI 链路，一个 LUN 还可以通过 LUN 组同时映射给 FC 主机组和 IP 主机组，两种主机链接方式能够共存。题干把可以选其一说成只能其一，否掉了混合组网能力，故判错。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-141","note":"","flag":"","pnum":141,"ex_src":"编写"},{"num":142,"stem":"以下哪项是华为 OceanStor V3 存储系统正确的配置过程？","type":"single","options":[["A","创建存储池->创建 LUN->添加映射"],["B","创建存储池->添加映射->创建 LUN"],["C","创建 LUN->创建存储池->添加映射"],["D","创建 LUN->添加映射->创建存储池"]],"answer":["A"],"ans_raw":"A","explain":"选 A。依赖顺序决定流程：RAID2.0+ 下 LUN 必须从存储池划分 Extent 才能创建，池是 LUN 的前提；映射是把已存在的 LUN 经 LUN 组与主机组分配给主机，没有 LUN 就无从映射。因此是创建存储池、创建 LUN、添加映射。B、C、D 都颠倒了对前后置关系的依赖。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-142","note":"","flag":"","pnum":142,"ex_src":"编写"},{"num":143,"stem":"x86 架构属于数据中心基础架构中的一种类型。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"数据中心基础架构按承载的业务与服务器体系分类，x86 通用计算体系是其中最主流的一类（与之并列的还有小型机、大型机等体系），题干只说「属于其中一种」，未说唯一，判对。判据在于「一种」而非「全部」。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-143","note":"","flag":"","pnum":143,"ex_src":"编写"},{"num":144,"stem":"在盘不能访问的期间，对盘进行写操作时，使用的是哪种重构方式？","type":"single","options":[["A","全盘重构"],["B","局部重构"],["C","恢复重构"],["D","本地重构"]],"answer":["C"],"ans_raw":"C","explain":"选 C。盘处于不可访问期间，新写的数据先落在为其顶替的热备 CK 上；该盘修复重新上线后，要把这段期间产生的数据从热备 CK 回补到原盘、让数据回归原位，这一过程即恢复重构。干扰项：全盘重构用于整盘或整 CKG 失效，局部重构只处理介质异常块，本地重构不是 RAID2.0+ 的重构类型。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-144","note":"","flag":"","pnum":144,"ex_src":"编写"},{"num":145,"stem":"卷镜像即 HyperMirror 主要应用哪些镜像场景？","type":"multi","options":[["A","本阵列内两个 LUN 的镜像"],["B","配合异构虚拟化功能实现异构阵列的 LUN 与本阵列的镜像"],["C","配合异构虚拟化功能实现两个异构 LUN 的镜像"],["D","卷镜像的两个 LUN 的镜像不在同一个归属控制器下"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"HyperMirror 做卷镜像，覆盖本阵列内两个 LUN 互为镜像、经异构虚拟化把第三方阵列 LUN 与本阵列 LUN 镜像、以及两个异构 LUN 之间镜像，故选 ABC。最易误选 D：镜像要求主备 LUN 归属同一控制器，由同一控制器保证两份写的一致性与顺序，跨控制器不属于其支持场景。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-145","note":"","flag":"","pnum":145,"ex_src":"编写"},{"num":146,"stem":"备份关注的是数据的可恢复性，容灾关注的是业务的连续性。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。备份交付的是可回拷的数据副本，考核点是能不能把数据找回来，属可恢复性；容灾交付的是可接替生产的站点与链路，考核点是业务能否不中断或在很短时间内继续跑，属连续性。两者的目标指标分别是 RPO 与 RTO，题干表述与定义一致。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-146","note":"","flag":"","pnum":146,"ex_src":"编写"},{"num":147,"stem":"在 Linux 系统中，如果某个 SCSI 目标的表示为：2:1:0:3，则以下描述正确的是：（此题 为多选题）","type":"single","options":[["A","设备 LUN ID 为 3"],["B","总线 ID 为 0"],["C","目标器 ID 为 3"],["D","LUN ID 为 0"]],"answer":[],"ans_raw":"我也不知道","explain":"","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-147","note":"题源未给答案，原书批注：“我也不知道，个人感觉题目有问题”","flag":"","pnum":147,"ex_src":""},{"num":148,"stem":"以下哪项是对象存储的优点？","type":"multi","options":[["A","对象接口，灵活分割数据"],["B","外部 SCSI 或者文件接口"],["C","对象扁平化，易于访问和扩展"],["D","提高了数据的完整性和安全性"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"对象存储用 REST 类对象接口、把数据当作带元数据的整体存取，不受目录层级约束，可灵活切分；命名空间扁平、无中心目录树，扩容只加节点；再配合冗余放置与元数据校验保证完整性，故选 ACD。B 错：SCSI 是块存储接口、文件接口属 NAS，对象存储对外不提供这两类外部接口。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-148","note":"","flag":"","pnum":148,"ex_src":"编写"},{"num":149,"stem":"数据中心存储管理员的维护项目有以下哪几项？","type":"multi","options":[["A","首次维护项目"],["B","每周定期维护项目"],["C","每日定期维护项目"],["D","实时维护项目"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"存储维护按周期归类，分首次（上线）维护、每日巡检和每周定期维护三类，故选 ABC。D 的「实时维护项目」不是一类维护项：需要实时处理的是告警与故障，属事件驱动的运维流程，不列入周期性维护清单。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-149","note":"","flag":"","pnum":149,"ex_src":"编写"},{"num":150,"stem":"下列描述正确的是：","type":"multi","options":[["A","OceanStor V3 系列产品支持 8 控，控制器之间的交换平面是基于 IP 的 Scale-out 互连"],["B","OCeanStor 5300 V3 的控制框由 2 控扩展到 4 控时，既可以采用直连组网，也可以采用交换机组网"],["C","OceanStor V3 系列新一代存储产品中，同一张 SAS 接口卡的后端环路可以混合连接着普通硬盘框和高密度硬盘框"],["D","OceanStor V3 中端存储阵列采用 IP 交换机互连有成本优势，PCIe 交换机属于专用交换机，成本相对较高，主要应用于高端存储"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"V3 中端支持 8 控、控制器间用基于 IP 的 Scale-out 互连，5300 V3 由 2 控扩到 4 控时既可直连也可走交换机，IP 交换机比高端所用的 PCIe 专用交换机成本低，故 ABD 正确。C 错：同一条 SAS 链路（同一张 SAS 接口卡的环链）上不允许混接普通硬盘框与高密度硬盘框，必须按盘框类型分开连接，否则链路的盘数与拓扑规格不一致。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-150","note":"","flag":"","pnum":150,"ex_src":"编写"},{"num":151,"stem":"如下对于 RAID 1 的描述，哪项是不正确的？","type":"single","options":[["A","RAID 1 写入数据到每个成员盘，每个成员盘上的数据都是相同的"],["B","RAID 1 采用XOR 算法校验"],["C","通常情况下，RAID 1 从数据盘和镜像盘读取数据"],["D","当某些成员盘的数据被损坏，RAID 1 允许其从其它成员盘上快速恢复数据"]],"answer":["B"],"ans_raw":"B","explain":"B 的说法不成立：RAID 1 用整盘镜像冗余，把同一份数据写进每个成员盘，不做 XOR 校验，奇偶校验是 RAID 3/4/5/6 的机制。其余三项都对——镜像即多副本，读可分别从数据盘与镜像盘取，坏盘后直接从另一份副本恢复。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-151","note":"","flag":"","pnum":151,"ex_src":"编写"},{"num":152,"stem":"OceanStor 5300 V3 是双控制器融合存储产品，必须保证 LUN 的工作控制器和归属控制器一致。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。归属控制器是 LUN 配置的处理者，工作控制器是当前实际承接该 LUN I/O 的控制器；多路径会把经由非归属控制器的请求转发过去，控制器故障或负载切换时接管端也会变更，两者本就可以不一致。题干把常态当成强制约束，判错。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-152","note":"","flag":"","pnum":152,"ex_src":"编写"},{"num":153,"stem":"同步远程复制管理模块 RM 是软件。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。远程复制的控制平面由 RM（复制管理）模块与 RA（复制代理）模块组成，两者都是软件，RM 负责复制关系配置、状态监控与切换控制，RA 负责具体执行复制，故「RM 是软件」成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-153","note":"","flag":"","pnum":153,"ex_src":"编写"},{"num":154,"stem":"精简配置技术给客户带来的价值有？","type":"multi","options":[["A","提高存储资源利用率"],["B","减少数据占用的存储空间"],["C","降低初次购买成本"],["D","降低存储系统整体TCO"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"精简配置按主机实际写入量分配物理空间，逻辑容量先超分给出，所以能提高利用率、推迟扩容采购、降低整体 TCO，选 ACD。B 是最易误选项：Thin 只是推迟分配，落盘的数据仍按原大小占用空间，真正减少数据占用的是重删与压缩。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-154","note":"","flag":"","pnum":154,"ex_src":"编写"},{"num":155,"stem":"同城容灾中心的 RTO=0，RPO=0。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"同步远程复制适用于同城灾备，对网络要求高，但数据丢失量（RPO）可以为 0","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-155","note":"","flag":"","pnum":155,"ex_src":"题源"},{"num":156,"stem":"以下对于 iSCSI 的三种连接方式描述正确的是？","type":"single","options":[["A","以太网卡+initiator 软件的连接方式完全不占用主机资源"],["B","硬件TOE 网卡+initiator 软件的连接方式，减少主机资源压力"],["C","iSCSI HBA 卡完成TCP/IP 协议转换，完全不占用主机资源"],["D","TOE 网卡完成iSCSI 报文到 TCP/IP 报文转换"]],"answer":["B"],"ans_raw":"B","explain":"B 对：TOE 网卡把 TCP/IP 校验与分段卸载给网卡，主机仍跑 initiator 软件，协议栈开销明显下降。A 错：普通网卡加纯软件的 iSCSI initiator 全靠 CPU 封包，占用主机资源最多。C 错在「完全不占用」，HBA 只是把 SCSI 与 TCP/IP 处理全部卸载，命令下发与驱动仍有主机开销。D 错：TOE 只卸载 TCP/IP，iSCSI 报文转换由 initiator 软件或 iSCSI HBA 完成。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-156","note":"","flag":"","pnum":156,"ex_src":"编写"},{"num":157,"stem":"关于华为 RAID 2.0+的优势，描述正确的是？","type":"multi","options":[["A","数据在存储池中硬盘上的自动均匀分布，避免了硬盘的冷热不均，从而降低了存储系统整体的故障率"],["B","克服了传统RAID 重构的目标盘（热备盘）性能瓶颈，使得重构数据流的写带宽不再成为重构速度的瓶颈，从而大大提升了重构速度，降低了双盘失效的概率，提升了存储系统的可靠性。"],["C","RAID2.0+中不存在写惩罚，克服了传统 RAID 技术中 RAID 5 和RAID 6 级别中的写惩罚对 LUN 写性能的影响，使得 LUN 性能大幅度提升"],["D","单个 LUN 上的数据分布到很多不同的硬盘上，避免了硬盘热点，使得单 LUN 性能和容量都得到了大幅度提升"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"RAID2.0+ 把盘切成 CK 后在硬盘域内均衡分布，全盘参与 I/O，既避免冷热不均也消除单盘热点，故 A、D 对；重构以 CK 粒度并行写到多盘的热备空间，没有独立热备盘的写带宽瓶颈，B 对；写落到大量不同 CKG 上，不必像传统 RAID5/6 那样在同一校验单元上反复读改写，写惩罚被摊薄，C 对，四项全选。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-157","note":"","flag":"","pnum":157,"ex_src":"编写"},{"num":158,"stem":"下列关于华为 RAID 2.0+的说法正确的是？","type":"multi","options":[["A","热备空间不能跨引擎"],["B","RAID 2.0+使用了独立的热备盘"],["C","Chunk 大小和 Extent 大小都不可调整"],["D","根据热备策略自动在硬盘域中预留一定数量的热备空间"]],"answer":["A","D"],"ans_raw":"AD","explain":"选 AD。热备空间按引擎预留、只在同类型盘的 CK 内顶替故障盘，不能跨引擎共享，系统按热备策略在硬盘域中自动预留，这两条正确。B 错：RAID2.0+ 用热备空间而非独立热备盘，整盘热备属传统 RAID。C 错在「都不可调」：CK 由系统按盘类型与容量自动切分不可设，但上层 Extent 粒度可在建池时选择。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-158","note":"","flag":"","pnum":158,"ex_src":"编写"},{"num":159,"stem":"描述 1：NAS 的文件系统由提供资源的存储或服务器管理。描述 2：SAN 的文件系统由主机自身管理。","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 错误，描述 2 错误"]],"answer":["A"],"ans_raw":"A","explain":"两个描述都对，故选 A。NAS 对外给的是共享目录，文件系统与元数据都在阵列侧的 NAS 引擎上维护，主机不建文件系统；SAN 只暴露裸 LUN，文件系统由主机操作系统创建并独占管理，多主机同读写还得靠集群文件系统协调。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-159","note":"","flag":"","pnum":159,"ex_src":"编写"},{"num":160,"stem":"以下关于云计算的描述正确的有？","type":"multi","options":[["A","云计算动态可伸缩"],["B","云计算的最终用户需要了解云计算是如何运行的"],["C","云计算可以提供虚拟磁盘空间"],["D","云计算通常在需要高性能和高响应速度的业务系统中使用"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"云计算的特征是按需自助、泛在接入、资源池化、快速弹性与计量服务，可动态伸缩并按需给出虚拟磁盘等池化资源，业务也能靠弹性调度快速取得算力，故 ACD 对。B 错在违背「资源抽象、对用户透明」这一条：最终用户只关心申请的规格和用量，无需知道底层如何调度运行。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-160","note":"","flag":"","pnum":160,"ex_src":"编写"},{"num":161,"stem":"用于备份目的的快照应该设置为只读，以防止被其它应用程序修改，影响备份数据的一致性。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。快照的意义是固化某一时点的视图，若快照 LUN 还允许写，新 I/O 会改变视图、并额外消耗池内空间，备份出去的就不是那个时点的一致性数据。判据是用途：为备份/校验而映射出去的快照应设只读。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-161","note":"","flag":"","pnum":161,"ex_src":"编写"},{"num":162,"stem":"以下有两个关于光纤交换机的描述，正确的是： 描述 1：一个端口可以在多个 zone 中。 描述 2：一个交换机可以有多个 zone。","type":"single","options":[["A","描述 1 和描述 2 都对"],["B","描述 1 对，描述 2 错"],["C","描述 1 错，描述 2 对"],["D","描述 1 和描述 2 都错"]],"answer":["A"],"ans_raw":"A","explain":"两个描述都对，故选 A。Zone 只是成员的集合，一个端口可以同时属于多个 zone，便于多主机共同访问同一设备；一台交换机可划多个 zone，再由 zone set 决定哪些集合生效。可见 zone 是访问控制边界，不是数量互斥限制。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-162","note":"","flag":"","pnum":162,"ex_src":"编写"},{"num":163,"stem":"云数据中心对存储、计算和网络资源进行虚拟化，并提供虚拟化平台给用户使用。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。云数据中心的定义就是把计算、存储、网络三类资源虚拟化后形成资源池，再以平台方式按需交付给用户，题干的「虚拟化 + 虚拟化平台交付」正是其两个必要构成，与定义吻合。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-163","note":"","flag":"","pnum":163,"ex_src":"编写"},{"num":164,"stem":"关于 DAS 的优点，以下描述正确的是：","type":"multi","options":[["A","部署很简单"],["B","初期投资大"],["C","组网复杂度小"],["D","配置比较复杂"]],"answer":["A","C"],"ans_raw":"AC","explain":"DAS 直接挂在服务器上，不引入交换网络与专用协议栈，所以部署简单、组网复杂度小，选 AC。B、D 恰与其优点相反：DAS 初期投入低、单机配置简单，真正的短板是容量与数据无法共享、形成信息孤岛、规模化后只能逐台扩容管理。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-164","note":"","flag":"","pnum":164,"ex_src":"编写"},{"num":165,"stem":"某银行员工小 A 在数据中心存储首次维护项目中需要做以下哪些操作？ A、检查Toolkit 安装 B、检查 eService 安装与配置 C、检查告警策略配置","type":"single","options":[["A","AB"],["B","ABC"],["C","C"]],"answer":["B"],"ans_raw":"B","explain":"三项都属于设备上线后的首次维护内容：Toolkit 是主机侧安装与多路径工具包，eService 是远程维护通道与自动上报，告警策略决定故障能否被及时发现与定位，故选 B。易错是以为告警可留到日常维护再做，首次维护就要配好。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-165","note":"","flag":"","pnum":165,"ex_src":"编写"},{"num":166,"stem":"增量备份备份的数据量大于差量备份。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。增量备份只保存自上一次备份（含上一次增量）以来变化的数据，差量备份保存自上一次完全备份以来的全部变化，后者覆盖范围必然更大。判据是参照点：增量的参照点是「最近一次任何备份」，差量固定参照完全备份，故题干把大小关系说反。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-166","note":"","flag":"","pnum":166,"ex_src":"编写"},{"num":167,"stem":"以下说法正确的是？","type":"single","options":[["A","6 个 200G 的硬盘做RAID 5 之后可用空间为 1200G"],["B","NL SAS/SATA 硬盘适合使用 RAID 6 进行数据保护，SAS 硬盘适合使用 RAID 5 进行数据保护"],["C","S2200 V3 可以支持 SSD、SAS、SATA 硬盘"],["D","OceanStor V3 系列产品支持 RAID 0/RAID 1/RAID 5/RAID 10，不支持RAID 6"]],"answer":["B"],"ans_raw":"B","explain":"OceanStor 2200 V3 支持的硬盘类型有：SAS、NL-SAS 和 SSD，不支持 SATA。OceanStor V3 系列产品支持 RAID 6","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-167","note":"","flag":"","pnum":167,"ex_src":"题源"},{"num":168,"stem":"华为 OceanStor V3 存储系统的初始容量分配策略默认为自动分配。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。V3 创建 Thin LUN 时的初始容量分配策略有自动分配、优先高性能层、优先容量层等选项，系统默认取自动分配，由系统按各层空闲情况决定落盘位置，故判对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-168","note":"","flag":"","pnum":168,"ex_src":"编写"},{"num":169,"stem":"描述 1：ICT 基础设施应该用可靠性高的高端设备建造，因而不需要建立备份。 描述 2：服务器通常被用来指一些企业中规格较高的计算机，这些计算机通常会安装企业中一些重要的软件，运行重要的业务。","type":"single","options":[["A","描述 1 和描述 2 都正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 和描述 2 都错误"]],"answer":["C"],"ans_raw":"C","explain":"描述 1 错、描述 2 对，故选 C。高可靠设备只能降低本地硬件故障概率，防不住误删除、逻辑损坏、勒索加密与站点级灾难，备份仍然必需；描述 2 只是服务器的一般定义，成立。判据：可靠性冗余与数据可恢复性是两件事。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-169","note":"","flag":"","pnum":169,"ex_src":"编写"},{"num":170,"stem":"某公司使用 CIFS 协议进行文件共享，根据安全策略使用 Homedir 共享方式，提供给所有用户访问文件夹和写入的空间。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。判据是协议与共享方式是否匹配：CIFS（SMB）面向 Windows 客户端的文件共享，Homedir 会按用户在共享根目录下分配各自私有且可读写的目录，所以「提供访问文件夹和写入的空间」成立。Homedir 的限制是用户只能进入自己的目录、彼此不可互访，这是该方式的安全特性，不构成题干错误。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-170","note":"题源原解析（排版截断）：“CIFS 为 Windows 用，”","flag":"","pnum":170,"ex_src":"编写"},{"num":171,"stem":"以下有两个关于备份的描述，正确的是： 描述 1：保存周期是指备份所需要花费的时间。 描述 2：增量备份在三种备份类型中花费时间最长。","type":"single","options":[["A","描述 1 和 2 都是对的"],["B","描述 1 是对的，描述 2 是错的"],["C","描述 1 是错的，描述 2 是对的"],["D","描述 1 和 2 都是错的"]],"answer":["D"],"ans_raw":"D","explain":"两个描述都错，故选 D。保存周期指备份数据的保留时长（保留几代、多久可回收介质），不是备份耗时；完全备份每次复制全量数据，耗时最长，增量只复制变化部分、单次耗时最短，其代价体现在恢复链条长而不是备份慢。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-171","note":"","flag":"","pnum":171,"ex_src":"编写"},{"num":172,"stem":"在华为 OceanStor V3 存储系统中，以下关于 SmartThin LUN 的哪项描述是对的？","type":"single","options":[["A","在创建一个精简 LUN 的时候，不能分配给它比所在存储池可用空闲空间更大的容量"],["B","Thin LUN 不能转变成 Thick LUN"],["C","创建Thin LUN 时可用不指定初始分配容量"],["D","一个存储池上的 LUN 的类型必须一致，要么都是Thin LUN，要么都是 Thick LUN"]],"answer":["C"],"ans_raw":"C","explain":"Thin LUN 在创建的时候，可以设置一个初始分配容量。创建完成后，存储池 Pool 只会分配这个初始容量大小的空间，剩余的空间仍然放在存储池中。当Thin LUN 已分配的存储空间的使用率达到阈值时，存储系统才会再从Pool 中划分一定的配额给Thin LUN。如此反复，直到达到 Thin LUN 最初设定的全部容量。因此，它拥有较高的存储空间利用率。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-172","note":"","flag":"","pnum":172,"ex_src":"题源"},{"num":173,"stem":"以下有两个关于备份的描述： 描述 1：任何时间都可以使用备份在磁带上的数据进行数据恢复，但是只能恢复到备份时刻的历史数据，而不是故障时的数据。 描述 2：采用磁带做备份介质，是RTO 最高的备份方法。","type":"single","options":[["A","描述 1 是对的，描述 2 是对的"],["B","描述 1 是对的，描述 2 是错的"],["C","描述 1 是错的，描述 2 是对的"],["D","描述 1 是错的，描述 2 是错的"]],"answer":["A"],"ans_raw":"A","explain":"两个描述都对，故选 A。备份是周期性副本，介质上只有各备份时点的数据，恢复只能回到最近一次备份时刻，故障后写入的部分不在介质上；磁带是顺序寻址介质，装载、定位与串流回拷使恢复耗时以小时甚至天计，是各类备份方式中 RTO 最高的。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-173","note":"","flag":"","pnum":173,"ex_src":"编写"},{"num":174,"stem":"下列传输协议可以不使用交换机的是？","type":"single","options":[["A","iSCSI 协议"],["B","SCSI 协议"],["C","FC 协议"],["D","FCoE 协议"]],"answer":["B"],"ans_raw":"B","explain":"选 B。SCSI 是主机与设备之间的点对点/总线型 I/O 协议，用电缆直连即可工作，链路中本就没有交换设备。iSCSI 跑在以太网上、FC 跑在 FC 网络上、FCoE 把 FC 帧承载于以太网，要形成多主机与多设备的存储网络都得配交换机。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-174","note":"","flag":"","pnum":174,"ex_src":"编写"},{"num":175,"stem":"常用的容灾技术通常有以下哪三种？","type":"multi","options":[["A","基于主机层的容灾"],["B","基于网络层的容灾"],["C","基于阵列层的容灾"],["D","基于应用层的容灾"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"教材按复制逻辑所在位置把容灾分为主机层（主机卷复制软件）、网络层（交换网络或虚拟化网关）、阵列层（阵列原生远程复制）三类，故选 ABC。D 的应用层容灾（靠数据库/应用自身同步）是另一套体系，不在这三分法内。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-175","note":"","flag":"","pnum":175,"ex_src":"编写"},{"num":176,"stem":"iSCSI 是把 SCSI 命令和数据描述块封装成了 iSCSI 协议。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。iSCSI 的本质是 SCSI over TCP/IP：发起端把 SCSI 命令描述块、数据与状态信息封装成 iSCSI 协议数据单元，交给 TCP 通道在 IP 网络上传输，会话由 IQN 加 IP 地址标识。判据是它只改变承载方式、不改变 I/O 语义，靠 IP 网络延展了 SCSI 的可达距离，题干表述成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-176","note":"","flag":"","pnum":176,"ex_src":"编写"},{"num":177,"stem":"SAN 对于 NAS 统一存储的方案优势不包含：","type":"single","options":[["A","用户不用去单独规划 SAN 和 NAS 存储容量"],["B","用户可以自由分配存储来满足应用环境的需求"],["C","用户不用关心对数据块及文件存储支持相关的容量利用率方面的问题"],["D","用户买一套 SAN 就可以实现 NAS 的功能"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）按华为统一存储口径，不必分别规划 SAN 与 NAS 容量、可在块与文件之间自由分配、无需操心两者各自的容量利用率，正是统一存储相对分离部署的三条优势，A、B、C 均成立；真正不属于优势的是 D：块阵列要提供文件共享必须另配 NAS 引擎与文件服务授权，不是买一套 SAN 就能实现 NAS。题干问法表述串行，按此口径应选 D，请复核答案键。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-177","note":"","flag":"","pnum":177,"ex_src":"编写"},{"num":178,"stem":"以下说法错误的是：","type":"multi","options":[["A","备份无法解决数据损坏的找回"],["B","备份解决数据丢失的找回"],["C","备份无法解决历史数据的找回"],["D","备份可以直接接管业务"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"题目问错误说法，故选 ACD。备份副本本身就用来找回被损坏、被误删的历史数据，所以「无法解决数据损坏」「无法解决历史数据找回」两项不成立；备份也不接管业务，接管生产是容灾的能力，备份必须执行恢复动作、RTO 很长。只有 B 是备份的正确定位。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-178","note":"","flag":"","pnum":178,"ex_src":"编写"},{"num":179,"stem":"如果某公司的业务是大规模数据随机写入 LUN 中，那推荐哪种容量初始分配策略和哪种数据迁移策略？","type":"single","options":[["A","自动分配：向低性能层迁移"],["B","优先从高性能层分配：向低性能层迁移"],["C","优先从低性能层分配：向高性能层迁移"],["D","优先从容量层分配：自动迁移"]],"answer":["D"],"ans_raw":"D","explain":"选 D。数据量大、随机写且访问分散时，热度难以判定、命中率低，把初始空间优先落在大容量容量层可省出昂贵的 SSD/SAS 资源，迁移策略交给自动迁移按实际活跃度决定，比强制向某一层迁移更合理。注意：若业务对写时延高度敏感且数据量可控，实践上更倾向优先高性能层分配，本题的关键限定是「大规模」。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-179","note":"","flag":"","pnum":179,"ex_src":"编写"},{"num":180,"stem":"在华为存储系统中，关于虚拟快照 LUN 的特点描述以下哪项是正确的？","type":"multi","options":[["A","存储系统可以在几秒钟内生成一个快照"],["B","快照 LUN 不能映射到主机"],["C","完整的数据复制是不必要的"],["D","数据使用映射表查找"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"虚拟快照只创建快照对象与源 LUN 的映射关系，不做完整数据复制，所以能在秒级生成，写过的块才占用快照空间，读取时靠映射表判断该块取源 LUN 还是快照空间，故选 ACD。B 错：快照 LUN 可以映射给主机，用于备份、校验或报表读取，只是应保持只读。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-180","note":"","flag":"","pnum":180,"ex_src":"编写"},{"num":181,"stem":"SATA 连接器可以同时支持 SATA 和 SAS 硬盘。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。兼容性是单向的：SAS 控制器与背板能识别并驱动 SATA 盘（走 STP 转换），而 SATA 连接器/扩展器没有 SAS 所需的双端口与 SAS 信号，插 SAS 盘无法工作。判据看接口定义哪一侧是超集，SAS 口兼容 SATA，反之不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-181","note":"","flag":"","pnum":181,"ex_src":"编写"},{"num":182,"stem":"关于 ICT 新时代及技术，以下说法正确的是？","type":"multi","options":[["A","云计算（cloud computing）是基于互联网的相关服务的增加、使用和交付模式，通常涉及通过互联网来提供动态易扩展且经常是虚拟化的资源"],["B","社交媒体（social media）是人们用来创作、分享、交流意见、观点及经验的虚拟社区和网络平台"],["C","CPS（Cyber Phsical System）包含了将来无处不在的环境感知，嵌入式计算、网络通 信和网络控制等系统工程，是物理系统具有计算、通信、精确控制、远程协作和自治功能"],["D","在新 ICT 时代 ICT 系统从支撑系统向生产系统迁移"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项均为教材定义，全选。云计算是按需交付、动态易扩展、通常虚拟化的互联网相关服务模式；社交媒体是创作、分享、交流观点的虚拟社区与网络平台；CPS（Cyber-Physical System，题干拼作 Phsical 属笔误）融合环境感知、嵌入式计算、网络通信与控制，使物理系统具备计算、通信、精确控制、协作与自治能力；新 ICT 时代 ICT 从支撑系统转为生产系统。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-182","note":"","flag":"","pnum":182,"ex_src":"编写"},{"num":183,"stem":"银行的票据影像系统，往往是结构化的数据存放在 SAN 阵列上，非结构化的数据存放在 NAS 阵列上。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。票据影像的主体是扫描件这类非结构化大文件，需要目录语义与共享访问，落在 NAS；影像对应的账号、索引与交易流水是关系型数据、以随机小块 I/O 为主，落在块存储 SAN。判据是数据形态与 I/O 模式，与题干分配方式一致。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-183","note":"","flag":"","pnum":183,"ex_src":"编写"},{"num":184,"stem":"描述 1：快照的数据恢复依赖于源数据。如果源数据遭受物理损坏，将无法恢复。而克隆在这种情况下仍然可以恢复源数据。 描述 2：在源数据损坏后，LUN 拷贝必须将备份数据完全拷贝一份来恢复源数据。而克隆只 需恢复损坏的数据，从而使恢复时间大大缩短。","type":"single","options":[["A","描述 1 是对的，描述 2 是对的"],["B","描述 1 是对的，描述 2 是错的"],["C","描述 1 是错的，描述 2 是对的"],["D","描述 1 是错的，描述 2 是错的"]],"answer":["A"],"ans_raw":"A","explain":"两个描述都对，故选 A。快照不保存全量数据，读未改动块仍指回源 LUN，源盘物理损坏后指针失效、无法恢复；克隆拥有独立可访问的数据，可反向回拷救回源 LUN（前提是其差异数据已落到独立空间）。恢复粒度上，克隆按差异块回拷，LUN 拷贝则要把全量数据重拷一遍，故克隆耗时更短。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-184","note":"","flag":"","pnum":184,"ex_src":"编写"},{"num":185,"stem":"随着大数据时代的到来，相应的存储技术也正在经历着变革，关于存储技术变革，以下说法正确的是？","type":"multi","options":[["A","文件系统由本地文件系统向集群文件系统和分布式文件系统发展"],["B","传统 NAS，面向PB 级数据，复杂的卷管理及系统容量分配不均衡，会导致资源浪费"],["C","海量存储系统的特点是文件系统更复杂，管理更复杂"],["D","具有大规模扩展能力是海量存储系统的特点"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都成立。大数据推动文件系统从本地单节点向集群/分布式文件系统演进；传统 NAS 在 PB 级下面对大量卷、容量分配不均衡会造成资源浪费；海量存储系统的特征正是文件系统更复杂、管理更复杂、必须具备大规模横向扩展能力，故选 ABCD。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-185","note":"","flag":"","pnum":185,"ex_src":"编写"},{"num":186,"stem":"SSD 盘的存储介质 cell 的可擦写次数是有限的，多次擦写造成 SSD 的磨损，也使得 SSD 的使用期限有限，这个期限与其具体被擦写的次数有关。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。NAND 靠反复编程/擦除写入，每次 P/E 都损伤隧穿氧化层，SLC/MLC/TLC 的可擦写次数依次下降，寿命以总 P/E 次数与折算写入量衡量。判据：期限由擦写量决定这一因果成立，磨损是 SSD 寿命的决定因素。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-186","note":"","flag":"","pnum":186,"ex_src":"编写"},{"num":187,"stem":"多路径软件的作用有？","type":"multi","options":[["A","故障路径切换"],["B","IO 流量的负载均衡"],["C","故障路径恢复"],["D","数据恢复"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"多路径软件把主机到同一 LUN 的多条链路聚合管理：链路故障时切换到可用路径，正常时按策略做 I/O 负载均衡，故障链路修复后可重新纳入并回切，故选 ABC。D 的数据恢复由阵列侧重构、复制或备份完成，路径恢复只是传输通道恢复，不是数据恢复。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-187","note":"","flag":"","pnum":187,"ex_src":"编写"},{"num":188,"stem":"NAS 引擎与存储单元之间采用以太网交换机互连。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。NAS 引擎与后端存储单元之间是阵列内部通道，走 SAS 级联链路（V3 控制器与硬盘框间为 SAS）；以太网用于客户端访问共享目录，不用于阵列内部引擎到盘的互连。判据在内外网络边界：客户端网络与后端磁盘通道不是一回事。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-188","note":"","flag":"","pnum":188,"ex_src":"编写"},{"num":189,"stem":"传统数据中心面临的挑战有哪些？","type":"multi","options":[["A","传统数据中心只监控不管理"],["B","传统数据中心以节点为单位扩容"],["C","传统数据中心制冷效率低"],["D","传统数据中心维护成本高"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"传统数据中心以机柜为单位扩容；云数据中心以节点为单位扩容。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-189","note":"","flag":"","pnum":189,"ex_src":"题源"},{"num":190,"stem":"FC 协议中，以下哪一层负责编码和解码？","type":"single","options":[["A","FC-0"],["B","FC-1"],["C","FC-2"],["D","FC-3"]],"answer":["B"],"ans_raw":"B","explain":"选 B。FC-1 负责 8B/10B 编码解码、传输时序与字序列，把 FC-0 的物理信号整理成可用的字符流。FC-0 只定义介质与光电信号，FC-2 定义帧、序列与交换等传输协议，FC-3 提供条带化等通用服务，均不承担编解码。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-190","note":"","flag":"","pnum":190,"ex_src":"编写"},{"num":191,"stem":"下面关于灾备的描述，不正确的是？","type":"single","options":[["A","无论使用容灾还是备份方案，灾备的数据比系统故障时的数据相比，数据丢失是无法避免的"],["B","灾难发生后，希望能马上访问远端设备上的备份"],["C","还原出来的数据希望能立即满足当前的工作需求"],["D","传统的使用软件进行数据备份仍然有使用场景"]],"answer":["A"],"ans_raw":"A","explain":"A 的说法不正确：同步远程复制可做到 RPO 为 0，主站点整体故障时从端已持有完整一致数据，「数据丢失无法避免」只对周期性备份成立；容灾的设计目标正是把丢失量压到可接受范围乃至零。B、C 是灾备的用户期望，D 也成立，小规模、低预算与长期归档场景下软件备份仍有位置。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-191","note":"","flag":"","pnum":191,"ex_src":"编写"},{"num":192,"stem":"主机层、网络层和阵列层的容灾技术的优缺点，以下说法正确的是？","type":"multi","options":[["A","对于主机层容灾，主机层复制会占用一定的主机资源，对应用系统会有影响"],["B","网络层容灾初次构建成本相对较低，可提供解决方案的厂商较多"],["C","阵列层容灾，两端阵列必须为同一厂家产品，无法解决异构问题"],["D","主机层容灾在主机端实现，无需考虑底层设备之间的兼容性"]],"answer":["A","D"],"ans_raw":"AD","explain":"主机层复制在操作系统内做镜像写，确实消耗主机 CPU/内存并影响应用，也因只在主机端实现而不必考虑底层设备兼容，故选 AD。B 把主机层的优点（构建成本低、方案厂商多）安到了网络层：网络层要部署专用交换/虚拟化网关，成本更高、可选厂商更少。C 的「需同厂商」属实，但「无法解决异构」过头，可用异构虚拟化纳管第三方 LUN，复制也支持不同型号阵列配对。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-192","note":"","flag":"","pnum":192,"ex_src":"编写"},{"num":193,"stem":"关于传统模式和云计算模式下，数据中心内高可靠性和跨数据中心容灾方式，以下说法错误的是？","type":"single","options":[["A","传统模式下，数据中心内部依靠部件冗余实现高可靠性"],["B","云计算模式下，数据中心内部依靠部件冗余实现高可靠性"],["C","传统模式下，跨数据中心容灾以复制业务数据为主，恢复过程复杂、恢复周期较长"],["D","云计算模式下，跨数据中心容灾是业务数据和运行环境的全部数据复制，整体化的管理恢复过程简单、恢复周期短"]],"answer":["B"],"ans_raw":"B","explain":"选 B。云计算模式在通用 x86 大规模集群上，靠分布式软件冗余（多副本/纠删码、故障自愈调度与虚拟机迁移）保障可靠性，而不是主要依赖单机部件冗余；传统数据中心才以内置部件冗余为主要手段。A、C、D 对两种模式的对比表述均成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-193","note":"","flag":"","pnum":193,"ex_src":"编写"},{"num":194,"stem":"关于双活、热备、暖备、冷备四种容灾模式，以下说法错误的是？","type":"single","options":[["A","双活技术可以实现主备数据中心均对外提供服务，正常工作时两个数据中心的业务可根据权重做负载分担，没有主备之分，分别响应一部分用户，权重可以是按地域划分，或数据中心服务能力或对外带宽"],["B","暖备技术，当出现数据中心故障造成该业务不可用时，在规定的 RTO 时间内，可以自动将该业务切换至备用数据中心"],["C","热备的业务由主用数据中心响应，当出现数据中心故障造成该业务不可用时，在规定的 RTO 时间内，可以自动将该业务切换至备用数据中心"],["D","多活的最大特点是不会造成数据中心的资源存在浪费，数据中心都承载应用业务运行"]],"answer":["B"],"ans_raw":"B","explain":"暖备技术是在主备数据中心的基础上实现的，前提是拥有两个一主一备的数据中心。 备用数据中心为暖备部署，应用业务由主用数据中心响应，当主用数据中心出现故障造成该业务不可用时，需要在规定的 RTO 时间以内，实现数据中心的整体切换。当实现主备数据中心切换时，需要断开主用数据中心路由链路，并连接备用数据中心路由链路，保证同一时间只有一个数据中心在线。暖备技术还是手工方式，操作时需要有人 24 小时值守才能完成， 工作效果较低。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-194","note":"","flag":"","pnum":194,"ex_src":"题源"},{"num":195,"stem":"SCSI 协议是主机和磁盘通信的基本协议。它由 SCSI 控制器进行数据操作，控制器相当于一个小CPU，有自己的命令集和缓存。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。SCSI 是主机与磁盘等设备通信的基本协议族，命令与数据由两端的 SCSI 控制器处理；控制器自带处理器、命令集与缓存，独立执行 I/O 调度，作用类似一个小 CPU，题干表述准确。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-195","note":"","flag":"","pnum":195,"ex_src":"编写"},{"num":196,"stem":"以下不同类型的 SSD 盘，单位容量价格最低的是：","type":"single","options":[["A","SLC"],["B","eMLC"],["C","cMLC"],["D","TLC"]],"answer":["D"],"ans_raw":"D","explain":"选 D。每个 cell 存的比特位越多，同样 die 面积容量越大、单位容量成本越低：SLC 1 位、MLC 2 位、TLC 3 位，TLC 单价最低，代价是 P/E 寿命与性能最差。eMLC 与 cMLC 只是企业级/消费级 MLC 的分级，成本仍高于 TLC。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-196","note":"","flag":"","pnum":196,"ex_src":"编写"},{"num":197,"stem":"双控制器存储系统普遍含有镜像通道，写入存储系统 Cache 的数据会通过镜像通道写入对端控制器。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。双控通过专用镜像通道把本端 Cache 中尚未下盘的写数据实时复制到对端 Cache，控制器宕机后接管端仍握有完整写数据，再下盘保证不丢。判据是未落盘的易失数据是否有第二份副本，这正是镜像通道存在的意义。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-197","note":"","flag":"","pnum":197,"ex_src":"编写"},{"num":198,"stem":"某公司员工 A 登录到公司系统的存储设备后，发现其具有一定的控制权限。但不能修改系统时间，也不能进行用户管理。请问，员工A 具有以下哪种角色的权限？","type":"single","options":[["A","超级管理员"],["B","管理员"],["C","普通用户"],["D","只读用户"]],"answer":["B"],"ans_raw":"B","explain":"选 B。管理员角色可创建与配置业务对象（LUN、主机组、映射等），但修改系统时间、用户与权限管理属超级管理员专属；只读用户连配置权都没有，与题干「有一定控制权限」矛盾，故既不是 A 也不是 D。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-198","note":"","flag":"","pnum":198,"ex_src":"编写"},{"num":199,"stem":"某公司主要应用于 Linux、UNIX、Mac OS 和 VMware 操作系统环境的文件系统共享。请问该公司适合使用以下哪种文件访问协议？","type":"single","options":[["A","NFS"],["B","CIFS"],["C","Telnet"],["D","HTTP"]],"answer":["A"],"ans_raw":"A","explain":"Linux、UNIX、Mac OS 以及 VMware 的客户机原生自带 NFS 客户端，直接挂载共享目录即可，故选 A。CIFS/SMB 的主场是 Windows，非 Windows 端要靠 Samba 等软件；Telnet 是远程登录协议、HTTP 是超文本传输协议，都不提供文件系统共享语义。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-199","note":"","flag":"","pnum":199,"ex_src":"编写"},{"num":200,"stem":"3DC 是指容灾方案中的哪三个数据中心？","type":"multi","options":[["A","生产中心"],["B","同城灾备中心"],["C","异地灾备中心"],["D","数据中心"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"3DC 指三数据中心方案：生产中心加同城灾备中心（低时延、同步或双活）再加异地灾备中心（异步复制、抗区域性灾难），故选 ABC。D 只是泛称，不构成方案中的角色。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-200","note":"","flag":"","pnum":200,"ex_src":"编写"},{"num":201,"stem":"以下关于 NAS 的描述，正确的是： 描述 1：NAS 总是基于文件共享。 描述 2：网络连接的距离影响 NAS 的性能。","type":"single","options":[["A","描述 1 和描述 2 都正确。"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 和描述 2 都错误"]],"answer":["A"],"ans_raw":"A","explain":"两个描述都对，故选 A。NAS 以文件语义对外提供共享目录，客户端不接触裸块，这正是它与 SAN 的边界；数据要走网络到 NAS 引擎再落盘，链路的时延与带宽随距离增加而恶化，直接决定访问性能与可承载的主机数量。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-201","note":"","flag":"","pnum":201,"ex_src":"编写"},{"num":202,"stem":"衡量一个系统可靠性常见的是时间指标有哪些？","type":"multi","options":[["A","可靠度"],["B","有效率"],["C","平均失效时间"],["D","平均无故障时间"]],"answer":["C","D"],"ans_raw":"CD","explain":"题目问时间指标，故选 CD：平均无故障时间 MTBF 与平均失效时间 MTTF 都以时长衡量。可靠度是在规定条件下正常工作的概率、有效率是可用时长占比，两者属概率或比例型指标，不在时间指标之列。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-202","note":"","flag":"","pnum":202,"ex_src":"编写"},{"num":203,"stem":"远程复制要求主从端存储来自同一厂家。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。远程复制是阵列原生特性，主从两端需为同一厂家、版本兼容的阵列，复制位点、一致性组与切换语义都由双方软件对齐；异构环境得靠存储虚拟化网关或主机层复制方案，不属于这条路径。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-203","note":"","flag":"","pnum":203,"ex_src":"编写"},{"num":204,"stem":"SAN 解决方案的应用场景有哪些？","type":"multi","options":[["A","数据共享"],["B","存储共享"],["C","数据备份"],["D","灾难恢复"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"SAN 可把 LUN 同时映射给多台主机，配合集群软件实现共享访问，也便于集中与池化存储资源，并在 SAN 上挂磁带做 LAN-Free 备份、用阵列层远程复制支撑灾难恢复，四项全选。注意 SAN 的共享必须由集群文件系统或数据库协调，裸块多主机同时写会互相破坏。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-204","note":"","flag":"","pnum":204,"ex_src":"编写"},{"num":205,"stem":"在华为 RAID 2.0+中，当某存储层的热备策略为低，则以下关于系统为该层预留的热备空间的容量描述，错误的是？","type":"single","options":[["A","该层总硬盘数为 10 时，预留相当于 1 块硬盘的容量"],["B","该层总硬盘数为 12 时，预留相当于 1 块硬盘的容量"],["C","该层总硬盘数为 20 时，预留相当于 2 块硬盘的容量"],["D","该层总硬盘数为 48 时，预留相当于 2 块硬盘的容量"]],"answer":["C"],"ans_raw":"C","explain":"选 C。热备策略为低时，预留量随硬盘域盘数分档递增：10 块、12 块各留 1 块盘容量，48 块这一档留 2 块盘容量都符合规则，而 20 块仍落在只留 1 块容量的档位，说成 2 块即错误项。具体档位边界以产品文档为准，本题只需识别 C 跨了档。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-205","note":"","flag":"","pnum":205,"ex_src":"编写"},{"num":206,"stem":"如下关于 RAID 技术的描述，哪些是正确？","type":"multi","options":[["A","并不是每一种RAID 技术都能够提升写性能"],["B","在 RAID 0 中，多块硬盘被同时访问（并行访问），加快了数据访问性能"],["C","当前的RAID 技术只用奇偶校验机制对数据进行保护"],["D","所有 RAID 级别的性能随着成员盘的数量增加而成线性提升"]],"answer":["A","B"],"ans_raw":"AB","explain":"选 AB。RAID 1/5/6 引入镜像或校验后写开销反而上升，只有纯条带化才稳定提升写吞吐，A 成立；RAID 0 把数据条带分散到多盘并行读写，性能提升，B 成立。C 错：数据保护除奇偶校验外还有镜像机制；D 错：校验盘带宽、控制器与链路都会形成瓶颈，加盘不带来线性提升，且盘数越多双盘失效风险越高。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-206","note":"","flag":"","pnum":206,"ex_src":"编写"},{"num":207,"stem":"SCSI 通信由启动器发起，由目标器接收和处理。在主机和存储设备通信时，存储设备侧承担启动器的角色。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。SCSI 会话由启动器发起命令、目标器接收并处理，角色取决于谁下命令：主机侧是启动器，存储设备侧是目标器。题干前半句正确，后半句把存储侧说成启动器，方向反了，故判错。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-207","note":"","flag":"","pnum":207,"ex_src":"编写"},{"num":208,"stem":"数据什么时候变成信息？","type":"single","options":[["A","当它已经以正确的文件格式存储"],["B","当数据已经用数字的形式存储后"],["C","当企业了解数据的含义，并从中提取出决策的需要内容"],["D","当数据被验证过是正确的"]],"answer":["C"],"ans_raw":"C","explain":"选 C。数据是原始事实的记录，只有被赋予语境与含义、能支撑判断和决策时才成为信息。文件格式正确、以数字存储、经校验为真，都只解决可读与可信，不产生含义，这正是 A、B、D 的落点偏差。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-208","note":"","flag":"","pnum":208,"ex_src":"编写"},{"num":209,"stem":"当应用服务器上已安装 UltraPath 时，操作系统可以自动识别映射到主机的 LUN，而不需要重启主机。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。UltraPath 接管设备发现与路径聚合，阵列侧完成 LUN 映射后主机即可识别到新增设备并生成路径组，无需重启。判据在是否依赖重启重新枚举 SCSI 设备；严格说仍可能要触发一次设备重扫描，但重扫描本身不算重启，结论不变。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-209","note":"","flag":"","pnum":209,"ex_src":"编写"},{"num":210,"stem":"以下关于 FC 协议和 SCSI 协议的关系描述错误的是？","type":"single","options":[["A","FC 可以通过构建帧来传输 SCSI 指令、数据和状态信息单元"],["B","FC 或者iSCSI 协议是用来承载 SCSI 协议的，是对 SCSI 协议的一种扩展"],["C","SCSI 是 FC4 的上层协议，SCSI 是 FC 协议的子集"],["D","FC 是 SCSI 的替代"]],"answer":["D"],"ans_raw":"D","explain":"选 D。FC 是承载层，通过 FCP 把 SCSI 的命令、数据与状态封装成帧传输，SCSI 仍是上层 I/O 语义，二者是承载与被承载关系，谈不上替代。A、B、C 都表达了同一层叠关系：FC/iSCSI 扩展 SCSI 的可达距离与组网规模，SCSI 属 FC-4 层协议。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-210","note":"","flag":"","pnum":210,"ex_src":"编写"},{"num":211,"stem":"某政府单位采用华为两地三中心解决方案进行灾备建设，业务主要集中在 8:00 到 18:00， 以下做法错误的是？","type":"single","options":[["A","生产中心和异地的灾备中心应采用同步远程复制"],["B","生产中心和灾备中心进行数据同步的时间段应该选在夜间业务量小的时候"],["C","在做远程复制时，应该根据单位的业务来创建一致性组，有关联的业务放在一个一致组内"],["D","可以用BCManager 软件对数据的同步周期进行设置"]],"answer":["A"],"ans_raw":"A","explain":"选 A。异地链路距离远、时延高且带宽有限，同步复制必须等从端确认才向主机返回，会直接抬高业务时延甚至中断，应使用异步远程复制；同步只用于同城低时延链路。B、C、D 符合做法：业务集中在白天则把同步窗口压到夜间，关联业务用一致性组保证时间序，BCManager 负责复制排程与切换编排。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-211","note":"","flag":"","pnum":211,"ex_src":"编写"},{"num":212,"stem":"按照 NAS 引擎和存储设备的物理位置，NAS 分为：","type":"multi","options":[["A","内部NAS"],["B","外部 NAS"],["C","统一 NAS"],["D","网关 NAS"]],"answer":["C","D"],"ans_raw":"CD","explain":"NAS 主要有三种类型的实现：统一式、网关式和横向扩展式（Scale-out）。统一 NAS使用统一的存储平台将基于 NAS 和基于 SAN 的数据访问合并，提供了可以同时管理二种环境的统一管理界面。网关 NAS 使用外部存储来存取数据，网关 NAS 和存储的管理操作是分开的。横向扩展式（Scale-out）NAS 可组合多个节点，形成一个集群 NAS 系统。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-212","note":"","flag":"","pnum":212,"ex_src":"题源"},{"num":213,"stem":"在 RAID 2.0+中，管理员需要手动设置，指定哪些硬盘作为热备盘。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。RAID2.0+ 取消了独立热备盘，改为按热备策略在整个硬盘域的 CK 中自动预留热备空间，故障时由多块盘的 CK 并行承接重构，管理员只调策略、不指定具体哪块盘做热备，故「需要手动指定」不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-213","note":"","flag":"","pnum":213,"ex_src":"编写"},{"num":214,"stem":"DAS 和 SAN 之间的差异，以下哪项描述是错误的？","type":"single","options":[["A","SAN 冗余组网的方式提供了更高的可靠性"],["B","DAS 和 SAN 都是外部存储，因此可以轻松实现存储资源共享"],["C","DAS 适用于只有少数几台服务器的中小型局域网环境"],["D","SAN 适用于中高端存储应用环境，例如关键数据库，集中存储，大规模存储，备份和灾难恢复等场景"]],"answer":["B"],"ans_raw":"B","explain":"选 B。DAS 虽也可用外置盘柜，但它直连单台服务器、容量与数据难以跨主机共享，「都是外部存储因此都能轻松共享」把 DAS 与 SAN 的关键差异说反了。A、C、D 均成立：SAN 冗余组网可靠性更高，DAS 适合少量服务器的小环境，SAN 面向关键数据库与备份容灾等场景。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-214","note":"","flag":"","pnum":214,"ex_src":"编写"},{"num":215,"stem":"异步远程复制多时间点技术的步骤，以下说法正确的是？ （1）、每个复制周期启动时在主 LUN 和从 LUN 的缓存中产生新的时间片（T2，P2） （2）、主机新写入的数据缓存在主 LUN Cache 的时间片T2 中，响应主机完成 （3）、主从 LUN 各自将收到的数据下盘 （4）、将时间片 T1 的数据直接复制到从 LUN，写入从 LUN 的时间片P2 中","type":"single","options":[["A","（1）（2）（3）（4）"],["B","（1）（3）（2）（4）"],["C","（1）（2）（4）（3）"],["D","（2）（1）（4）（3）"]],"answer":["C"],"ans_raw":"C","explain":"选 C。多时间点技术的逻辑是：复制周期启动先在主从 Cache 切出新时间片 T2、P2，主机新写只落到当前 T2 并立即收到完成响应，随后把上一个时间片 T1 的数据复制到从端写入 P2，主从各自把已收到的数据下盘。顺序不能颠倒，因为「先给主机回响应、后台再搬上一片」正是该特性降低写时延的原因；实际传输与下盘是流水并行的，教材只表达逻辑先后。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-215","note":"","flag":"","pnum":215,"ex_src":"编写"},{"num":216,"stem":"描述 1：LUN 由存储池中的多个 Extent 组成。描述 2：LUN 可以包含一种或多种类型的 Extent。","type":"single","options":[["A","描述 1 正确，描述 2 正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 错误，描述 2 错误"]],"answer":["A"],"ans_raw":"A","explain":"两个描述都对，故选 A。RAID2.0+ 中 LUN 从存储池按 Extent（Extent Group）粒度分配空间，由大量 Extent 拼装而成；一个 LUN 可全部由同层 Extent 构成，也可在分层特性作用下跨 SSD/SAS/SATA 多层分布，从而同时包含不同类型 Extent。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-216","note":"","flag":"","pnum":216,"ex_src":"编写"},{"num":217,"stem":"关于华为 OceanStor 存储系统保险箱盘的描述，以下哪项是正确的？","type":"multi","options":[["A","当设备掉电后，保险箱盘存储缓存中的数据，以防止数据丢失"],["B","当意外发生电源故障时，BBU 为缓存和保险箱盘供电"],["C","保险箱盘不能用于存储用户数据"],["D","控制器机柜中只有前两块盘用于保险箱盘"]],"answer":["A","B"],"ans_raw":"AB","explain":"存储系统中存在两种保险箱盘：内置的保险箱盘和外置的保险箱盘。保险箱盘用于保存存储系统的数据、系统配置信息和日志、系统掉电后 Cache 中的数据。盘控一体控制框中前 4 块硬盘或者盘控分离存储系统中第一个硬盘框的前 4 块硬盘规划为保险箱盘。保险箱盘必须使用 SAS、NL-SAS 或者 SSD 硬盘，并且四块保险箱盘的硬盘类型必须一致。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-217","note":"","flag":"","pnum":217,"ex_src":"题源"},{"num":218,"stem":"在华为 OceanStor 存储设备中，保险箱盘是一个可选配置，因为写缓存有镜像，并且有备用电源给控制器供电。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"每个控制器内置 1 块或多块硬盘作为数据保险箱。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-218","note":"","flag":"","pnum":218,"ex_src":"题源"},{"num":219,"stem":"文件系统的 QoS 支持 IO 优先级配置，也支持策略配置。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。文件系统级 QoS 有两类可配项：一是 I/O 优先级，让关键业务的请求在调度时优先得到处理；二是控制策略，按对象设定 IOPS 与带宽上限并绑定生效条件。两类能力同时具备，故题干成立。判据在 QoS 既能排队分级、也能限额管控，不是单一手段。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-219","note":"","flag":"","pnum":219,"ex_src":"编写"},{"num":220,"stem":"容灾应用时，HyperMirror 功能（数据远程复制）只能在两台OceanStor 5300 V3 间进行，不能再 OceanStor 5500 V3 与OceanStor 5300 V3 间进行。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。HyperMirror 是卷级镜像特性，镜像两端只受控制器归属与版本兼容约束，并不锁死在两台同型号 5300 V3 上，5500 V3 与 5300 V3 之间同样可以建立镜像；它还可用于本阵列内以及经异构虚拟化纳管的第三方 LUN。判据是型号锁定这一限制并不存在。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-220","note":"","flag":"","pnum":220,"ex_src":"编写"},{"num":221,"stem":"在 RHEL 5 操作系统中，哪条命令用于将 dev 目录下的sdb5 设备挂载到 mnt 目录下的 sdb5 目录？","type":"single","options":[["A","cat /dev/sdb5 /mmt/sdb5"],["B","ln /dev/sdb5 /mnt/sdb5"],["C","mount /dev/sdb5 /mnt/sdb5"],["D","df /dev/sdb5 mnt/sdb5"]],"answer":["C"],"ans_raw":"C","explain":"选 C。挂载是把已格式化的文件系统接到某个空目录上，Linux 语法为 mount 设备文件 挂载点，即 mount /dev/sdb5 /mnt/sdb5，前提是目标目录已存在。cat 只输出文件内容、ln 建立链接、df 查看容量，三者都不执行挂载；A 中的 /mmt 是笔误，但不影响判断。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-221","note":"","flag":"","pnum":221,"ex_src":"编写"},{"num":222,"stem":"分布式对象存储有统一命名空间，并且支持在线扩容。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。分布式对象存储用扁平命名空间加元数据集群提供全局唯一的桶与对象访问路径，新增节点后自动再平衡数据分布，扩容过程对上层业务透明，两个特征都成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-222","note":"","flag":"","pnum":222,"ex_src":"编写"},{"num":223,"stem":"FCoE 协议是指将 FC 协议封装到 TCP/IP 协议包中，在以太网上传输。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"FCoE 面向的是 10G 以太网。增强型以太网能够支持多种传输类型，包括 FCoE 和TCP/IP","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-223","note":"","flag":"","pnum":223,"ex_src":"题源"},{"num":224,"stem":"一个业务连续性高的系统找那个，RPO 和 RTO 值应该具备的特点是：","type":"single","options":[["A","RPO 较高，RTO 较低"],["B","RPO 较低，RTO 较高"],["C","RPO 和RTO 都较低"],["D","RPO 和 RTO 都较高"]],"answer":["C"],"ans_raw":"C","explain":"选 C。RPO 衡量允许丢失多少时间的数据，RTO 衡量允许业务停多久，两者都越小业务连续性越高；一高一低的组合意味着要么丢数据要么停业务，不能同时称为高连续性，故 A、B 不成立，D 最差。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-224","note":"","flag":"","pnum":224,"ex_src":"编写"},{"num":225,"stem":"华为在 ICT 领域聚焦于 IT 基础设施。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）华为公开口径是在 ICT 领域聚焦「ICT 基础设施」，同时包含 CT 通信设备与 IT 侧的云计算、存储、网络。题干只写「聚焦于 IT 基础设施」，范围偏窄：若按教材原文判断，此说法应选「错」。题给 A 请连同教材原文复核。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-225","note":"","flag":"","pnum":225,"ex_src":"编写"},{"num":226,"stem":"在华为 RAID 2.0+中，关于 chunck 和extent 的描述，正确的是？","type":"single","options":[["A","chunck 是 LUN 从存储池中申请空间、释放空间的最小单位"],["B","extent 是存储池从硬盘域上分配资源的最小单位"],["C","chunck 是热点数据统计和迁移的最小单位（数据迁移粒度）"],["D","不同存储池的 extent 大小可以不同，但同一存储池中的 extent 大小是统一的"]],"answer":["D"],"ans_raw":"D","explain":"extent 是在 CKG 基础上划分的固定大小的逻辑存储空间，大小可调，是热点数据统计和迁移的最小单元（数据迁移粒度），也是存储池中申请空间、释放空间的最小单位。不同存储池的 extent 大小可以不同，但同一存储池中的 extent 大小是统一的。 CKG 是由来自于同一个 DG 内不同硬盘的 CK 按照 RAID 算法组成的逻辑存储单元，是存储 池从硬盘域上分配资源的最小单位。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-226","note":"","flag":"","pnum":226,"ex_src":"题源"},{"num":227,"stem":"关于华为 OceanStor V3 存储动态分级存储技术，以下哪项描述是不正确的？","type":"single","options":[["A","SmartTier 计算和分析数据的活跃度，以确定数据的活动级别"],["B","SmartTier 根据数据的不同活动级别，自动和动态的将数据移动到不同性能的存储介质上"],["C","SmartTier 数据移动基于配置的数据迁移策略"],["D","SmartTier 特性的数据统计，分析和数据迁移将影响业务连续性和数据可用性"]],"answer":["D"],"ans_raw":"D","explain":"选 D。SmartTier 的 I/O 统计采样、活跃度分析与数据迁移都在后台以低优先级运行，并可设迁移速率与生效时间窗，设计目标恰是不影响业务连续性与数据可用性，D 与特性定位相反。A、B、C 是标准描述：分析活跃度、按活跃度把数据在层间动态搬迁、迁移遵循配置的策略。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-227","note":"","flag":"","pnum":227,"ex_src":"编写"},{"num":228,"stem":"描述 1：某公司存储系统提供的 CIFS 共享为公共目录，具有权限的用户都可以访问。描述 2：某公司存储系统通过设置 Homedir 共享使不同的用户只能访问与其用户名相同的私有目录。","type":"single","options":[["A","描述 1 正确，描述 2 错误"],["B","描述 1 错误，描述 2 错误"],["C","描述 1 正确，描述 2 正确"],["D","描述 1 错误，描述 2 正确"]],"answer":["C"],"ans_raw":"C","explain":"选 C（两描述均正确）。公共共享导出同一目录，靠权限与 ACL 决定哪些用户可访问；Homedir 共享按客户端登录用户名映射到同名私有目录，每个用户只见自己的目录，两者都是 V3 文件服务的共享类型。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-228","note":"","flag":"","pnum":228,"ex_src":"编写"},{"num":229,"stem":"备份是将数据或系统进行复制保存，一旦发生错误或灾难，这些备份可以用来还原系统数据，使业务恢复到正常的运行状态。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。备份的定义就是把数据或系统复制保存到独立介质并按保留策略归档，故障或灾难发生时通过回拷把数据还原、使业务回到正常运行状态，题干表述与定义一致；其局限在 RTO 长、不接管业务，但并不影响定义本身成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-229","note":"","flag":"","pnum":229,"ex_src":"编写"},{"num":230,"stem":"存储系统要实现 SmartTier 需要经历哪三个阶段？","type":"multi","options":[["A","初始容量分配"],["B","数据排布分析"],["C","数据迁移"],["D","I/O 监控"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"选 BCD。SmartTier 的工作过程是 I/O 监控采集访问信息、数据排布与活跃度分析判定热冷、再按策略执行数据迁移三段。A 的初始容量分配是创建 Thin LUN 时的独立策略选项（自动分配或偏向某层），不属于分级本身的三个阶段。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-230","note":"","flag":"","pnum":230,"ex_src":"编写"},{"num":231,"stem":"增量备份在数据恢复时必须依赖上一次完全备份和上一次的增量备份才能对数据进行完整恢复，恢复时数据重构较完全备份慢，恢复窗口更大。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。增量备份只存自上次备份以来的变化，恢复必须从上一次完全备份开始把其后的增量逐级重放，链条越长依赖越多、重构比直接恢复完全备份慢，所需覆盖的备份集范围（恢复窗口）更大。严格说依赖的是整条增量链，而不只是最近一次增量，但整体结论成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-231","note":"","flag":"","pnum":231,"ex_src":"编写"},{"num":232,"stem":"关于 ICT 常用组件，以下说法正确的是？","type":"multi","options":[["A","ICT 常用组件有主机、存储阵列、交换机、网络"],["B","主机也称服务器，指一些企业中规格较高的计算机"],["C","存储阵列通常是指提供数据存储的设备"],["D","交换机又称交换式集线器，主要工作在三层网络"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"选 ABC。主机即服务器、指企业中规格较高的计算机，存储阵列提供数据存储，ICT 常用组件含主机、存储阵列、交换机与网络，均成立。D 错：交换机又称交换式集线器，普通以太网交换机主要工作在二层数据链路层，三层交换才承担网络层路由。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-232","note":"","flag":"","pnum":232,"ex_src":"编写"},{"num":233,"stem":"某企业需要为数据备份购买备份介质，要继承企业原有磁带备份架构和策略，又要提高备份速度。此企业时候购买哪种备份介质？","type":"single","options":[["A","磁盘阵列"],["B","虚拟带库"],["C","磁带库"],["D","光盘塔"]],"answer":["B"],"ans_raw":"B","explain":"选 B。虚拟带库用磁盘阵列模拟磁带库与磁带机，备份软件沿用原有磁带介质、策略与作业接口，架构不动；同时享受磁盘随机写与多流并发，备份窗口和恢复时间都显著缩短。换纯磁盘阵列要改备份架构，磁带库速度不变，光盘塔在容量与速度上更差。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-233","note":"","flag":"","pnum":233,"ex_src":"编写"},{"num":234,"stem":"以下关于 DAS 的描述，错误的是：","type":"single","options":[["A","DAS 是直接连接到使用它们的服务器上的指定的存储设备"],["B","DAS 又分为内部DAS 和外部DAS"],["C","服务器内部的硬盘并不是DAS"],["D","外部DAS 可通过 FC 协议或者 SCSI 协议连接到访问它们的服务器上"]],"answer":["C"],"ans_raw":"C","explain":"选 C。DAS 分内部与外部两类，服务器机箱内直挂在 RAID 卡或主板控制器上的硬盘正是内部 DAS，C 把内置硬盘排除在 DAS 之外，说法错误。A、B、D 对 DAS 的定义、分类与外部直连协议（SCSI/SAS/FC）描述均成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-234","note":"","flag":"","pnum":234,"ex_src":"编写"},{"num":235,"stem":"容灾系统衡量指标中的 RTO 是指灾难发生后，系统和数据必须恢复到的时间点目标要求。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。「灾难后系统和数据必须恢复到的时间点目标」是 RPO，即允许丢失的数据区间；RTO 是灾难发生到业务恢复可用所允许的时长，衡量停机而不是数据丢失。判据看指标落在时间轴上的含义：RPO 指向过去的数据点，RTO 指向未来的恢复耗时。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-235","note":"","flag":"","pnum":235,"ex_src":"编写"},{"num":236,"stem":"以下两种描述，正确的是： 描述 1：传统 PC 的维护成本通常低于桌面云。描述 2：在云计算中，数据被集中存储和管理。","type":"single","options":[["A","描述 1 和 2 均正确"],["B","描述 1 正确，描述 2 错误"],["C","描述 1 错误，描述 2 正确"],["D","描述 1 和 2 均错误"]],"answer":["C"],"ans_raw":"C","explain":"描述 1 错、描述 2 对，故选 C。传统 PC 每台都要装系统、打补丁、现场排障，运维成本随终端数量线性上升；桌面云把桌面与数据集中在数据中心，统一镜像发放、终端瘦化，整体维护成本更低。云计算下数据集中存储与统一管理，描述 2 成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-236","note":"","flag":"","pnum":236,"ex_src":"编写"},{"num":237,"stem":"NFS 协议有哪些版本？","type":"multi","options":[["A","NFS V1"],["B","NFS V2"],["C","NFS V3"],["D","NFS V4"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"NFS 是网络文件系统。随着网络的不断发展，这个协议版本也逐渐增多。现在已经有了 4.1 的最新版本了。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-237","note":"","flag":"","pnum":237,"ex_src":"题源"},{"num":238,"stem":"对于存储在介质上的数据来说，不存在像记录在纸件上的数据那样需要物理粉碎或销毁的情况。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。介质上的数据删除往往只改索引或映射，剩余磁记录、旧扇区、重映射坏块与 SSD 磨损均衡留下的副本都可能被恢复，报废盘必须消磁、物理粉碎或用安全擦除特性处理。判据：电子介质同样存在物理销毁需求，「不存在」不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-238","note":"","flag":"","pnum":238,"ex_src":"编写"},{"num":239,"stem":"下列关于文件访问协议，描述正确的是？","type":"multi","options":[["A","CIFS 协议用在 Linux 和 UNIX 环境中"],["B","NFS 协议用在 Windows 环境中"],["C","CIFS 协议、NFS 协议以及 FTP 协议的工作方式都是 C/S 架构"],["D","HTTP 协议的工作方式是 B/S 架构"]],"answer":["C","D"],"ans_raw":"CD","explain":"选 CD。CIFS/SMB 与 NFS、FTP 都是客户端向服务器请求服务的 C/S 模型，HTTP 是浏览器/服务器方式。A、B 把两种协议的生态说反了：CIFS 主要用在 Windows，NFS 主要用在 Linux/UNIX，跨平台一端需装相应软件才可用。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-239","note":"","flag":"","pnum":239,"ex_src":"编写"},{"num":240,"stem":"在华为 OceanStor V3 上创建一个 Thin LUN，容量为 100G，初始分配容量为 10G，则将此 LUN 映射给 Windows 2012 主机后，在该主机上扫描到的相应的磁盘，该磁盘显示的容量应该为 10G。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。精简 LUN 对主机呈现的是其逻辑容量，Windows 磁盘管理扫描到的是 100G；初始分配量只决定阵列侧此刻实际占用的物理空间。判据在两个容量层次：主机看到逻辑卷大小，物理占用靠阵列超分与容量告警控制，若显示 10G 则应用根本写不进剩余空间。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-240","note":"","flag":"","pnum":240,"ex_src":"编写"},{"num":241,"stem":"FTP 是一个十分安全的协议，不存在安全风险。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。FTP 的控制通道与数据通道都是明文，账号口令可被嗅探，且主动/被动模式要开放动态端口、难以穿透防火墙，也没有完整性校验。需要安全传输时应改用 SFTP 或 FTPS，故「不存在安全风险」不成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-241","note":"","flag":"","pnum":241,"ex_src":"编写"},{"num":242,"stem":"在 RTO 要求是 10 分钟内时，不建议采用传统的磁带备份方式。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。磁带是顺序介质，恢复要先装载、定位再串流回拷，端到端耗时通常远超 10 分钟，还可能涉及取回离线介质。RTO 要求这么短时，应选磁盘副本、快照或复制等可直接挂载接管的介质，故「不建议磁带」成立。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-242","note":"","flag":"","pnum":242,"ex_src":"编写"},{"num":243,"stem":"当对 RPO 时间需求为分钟级别时，可以采用传统的磁带备份方式。","type":"judge","options":[["A","对"],["B","错"]],"answer":["B"],"ans_raw":"B","explain":"错。RPO 分钟级要求数据持续或高频同步，而磁带备份受作业周期与备份窗口限制，两次备份之间的写入全部丢失，达不到分钟级。判据看保护频率：磁带面向小时/天级 RPO 与归档，分钟级要靠同步或异步远程复制。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-243","note":"","flag":"","pnum":243,"ex_src":"编写"},{"num":244,"stem":"如下对 RAID 10 描述，哪些是正确的？","type":"multi","options":[["A","RAID 10 应用于对速度和容错有较高要求的场景"],["B","RAID 10 要求至少 4 块成员盘"],["C","在RAID 10 中，如果一个子组中的两块成员盘失效，数据读正常"],["D","在RAID 10 中数据先镜像然后再被条带化"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"选 ABD。RAID 10 先做镜像再条带化（RAID 01 才是先条带后镜像），最少要 4 块盘组成两个镜像组，兼具条带速度与镜像容错。C 错在容错粒度：镜像子组内两块盘同时失效即该组数据丢失，整个 RAID 不可用，每子组只能容忍 1 块盘。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-244","note":"","flag":"","pnum":244,"ex_src":"编写"},{"num":245,"stem":"FC 交换机中的哪些端口可以相互通信由 zone 决定。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。Zone 是交换机侧的访问控制集合，只有同属一个生效 zone 的成员端口之间才能建立 N_Port 会话，其余端口彼此隔离；zone set 决定哪些 zone 被激活。判据是通信许可由 zone 成员关系给出，与物理端口位置无关。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-245","note":"","flag":"","pnum":245,"ex_src":"编写"},{"num":246,"stem":"一个设备只有一个 WWNN 号，但可以有多个 WWPN 号。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。WWNN 标识节点本身，一台设备全局唯一一个；WWPN 标识节点上的每个端口，一个 HBA 有两个口或设备有多个控制器端口就有多个 WWPN。判据是两级编号的粒度：节点级唯一、端口级可多个。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-246","note":"","flag":"","pnum":246,"ex_src":"编写"},{"num":247,"stem":"下列属于集群 NAS 存储架构的特点的是：","type":"multi","options":[["A","统一命名空间，全局共享"],["B","高性能，多台阵列并发 I/O"],["C","在线扩容"],["D","可以提供块级存储"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"集群 NAS 由多台 NAS 引擎协同对外提供文件服务，具备统一命名空间与全局共享、多节点并发 I/O 带来的高性能以及加节点即可在线扩容，故选 ABC。D 错：集群 NAS 对外是文件级（NFS/CIFS）访问，块级存储属 SAN 或 iSCSI。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-247","note":"","flag":"","pnum":247,"ex_src":"编写"},{"num":248,"stem":"重删压缩只能对 Thin LUN 开启。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"只有 thin LUN 才能开启重复数据删除功能。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-248","note":"","flag":"","pnum":248,"ex_src":"题源"},{"num":249,"stem":"下面哪种 RAID 级别硬盘空间利用率最低？","type":"single","options":[["A","RAID 0"],["B","RAID 1"],["C","RAID 3"],["D","RAID 5"]],"answer":["B"],"ans_raw":"B","explain":"选 B。利用率按可用容量除以裸容量算：RAID 1 两块盘各存一份完整副本，固定 50%；RAID 0 无冗余为 100%；RAID 3/5 只占一块校验盘，为 (n-1)/n，盘数越多越接近 100%，即便 3 块盘也有约 67%，都高于 RAID 1。补充：RAID 10 同为 50%，本选项未列。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-249","note":"","flag":"","pnum":249,"ex_src":"编写"},{"num":250,"stem":"以下哪个操作系统，无需另外安装软件，即可访问 CIFS 共享？","type":"single","options":[["A","Win7"],["B","Solaris"],["C","FreeBSD"],["D","AIX"]],"answer":["A"],"ans_raw":"A","explain":"选 A。判据是谁原生实现了 SMB/CIFS 客户端：CIFS 本就是 Windows 平台的文件共享协议，Win7 直接映射网络驱动器即可访问；Solaris、FreeBSD、AIX 等类 UNIX 系统原生只有 NFS 客户端，访问 CIFS 要装 Samba 客户端或第三方软件。Telnet、HTTP 与此无关。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-250","note":"","flag":"","pnum":250,"ex_src":"编写"},{"num":251,"stem":"以下两种描述中，正确的是： 描述 1：同步远程复制，在主端存储故障时，数据的丢失量可以为 0. 描述 2：当主机是基于 Linux 的文件系统时，必须使用异步远程复制。","type":"single","options":[["A","描述 1 和描述 2 都是对的"],["B","描述 1 对，描述 2 错"],["C","描述 1 错，描述 2 对"],["D","描述 1 和描述 2 都是错的"]],"answer":["B"],"ans_raw":"B","explain":"描述 1 对、描述 2 错，故选 B。同步复制在从端写入确认后才向主机返回完成，主端整体故障时从端已有一致完整数据，RPO 可为 0；复制方式由距离、链路时延、带宽与可容忍的业务影响决定，与主机上是何种文件系统无关，Linux 主机同样可用同步复制。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-251","note":"","flag":"","pnum":251,"ex_src":"编写"},{"num":252,"stem":"以下哪项不属于 IP SAN 组件？","type":"single","options":[["A","带有iSCSI 接口的存储设备"],["B","双绞线"],["C","NIC"],["D","FC 交换机"]],"answer":["D"],"ans_raw":"D","explain":"选 D。IP SAN 由带 iSCSI 接口的存储、网卡或 iSCSI HBA、以太网交换机和双绞线/光模块组成，FC 交换机是 FC SAN 的设备，不属于 IP SAN。易误选 B：双绞线正是 IP 组网的传输介质，而本题干缺的其实是以太网交换机这一项。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-252","note":"","flag":"","pnum":252,"ex_src":"编写"},{"num":253,"stem":"DAS 是不具备扩展性的存储架构。","type":"judge","options":[["A","对"],["B","错"]],"answer":["A"],"ans_raw":"A","explain":"对。教材把扩展性差列为 DAS 的核心短板：容量与端口绑定在单台服务器上，扩展只能逐台加盘加柜，跨机无法共享空闲容量，也不具备 SAN 那样的在线弹性扩展与统一资源池。严格说仍可级联外置盘柜做有限扩展，本题取其定性口径。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-253","note":"","flag":"","pnum":253,"ex_src":"编写"},{"num":254,"stem":"全盘重构的流程顺序正确的是？ 1、查询有CK 落在故障盘上的所有CKG 2、为所有这些CKG 分配热备CK 3、更新CKG 信息，释放被重构过的 CK 4、将重构出来的数据写到热备 CK 上 5、通过RAID 算法，根据正常盘和校验盘上的数据计算出故障盘上的数据","type":"single","options":[["A","1->2->5->4->3"],["B","1->2->3->5->4"],["C","5->1->2->3->4"],["D","5->2->1->4->3"]],"answer":["A"],"ans_raw":"A","explain":"选 A。全盘重构先查询有哪些 CK 落在故障盘上、定位受影响的 CKG，再为这些 CKG 分配热备 CK，然后按 RAID 算法用同条带的正常 CK 与校验 CK 计算出故障数据、写入热备 CK，最后更新 CKG 信息并释放被重构的源 CK。先定位、再分配、后计算写入、末尾改元数据的因果顺序不能颠倒，故 B、C、D 均错。","source":"HCNA-Storage-(H13-611)题库-v4.0.doc","subject":"hcna_storage","id":"hcna_storage-254","note":"","flag":"","pnum":254,"ex_src":"编写"},{"num":1,"stem":"主机存储虚拟化层+文件系统方式，需要在主机侧挂载存储设备后，对挂载的 LUN 创建文件系统。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"主机侧做存储虚拟化并以文件系统方式管理空间时，确实由 CNA 主机先登录并挂载 LUN，再在该 LUN 上创建文件系统，虚拟机磁盘以文件形式落在其中，故说法正确。判据是谁做虚拟化、以块还是文件形式管理：若由存储层做块虚拟化并把 LUN 直接映射给虚拟机，主机侧就不需要建文件系统。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-1","note":"","flag":"","pnum":1,"ex_src":"编写"},{"num":2,"stem":"FusionCompute 同一台主机上，智能网卡和普通网卡不能混合使用。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"智能网卡与普通网卡的驱动和卸载能力不同，同一主机尤其是同一绑定、同一网络平面内混用，会使路径选择与故障切换行为不一致，官方按不允许混用处理，故正确。判据是同一逻辑网口内的转发与卸载路径能否保持同质，而不是网口数量够不够。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-2","note":"","flag":"","pnum":2,"ex_src":"编写"},{"num":3,"stem":"在华为 FusionSphere 解决方案中，如果想要虚拟机在主机宕机后自动进行 HA，切换到另外的主机，下面哪个条件不是必须的？","type":"single","options":[["A","主机属于同一个集群"],["B","主机所属的集群开启 HA"],["C","主机连接相同的共享数据存储"],["D","主机上需要 HA 的虚拟机均使用同一网段 IP"]],"answer":["D"],"ans_raw":"D","explain":"HA 的动作是宕机主机上的虚拟机在其他主机上重新拉起，前提是同集群、集群开启 HA、虚拟机磁盘位于共享存储让目标主机读得到同一份数据。虚拟机的 IP 是否同网段并不影响能否重启，只要目标主机把对应端口组、VLAN 接通即可，故不是必须条件的是 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-3","note":"","flag":"","pnum":3,"ex_src":"编写"},{"num":4,"stem":"可以采用多种方式安装 FusionManager，当 FusionManager 部署在 VMware 虚拟化环境时，需要采用哪种方式安装？","type":"single","options":[["A","ISO 镜像"],["B","模板文件"],["C","PXE 自动安装"],["D","ISO 镜像和模板文件都可以"]],"answer":["A"],"ans_raw":"A","explain":"部署在自家 FusionCompute 上可用模板方式导入，而 VMware 虚拟化环境识别不了华为的模板格式，只能用 ISO 光盘镜像引导安装，故选 A。易错点：模板文件仅限自家平台；PXE 是给物理主机批量安装 CNA 用的，与部署管理层 FusionManager 无关，所以 D 的两者都可以也不成立。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-4","note":"","flag":"","pnum":4,"ex_src":"编写"},{"num":5,"stem":"FusionAccess 中一次任务即对系统的一次操作，所有的任务被 FusionAccess 任务中心记录管理，支持任务的定时操作管理。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"FusionAccess 以任务为单位管理运维操作：ITA 受理的一次操作登记为一个任务，任务中心统一记录其进度与结果，支持查询和对失败任务重试，定时或批量提交的操作同样以任务形式呈现，故说法正确。判据是该操作是否被任务中心统一记录管理，而不是由谁触发。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-5","note":"","flag":"","pnum":5,"ex_src":"编写"},{"num":6,"stem":"FusionManager 对服务器配置监控后，可以对硬件执行某些维护操作。如下哪个动作不能通过 FusionManager 对硬件执行？","type":"single","options":[["A","上下电"],["B","安全重启"],["C","安全下电"],["D","PXE 加载"]],"answer":["D"],"ans_raw":"D","explain":"FusionManager 通过主机的 BMC 带外通道做电源类维护，上电、下电、安全下电、安全重启都属于标准电源控制动作。PXE 加载是引导方式的选择，要在 BMC 启动设置或安装服务侧完成，不是平台下发给硬件的维护动作，故选 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-6","note":"","flag":"","pnum":6,"ex_src":"编写"},{"num":7,"stem":"FusionAccess 终端用户在 Web Interface 页面看到的虚拟桌面列表，事实上是存储在哪个部件里的？","type":"single","options":[["A","WI"],["B","HDC"],["C","AD"],["D","Database"]],"answer":["D"],"ans_raw":"D","explain":"用户与桌面虚拟机的对应关系、桌面状态这些持久化数据都存在 FusionAccess 数据库里，WI 只是登录页面，查询后把结果渲染成列表，本身不保存数据；HDC 负责连接与调度，AD 只做身份认证与账号，所以列表的真正数据源是 Database，选 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-7","note":"","flag":"","pnum":7,"ex_src":"编写"},{"num":8,"stem":"在安装 FusionCompute 的过程中需要设置主机管理网口 IP 地址和 VRM 管理 IP 地址，下面对这两者的描述正确的是？","type":"single","options":[["A","使用主机管理网口 IP 进行多个站点级联"],["B","使用 VRM 管理 IP 地址向集群添加多个主机"],["C","使用 VRM 管理 IP 地址访问 FusionCompute 的 Web Portal 页面"],["D","主机管理网口 IP 地址就是 VRM 管理 IP 地址"]],"answer":["C"],"ans_raw":"C","explain":"选 C。VRM 是 FusionCompute 的管理节点，负责集群乃至多个站点资源的统一管理，其管理 IP 就是访问 Web Portal 的入口。主机管理网口 IP 是 CNA 主机被 VRM 纳管时使用的地址，两者不是同一个地址，D 错；向集群添加主机时填报的是主机管理网口 IP，B 错；多站点级联也不靠主机网口 IP 实现，A 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-8","note":"题源原解析（排版截断）：“管理多个站点资源。”","flag":"","pnum":8,"ex_src":"编写"},{"num":9,"stem":"华为云计算解决方案中 TC 设备支持多种操作系统，CT3100 支持的操作系统是哪个？","type":"single","options":[["A","Linux"],["B","WES7"],["C","Windows"],["D","FreeBSD"]],"answer":["A"],"ans_raw":"A","explain":"CT3100 属瘦客户机形态，运行厂商定制的 Linux 系统；Windows、WES7 这类桌面级系统用在 x86 架构的终端系列上，FreeBSD 并不作为华为瘦终端的客户端系统。判断依据是终端的硬件架构决定可用系统，而不是认为瘦终端都跑 Windows。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-9","note":"","flag":"","pnum":9,"ex_src":"编写"},{"num":10,"stem":"FusionManager 可以统一管理异构虚拟化产品， 如 VMware vCenter 和华为 FusionCompute等。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"FusionManager 定位是云管理层，通过各自的适配器纳管 FusionCompute 与 VMware vCenter 等异构虚拟化，在其上统一提供资源申请、发放与运维视图，故正确。可统一管理的前提是读取并调用对方接口，并不替换底层虚拟化平台。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-10","note":"","flag":"","pnum":10,"ex_src":"编写"},{"num":11,"stem":"下面对 VRM 的描述中，哪个是错误的？","type":"single","options":[["A","一个 VRM 的管理范围就是一个站点的管理范围"],["B","多个 VRM 级联后可以提供统一的 Portal 管理多个站点资源"],["C","推荐将 VRM 节点虚拟机绑定到所在主机"],["D","主备 VRM 节点可以部署到管理集群的同一台主机上 1"]],"answer":["D"],"ans_raw":"D","explain":"D 是错误描述：主备 VRM 放在管理集群同一台主机上，该主机故障会同时打掉主备两个节点，失去冗余，正确做法是分布在不同主机。A、B 是 VRM 站点边界与级联提供统一门户的基本定位；C 的绑定主机用于让主备节点固定在指定主机上，避免随意漂移带来的依赖混乱。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-11","note":"","flag":"","pnum":11,"ex_src":"编写"},{"num":12,"stem":"可以使用物理主机光驱为虚拟机安装操作系统。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"可以把物理主机上的光驱或 ISO 映射给虚拟机当作 CD-ROM 使用，因此用主机光驱给虚拟机装系统是允许的，故正确。判据是虚拟机看到的仍是虚拟光驱设备，只是介质来自主机硬件或文件；这与制作模板、用 PXE 批量安装只是效率和规模上的取舍不同，并非唯一途径。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-12","note":"","flag":"","pnum":12,"ex_src":"编写"},{"num":13,"stem":"华为公司为了解决早期虚拟桌面体验差、兼容性差、管理难等问题，自主研发了以下哪种协议？","type":"single","options":[["A","RDP"],["B","ICA"],["C","HDX"],["D","HDP"]],"answer":["D"],"ans_raw":"D","explain":"HDP 是华为自研的桌面传输协议，针对办公与多媒体场景做了重定向和带宽优化。RDP 属于微软，ICA 与 HDX 属于 Citrix，其中 ICA 是协议、HDX 是其上的体验增强包，三者都不是华为自主研发，故选 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-13","note":"","flag":"","pnum":13,"ex_src":"编写"},{"num":14,"stem":"某企业准备部署华为桌面云解决方案，终端用户 800 人左右，请推荐一种适合该企业的部署形态。","type":"single","options":[["A","标准桌面云，组网形态为 E9000+IP SAN 10GE"],["B","桌面云一体机，组网形态为 RH2288H+FusionStorage 10GE"],["C","桌面云一体机，组网形态为 E9000+FusionStorage 10GE"],["D","FusionSphere 虚拟化，组网形态为 RH2288H+IP SAN 10GE"]],"answer":["B"],"ans_raw":"B","explain":"800 用户属中小规模，桌面云一体机用机架服务器配合 FusionStorage 做超融合，计算与存储合一，省掉外置存储和独立存储网络，性价比与扩容弹性更好，选 B。易错点：E9000 刀片箱适合更大规模集中部署，对该规模偏重；D 只有虚拟化加 IP SAN，不是完整桌面云方案，管理和成本都不占优。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-14","note":"","flag":"","pnum":14,"ex_src":"编写"},{"num":15,"stem":"FusionAccess 分支机构部署场景中，如果分支机构与总部网络中断，分支机构的用户将无法接入桌面云系统。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"分支方案在分支侧部署本地接入组件并由本地资源承载桌面，用户就近接入，与总部的链路只用于统一管理和运维，中断后已发放的桌面仍可接入使用，故说法错误。判据是桌面运行与接入能否在分支本地闭环；只有需要总部下发的新发放或变更才会暂时受阻。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-15","note":"","flag":"","pnum":15,"ex_src":"编写"},{"num":16,"stem":"配置 FusionCompute 时，修改主机存储多路径属于下面哪个功能配置？","type":"single","options":[["A","主机和集群管理"],["B","存储管理"],["C","网络管理"],["D","系统管理"]],"answer":["A"],"ans_raw":"A","explain":"多路径描述的是主机这个启动器到存储 LUN 之间可用路径的数量与负载分担、故障切换策略，配置对象挂在主机侧的存储适配器上，属主机与集群管理范畴，选 A。存储管理页面针对数据存储、资源存储的创建挂载与容量，路径策略本身不在那里定义。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-16","note":"","flag":"","pnum":16,"ex_src":"编写"},{"num":17,"stem":"在使用 ISO 镜像文件安装 FusionCompute 的 CNA 组件过程中， 哪个参数不能采用默认值，必须手动配置？","type":"single","options":[["A","Hard Drive"],["B","Network"],["C","Hostname"],["D","Password"]],"answer":["D"],"ans_raw":"D","explain":"CNA 安装向导对硬盘分区、网络、主机名都给了默认值可以直接确认，唯独登录密码必须手工输入且不允许沿用默认，属安全强制项，故选 D。Hostname 可先按默认再统一规划，Network 也可先默认、纳管后再改业务与存储平面，都不构成必改项。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-17","note":"","flag":"","pnum":17,"ex_src":"编写"},{"num":18,"stem":"部署 VRM 时，一般推荐在 VRM 部署在哪种存储上？","type":"single","options":[["A","本地磁盘"],["B","FC SAN"],["C","IP SAN"],["D","NAS"]],"answer":["A"],"ans_raw":"A","explain":"VRM 是管理平面的大脑，其虚拟机磁盘推荐放在所在主机的本地磁盘上，使管理组件不依赖共享存储：共享存储或链路故障时 VRM 仍能启动并继续管理，避免出现管存储的组件自己读不到存储的循环依赖，选 A。FC SAN、IP SAN、NAS 都属外置共享存储，正是要避开的依赖对象。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-18","note":"","flag":"","pnum":18,"ex_src":"编写"},{"num":19,"stem":"集群开启 DRS 后，FusionCompute 会基于多种因素进行衡量从而实现资源调度，下面哪种不属于衡量的因素？","type":"single","options":[["A","CPU"],["B","磁盘"],["C","内存"],["D","CPU 和内存"]],"answer":["B"],"ans_raw":"B","explain":"DRS 依据主机的 CPU 与内存等资源使用率判断负载是否失衡，再触发虚拟机迁移来均衡，磁盘容量或 I/O 不作为其衡量因素，故选 B。易错点是 CPU 与内存这两项都正确，而 D 把两者合在一起更像是正确项，题目要的是不属于的那一个，磁盘看似相关实则属存储侧考虑。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-19","note":"","flag":"","pnum":19,"ex_src":"编写"},{"num":20,"stem":"FusionManager 支持多种接口，下面哪种接口不是用来被第三方运营平台集成管理的？","type":"single","options":[["A","REST 接口"],["B","SOAP 接口"],["C","SNMP 接口"],["D","HTTPS 接口"]],"answer":["D"],"ans_raw":"D","explain":"REST、SOAP 是供第三方运营或云管平台调用的北向业务接口，SNMP 用于向第三方网管上报性能与告警，三者都属于可被集成的接口。HTTPS 只是承载 Web 门户与北向接口访问的传输层安全方式，不构成一种独立的集成接口类型，故选 D。别把用 https 访问误当成对外接口协议。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-20","note":"","flag":"","pnum":20,"ex_src":"编写"},{"num":21,"stem":"下面关于 FusionAccess 各个部件功能的描述中，哪个是错误的？","type":"single","options":[["A","Web Interface 提供最终用户接入界面入口"],["B","HDA 部署在 Windows 和 Linux 用户虚拟机中，负责实现 HDP 接入以及向 HDC 上报状态 和连接信息"],["C","TC 是用于接入桌面的终端"],["D","WI 通过 WIA 控制虚拟机的启动、重启"]],"answer":["B"],"ans_raw":"B","explain":"正确分工是 WI 提供最终用户接入入口，HDC 负责桌面连接与状态调度，ITA 与底层 FusionCompute 交互完成电源类操作，TC 是接入终端，因此 A、C、D 成立。B 把 HDP 接入的建立与桌面状态的调度算到 HDA 头上；HDA 只是装在用户虚拟机内的代理，上报本机桌面服务与连接状态，不承担接入调度。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-21","note":"","flag":"","pnum":21,"ex_src":"编写"},{"num":22,"stem":"E9000 服务器支持多种不同计算节点刀片，当企业运行的应用只要求一般的计算性能，但需要大数据存储时，选择下面哪种计算节点是最合适的？","type":"single","options":[["A","CH121"],["B","CH222"],["C","CH240"],["D","CH242"]],"answer":["B"],"ans_raw":"B","explain":"和容量均要求较高的数据库应用，CH242 适合对性能和容量均要求较高的数据库应用。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-22","note":"","flag":"","pnum":22,"ex_src":"题源"},{"num":23,"stem":"FusionManager 定位于解决哪个层次的资源统一管理问题？","type":"single","options":[["A","主机级"],["B","集群级"],["C","站点级"],["D","数据中心级"]],"answer":["D"],"ans_raw":"D","explain":"选 D。FusionManager 定位是数据中心级的统一管理，把物理资源与虚拟资源两类纳入同一视图做集中发放和运维。主机级与集群级的虚拟化和资源调度由 FusionCompute（CNA 加 VRM）承担，A、B 层次过低；站点级管理同样在 FusionCompute 范围内，C 也不符。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-23","note":"题源原解析（排版截断）：“2 源和虚拟资源。”","flag":"","pnum":23,"ex_src":"编写"},{"num":24,"stem":"为了保证数据安全，某企业桌面云管理员想禁止桌面用户使用 USB 存储设备，采用下面哪种措施最合适？","type":"single","options":[["A","物理禁用 TC 设备 USB 端口"],["B","设置桌面云策略，禁止使用 USB 存储设备"],["C","制定公司制度，禁止使用 USB 存储设备"],["D","管理员定期监督"]],"answer":["B"],"ans_raw":"B","explain":"桌面云外设策略可精确到是否允许 USB 存储重定向，集中下发、按用户或桌面组生效，且不影响打印机等其他外设，故选 B。物理封堵 TC 端口成本高又无法按人区分；公司制度和定期监督没有技术强制力，遇到实际接入需求就失效，起不到防泄密作用。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-24","note":"","flag":"","pnum":24,"ex_src":"编写"},{"num":25,"stem":"华为云计算解决方案整体名称是什么？","type":"single","options":[["A","FusionCloud"],["B","FusionSphere"],["C","FusionCube"],["D","FusionAccess"]],"answer":["A"],"ans_raw":"A","explain":"产品，FusionCube 整合一体机， FusionSphere 云操作系统，以及 FusionInsight 大数据平台 几大产品。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-25","note":"","flag":"","pnum":25,"ex_src":"题源"},{"num":26,"stem":"FusionCompute 中 DPM 的主要价值是什么？","type":"single","options":[["A","提高运算性能"],["B","节能环保"],["C","提高机器使用率"],["D","消除性能瓶颈"]],"answer":["B"],"ans_raw":"B","explain":"节能减排即动态电源管理(DPM)可以优化数据中心的能耗。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-26","note":"","flag":"","pnum":26,"ex_src":"题源"},{"num":27,"stem":"部署 FusionCompute 时，如果一台主机有 4 个以上以太网口，一般建议将 etho 和 eth1 同时设置为管理平面网口，并在安装完 FusionCompute 后进行绑定，一般会采用下面哪种方式 进行管理平面网口绑定？","type":"single","options":[["A","基于源和目的 MAC 的负荷分组"],["B","主备"],["C","基于轮询的负荷分组"],["D","基于源目的端口负载分组"]],"answer":["B"],"ans_raw":"B","explain":"和 eth1 同时设置为管理平面网口，在安装完 FusionCompute 后绑定为主备网口。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-27","note":"","flag":"","pnum":27,"ex_src":"题源"},{"num":28,"stem":"云数据中心中，云系统会根据服务器的压力进行自动调节，把一部分业务从压力大的服务器转移到压力小的服务器，保持压力的平均分布。在这种调节过程中，体现了云计算的哪 种技术？","type":"single","options":[["A","内存复用"],["B","链接克隆"],["C","资源动态调整"],["D","负载均衡"]],"answer":["D"],"ans_raw":"D","explain":"题干的关键词是把压力从繁忙节点分流到空闲节点、保持压力平均分布，这体现的是负载均衡思想，在 FusionCompute 里由 DRS 通过动态资源调度实现，选 D。内存复用与链接克隆提高的是单机资源利用率，不改变节点之间的压力分布；资源动态调整是手段，题干问的是体现的技术。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-28","note":"","flag":"","pnum":28,"ex_src":"编写"},{"num":29,"stem":"FusionAccess 有标准发放和快速发放两种桌面发放方式，这两种方式的差异体现在哪个步骤？","type":"single","options":[["A","创建业务资源"],["B","制作模板"],["C","创建虚拟机用户"],["D","创建网络资源"]],"answer":["A"],"ans_raw":"A","explain":"两种发放方式在创建业务资源这一步分岔：标准发放为每台桌面分配独立完整磁盘，快速发放基于母盘只派生差异盘，因此耗时与空间占用差异集中在这一环节，选 A。易错点：制作模板两种方式都要做，只是快速发放更依赖母盘一致性；网络资源、加域与创建用户的流程并没有区别。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-29","note":"","flag":"","pnum":29,"ex_src":"编写"},{"num":30,"stem":"某公司使用云计算技术构建虚拟化数据中心后，IT 技术支撑人员大大减少，这体现了云计算的哪项价值？","type":"single","options":[["A","数据安全"],["B","提高资源利用率"],["C","节省维护成本"],["D","统一管理"]],"answer":["C"],"ans_raw":"C","explain":"IT 支撑人员大幅减少，说明日常运维投入的人力下降，属节省维护成本，选 C。提高资源利用率对应同样硬件承载更多业务，统一管理对应一个门户管多处资源，数据安全对应数据集中不落地，都与用人变少不是同一维度，容易被题干的管理字样带偏。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-30","note":"","flag":"","pnum":30,"ex_src":"编写"},{"num":31,"stem":"当需要使用 FusionManager 提供虚拟防火墙、负载均衡和 DHCP 功能时，需要部署哪种虚拟机？","type":"single","options":[["A","VRM"],["B","FusionManager"],["C","VSAM"],["D","PVM"]],"answer":["C"],"ans_raw":"C","explain":"功能的系统服务虚拟机进行自动化配置和管理。 当需要使用 FusionManager 提供这些功能时， 需要部署 VSAM。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-31","note":"","flag":"","pnum":31,"ex_src":"题源"},{"num":32,"stem":"谈到系统的可伸缩性，Scale Up 和 Scale Out 是两种典型的扩展模式。Scale Up 使用横向扩展模式，规模扩大时计算、存储和网络等各种资源均衡扩展，更利于部署大规模的云计算3 环境。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"的需求。但是这种方式只增加了容量，而带宽和计算能力并没有相应的增加。所以，整个系 统很快就会达到性能瓶颈，需要继续扩展。Scale out 横向扩展架构的升级通常是以节点为单 位，每个节点往往将包含容量、处理能力和 I/O 带宽。一个节点被添加到系统，系统中的三 种资源将同时升级。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-32","note":"","flag":"","pnum":32,"ex_src":"题源"},{"num":33,"stem":"FusionCompute 中有 4 台虚拟机通过链接克隆共享同一母镜像，当母镜像升级后，这四台虚拟机无法感知升级变化，依然使用升级前的镜像。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"链接克隆虚拟机只保存自己写入的差异数据，基础内容实时读取母盘，母盘升级后派生虚拟机重启即用上新内容，说无法感知是错的，故选 B。判据是差异盘与母盘是引用关系而非某一时刻的完整拷贝；只有完整复制出来的独立磁盘才与母盘再无关系。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-33","note":"","flag":"","pnum":33,"ex_src":"编写"},{"num":34,"stem":"下列哪个组件不属于 FusionInsight 架构的 Hadoop 层？","type":"single","options":[["A","HDFS"],["B","HBase"],["C","Miner"],["D","Hive"]],"answer":["C"],"ans_raw":"C","explain":"Hadoop 层是开源的分布式存储与计算框架：HDFS 负责存，HBase 提供分布式数据库，Hive 提供 SQL 层与元数据。Miner 即数据挖掘，属华为在开源之上叠加的上层分析应用与服务，不在 Hadoop 层，故选 C。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-34","note":"","flag":"","pnum":34,"ex_src":"编写"},{"num":35,"stem":"桌面云中虚拟机快速发放过程是指虚拟机的分配（绑定）过程，不包括虚拟机的创建过程。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"虚拟桌面的快速发放过程包含虚拟机的创建、虚拟机的分配（绑定）。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-35","note":"","flag":"","pnum":35,"ex_src":"题源"},{"num":36,"stem":"FusionAccess 的配置管理功能包含 FusionAccess 管理系统的配置，例如与 FusionCompute对接、时间同步、域信息、审计规则、ITA 组件数据库端口配置等。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"配置管理改的是 FusionAccess 系统自身的对接与运行参数，包括与 FusionCompute 的对接、时间同步、域信息、审计规则以及组件数据库端口等，故正确。判据是所改内容属于平台自身如何对接运行，还是某台桌面的使用行为，后者归策略管理。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-36","note":"","flag":"","pnum":36,"ex_src":"编写"},{"num":37,"stem":"虚拟机运行在主机之上，可以读取其所在主机物理光驱里的光盘数据。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"主机可把物理光驱设备映射给指定虚拟机，虚拟机通过自己的虚拟 CD-ROM 读取光盘中的数据，故正确。判据是介质来源可以是主机硬件或 ISO 文件，呈现给虚拟机的始终是虚拟光驱，因此不需要给每台虚拟机单独配物理光驱。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-37","note":"","flag":"","pnum":37,"ex_src":"编写"},{"num":38,"stem":"E9000 服务器的交换模块中，哪个可以同时支持 10GE 和 FC 网络？","type":"single","options":[["A","CX310"],["B","CX311"],["C","CX611"],["D","CX710"]],"answer":["B"],"ans_raw":"B","explain":"CX310 支持 10GE，CX311 支持 10GE 和 FC，CX611 支持 IB/FD。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-38","note":"","flag":"","pnum":38,"ex_src":"题源"},{"num":39,"stem":"FusionAccess 部件 Huawei Desktop Controller 实现的主要功能是?","type":"single","options":[["A","用于桌面接入网关代理，隔离内外网"],["B","用于 WEB 接入负载均衡"],["C","桌面接入的协议网关，内外网隔离、传输加密"],["D","记录用户与桌面的关联关系并实时同步虚拟桌面的使用状态和连接状态"]],"answer":["D"],"ans_raw":"D","explain":"选 D。HDC 即 Huawei Desktop Controller，核心职责是记录用户与虚拟桌面的关联关系，并实时同步桌面的使用状态与连接状态，同时负责桌面发放与生命周期调度。A、C 描述的接入网关代理、内外网隔离与传输加密属 vAG 的功能，B 的 Web 接入负载均衡由 vLB 承担，都不是 HDC 的职责。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-39","note":"题源原解析（排版截断）：“会实时同步虚拟桌面的使用状态和连接状态。”","flag":"","pnum":39,"ex_src":"编写"},{"num":40,"stem":"当用户虚拟机 OS 为 Windows Server 2008 R2 时， 对虚拟机的哪种资源不可以在线调整？","type":"single","options":[["A","vRAM"],["B","vCPU"],["C","vMainboard"],["D","vNIC"]],"answer":["C"],"ans_raw":"C","explain":"vCPU 与 vRAM 支持热插拔在线调整，前提是客户机系统支持并安装 Tools，Windows Server 2008 R2 满足；虚拟网卡也可在线增删。主板是虚拟机的硬件描述基础，改动它必须在关机状态下进行，故选 C。别把内存可以热添加误推成主板规格也能在线改。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-40","note":"","flag":"","pnum":40,"ex_src":"编写"},{"num":41,"stem":"FusionInsight 不支持单点登录。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"FusionInsight 的管理界面可与外部认证体系对接，一次登录后即可访问相关的管理与分析入口，具备单点登录能力，因此不支持的说法错误，选 B。判据是有没有与统一账号认证打通的入口，而不是每个界面是否都要单独输一遍口令。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-41","note":"","flag":"","pnum":41,"ex_src":"编写"},{"num":42,"stem":"FusionSphere 解决方案包含多个组成部件，从定位来看，FusionCompute 的逻辑位置在哪儿？","type":"single","options":[["A","FusionManager 之上"],["B","FusionManager 与物理设备之间"],["C","FusionAccess 之上"],["D","FusionCompute 包含 FusionManager 和 FusionAccess 两个组件"]],"answer":["B"],"ans_raw":"B","explain":"和虚拟云桌面 FusionAccess 组成。在底层硬件上部署 FusionCompute。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-42","note":"","flag":"","pnum":42,"ex_src":"题源"},{"num":43,"stem":"如下关于 FusionCompute 中 FT 技术和 HA 机制的描述，哪个是正确的?","type":"single","options":[["A","从业务中断时间长短看，FT 长于 HA"],["B","HA 指的是冗余配置主备双机，当主虚拟机发生故障时备虚拟机迅速接管主虚拟机"],["C","HA 迁移虚拟机可以保证业务无中断 4"],["D","FT 技术需要主备双虚拟机之间数据实时同步"]],"answer":["D"],"ans_raw":"D","explain":"复时间较长，但更为灵活、相对成本更低，适用于可以容忍短时中断的系统。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-43","note":"","flag":"","pnum":43,"ex_src":"题源"},{"num":44,"stem":"FusionAccess 由多个部件组成，下面哪个不是必选的部件？","type":"single","options":[["A","TSM"],["B","HDC"],["C","ITA"],["D","WI"]],"answer":["A"],"ans_raw":"A","explain":"选 A。ITA 负责桌面管理与发放流程，HDC 负责桌面控制与状态维护，WI 提供 Web 接入入口，三者都是 FusionAccess 组网中不可缺省的核心部件。TSM 只是配套的备份组件，需要单独购买部署，桌面云没有它照样能发放和使用桌面，本身不是必须的部件。答题时把备份、防病毒一类增强组件都归为可裁剪项。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-44","note":"题源原解析（排版截断）：“买，其本身不是桌面云必须的部件”","flag":"","pnum":44,"ex_src":"编写"},{"num":45,"stem":"VPC 的网络安全隔离功能不依赖于如下哪种技术实现？","type":"single","options":[["A","硬件防火墙"],["B","软件防火墙"],["C","交换机"],["D","弹性 IP"]],"answer":["D"],"ans_raw":"D","explain":"vFirewall(物理防火墙实现或华为软件防火墙实现)为租户提供 VPC 能力","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-45","note":"","flag":"","pnum":45,"ex_src":"题源"},{"num":46,"stem":"华为存储设备的 4U 3.5 寸高密硬盘框通过哪种接口连接控制框，实现容量扩展。","type":"single","options":[["A","GE 接口"],["B","FC 接口"],["C","SAS 接口"],["D","MINI SAS HD 接口"]],"answer":["D"],"ans_raw":"D","explain":"硬盘框通过 Mini SAS HD 线缆连接到控制框，或级联其他硬盘框，实现容量扩展。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-46","note":"","flag":"","pnum":46,"ex_src":"题源"},{"num":47,"stem":"运行在虚拟机之上的操作系统称之为客户机操作系统，即 Guest OS。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"Machine，运行在其上的 OS 为 Host OS；称多个虚拟机为 Guest Machine，运行在其上的 OS 为 GuestOS","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-47","note":"","flag":"","pnum":47,"ex_src":"题源"},{"num":48,"stem":"某个虚拟机的磁盘不支持在线增加磁盘容量，该虚拟机可能使用的是下面哪种数据存储类型？","type":"single","options":[["A","虚拟化本地磁盘"],["B","FusionStorage"],["C","虚拟化 SAN 存储"],["D","NAS 存储"]],"answer":["D"],"ans_raw":"D","explain":"块虚拟化形态的数据存储，如虚拟化本地磁盘、FusionStorage、虚拟化 SAN，扩容走卷或 LUN 增长流程，可以在线扩。NAS 数据存储由主机挂载文件系统后以文件形式存放磁盘，容量与格式受文件系统侧约束，平台不支持对其上的虚拟机磁盘在线扩容，需关机处理，故选 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-48","note":"","flag":"","pnum":48,"ex_src":"编写"},{"num":49,"stem":"FusionAccess 部件 Web Interface 实现的主要功能是？","type":"single","options":[["A","提供最终用户的接入界面入口"],["B","桌面接入登录负载均衡"],["C","桌面接入的协议网关，内外网隔离、传输加密"],["D","与 VM 中的 HDA 进行交互，收集 HDA 上报的虚拟机状态及接入状态"]],"answer":["A"],"ans_raw":"A","explain":"WI(Web Interface)，提供用户登录虚拟机页面的 WEB 服务。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-49","note":"","flag":"","pnum":49,"ex_src":"题源"},{"num":50,"stem":"华为存储设备的 4U 3.5 寸高密硬盘支持在线更换硬盘。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"企业级存储的盘位支持热插拔，4U 高密 3.5 寸盘机型可在系统不停机时拔出故障盘插入新盘，由冗余组自动重构恢复保护，故正确。判据是盘位供电与链路是否支持在线插拔、数据是否有冗余保护，而不是必须整机下电才能换盘。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-50","note":"","flag":"","pnum":50,"ex_src":"编写"},{"num":51,"stem":"如下关于 FusionAccess 资产管理的描述，哪个是错误的？","type":"single","options":[["A","通过 ITA 的管理 PORTAL 进行资产发放管理"],["B","绑定用户与虚拟桌面关系的操作成为“关联” （attach）"],["C","使用域账号标识虚拟桌面"],["D","FusionAccess 可创建虚拟桌面并分配给用户"]],"answer":["C"],"ans_raw":"C","explain":"选 C。标识关系要分清：域账号用来标识用户，虚拟桌面靠虚拟机计算机名来唯一标识，C 把两者混淆，正是错误描述。A 成立，桌面发放与资产管理通过 ITA 的管理 Portal 完成；B 正确，把用户与虚拟桌面绑定的动作称为「关联（attach）」；D 是 FusionAccess 的基本能力，创建虚拟桌面并分配给用户。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-51","note":"题源原解析（排版截断）：“域账号标识用户，计算机名称标识虚拟桌面”","flag":"","pnum":51,"ex_src":"编写"},{"num":52,"stem":"在安装 FusionCompute 的 CNA 组件过程中， 如果主机有 4 块网卡， 推荐怎样配置 Network参数？","type":"single","options":[["A","为 eth0 配置 IP 地址，并马上和 eth1 进行绑定"],["B","为每个网口配置一个 IP 地址"],["C","为 eth0 配置 IP 地址，其它不配置"],["D","使用 DHCP 自动获取主机 IP 地址 5"]],"answer":["C"],"ans_raw":"C","explain":"安装阶段只有管理网口必须有 IP，VRM 才能通过它纳管该主机，所以给 eth0 配地址、其余网口留空即可，选 C。业务与存储网口等纳管后再通过上行链路、端口组和绑定划入各自平面；安装时就绑定为时过早，给每个网口配 IP 会造成平面混淆，DHCP 则不利于管理地址固定。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-52","note":"","flag":"","pnum":52,"ex_src":"编写"},{"num":53,"stem":"配置物理网络设备时，一般采用哪种方法隔离华为云计算解决方案中不同的网络平面？","type":"single","options":[["A","端口"],["B","IP 地址"],["C","MAC"],["D","VLAN"]],"answer":["D"],"ans_raw":"D","explain":"选 D。物理交换机上隔离网络平面的通行做法是按平面划分 VLAN，每个平面独占自己的 VLAN 与网段，从而保证各平面内的互通和平面间的隔离。端口与 MAC 只是二层转发的要素，不能充当隔离边界，A、C 错；IP 地址属三层概念，同一 VLAN 内可有多个网段，无法替代 VLAN 的隔离作用，B 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-53","note":"题源原解析（排版截断）：“保证各个平面内的互通和平面间的隔离。”","flag":"","pnum":53,"ex_src":"编写"},{"num":54,"stem":"HyperDP 是华为 FusionSphere 的备份管理软件，主要针对的是哪个级别的备份？","type":"single","options":[["A","存储级别"],["B","主机级别"],["C","虚拟机级别"],["D","OS 系统级别"]],"answer":["C"],"ans_raw":"C","explain":"选 C。HyperDP 是 FusionSphere 的备份管理软件，作为独立模块对接虚拟化平台，实现虚拟机级别的备份管理能力，可按 VM 粒度制定策略并做恢复。存储级备份由阵列或分布式存储提供，主机级与操作系统级备份要在每台主机或 OS 内部署代理，都不是 HyperDP 的定位，A、B、D 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-54","note":"题源原解析（排版截断）：“模块，实现虚拟机级别的备份管理能力。”","flag":"","pnum":54,"ex_src":"编写"},{"num":55,"stem":"如下哪个不是 FusionManager 提供的功能？","type":"single","options":[["A","异构虚拟化管理"],["B","异构硬件设备监控"],["C","多数据中心统一管理"],["D","虚拟化服务器"]],"answer":["D"],"ans_raw":"D","explain":"虚拟化，从云到非云资源，提供统一的 Portal 管理。FusionManager 提供多数据中心管理能 力：多个数据中心资源集中规划，统一分配，扩大资源共享范围，提高资源利用率，跨地域 多个数据中心资源统一监控和维护，进一步简化数据中心管理。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-55","note":"","flag":"","pnum":55,"ex_src":"题源"},{"num":56,"stem":"FusionInsight Hive 支持加密，且加密算法可自定义。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"Hive/HBase 支持 AES/SM4/RC4 等加密算法，同时允许使用用户自定义加密算法。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-56","note":"","flag":"","pnum":56,"ex_src":"题源"},{"num":57,"stem":"“裸设备+逻辑卷” ，方式是最直接的存储虚拟化方式，管理简单并支持存储高级功能。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"为单元的存储块，通过管理这些单元，实现卷的维护操作。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-57","note":"","flag":"","pnum":57,"ex_src":"题源"},{"num":58,"stem":"在批量安装 CNA 节点时，推荐将主机的 BIOS 设置为从哪个选项启动？","type":"single","options":[["A","硬盘"],["B","网络"],["C","光驱"],["D","USB"]],"answer":["B"],"ans_raw":"B","explain":"通过 PXE 方式批量安装主机，或者通过挂载 ISO 安装镜像方式手动安装主机。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-58","note":"","flag":"","pnum":58,"ex_src":"题源"},{"num":59,"stem":"某企业在多个城市有数据中心， 在每一个数据中心都部署了华为 Fusioncompute 虚拟化环境，推荐采用哪种方式？","type":"single","options":[["A","在每个数据中心部署一套 local­FusionManager 管理单个数据中心资源， 然后在某个数据中 心部署一套 top­FusionManager 统一管理多数据中心的资源"],["B","在每个数据中心部署一套 top­FusionManager 管理数据中心的资源"],["C","在每个数据中心部署一套 local­FusionManager 管理数据中心的资源"],["D","在每个数据中心部署一套 All­in­one FusionManager 管理数据中心的资源"]],"answer":["A"],"ans_raw":"A","explain":"localFusionManager，所谓分布式部署架构。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-59","note":"","flag":"","pnum":59,"ex_src":"题源"},{"num":60,"stem":"某用户从云服务提供商租用虚拟机进行日常使用，外出旅游时把虚拟机归还给云服务提供商，这体现了云计算的哪个关键特征？","type":"single","options":[["A","按需自助服务"],["B","与位置无关的资源池"],["C","按使用付费"],["D","快速弹性"]],"answer":["C"],"ans_raw":"C","explain":"模式，以促进资源的优化利用。比如计量存储，带宽和计算资源的消耗，按月根据用户实际 使用收费。在一个组织内的云可以在部门之间计算费用。 6","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-60","note":"","flag":"","pnum":60,"ex_src":"题源"},{"num":61,"stem":"以下哪个算得上是华为 FusionCloud 云解决方案的基石？","type":"single","options":[["A","FusionAccess"],["B","FusionSphere"],["C","FusionInsight"],["D","FusionCube"]],"answer":["B"],"ans_raw":"B","explain":"FusionSphere 提供计算、存储、网络虚拟化能力，是桌面云、大数据与云管理共用的资源底座，因而称基石，选 B。FusionAccess 是桌面云应用，FusionInsight 是大数据平台，FusionCube 是基础设施融合形态，它们建立在虚拟化底座之上或与之并列，本身不是底座。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-61","note":"","flag":"","pnum":61,"ex_src":"编写"},{"num":62,"stem":"FusionManager 中的业务管理员可以创建虚拟机模板。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"制作与发布虚拟机模板要操作底层虚拟机与磁盘，属资源或运维管理员权限；业务管理员只能在服务目录里用已有模板申请、部署并管理自己的业务，所以该说法错误，选 B。判据是该角色能否触达并修改底层虚拟化资源。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-62","note":"","flag":"","pnum":62,"ex_src":"编写"},{"num":63,"stem":"一个桌面虚拟机可以不属于任何虚拟机或者桌面组。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。判据在归属关系：FusionAccess 的桌面必须发放到某个桌面组下（完整克隆桌面、静态池桌面、动态池桌面等类型），桌面组记录桌面类型、描述以及关联的用户或用户组，不存在游离于所有虚拟机组和桌面组之外的桌面虚拟机，题干说法因此不成立。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-63","note":"题源原解析（排版截断）：“有桌面、静态池桌面）、桌面组描述等信息。”","flag":"","pnum":63,"ex_src":"编写"},{"num":64,"stem":"如果使用华为服务器安装 FusionCompute，需要知道 BMC 系统 IP 地址和主机管理网口IP 地址，下面对这两者的描述正确的是？","type":"single","options":[["A","两者是同一个 IP 地址"],["B","BMC 系统 IP 地址用于在 FusionCompute 中添加 CNA 节点主机时使用"],["C","主机管理网口 IP 地址用于给物理主机远程安装操作系统时使用"],["D","BMC 系统 IP 地址可以添加到 FusionCompute 中，方便主机自动上下电"]],"answer":["D"],"ans_raw":"D","explain":"把 BMC 的带外管理地址录入 FusionCompute 后，平台可以在主机下电状态下远程上电与复位，实现自动上下电，D 正确。A 错在 BMC 走独立管理口，与主机管理网口 IP 不是同一地址；添加 CNA 节点用的是主机管理网口 IP，故 B 错；远程装系统靠 BMC 挂载介质或安装服务，C 把用途记反了。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-64","note":"","flag":"","pnum":64,"ex_src":"编写"},{"num":65,"stem":"MapReduce 的核心理念是将一个大的运算任务分解到集群每个节点上，充分运用集群资源，缩短运行时间。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"通过一些简单的逻辑即可完成复杂的并行计算。 其核心理念是将一个大的运算任务分解到集 群每个节点上，充分运用集群资源，缩短运行时间。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-65","note":"","flag":"","pnum":65,"ex_src":"题源"},{"num":66,"stem":"FusionInsight 是华为针对哪种场景的技术解决方案？","type":"single","options":[["A","办公云化"],["B","IT 基础设施云化"],["C","企业大数据处理平台"],["D","企业应用云化"]],"answer":["C"],"ans_raw":"C","explain":"FusionInsight 是企业级大数据平台，在开源分布式框架之上提供存储、计算与分析挖掘能力，面向海量数据处理场景，选 C。办公云化对应桌面云方案，IT 基础设施云化对应虚拟化与云管理，企业应用云化属应用平台层，都不是大数据方案的定位。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-66","note":"","flag":"","pnum":66,"ex_src":"编写"},{"num":67,"stem":"安装完 FusionManager 后，需要初始化配置 FusionManager。如果在配置过程中出错，需要先运行哪个命令停止进程，再重新配置？","type":"single","options":[["A","fmconfig"],["B","stopALL"],["C","fminit"],["D","restartALL"]],"answer":["B"],"ans_raw":"B","explain":"初始化配置出错时，需要先把已经拉起的 FusionManager 进程全部停止，再从干净状态重新配置，对应 stopALL，选 B。发起配置是另一类命令的作用，进程未停就直接重跑会沿用到半截配置；restartALL 只是重启进程，并没有解决配置错误这一前提。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-67","note":"","flag":"","pnum":67,"ex_src":"编写"},{"num":68,"stem":"华为云计算解决方案中，桌面云一体机部署形态中 FusionStorage 主要功能是？","type":"single","options":[["A","提供基础设施虚拟化功能。以计算、存储和网络虚拟化为核心，将异构的硬件资源汇聚为 资源池，并在资源池内提供各种资源调度与服务保障能力"],["B","提供云管理功能。对外提供统一基础设施发放、跨集群资源调度、应用发放与应用伸缩等 能力"],["C","提供高性能分布式存储功能。通过将服务器磁盘资源池化和数据的多节点冗余存储实现 IO 访问的高并发"],["D","提供对硬件设备的统一发现、自动配置、故障监控能力"]],"answer":["C"],"ans_raw":"C","explain":"选 C。FusionStorage 在一体机里承担分布式存储角色，把多台服务器的本地磁盘资源池化，数据分片后多节点冗余存放，提供 SERVER SAN 能力并支撑 IO 高并发。A 描述的算存网虚拟化与资源调度属虚拟化层（FusionCompute），B 的跨集群资源调度与应用发放属云管理组件，D 的硬件统一发现与故障监控属设备管理组件。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-68","note":"题源原解析（排版截断）：“SERVER SAN 能力”","flag":"","pnum":68,"ex_src":"编写"},{"num":69,"stem":"下面哪个不属于瘦终端管理系统 TCM 的主要功能?","type":"single","options":[["A","TC 版本升级"],["B","TC 防病毒管理"],["C","信息监控"],["D","日志管理"]],"answer":["B"],"ans_raw":"B","explain":"TCM 负责瘦终端的集中管理，包括终端版本与镜像升级、在线状态与硬件信息监控、日志收集查询等。防病毒针对的是用户虚拟机内的操作系统，由桌面侧安全软件承担，不是终端管理系统的功能，故选 B。判据是管理对象是瘦终端设备还是虚拟机里的系统。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-69","note":"","flag":"","pnum":69,"ex_src":"编写"},{"num":70,"stem":"当部署华为桌面云时，终端用户必须使用瘦终端接入。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"除瘦终端外，还可以用 PC、笔记本等通用终端安装软件客户端，经接入网关和 Web Interface 登录桌面，所以必须用瘦终端的说法错误，选 B。判据是接入方式按场景选择：瘦终端便于集中管控与合规，软件客户端满足临时与自带设备接入，两者可以共存。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-70","note":"","flag":"","pnum":70,"ex_src":"编写"},{"num":71,"stem":"同一个数据存储空间建议添加给不同的 FusionCompute 站点使用，提升存储空间利用率。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"同一存储空间应只归属一个 FusionCompute 站点使用。多个站点各自维护元数据并读写同一批 LUN，会造成冲突与不可预期风险，所以建议是隔离而非共用，故错误，选 B。提升利用率靠精简置备、资源调度与容量治理，而不是跨站点共用同一套存储。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-71","note":"","flag":"","pnum":71,"ex_src":"编写"},{"num":72,"stem":"FusionManager 中 VDC 有非常强大的功能，下面关于 VDC 的描述中，哪个是错误的？7","type":"single","options":[["A","VDC 是划分给租户的虚拟资源边界"],["B","VDC 上可以指定租户使用的资源配额，限制租户对计算、网络、存储使用量"],["C","VDC 提供安全的租户间网络隔离环境"],["D","VDC 是软件定义数据中心，多租户可独立使用虚拟化资源"]],"answer":["C"],"ans_raw":"C","explain":"选 C。VDC 是划分给租户的虚拟资源边界，即可用做租户隔离的软件定义数据中心，能在其上指定计算、网络、存储的资源配额，租户不能超额使用系统资源，A、B、D 均正确。跨租户的网络隔离不由 VDC 本身提供，而是靠 VLAN、虚拟路由器与安全组等网络能力实现，C 夸大了 VDC 的功能。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-72","note":"题源原解析（排版截断）：“存储的资源配额，租户不能超额使用系统资源。”","flag":"","pnum":72,"ex_src":"编写"},{"num":73,"stem":"FusionCompute 采用多种内存复用技术，其中的内存共享技术，指的是多个虚拟机可以对主机同一物理内存空间进行读和写操作。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"内存共享：虚拟机之间共享同一物理内存空间，此时虚拟机仅对内存做只读操作","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-73","note":"","flag":"","pnum":73,"ex_src":"题源"},{"num":74,"stem":"某企业是一家大型的专业视频制作公司，基于数据安全方面的考虑，现在准备部署华为桌面云解决方案。","type":"single","options":[["A","GPU 共享"],["B","GPU 硬件虚拟化"],["C","GPU 直通"],["D","GPU 映射"]],"answer":["C"],"ans_raw":"C","explain":"复杂图纸编辑，图纸总装，复杂视频编辑，中高端游戏采用 GPU 直通。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-74","note":"","flag":"","pnum":74,"ex_src":"题源"},{"num":75,"stem":"主机存储虚拟化层+文件系统方式，虚拟机模板放在哪一层存储模型上？","type":"single","options":[["A","文件系统"],["B","通用块层"],["C","设备驱动层"],["D","物理层"]],"answer":["A"],"ans_raw":"A","explain":"选 A。主机存储虚拟化层加文件系统这种方式，由主机上的存储虚拟化层把本地磁盘组织成文件系统，虚拟机模板与虚拟磁盘都以文件形式存放在该文件系统目录中，业务能力不依赖具体存储设备。通用块层、设备驱动层与物理层是更底层的抽象，模板不会直接落在这三层，B、C、D 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-75","note":"题源原解析（排版截断）：“化层提供很多 高级业务，业务能力不依赖存储设备”","flag":"","pnum":75,"ex_src":"编写"},{"num":76,"stem":"构建绿色云数据中心，不仅需要软件平台、服务器、存储和网络设备，还需要考虑整体的安全设计、底层的绿色节能设计和 E2E 的集成交付能力。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"绿色数据中心的能效由整栈决定：软件平台、服务器、存储、网络之外，还需要安全设计、供配电与制冷等底层绿色节能设计以及端到端集成交付能力，故正确。判据是能否整体降低能耗指标并保证方案协同，只优化其中一层无法达成。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-76","note":"","flag":"","pnum":76,"ex_src":"编写"},{"num":77,"stem":"某企业一个数据中心，同时部署了 FusionCompute 和 VMware vCenter。针对这种场景，建议部署下面哪个软件统一管理该数据中心的虚拟化资源？","type":"single","options":[["A","Top­Manager"],["B","All­in­One FusionManager"],["C","FusionCompute"],["D","FusionManager"]],"answer":["B"],"ans_raw":"B","explain":"单一数据中心内异构虚拟化并存，需要一个云管理平台同时纳管 FusionCompute 与 vCenter，All-in-One 形态把管理组件合一部署，规模匹配、投入更小，选 B。易错点：普通的 FusionManager 形态面向多数据中心大规模部署，能用但不经济；TopManager 偏运维监控，不承担统一资源发放；FusionCompute 管不了 vCenter。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-77","note":"","flag":"","pnum":77,"ex_src":"编写"},{"num":78,"stem":"某企业使用 8 台 RH2288H 服务器 1 台 OceanStor S5800 V3 存储部署华为桌面云， 业务网络平面采用 10GE 组网方式。如果你是该企业 IT 管理员，出于性价比考虑，推荐选用下面 哪款交换机承载该桌面云方案的管理网络平面流量？","type":"single","options":[["A","S5700­28C­EI­24S"],["B","S5700­52C­PWR­EI"],["C","S6700­24­EI"],["D","S6700­48­EI"]],"answer":["A"],"ans_raw":"A","explain":"8 台主机的管理平面口数很少，万兆带宽足够，选型只看端口数量与形态是否够用，名称中 24S 即 24 个万兆光口，满足每主机一到两个管理口加上联，价格最低，选 A。B 的 PoE 供电是给无线 AP、话机用的，管理网用不上；C、D 属更高密度或更高性能的汇聚机型，对本场景是多余投入。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-78","note":"","flag":"","pnum":78,"ex_src":"编写"},{"num":79,"stem":"以下关于 FusionCompute 级联管理架构描述正确的是？","type":"single","options":[["A","任何 VRM 节点都可以设置为级联域控制器"],["B","一个级联域中心只存在一个级联域控制器"],["C","设置为级联域控制器的站点必须手动加入级联域"],["D","级联站点的 VRM 节点虚拟机需要创建在虚拟化的 SAN 存储上"]],"answer":["B"],"ans_raw":"B","explain":"级联域中心内的级联域控制器唯一，由它汇聚各站点资源视图并对外提供统一入口，避免多个控制点造成配置与视图冲突，故 B 正确。A 错在并非任意 VRM 节点都能充当控制器；C 把设置控制器与站点加入级联混为一谈，控制器所在站点就是域中心本身；D 对 VRM 磁盘所在存储类型没有必须用 SAN 的要求。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-79","note":"","flag":"","pnum":79,"ex_src":"编写"},{"num":80,"stem":"在使用批量部署工具安装 CNA 的过程中，如果主机上同时存在硬盘和 U 盘，工具会自动将主机操作系统安装在哪里？","type":"single","options":[["A","第一块硬盘"],["B","第一块硬盘第一个分区"],["C","U 盘"],["D","随机选择安装位置"]],"answer":["C"],"ans_raw":"C","explain":"主机上同时存在硬盘和 U 盘的存储介质时，工具会自动将主机操作系统安装在 U 盘。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-80","note":"","flag":"","pnum":80,"ex_src":"题源"},{"num":81,"stem":"在华为云计算整体解决方案 FusionCloud 中，FusionAccess 的逻辑位置在哪里？","type":"single","options":[["A","在物理设备和 FusionSphere 之间"],["B","在 FusionCompute 之上 8"],["C","和 FusionStorage 平行"],["D","在 FusionManager 之上"]],"answer":["B"],"ans_raw":"B","explain":"FusionAccess 是桌面云应用层，把桌面发放逻辑建在虚拟化与云 OS 之上，通过接口调用 FusionCompute 创建和管理用户虚拟机，因此位于 FusionCompute 之上，选 B。它不在物理设备与虚拟化平台之间，与 FusionStorage 只是资源使用关系而非同层，也不在云管理层 FusionManager 之上。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-81","note":"","flag":"","pnum":81,"ex_src":"编写"},{"num":82,"stem":"华为桌面云终端用户在 Web Interface 登录页面可以自定义虚拟桌面的电源管理策略，下面哪项不是华为云桌面提供的虚拟桌面电源管理策略？","type":"single","options":[["A","禁止自动关机/重启/休眠"],["B","禁止关机"],["C","允许自动关机/重启"],["D","允许自动休眠"]],"answer":["B"],"ans_raw":"B","explain":"Web Interface 上的电源管理策略约束的是自动与定时行为，如禁止自动关机重启休眠、允许自动关机重启、允许自动休眠；关机重启这类用户主动操作不会被整体禁用，否则桌面无法正常使用，故禁止关机不在提供的策略之内，选 B。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-82","note":"","flag":"","pnum":82,"ex_src":"编写"},{"num":83,"stem":"在使用 FusionCompute 安装向导工具部署 VRM 时，实质上是利用哪种形式部署 VRM 虚拟机？","type":"single","options":[["A","ISO 文件自动应答安装"],["B","模板文件导入虚拟机"],["C","PXE 自动安装"],["D","自动创建虚拟机，自动挂载 ISO 文件安装"]],"answer":["B"],"ans_raw":"B","explain":"使用虚拟机部署的 VRM 节点便于维护，且无需独占物理服务器。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-83","note":"","flag":"","pnum":83,"ex_src":"题源"},{"num":84,"stem":"下列哪种场景不适用于 Storm?","type":"single","options":[["A","实时分析"],["B","持续计算"],["C","在线机器学习"],["D","大量数据离线分析"]],"answer":["D"],"ans_raw":"D","explain":"Storm 经常用于在实时分析、在线机器学习、持续计算、分布式远程调用和 ETL 等领\n\n域。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-84","note":"","flag":"","pnum":84,"ex_src":"题源"},{"num":85,"stem":"以下哪个选项不是在 FusionCompute 集群创建时指定的？","type":"single","options":[["A","集群 HA 策略"],["B","内存复用策略"],["C","内存资源控制策略"],["D","GuestNUMA 策略"]],"answer":["C"],"ans_raw":"C","explain":"创建集群时指定的是集群级一致性属性：HA 策略、内存复用开关、GuestNUMA 策略，另有 DRS、IMC 等。针对具体虚拟机或主机资源的内存预留、限制与份额属资源控制配置，要在资源侧单独设置，不在集群创建向导里，故选 C。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-85","note":"","flag":"","pnum":85,"ex_src":"编写"},{"num":86,"stem":"电子商务网站平台，平时业务流量比较均衡，数据处理在其公司自身构建的云环境上；当节假日来临流量增大，从云服务提供商相同资源进行处理。","type":"single","options":[["A","公有云"],["B","私有云"],["C","政务云"],["D","混合云"]],"answer":["D"],"ans_raw":"D","explain":"平时业务跑在自建的私有云上，节假日峰值借用云服务商的同类资源处理溢出流量，两种云形态并存并统一调度，正是混合云，选 D。全部用公有云会失去自建环境，全部私有云无法弹性借用外部资源，政务云只是按行业属性划分的公有云，都不符合自建加外借这一描述。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-86","note":"","flag":"","pnum":86,"ex_src":"编写"},{"num":87,"stem":"FusionManager 中应用管理不包括哪一项？","type":"single","options":[["A","应用归档"],["B","应用上线"],["C","应用部署"],["D","应用建模"]],"answer":["A"],"ans_raw":"A","explain":"FusionManager 提供应用的全生命周期管理能力：创建>发布（上线）>部署>监控>\n\n保障>开发。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-87","note":"","flag":"","pnum":87,"ex_src":"题源"},{"num":88,"stem":"分支机构桌面云可以实现虚拟桌面分支就近接入，保证了接入的网络质量，同时分支机构虚拟桌面是由分支结构本地管理发放的，与总部管理没有关系。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"分支桌面可就近接入并由本地资源承载，这半句成立；但桌面的发放与管理仍归总部统一平台完成，分支侧只是本地接入与资源，并非与总部无关的独立管理，所以整体说法错误，选 B。判据是管理平面归属是否仍在总部，而不是桌面流量路径是否就近。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-88","note":"","flag":"","pnum":88,"ex_src":"编写"},{"num":89,"stem":"FusionAccess 部件 AccessGateway 实现的主要功能是？","type":"single","options":[["A","用于用户接入时，与 WI 交互，为其提供接入信息，支持完成用户的整个接入过程"],["B","与 WM 中的 HDA 进行交互，收集 HDA 上报的虚拟机状态及接入状态"],["C","桌面接入的协议网关，内外网隔离、传输加密"],["D","记录用户与桌面的关联关系，并实时同步虚拟桌面的使用状态和连接状态"]],"answer":["C"],"ans_raw":"C","explain":"设备。用户可以很容易地利用它随时来访问工作所需的应用和数据，企业可有效地将数据中 心的资源访问扩展到企业的外网，同时，利用丰富 SmartAccess 控制策略，可以实现非常好 的访问控制。对用户进行认证、设置访问策略、安全性连接 NAT 功能。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-89","note":"","flag":"","pnum":89,"ex_src":"题源"},{"num":90,"stem":"下面哪项不属于虚拟化带来的好处？","type":"single","options":[["A","提高硬件利用率"],["B","降低能耗"],["C","提升服务器性能"],["D","操作系统与硬件解耦"]],"answer":["C"],"ans_raw":"C","explain":"虚拟化在同一硬件上运行多台虚拟机，提高硬件利用率，减少物理机数量从而降低能耗，并让操作系统与硬件解耦，便于迁移与扩容。它自身引入虚拟化层开销，单机性能通常不高于裸机，谈不上提升服务器性能，故选 C。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-90","note":"","flag":"","pnum":90,"ex_src":"编写"},{"num":91,"stem":"关于网络虚拟交换技术的描述，哪一个是错误的？","type":"single","options":[["A","基于物理交换机的虚拟交换迁移灵活，虚拟机迁移不影响虚拟机的快照技术应用 9"],["B","基于软件的虚拟交换技术不依赖硬件的高级功能，迁移更灵活"],["C","基于智能网卡的交换可以降低服务器 CPU 的消耗"],["D","可以由物理交换机来实现虚拟机间的数据交换"]],"answer":["A"],"ans_raw":"A","explain":"从而达到虚拟机直接使用物理的网卡资源实现网络通信，减少传统的虚拟交换带来的 CPU 消耗，提升性能，减少时延。但是，网卡硬件信息（ PF、 VF 等）绑定，不同物理硬件会 有所不同，因此热迁移、快照等特性无法使用。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-91","note":"","flag":"","pnum":91,"ex_src":"题源"},{"num":92,"stem":"下面关于 E9000 服务器管理模块的描述中，错误的是？","type":"single","options":[["A","一个机箱可以配置两块 MM910，以主、备方式运行"],["B","MM910 需要离线插拔、更换"],["C","MM910 管理模块遵循 IPMI v2.0 规范"],["D","MM910 提供远程开关机功能"]],"answer":["B"],"ans_raw":"B","explain":"供远程开关机、复位、日志、硬件监控、SQL、风扇监控等。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-92","note":"","flag":"","pnum":92,"ex_src":"题源"},{"num":93,"stem":"FusionAccess 有完善的业务容灾能力，当没有部署 GSLB 时，采用哪种措施可保证灾难发生后的用户桌面业务运维继续进行？","type":"single","options":[["A","虚拟机备份还原技术"],["B","存储备份还原技术"],["C","TC 主动检测，桌面切换技术"],["D","虚拟站点容灾技术"]],"answer":["C"],"ans_raw":"C","explain":"当没有部署 GSLB 情况下，由 TC 上软件进行生产和灾备中心健康监测。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-93","note":"","flag":"","pnum":93,"ex_src":"题源"},{"num":94,"stem":"FusionStorage 是华为研发的分布式存储系统，其分布式特性主要体现在哪个方面？","type":"single","options":[["A","聚合巨量磁盘，提供大容量存储"],["B","提供超大数量快照副本"],["C","整合多台通用服务器磁盘，提供 SERVER SAN"],["D","提供高效阵列自愈能力"]],"answer":["C"],"ans_raw":"C","explain":"选 C。分布式特性体现在横向整合多台通用服务器的本地磁盘，组成可线性扩展的 SERVER SAN 资源池，数据分片加多副本分布在多个节点。单纯聚合巨量磁盘只是容量结果，集中式阵列同样做得到，A 不是分布式特征；快照副本数量属功能特性而非分布式体现，阵列自愈更是传统 RAID 存储的能力，B、D 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-94","note":"题源原解析（排版截断）：“SERVER SAN 能力”","flag":"","pnum":94,"ex_src":"编写"},{"num":96,"stem":"FusionAccess 组件 HDA 支持装在 Windows 和 Linux 用户虚拟机上。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。判据在 HDA 的操作系统适配范围：HDA（华为桌面代理）必须安装在用户虚拟机内部，与桌面协议、会话管理组件配合工作，只支持 Windows 系列系统（题源举例为 Windows Server 2008R2 64 位一类），不能安装到 Linux 用户虚拟机上。题干把 Linux 也算进去，故判错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-96","note":"题源原解析（排版截断）：“server 2008R2 64 位中。”","flag":"","pnum":96,"ex_src":"编写"},{"num":97,"stem":"FusionManager 中应用模板不能包含如下哪个要素？","type":"single","options":[["A","虚拟机"],["B","网络"],["C","虚拟负载均衡器"],["D","虚拟路由器"]],"answer":["D"],"ans_raw":"D","explain":"应用模板描述的是一套可部署的应用拓扑，要素包括虚拟机及其规格镜像、网络及其子网端口，以及虚拟负载均衡器这类应用交付设备。虚拟路由器属底层网络设施，由网络侧统一规划配置，不作为应用模板中可编排的对象，故选 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-97","note":"","flag":"","pnum":97,"ex_src":"编写"},{"num":98,"stem":"FusionAccess 由多个组件构成，所有组件都可以采用虚拟机部署。一般组件都推荐部署为主备双节点，哪个组件推荐单点部署？","type":"single","options":[["A","HDC"],["B","WI"],["C","ITA"],["D","Loggeter"]],"answer":["D"],"ans_raw":"D","explain":"FusionAccess 由多个组件构成，所有组件采用虚拟机部署。除 loggeter 外，全部部署\n\n成主备模式。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-98","note":"","flag":"","pnum":98,"ex_src":"题源"},{"num":99,"stem":"“存储设备虚拟化”方式提供的存储高级功能依赖于存储设备的能力。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"提供一些存储高级业务，例如精简配置、快照和链接克隆。 10","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-99","note":"","flag":"","pnum":99,"ex_src":"题源"},{"num":100,"stem":"主备部署 VRM 后，可以通过浮动 IP 地址访问 FusionCompute。网络正常的情况下，浮动 IP 地址始终不能访问，下面哪个是最有可能的故障点？","type":"single","options":[["A","VRM 主节点出现故障"],["B","VRM 备节点出现故障"],["C","VRM 主节点或备节点其中一个出现问题"],["D","主备 VRM 节点都出现故障"]],"answer":["D"],"ans_raw":"D","explain":"地址刷新到网关，所有原主节点检测的进程在备节点启动，对外提供服务。主备管理节点采 用管理平面的心跳检测，备用节点实时检测主用节点的健康状态， 一旦发现主用管理节点故 障，备用管理节点将立刻接管主用节点的任务，保证整个系统不间断运行。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-100","note":"","flag":"","pnum":100,"ex_src":"题源"},{"num":101,"stem":"下面关于用户登录虚拟桌面的描述中，哪个是错误的？","type":"single","options":[["A","用户通过浏览器就可以查看自己所拥有的虚拟桌面"],["B","用户可以启动、登录、重启分配给自己的虚拟桌面"],["C","FusionAccess 管理所有虚拟桌面的状态"],["D","用户可以在 WI 登录页面删除分配给自己的虚拟桌面"]],"answer":["D"],"ans_raw":"D","explain":"拟桌面，实现虚拟资源的弹性管理，提高资源利用率，降低运营成本。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-101","note":"","flag":"","pnum":101,"ex_src":"题源"},{"num":102,"stem":"FusionCompute 默认会创建一个集群，该集群的名字是？","type":"single","options":[["A","DefaultCluster"],["B","FimtCluster"],["C","ManagementCluster"],["D","Administrator"]],"answer":["C"],"ans_raw":"C","explain":"部署完成后，承载 VRM 主备节点的默认集群名为 ManagementCluster，即管理集群，它与站点管理平面的高可用直接对应，选 C。DefaultCluster 是按直觉臆造的名字，FimtCluster 没有对应组件，Administrator 是用户或角色名称而非集群名，三个干扰项都靠字面相似来迷惑。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-102","note":"","flag":"","pnum":102,"ex_src":"编写"},{"num":103,"stem":"下列哪个属于 HDFS 适合的场景？","type":"single","options":[["A","存储大量小文件"],["B","实时读取"],["C","需经常修改数据"],["D","流式读取"]],"answer":["D"],"ans_raw":"D","explain":"选 D。HDFS 是分布式文件系统，扩展性良好，设计目标是大文件、高吞吐、一次写入多次读取的流式访问，适合流式读取。元数据集中在 NameNode，大量小文件会挤占元数据空间，A 不适合；它面向批处理而非低延迟随机访问，实时读取 B 不成立；文件写入后基本只追加、不支持随机改写，需经常修改数据的 C 也不对。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-103","note":"题源原解析（排版截断）：“是分布式的，具有良好的扩展性。”","flag":"","pnum":103,"ex_src":"编写"},{"num":104,"stem":"VRM 组件是 FusionCompute 的管理中枢，负责 IT 业务的编排、发放和自动部署，可以进行级联管理。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"配、调度，并提供统一的操作维护、资源监控、资源管理功能。 FusionManager 是华为云管理软件，包括服务目录，资源自动化发放以及集中监控运维，能 够实现对 IT 业务的编排和发放以及自动部署。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-104","note":"","flag":"","pnum":104,"ex_src":"题源"},{"num":105,"stem":"通过 Hive 表的索引建在 HBase 表中，能大大提升查询。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在索引存放位置带来的读取方式差异：Hive 查询以扫描为主，把 Hive 表的索引建在 HBase 表中后，可借助 HBase 按行键快速随机读的能力直接定位数据，避免全表扫描，从而提升索引查询性能。代价是索引数据需自行维护并与表保持同步。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-105","note":"题源原解析（排版截断）：“提升索引查询性能。”","flag":"","pnum":105,"ex_src":"编写"},{"num":106,"stem":"HBase 是一种分布式数据库，所以不需要依赖于 HDFS 也可以运行。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"HBase 是分布式数据库没错，但它把数据文件与预写日志放在底层分布式文件系统之上，靠多副本机制保证可靠性与扩展性，自身不做数据冗余复制，所以不依赖 HDFS 也能运行的说法错误，选 B。判据是存储层与数据组织层的分工。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-106","note":"","flag":"","pnum":106,"ex_src":"编写"},{"num":107,"stem":"部署 FusionCompute 后，某台主机上的用户虚拟机出现能够登录 VNC 的窗口，但不能正常操作、卡死的现象（无法点击打开文件等）。该主机有 3 个网口，分别连接了管理、业 务和存储 3 个不同的网络平面，最有可能的故障原因是那个？","type":"single","options":[["A","管理链路中断"],["B","业务链路中断"],["C","存储链路中断"],["D","虚拟机损坏"]],"answer":["C"],"ans_raw":"C","explain":"能打开 VNC 窗口说明管理平面与虚拟化通道正常，但点击无响应、文件打不开是磁盘 I/O 被阻塞的典型表现：虚拟机读不到存储上的数据，客户机整体卡住，故最可能是存储链路中断，选 C。管理链路断则 VNC 连不上；业务链路断只影响用户的网络访问；虚拟机损坏与三平面组网这条线索无关。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-107","note":"","flag":"","pnum":107,"ex_src":"编写"},{"num":108,"stem":"下列哪种场景最不适合 Spark？11","type":"single","options":[["A","近线或准实时"],["B","数据挖掘"],["C","大量数据离线分析"],["D","机器学习"]],"answer":["C"],"ans_raw":"C","explain":"Spark 适用于近线或准实时，数据挖掘和机器学习场景。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-108","note":"","flag":"","pnum":108,"ex_src":"题源"},{"num":109,"stem":"下面关于 FusionCompute 使用的存储描述中，哪个是错误的？","type":"single","options":[["A","当存储设备为 NAS 存储时，需要按规划配置共享目录（即数据存储）和允许访问的主机 列表"],["B","使用共享存储提供的数据存储时，应同时将该数据存储添加到同一集群的所有主机，以保 证虚拟机在集群内的迁移不受数据存储的影响"],["C","管理节点虚拟机支持使用虚拟化的数据存储，建议使用本地硬盘或 SAN 存储提供的虚拟 化的数据"],["D","存储类型为本地存储时，只有主机操作系统所在磁盘的剩余空间，以及其他未分区的裸盘 可作为数据存储使用"]],"answer":["C"],"ans_raw":"C","explain":"管理虚拟机（VRM）主备部署在不同主机上，其磁盘必须落在集群内所有主机可见的共享数据存储上；用本地硬盘则备机无法接管、管理节点失去冗余，故 C 的说法错误。A（NAS 要配共享目录和允许访问的主机列表）、B（共享存储需加入集群全部主机以保证迁移不受限）、D（本地存储只能用系统盘剩余空间和未分区裸盘）都是正确描述。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-109","note":"","flag":"","pnum":109,"ex_src":"编写"},{"num":110,"stem":"下面关于 FusionCompute 的描述中，哪个是错误的？","type":"single","options":[["A","FusionCompute 是 FusionSphere 的虚拟化部件"],["B","FusionCompute 实现对 x86 服务器、存储和网络的虚拟化，形成 IT 弹性资源池"],["C","FusionCompute 能够实现对 IT 业务的编排和发放以及自动部署"],["D","FusionCompute 是 FusionSphere 解决方案的基石"]],"answer":["C"],"ans_raw":"C","explain":"维，能够实现对 IT 业务的编排和发放以及自动部署。FusionCompute 实现对 x86 服务器、 存储和网络的虚拟化，形成 IT 弹性资源池。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-110","note":"","flag":"","pnum":110,"ex_src":"题源"},{"num":111,"stem":"FusionManager 支持不同的部署形式， 当采用 Top­Level 部署形式时， 其中负责资源接入、配置、监控及维护功能的是哪个？","type":"single","options":[["A","Top FusionManager"],["B","Local FusionManager"],["C","All­in­one FusionManager"],["D","FusionManager"]],"answer":["B"],"ans_raw":"B","explain":"TopLevel 部署分两层：本地 FusionManager 负责本数据中心内计算、存储、网络资源的接入、配置、监控与日常维护；顶层 FM 只做跨数据中心的统一门户与运营编排，故选 B。误选 A 是把跨 DC 的集中管理当成了单 DC 的资源纳管。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-111","note":"","flag":"","pnum":111,"ex_src":"编写"},{"num":112,"stem":"OceanStor 5600 v3 存储设备支持交流、直流掉电保护。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"判据看两点：控制柜是否同时提供交流、直流两种供电制式，以及掉电瞬间写缓存能否被保护并落盘。该系列控制器具备缓存掉电保护，交流、直流供电配置下均成立，故为正确。不要因为只熟悉交流供电就误判。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-112","note":"","flag":"","pnum":112,"ex_src":"编写"},{"num":113,"stem":"下列哪个选项不属于大数据 4 个 V 特点？","type":"single","options":[["A","Volume"],["B","Variety"],["C","Value"],["D","Valid"]],"answer":["D"],"ans_raw":"D","explain":"Volume：数据量大， Variety：种类多 Velocity：速度，及时有效分析 Value：价值密 度低，数据存储要廉价","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-113","note":"","flag":"","pnum":113,"ex_src":"题源"},{"num":114,"stem":"网络虚拟化主要是为了解决计算虚拟化后的虚拟机通信问题。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"对。判据在需求来源：计算虚拟化之后，同一主机上虚拟机之间以及跨主机的虚拟机之间需要互通，同时还要维持网络隔离、安全策略并随虚拟机迁移，传统物理交换难以满足，因此出现网络虚拟化，通过虚拟交换机、虚拟端口、虚拟路由器等功能实现。题干抓住了这一主要动因，说法成立。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-114","note":"题源原解析（排版截断）：“务器，虚拟路由器等功能。”","flag":"","pnum":114,"ex_src":"编写"},{"num":115,"stem":"部署华为云计算解决方案时，一般将服务器 BMC 网络平面和下面哪个网络平面合一部署？","type":"single","options":[["A","存储网络平面"],["B","业务网络平面"],["C","管理网络平面"],["D","灾备网络平面"]],"answer":["C"],"ans_raw":"C","explain":"系统。如果 VRM 节点的管理平面和 BMC 平面互通。可将管理平面和 BMC 平面合并。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-115","note":"","flag":"","pnum":115,"ex_src":"题源"},{"num":116,"stem":"在 FusionManager 中，主要有两种类型的用户，下面哪个功能属于租户的职责范围？","type":"single","options":[["A","接入虚拟化环境"],["B","创建 VDC"],["C","创建 VPC"],["D","创建虚拟机模板 12"]],"answer":["C"],"ans_raw":"C","explain":"由器、 VLB 等。在租户 VPC 中可以清晰的看到 VPC 的网络拓扑，便于维护管理。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-116","note":"","flag":"","pnum":116,"ex_src":"题源"},{"num":117,"stem":"当在 E9000 服务器上部署桌面云时，虚拟机可以直通使用 E9000 刀片的 GPU，即某个GPU 只能供给一台虚拟机使用。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"直通（Passthrough）是把整块物理 GPU 独占分配给一台虚拟机，虚拟化层不再参与该设备调度，同一块 GPU 因此无法同时供两台虚拟机使用，结论正确。若要多台共享需改用 GPU 虚拟化切分方案，那时就不再是直通，这是本题唯一的判错点。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-117","note":"","flag":"","pnum":117,"ex_src":"编写"},{"num":118,"stem":"存储虚拟化就是在寻出设备之上部署逻辑层，通过逻辑层对存储资源进行控制。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"题干中“寻出设备”应为“存储设备”。存储虚拟化的定义正是在物理存储设备之上加一层逻辑抽象层，把异构物理容量统一成逻辑池并对其分配与控制，故说法正确。判错要点：这层逻辑做的是抽象与控制，不是把数据搬到别处或只做扩容。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-118","note":"","flag":"","pnum":118,"ex_src":"编写"},{"num":119,"stem":"当需要安装 CNA 的主机数量较少时，推荐采用哪种方式安装？","type":"single","options":[["A","批量部署工具"],["B","ISO 镜像文件"],["C","安装向导工具"],["D","USB 引导安装"]],"answer":["B"],"ans_raw":"B","explain":"主机数量少时，逐台用 CNA 的 ISO 镜像（物理光驱或管理口虚拟光驱引导）安装最直接，不需额外配套工具，故选 B。批量部署工具用于几十台以上的规模化安装；USB 引导只是加载安装介质的一种手段而非推荐方式；并无独立的安装向导工具这一部署形态。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-119","note":"","flag":"","pnum":119,"ex_src":"编写"},{"num":120,"stem":"FusionManager 支持硬件设备管理和监控，对于设备告警信息，一般是通过下面哪种方式收集？","type":"single","options":[["A","IPMI"],["B","SSH"],["C","SDK"],["D","SNMP"]],"answer":["D"],"ans_raw":"D","explain":"选 D。硬件设备的告警信息一般通过 SNMP 接入，由设备主动 Trap 或平台轮询 MIB 上报，这是设备侧最通用的告警接口。IPMI 主要用于带外管理与传感器读取，不是平台批量收集告警的方式，A 错；SSH 是命令行登录通道，B 错；SDK 面向软件 API 对接而非设备告警采集，C 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-120","note":"题源原解析（排版截断）：“对于设备告警一般是通过 SNMP 接入。”","flag":"","pnum":120,"ex_src":"编写"},{"num":121,"stem":"下列哪一项不是 FusionInsight 可靠运维的关键技术？","type":"single","options":[["A","故障检测"],["B","掉电保护"],["C","数据加密"],["D","在线换盘"]],"answer":["C"],"ans_raw":"C","explain":"数据加密属于安全能力，不是可靠运维技术，故选 C。故障检测（快速发现坏盘坏节点）、掉电保护（缓存数据不丢失并落盘）、在线换盘（不停业务替换故障磁盘）三者都直接服务于集群持续可用，是课件列出的可靠运维关键技术。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-121","note":"","flag":"","pnum":121,"ex_src":"编写"},{"num":122,"stem":"在 FusionCompute 中，必须先设置集群的哪个选项，才能使虚拟机在不同 CPU 类型的主机之间进行迁移？","type":"single","options":[["A","开启集群的 DRS"],["B","开启集群 DPM"],["C","开启集群的 IMC 模式"],["D","开启集群的 HA 功能"]],"answer":["C"],"ans_raw":"C","explain":"选 C。跨不同 CPU 类型的主机迁移，要求虚拟机能使用统一的 CPU 特性集合，这必须靠开启集群的 IMC（兼容性虚拟机）模式来屏蔽指令集差异。DRS 是动态资源调度，只决定把 VM 迁到哪台负载更低的主机，不解决 CPU 兼容；DPM 是动态能源管理，做主机休眠与容量回收；HA 负责故障后在其他主机重启 VM，A、B、D 都不是前提条件。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-122","note":"题源原解析（排版截断）：“DRS：动态资源调度，DPM：动态能源管理，”","flag":"","pnum":122,"ex_src":"编写"},{"num":123,"stem":"主备部署 VRM 时，需要配置仲裁 IP 地址。当仲裁 IP 全部失效是，会造成什么影响？","type":"single","options":[["A","发生 VRM 主备切换，切换后不影响 VRM 对系统进行管理"],["B","VRM 备节点掉线，不影响主节点"],["C","两个 VRM 节点均将为备节点，导致 VRM 无法对系统进行管理"],["D","两个 VRM 节点循环进行主备切换，导致 VRM 无法对系统进行管理"]],"answer":["C"],"ans_raw":"C","explain":"备状态，导致 VRM 无法对系统进行管理。建议在仲裁 IP 地址发生变化前，及时修改 VRM 的仲裁 IP 地址。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-123","note":"","flag":"","pnum":123,"ex_src":"题源"},{"num":124,"stem":"FusionAccess 链接克隆桌面特性不包含下面哪项？","type":"single","options":[["A","将母卷和差分卷组合映射为一个链接克隆卷，提供给虚拟机使用"],["B","链接克隆桌面池提供统一的软件更新和统一的系统还原等桌面维护功能"],["C","链接克隆具有创建虚拟机速度快、磁盘存储占用空间小的优点"],["D","链接克隆桌面比普通虚拟机的计算处理能力更高"]],"answer":["D"],"ans_raw":"D","explain":"选 D。链接克隆的价值在存储与运维效率：把母卷和差分卷组合映射为一个链接克隆卷供虚拟机使用，创建速度快、磁盘占用小，桌面池还能提供统一软件更新与统一系统还原，降低维护成本、提升桌面维护效率，A、B、C 都是其特性。它只改变磁盘数据的组织方式，虚拟机的 CPU、内存等计算处理能力与普通虚拟机相同，D 不成立。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-124","note":"题源原解析（排版截断）：“维护成本和提升了桌面维护的效率。”","flag":"","pnum":124,"ex_src":"编写"},{"num":125,"stem":"从技术角度看，云计算包括云设备和云服务，与虚拟化数据中心所需组件相同。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"判据是技术构成的两层：云设备（服务器、存储、网络等硬件）与云服务（虚拟化、管理平台等软件）。这两类与虚拟化数据中心所需组件一致，差别只在交付方式（按需自助、资源池、计量计费），故说法正确。别把商业模式的不同当成组件构成不同。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-125","note":"","flag":"","pnum":125,"ex_src":"编写"},{"num":126,"stem":"互联网公司的数据一般都是结构化数据。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"互联网数据以非结构化处理为主，企业大数据中仍然是结构化数据处理为主。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-126","note":"","flag":"","pnum":126,"ex_src":"题源"},{"num":127,"stem":"某企业现有一套 VMware vCenter 环境，准备引入华为 FusionSphere 解决方案。如下13 FusionSphere 各组件的功能中，哪个最适合该企业统一管理这两套环境？","type":"single","options":[["A","FusionManager 异构虚拟化管理功能"],["B","FusionCompute 服务器虚拟化功能"],["C","FusionManager 多租户功能"],["D","FusionCompute 多站点功能"]],"answer":["A"],"ans_raw":"A","explain":"虚拟化，从云到非云资源，提供统一的 Portal 管理。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-127","note":"","flag":"","pnum":127,"ex_src":"题源"},{"num":128,"stem":"FusionManager 采用哪种方式与 FusionCompute 交互？","type":"single","options":[["A","FusionCompute Driver"],["B","FusionCompute SDK"],["C","FusionCompute API"],["D","FusionCompute SOAP"]],"answer":["A"],"ans_raw":"A","explain":"FusionManager 通过针对不同被管平台的驱动（Driver）适配层纳管 FusionCompute，由驱动完成资源发现、配置下发与状态同步，故选 A。API、SDK 是驱动内部实际调用的接口形式，不是 FM 描述的交互方式；SOAP 只是报文协议风格，与纳管机制无关。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-128","note":"","flag":"","pnum":128,"ex_src":"编写"},{"num":129,"stem":"GPU 虚拟化是指在物理 GPU 上创建多个 vGPU，每个虚拟机通过绑定 vGPU，直接访问物理 GPU 的部分物理资源，从而实现虚拟机共享 GPU 能力，可以适用于任何型号的显卡。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"错。题干前半段对 vGPU 的描述基本成立，错在「适用于任何型号的显卡」。GPU 虚拟化要求显卡本身支持虚拟化切分并有配套驱动，题源也说明只有特定型号（如 K1、K2 一类，且一台服务器通常支持一块）才能被使用，普通显卡无法切分给多台虚拟机共享，判据落在硬件与驱动的适配范围。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-129","note":"题源原解析（排版截断）：“服务器支持一块 K1 或是 K2 显卡。”","flag":"","pnum":129,"ex_src":"编写"},{"num":130,"stem":"以下哪个不是 FusionCompute 中 VRM 的组件？","type":"single","options":[["A","BRM"],["B","PMS"],["C","LOG"],["D","VNA"]],"answer":["D"],"ans_raw":"D","explain":"VNA Virtual Node Agent 虚拟节点代理。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-130","note":"","flag":"","pnum":130,"ex_src":"题源"},{"num":131,"stem":"某公司搭建云计算服务平台，提供虚拟机资源需要的用户购买，此公司属于哪种云计算部署模式？","type":"single","options":[["A","公有云"],["B","私有云"],["C","政务云"],["D","混合云"]],"answer":["A"],"ans_raw":"A","explain":"平台由该公司建设，资源面向不特定的外部客户购买使用，用户通过网络自助获取并按需付费，符合公有云定义，选 A。私有云只服务本组织内部；混合云是私有云与公有云并存并互通；政务云是按行业划分的专用云，不是题目所给的部署模式。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-131","note":"","flag":"","pnum":131,"ex_src":"编写"},{"num":132,"stem":"下列哪个不是传统数据处理系统面临的问题？","type":"single","options":[["A","高存储成本"],["B","网络带宽不足"],["C","单一数据源"],["D","大数据量下数据处理性能不足"]],"answer":["B"],"ans_raw":"B","explain":"传统数据处理系统的痛点集中在成本高、数据来源单一、大数据量下性能不足，网络带宽属于承载层能力，不是这类系统本身的问题，故选 B。易误选 A、C：高存储成本（依赖高端盘阵扩容）与单一数据源（只能吃结构化关系库数据）恰是课件明确列出的问题。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-132","note":"","flag":"","pnum":132,"ex_src":"编写"},{"num":133,"stem":"某企业是一家传统的互联网数据中心服务商，有自建的数据中心。当该企业考虑向云计算行业转型的时候，最有可能选择如下哪种云计算商业模式？","type":"single","options":[["A","Iaas"],["B","Paas"],["C","Saas"],["D","DaaS"]],"answer":["A"],"ans_raw":"A","explain":"提供给最终用户使用。 PaaS（Platform as a service）：平台即服务，指的是把二次开发的平台以服务形式提供给最终 用户使用，客户不需要管理或控制底层的云计算基础设施，但能控制部署的应用程序开发平 台。 SaaS（Software as a service）：软件即服务，提供给消费者的服务是运行在云计算基础设施上 的应用程序。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-133","note":"","flag":"","pnum":133,"ex_src":"题源"},{"num":134,"stem":"某公司构建 IT 系统，使用虚拟化平台把物理服务器抽象组合为多个虚拟服务器使用，提高资源利用率，降低企业投资成本。该公司的云计算使用属于哪种流派？","type":"single","options":[["A","大分小"],["B","小聚多"],["C","一虚多"],["D","多合一"]],"answer":["A"],"ans_raw":"A","explain":"把一台物理服务器抽象组合成多个虚拟服务器使用，属于“大分小”——将大资源分区为小资源，选 A。小聚多是反向操作：用分布式软件把多台低配机器聚合成大算力；多合一指计算、存储、网络集成到同一设备的超融合形态；一虚多不是课件中的流派名称。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-134","note":"","flag":"","pnum":134,"ex_src":"编写"},{"num":135,"stem":"如下关于 FusionManager 基本概念的描述，哪个是错误的？","type":"single","options":[["A","Region 是地区，例如亚太区"],["B","DC 是数据中心概念，例如北京、香港、东京数据中心"],["C","Zone 是数据中心内的独立二层网络区域 14"],["D","Cluster 是数据中心虚拟化网络隔离边界"]],"answer":["D"],"ans_raw":"D","explain":"Cluster：集群，是虚拟化平台的计算虚拟化边界","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-135","note":"","flag":"","pnum":135,"ex_src":"题源"},{"num":136,"stem":"FusionAccess 使用的桌面连接协议 HDP 相比 RDP 协议具有外设支持多、多媒体性能好的特点，但是其占用带宽比 RDP 协议要大。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"HDP 相比 RDP 的优势确实是外设重定向丰富、多媒体体验好，同时通过自适应压缩与编码优化把带宽占用降到低于 RDP，“占用带宽更大”不成立，故为错误。前半句描述正确，容易诱导误选，判错点在最后一句。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-136","note":"","flag":"","pnum":136,"ex_src":"编写"},{"num":137,"stem":"某公司云计算环境由自己构建，并且把资源组合成虚拟桌面提供给公司员工使用，该使用模式属于 PaaS。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"判据看交付的服务层次：把虚拟桌面作为成品交付员工使用，属于资源型交付（IaaS/桌面即服务），不是 PaaS。PaaS 交付的是开发与运行平台（中间件、数据库、运行环境），由用户自行开发部署应用。另外“自己构建”只说明部署模式是私有云，与服务层次无关。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-137","note":"","flag":"","pnum":137,"ex_src":"编写"},{"num":138,"stem":"部署 FusionCompute 时，推荐将主备 VRM 直接部署在物理主机上，提高管理节点性能。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"在底层硬件上部署 FusionCompute， 推荐采用虚拟机方式部署主备 VRM 进行虚拟资\n\n源管理。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-138","note":"","flag":"","pnum":138,"ex_src":"题源"},{"num":139,"stem":"下列哪个不属于 FusionInsight 架构？","type":"single","options":[["A","DataFarm"],["B","VRM"],["C","Hadoop"],["D","Manager"]],"answer":["B"],"ans_raw":"B","explain":"VRM 是 Fusioncompute 的架构组件。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-139","note":"","flag":"","pnum":139,"ex_src":"题源"},{"num":140,"stem":"桌面云又被称为“云里的 PC 机” ，其底层的核心技术是什么？","type":"single","options":[["A","分布式管理技术"],["B","桌面协议技术"],["C","虚拟化技术"],["D","移动终端技术"]],"answer":["C"],"ans_raw":"C","explain":"桌面云的本质是把桌面操作系统和应用以虚拟机形式集中运行在数据中心，底层核心技术是虚拟化技术，选 C。桌面协议只负责把画面与输入送到远端，属交付通道；移动终端是接入方式；分布式管理是配套运维能力，都不是底层核心。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-140","note":"","flag":"","pnum":140,"ex_src":"编写"},{"num":141,"stem":"FusionCube 使用了一种创新的架构解决 I/O 性能瓶颈问题，该架构指什么？","type":"single","options":[["A","计算、网络和存储一体化架构"],["B","线性扩容架构"],["C","软硬件一体化架构"],["D","分布式 Server SAN 架构"]],"answer":["D"],"ans_raw":"D","explain":"FusionCube 采用分布式 Server SAN：存储以软件形式分布到各节点本地盘，数据分片后多节点并行读写，I/O 不再受外置集中式阵列制约，故选 D。A 说的是超融合的组成，未回答瓶颈从何解除；B 线性扩容讲的是规模；C 软硬件一体化只是交付形态。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-141","note":"","flag":"","pnum":141,"ex_src":"编写"},{"num":142,"stem":"如下关于 VPC 的描述中，哪个是错误的？","type":"single","options":[["A","VPC 提供隔离的网络环境"],["B","在 VPC 中可以使用 VPN"],["C","在 VPC 中可以使用安全组"],["D","VPC 不提供 NAT 服务"]],"answer":["D"],"ans_raw":"D","explain":"华为云 VPC 内可以通过 NAT 网关配置 SNAT、DNAT，实现子网统一访问公网和对外端口映射，“不提供 NAT 服务”错误，选 D。A 的隔离网络环境、B 用 VPN 打通本地网络与 VPC、C 用安全组做实例级流量控制，都是 VPC 的基本能力。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-142","note":"","flag":"","pnum":142,"ex_src":"编写"},{"num":143,"stem":"在使用 FusionCompute 的安装向导部署 VRM 时， 可以配置管理 VLAN 并设置 VLAN ID。如果不勾选，那么 VRM 默认使用的管理 VLAN 是哪个？","type":"single","options":[["A","主机管理网卡所属 VLAN"],["B","VLAN 0"],["C","VLAN 1"],["D","随机选择 VLAN"]],"answer":["B"],"ans_raw":"B","explain":"勾选“配置管理 VLAN” ，并设置“ VLAN ID” 。如无需指定管理平面 VLAN，即使用 VLAN 0 作为管理平面，则无需进行配置。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-143","note":"","flag":"","pnum":143,"ex_src":"题源"},{"num":144,"stem":"FusionInsight 不支持用户权限管理。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["B"],"ans_raw":"B","explain":"FusionInsight 具备完善的用户与权限管理：在 Manager 侧创建用户和用户组并绑定角色，按组件、服务粒度授权，还可对接外部认证源，因此“不支持”的说法错误。判据是是否有集中认证与角色化授权，而不是看界面里有没有登录入口。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-144","note":"","flag":"","pnum":144,"ex_src":"编写"},{"num":145,"stem":"下面关于华为云计算解决方案主机 CPU 配置的要求的描述中，哪条是错误的？","type":"single","options":[["A","Intel 或 AMD X86 架构的 32 位、64 位 CPU"],["B","CPU 支持硬件虚拟化技术"],["C","在 BIOS 中开启虚拟化功能"],["D","同一集群内计算节点 CPU 型号不一致"]],"answer":["A"],"ans_raw":"A","explain":"（存疑）选项 D 按现文本“同一集群内计算节点 CPU 型号不一致”本身也属错误描述，疑为漏字（原应为需保持一致），如此则答案不唯一。就 A 而言：虚拟化平台只支持 64 位 x86 CPU，把 32 位列入支持范围是错的。B（支持硬件虚拟化）、C（BIOS 中开启虚拟化）是必备要求；同集群 CPU 型号一致才能保证热迁移与 HA 兼容。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-145","note":"","flag":"","pnum":145,"ex_src":"编写"},{"num":146,"stem":"云服务提供商在虚拟机上安装操作系统、中间件和应用软件，然后把此整体资源提供给用户使用，此种云计算商业模式 SaaS。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"SaaS 的判据是用户拿到即可用的整套软件，不必自行安装或开发：服务商在虚拟机上预置操作系统、中间件和应用后整体交付，正属此类，故为正确。若交付的是操作系统加中间件与运行环境、由用户自己部署应用，那是 PaaS；只给虚拟机、存储和网络则是 IaaS。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-146","note":"","flag":"","pnum":146,"ex_src":"编写"},{"num":147,"stem":"VPC 的二层安全隔离采用什么技术？","type":"single","options":[["A","VLAN"],["B","安全组"],["C","ACL"],["D","VPN"]],"answer":["A"],"ans_raw":"A","explain":"VPC 的二层安全隔离采用 VLAN\n\n                               15","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-147","note":"","flag":"","pnum":147,"ex_src":"题源"},{"num":148,"stem":"从商业视角来看，云计算与下面哪种事物比较相像？","type":"single","options":[["A","加油站"],["B","自来水管"],["C","信息电厂"],["D","水库"]],"answer":["C"],"ans_raw":"C","explain":"商业视角强调按需取用、计量付费、用户不拥有底层设施，这与电厂供电最相似，故称“信息电厂”，选 C。自来水管只体现接上就用的单向供给，加油站是一次性买断商品，水库强调蓄存而非对外输出服务，都不如电厂贴切。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-148","note":"","flag":"","pnum":148,"ex_src":"编写"},{"num":149,"stem":"RH2288H 服务器的 4 个风扇支持热插拔。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"热插拔的判据是风扇模块能否在不停机、不断电的情况下从机箱抽出更换。RH2288H 的风扇模组为可插拔结构并支持冗余，4 个风扇可在线更换，故正确。别把支持热插拔误读成允许长期缺风扇运行。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-149","note":"","flag":"","pnum":149,"ex_src":"编写"},{"num":150,"stem":"FusionAccess 部件 LoadBalance 实现的主要功能是？","type":"single","options":[["A","提供最终用户的接入界面入口"],["B","桌面接入登陆负载均衡"],["C","桌面接入的协议网关，内外网隔离、传输加密"],["D","安装在每一个用户的虚拟桌面中，提供终端与虚拟桌面之间的连接功能"]],"answer":["B"],"ans_raw":"B","explain":"LoadBalance 实现桌面接入的登录负载均衡，把用户的接入请求分发到多台接入或管理节点，避免单点过载，选 B。A 是 WebInterface 的用户接入界面入口；C 是接入网关（内外网隔离、传输加密）；D 是装在用户虚拟机内的接入组件，均非 LB 职责。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-150","note":"","flag":"","pnum":150,"ex_src":"编写"},{"num":151,"stem":"电信运营数据以下面哪种为主？","type":"single","options":[["A","结构化数据"],["B","非结构化数据"],["C","半结构化数据"],["D","虚结构化数据"]],"answer":["A"],"ans_raw":"A","explain":"判据是数据能否用关系二维表描述：电信运营数据以话单、用户资料、账单、信令记录等结构化数据为主，故选 A。非结构化指音视频、图片、文档；半结构化指 XML、邮件、日志这类有标记但无固定表结构的数据；虚结构化不是数据分类术语。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-151","note":"","flag":"","pnum":151,"ex_src":"编写"},{"num":152,"stem":"云计算是一种基于互联网的计算方式，通过这种方式，共享的软硬件资源池和信息可以按需提供给计算机或其它设备。","type":"judge","options":[["A","正确"],["B","错误"]],"answer":["A"],"ans_raw":"A","explain":"该表述符合云计算的通用定义：以互联网为访问通道，把软硬件能力抽象为共享资源池，按用户需要自助、弹性地供给，故正确。复核时看三要素是否齐全——网络接入、共享资源池、按需服务；只有缺项时才应判错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-152","note":"","flag":"","pnum":152,"ex_src":"编写"},{"num":153,"stem":"哪种 CPU 虚拟化技术是未来的发展趋势？","type":"multi","options":[["A","全虚拟化"],["B","半虚拟化"],["C","寄居虚拟化"],["D","硬件辅助虚拟化"]],"answer":["D"],"ans_raw":"D","explain":"（注：本题标注多选，符合题意的仅 D）硬件辅助虚拟化由 CPU 直接提供虚拟化指令与两级特权，配合扩展页表做地址翻译，无需软件二进制翻译即可实现高性能全虚拟化，是发展趋势。半虚拟化要修改客户机操作系统，寄居虚拟化受宿主操作系统开销限制，都不是演进方向。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-153","note":"","flag":"","pnum":153,"ex_src":"编写"},{"num":154,"stem":"以下对 SPARK 的描述,正确的是：","type":"multi","options":[["A","高性能内存迭代计算框架"],["B","内存计算一站式解决方案"],["C","支持多语言快速开发应用"],["D","性能差"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"Spark 以内存中的分布式数据集支撑迭代计算，避免反复落盘，A 正确；SQL、流处理、机器学习、图计算等模块构成内存计算的一站式方案，B 正确；支持 Scala、Java、Python、R 等多语言快速开发应用，C 正确。D 与内存计算的性能定位直接相反，是明显错误项。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-154","note":"","flag":"","pnum":154,"ex_src":"编写"},{"num":155,"stem":"目前 FusionInsight 有哪些子产品？","type":"multi","options":[["A","FusionInsight HD"],["B","FusionInsight Farmer"],["C","FusionInsight Miner"],["D","FusionInsight MPPDB"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"发基于大数据平台的应用；FusionInsight Miner：提供数据挖掘服务集，基于分布式内存计 算的数据分析平台；FusionInsight MPPDB：提供相对独立部署的通用 MPP 数据库，用于性 能较高的交互分析场景。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-155","note":"","flag":"","pnum":155,"ex_src":"题源"},{"num":156,"stem":"以下那几项属于华为交换机堆叠的连接拓扑？","type":"multi","options":[["A","链形连接"],["B","环型连接"],["C","树形连接"],["D","全互连连接"]],"answer":["A","B"],"ans_raw":"AB","explain":"堆叠用堆叠端口把多台设备连成一台逻辑设备，标准连接拓扑是链形（成员首尾依次串联）和环形（每台与相邻两台互连，单链路故障不断开堆叠），选 AB。树形描述的是核心/汇聚/接入的网络分层结构，不是堆叠互连形态；成员全互连在端口开销上不经济，不属于课件所列拓扑。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-156","note":"","flag":"","pnum":156,"ex_src":"编写"},{"num":157,"stem":"硬件辅助虚拟化包括如下哪几类？","type":"multi","options":[["A","处理器辅助虚拟化"],["B","IO 辅助虚拟化"],["C","网络辅助虚拟化"],["D","可信执行技术"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"硬件虚拟化技术包括 VTx，VTd，VTc，TXT。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-157","note":"","flag":"","pnum":157,"ex_src":"题源"},{"num":158,"stem":"以下哪些虚拟交换技术可以在服务器上实现?","type":"multi","options":[["A","VxLan"],["B","VMDQ"],["C","SR­IOV"],["D","TRILL"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"网络与物理网络的解耦；TRILL 是物理设备虚拟化。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-158","note":"","flag":"","pnum":158,"ex_src":"题源"},{"num":159,"stem":"某公司提供多种资源给客户使用，下面哪些形式属于 IaaS？","type":"multi","options":[["A","网络存储服务"],["B","应用系统"],["C","开发平台"],["D","裸虚拟机"]],"answer":["A","D"],"ans_raw":"AD","explain":"IaaS，基础及服务。B 属于 PaaS，C 属于 SaaS。\n\n                                 16","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-159","note":"","flag":"","pnum":159,"ex_src":"题源"},{"num":160,"stem":"基础架构经历了下面哪几个时代?","type":"multi","options":[["A","分布式计算"],["B","大型机计算"],["C","PC 时代"],["D","云计算时代"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"基础架构演进划分为三个时代：大型机集中式计算、PC 与客户端/服务器普及、云计算资源池化，选 BCD。最易误选的 A“分布式计算”是一种技术形态而非独立时代，其思想在客户端/服务器等各阶段都有体现，故不单独成代。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-160","note":"","flag":"","pnum":160,"ex_src":"编写"},{"num":161,"stem":"使用 FusionInsight 平台，对分析型业务，能带来哪些价值？","type":"multi","options":[["A","高可靠"],["B","高安全"],["C","易管理"],["D","易开发"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都是对分析型业务的价值：多副本与故障自动恢复保证高可靠；认证、权限、加密与审计保证高安全；统一管理集群与组件、易运维；提供 SQL 与多语言接口、组件化开发降低门槛。多选题中只挑性能相关的 A、D，会漏掉安全与管理价值。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-161","note":"","flag":"","pnum":161,"ex_src":"编写"},{"num":162,"stem":"如下关于虚拟机热迁移（VM Motion）描述中，哪些是错误的？","type":"multi","options":[["A","可以在不同厂家不同系列 CPU 上迁移"],["B","为提高迁移效率使用了内存压缩传输技术"],["C","热迁移可以保证业务无任何中断"],["D","可以在物理机内部和物理机之间迁移虚拟机"]],"answer":["A","C"],"ans_raw":"AC","explain":"选 A、C。热迁移的前提是源与目的主机 CPU 兼容：题源举例的两颗 E5 系列型号属同构 CPU 才能迁得动，跨厂家或跨架构通常不支持，A 的说法错误。迁移末阶段虚拟机需短暂暂停并切换目的端，只做到用户基本无感知，并非业务无任何中断，C 也错。B、D 描述正确，迁移确实用到内存压缩传输来提升效率，既可在物理机内部调整，也能跨物理机进行。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-162","note":"题源原解析（排版截断）：“和 E5 2680 是同构 CPU。”","flag":"","pnum":162,"ex_src":"编写"},{"num":163,"stem":"FusionManager 支持如下哪些模板？","type":"multi","options":[["A","服务模板"],["B","虚拟机模板"],["C","配置模板"],["D","告警模板"]],"answer":["A","B"],"ans_raw":"AB","explain":"FusionManager 的模板分两类：虚拟机模板保存操作系统、规格与配置，用于批量发放；服务模板把多台虚拟机、网络与部署流程组合成可重复申请的业务单元，选 AB。配置模板、告警模板不是 FM 的模板对象类型，告警属于监控策略配置，不用模板概念描述。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-163","note":"","flag":"","pnum":163,"ex_src":"编写"},{"num":164,"stem":"以下哪些是 FusionCompute 的特性","type":"multi","options":[["A","存储资源裸设备映射 RDM"],["B","集群自治 HA 机制"],["C","基于 NUMA 架构的亲和性调度"],["D","虚拟机远程挂载光驱"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都是 FusionCompute 能力：裸设备映射可把 LUN 直接映射给虚拟机（如数据库、域控等场景）；集群 HA 在主机故障后在其他主机重建虚拟机；基于 NUMA 的亲和性调度降低跨节点访存开销；支持远程挂载 ISO 或光驱完成装机。最易漏选 D，它确由管理平台下发到主机实现。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-164","note":"","flag":"","pnum":164,"ex_src":"编写"},{"num":165,"stem":"如下哪些功能是 FusionManager 所支持的？","type":"multi","options":[["A","异构虚拟化平台统一管理"],["B","异构硬件统一监控"],["C","安全的网络隔离能力"],["D","多租户管理能力"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项均属 FusionManager 能力：以驱动方式纳管 FusionCompute、VMware 等异构虚拟化；对异构服务器、网络与存储硬件统一监控告警；通过 VDC、VPC、安全组提供网络隔离；按租户划分资源边界实现多租户运营。易漏项是 B，硬件层指标由 FM 的纳管采集通道统一获取。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-165","note":"","flag":"","pnum":165,"ex_src":"编写"},{"num":166,"stem":"虚拟化技术能带来哪些价值？","type":"multi","options":[["A","提高服务器利用率"],["B","应用负载错峰填谷"],["C","提高 HA 能力"],["D","大数据挖掘"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"虚拟化把一台物理机切给多个业务用，直接提高服务器利用率；配合资源调度可在低谷腾挪、高峰补齐，实现负载错峰填谷；HA 与在线迁移提高业务连续性，故选 ABC。大数据挖掘是上层数据处理能力，依赖分布式存储与计算框架，不是虚拟化本身带来的价值。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-166","note":"","flag":"","pnum":166,"ex_src":"编写"},{"num":167,"stem":"FusionSphere 的架构有哪些特点？","type":"multi","options":[["A","高效"],["B","安全"],["C","融合"],["D","开放"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项对应 FusionSphere 的架构特点：高效（虚拟化层轻量、调度开销低，性能接近裸机）；安全（管理网与业务网分离、权限分级、虚拟机隔离）；融合（计算、存储、网络、桌面与大数据统一管理）；开放（标准 API，兼容 OpenStack 并可纳管第三方平台）。别把融合误解为仅指硬件集成。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-167","note":"","flag":"","pnum":167,"ex_src":"编写"},{"num":168,"stem":"FusionAccess USBKEY 认证特性中的双因子是指？","type":"multi","options":[["A","USBKEY 硬件本身"],["B","域账号"],["C","用户指纹"],["D","PIN 码"]],"answer":["A","D"],"ans_raw":"AD","explain":"选 A、D。USBKEY 双因子取自「持有物加你知道的口令」这一组合：一是 USB Key 硬件本身，二是保护该 Key 的 PIN 码，两者同时具备才能完成认证。域账号只是登录账户的标识，不构成与之并列的独立因子，B 错；指纹属生物特征因子，不在 USB Key 认证所指的这两个要素之内，C 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-168","note":"题源原解析（排版截断）：“USB Key 都具有硬件和 PIN 码保护。”","flag":"","pnum":168,"ex_src":"编写"},{"num":169,"stem":"通过 FusionManager 的北向接口可以获取到哪些信息？","type":"multi","options":[["A","集群信息"],["B","虚拟机信息"],["C","虚拟网络信息"],["D","拓扑信息"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"FusionManager 北向接口面向云管与运营支撑系统，输出的是已纳管的资源与拓扑视图：集群信息、虚拟机信息、虚拟网络信息以及资源关联拓扑都能获取，选 ABCD。这四类数据 FM 本身就在维护，不存在只能给物理层信息的限制。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-169","note":"","flag":"","pnum":169,"ex_src":"编写"},{"num":170,"stem":"虚拟化的本质是什么？","type":"multi","options":[["A","分区"],["B","隔离"],["C","封装"],["D","硬件独立性"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"虚拟化的四个本质特征全部命中：分区（一台物理机按 CPU、内存划分给多台虚拟机）、隔离（故障与安全互不影响）、封装（整机状态以文件保存，支撑快照、迁移与模板）、硬件独立（不绑定具体物理硬件），故选 ABCD。漏选通常出在封装，它正是快照与迁移的基础。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-170","note":"","flag":"","pnum":170,"ex_src":"编写"},{"num":171,"stem":"FusionCompute 中使用的 HA 机制是？","type":"multi","options":[["A","集中控制式 HA 机制"],["B","脑裂机制"],["C","差分控制式 HA 机制"],["D","集群自治式 HA 机制"]],"answer":["A","D"],"ans_raw":"AD","explain":"支持集中控制 HA 和集群自治 HA 两种机制，可自选配置。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-171","note":"","flag":"","pnum":171,"ex_src":"题源"},{"num":172,"stem":"在安装 FusionAccess 过程中，需要配置 WindowsOS 基础架构主机，下面哪些组件是安装在 WindowsOS 基础架构主机上的？","type":"multi","options":[["A","GaussDB"],["B","ITA"],["C","HDC"],["D","Logger"]],"answer":["B","D"],"ans_raw":"BD","explain":"ITA（桌面与资源的管理控制入口）和 Logger（日志收集与转储）安装在 Windows 基础架构主机上，选 BD。GaussDB 是独立部署的数据库组件，按 Linux 主机形态交付；HDC 属桌面控制组件，课件部署表未归在 Windows 基础架构主机这一角色。易错是把所有 FusionAccess 组件都当成 Windows 程序。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-172","note":"","flag":"","pnum":172,"ex_src":"编写"},{"num":173,"stem":"如下关于 FusionManager 中的 VDC 和 VPC 的描述，哪些是正确的?","type":"multi","options":[["A","VDC 是划分给用户的虚拟资源边界，是租户可以使用的资源边界"],["B","VPC 是虚拟私有云，是在 VDC 中创建的私有网络隔离区域 17"],["C","在一个 VDC 中可以包含多个 VPC"],["D","VPC 中的网络是由管理员指定的，租户只能使用管理员创建的网络"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"VDC 是划分给租户的虚拟资源边界，限定其可用资源范围（A 对）；VPC 是 VDC 内的私有网络隔离区域（B 对）；一个 VDC 可创建多个 VPC 以隔离不同业务网络（C 对）；网络与子网由管理员规划下发，租户只能在给定网络内使用、不能自建（D 对）。最易误判的是 D，其要点是 FM 多租户场景下网络管理权归管理员。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-173","note":"","flag":"","pnum":173,"ex_src":"编写"},{"num":174,"stem":"FusionCompute 的基本安装包括哪几个步骤?","type":"multi","options":[["A","安装主机"],["B","安装 VRM"],["C","安装 VSAM"],["D","安装 PVM"]],"answer":["A","B"],"ans_raw":"AB","explain":"FusionCompute 基本安装两步：先在物理主机上安装 CNA 主机虚拟化层，再在主机上部署 VRM 管理虚拟机以提供集群与虚拟机管理，选 AB。VSAM 是大型机体系里的存储管理概念，与 FusionCompute 无关；PVM 不是其安装组件，属拼凑干扰项。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-174","note":"","flag":"","pnum":174,"ex_src":"编写"},{"num":175,"stem":"云计算环境把数据集中到云数据中心，给客户带来全方位的安全，主要包括哪些方面？","type":"multi","options":[["A","网络传输加密"],["B","数据加密存储"],["C","虚拟机防病毒"],["D","终端接入认证"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项构成云数据中心的纵深防护：传输加密保护数据在链路上不被窃取，数据加密存储保护落盘内容，虚拟机防病毒避免虚拟机之间横向传播，终端接入认证确认人或设备合法，全选 ABCD。易误判的是 C，认为杀毒只属终端职责，实际虚拟机同样需要防护。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-175","note":"","flag":"","pnum":175,"ex_src":"编写"},{"num":176,"stem":"下面哪些技术属于云计算技术体系？","type":"multi","options":[["A","虚拟化技术"],["B","存储技术"],["C","网络技术"],["D","分布式技术"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都属于云计算技术体系：虚拟化提供资源池抽象，存储技术（分布式存储、SAN/NAS）承载数据，网络技术（VLAN、虚拟交换、VPC）打通资源，分布式技术提供扩展与容错，全选 ABCD。易漏 A、D，把虚拟化只看成服务器技术、把分布式只看成大数据专有。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-176","note":"","flag":"","pnum":176,"ex_src":"编写"},{"num":177,"stem":"FusionInsight 可以做到如下哪些类型的组网隔离？","type":"multi","options":[["A","工作节点隔离"],["B","集群业务平面"],["C","集群管理平面"],["D","集群外维护网络"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"选 B、C、D。FusionInsight 的组网隔离按网络平面划分：集群业务平面承载数据处理与节点间业务通信，集群管理平面承载集群自身的管理与内部通信，集群外维护网络供运维与客户端接入，这几类网络彼此之间实施物理隔离。工作节点只是集群内的角色划分，不是一种网络平面隔离类型，A 错。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-177","note":"题源原解析（排版截断）：“络，彼此之间实施物理隔离。”","flag":"","pnum":177,"ex_src":"编写"},{"num":178,"stem":"华为云计算解决方案中使用了多种不同的网络虚拟化技术，下面描述中哪些是正确的？","type":"multi","options":[["A","普通虚拟网卡必须要由 Domain0 处理网络 I/O 活动"],["B","VMDq 支持无损热迁移"],["C","VMDq 网卡吞吐量好于 SR­IOV"],["D","SR­IOV 技术场景下，支持热迁移、快照"]],"answer":["A","B"],"ans_raw":"AB","explain":"的网络 I/O 活动，以及传送队列和调度优化。因此，计算量大、 CPU 资源开销高。SRIOV 中，网卡硬件 信息（ PF、 VF 等）绑定，不同物理硬件会有所不同，因此热迁移、快照等特性无法使用。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-178","note":"","flag":"","pnum":178,"ex_src":"题源"},{"num":179,"stem":"云计算行业包括哪些参与者?","type":"multi","options":[["A","云服务提供者"],["B","云设备提供者"],["C","云用户"],["D","云服务开发者"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"云计算产业链三个角色：云设备提供者提供服务器、存储、网络硬件，云服务提供者建设并运营云平台对外售卖能力，云用户消费资源或服务，选 ABC。服务开发者不是独立的产业角色，其工作被包含在云服务提供者或云用户一侧。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-179","note":"","flag":"","pnum":179,"ex_src":"编写"},{"num":180,"stem":"如下关于 VxLAN 的描述中，错误的是？","type":"multi","options":[["A","实现了虚拟网络和物理交换机配置的解耦"],["B","不支持网络设备利旧"],["C","最大支持 4K 个虚拟网络标识 VNI"],["D","实现虚拟机跨物理 3 层网络迁移"]],"answer":["B","C"],"ans_raw":"BC","explain":"选 B、C。VXLAN 用 24 位 VNI 提供约 1600 万（16M）个虚拟网络标识以支撑多租户，C 说的 4K 是把 VLAN 的 12 位上限套到 VXLAN 上；它在现有承载网络之上构建大二层，允许沿用原有网络设备，B 说不支持利旧也不成立。A 正确，虚拟网络与物理交换机配置解耦；D 正确，虚拟机可跨物理三层网络迁移。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-180","note":"题源原解析（排版截断）：“在此基础上提供大二层、 16M 多租户的能力”","flag":"","pnum":180,"ex_src":"编写"},{"num":181,"stem":"业界主流的虚拟化架构类型有哪些？","type":"multi","options":[["A","寄居虚拟化"],["B","裸金属虚拟化"],["C","全虚拟化"],["D","操作系统虚拟化"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"按虚拟化层位置与形态，主流架构是寄居虚拟化（Hypervisor 跑在宿主操作系统之上）、裸金属虚拟化（直接运行在硬件上）和操作系统虚拟化（容器，多实例共享宿主内核），选 ABD。全虚拟化是按客户机是否需要改造划分的技术方式，不属于架构类型，这是最易混选的一项。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-181","note":"","flag":"","pnum":181,"ex_src":"编写"},{"num":182,"stem":"VPC 可以提供哪些网络能力？","type":"multi","options":[["A","弹性 IP"],["B","安全组"],["C","VLB"],["D","虚拟路由功能"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"华为云 VPC 提供隔离网络及其配套能力：弹性 IP 用于公网进出，安全组做实例级访问控制，VLB 在子网内提供负载均衡分发，虚拟路由器负责子网间路由，全选 ABCD。易误选的是 C，认为负载均衡是独立产品；在 VPC 场景下确实以虚拟负载均衡对内网流量做分发。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-182","note":"","flag":"","pnum":182,"ex_src":"编写"},{"num":183,"stem":"在华为云计算解决方案中，下面哪几个组件既可以部署在物理机上，又可以部署在虚拟机上？","type":"multi","options":[["A","CAN"],["B","VRM"],["C","FusionManager"],["D","VSAM 18"]],"answer":["B","C"],"ans_raw":"BC","explain":"规模和服务器的配置情况选择； VRM 可以主备部署也可以单点部署， 根据局点的可靠性要 求和资源配置情况而定。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-183","note":"","flag":"","pnum":183,"ex_src":"题源"},{"num":184,"stem":"华为云计算解决方案中采用的 TC 瘦终端设备，显示接口支持哪些？","type":"multi","options":[["A","DVI"],["B","HDMI"],["C","VGA"],["D","PCI­E"]],"answer":["A","C"],"ans_raw":"AC","explain":"显示接口指直接输出视频信号给显示器的端口：VGA 为模拟、DVI 为数字，符合课件所列 TC 瘦终端显示接口，选 AC。最易误选 D：PCI-E 是主板扩展总线（可插显卡、网卡），不是对外显示接口。HDMI 与 DVI 同属数字视频信号，是否配备取决于具体 TC 型号规格。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-184","note":"","flag":"","pnum":184,"ex_src":"编写"},{"num":185,"stem":"云计算的部署模式有哪些？","type":"multi","options":[["A","公有云"],["B","私有云"],["C","政务云"],["D","混合云"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"选 A、B、D。按部署模式划分，云计算包括公有云、私有云和混合云三种。政务云是按服务对象与行业归属得到的类别，其本身仍落在私有云或混合云的部署形态之内，不是并列的第四种部署模式，C 错。区分标准看是「按部署运营方式」还是「按行业归属」命名。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-185","note":"题源原解析（排版截断）：“云计算的部署模式包括：公有云、私有云和混合云。”","flag":"","pnum":185,"ex_src":"编写"},{"num":186,"stem":"下面关于华为 FusionCube 的描述中，哪个是错误的？","type":"single","options":[["A","FusionCube 融合计算、存储、网络、虚拟平台、数据库和应用软件等，实现一站式解决 方案"],["B","FusionCube 融合的核心是分布式计算软件 （ FusionCompute + FusionManager +FusionStorage）"],["C","FusionCube 从底层的硬件到上层分布式云计算软件，都是华为自主研发的解决方案， 提供 端到端的精简管理部署"],["D","FusionCube 虚拟化多个外置 SAN 存储，提供分布式高性能存储池，解决 IO 性能瓶颈问 题"]],"answer":["D"],"ans_raw":"D","explain":"能力，实现一 站式解决方案；FusionCube 融合的核心是分布式云计算软件 (FusionCompute+FusionManager+FusionStorage)；从底层的硬件到上层分布式云计算软件， 都是华为自主研发的解决方案，提供端到端的精简管理部署；FusionStorage 采用分布式 Server SAN 架构，高速 InfiniBand 连接，高速 SSD 存储，性能更高，扩展能力更好","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-186","note":"","flag":"","pnum":186,"ex_src":"题源"},{"num":187,"stem":"FusionInsight 数据可靠性包含哪些？","type":"multi","options":[["A","跨数据中心数据备份"],["B","第三方备份系统集成"],["C","快速故障检测"],["D","底层磁盘在线更换"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都支撑数据可靠性：跨数据中心备份应对整机房级灾难，对接第三方备份系统纳入企业既有备份体系，快速故障检测缩短坏盘坏节点的发现与恢复时间，底层磁盘在线更换在不中断业务的前提下修复介质故障，全选 ABCD。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-187","note":"","flag":"","pnum":187,"ex_src":"编写"},{"num":188,"stem":"下列哪些组件是 FusionInsight 采用的开源组件？","type":"multi","options":[["A","HDFS"],["B","Manager"],["C","HBase"],["D","Hive"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"HDFS 提供分布式文件存储，HBase 是分布式列式数据库，Hive 提供数据仓库与 SQL 化查询，三者源自开源社区、由 FusionInsight 做增强，选 ACD。Manager 是华为自研的统一管理与运维组件，负责集群管理、监控告警与权限，并非开源，属最易误选项。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-188","note":"","flag":"","pnum":188,"ex_src":"编写"},{"num":189,"stem":"如下关于虚拟机的虚拟内存描述中，哪些是不正确的？","type":"multi","options":[["A","VMM 需要保存物理内存地址和虚拟内存地址的映射关系"],["B","虚拟内存的使用和物理内存的使用相同，可以不转换，直接使用"],["C","物理内存可以划分为多个内存块，每个虚拟机只分配一个虚拟内存块"],["D","虚拟内存地址和物理内存地址是一一对应的， 使用内存复用技术后可用虚拟内存量小于等 于物理内存量"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"不正确的是 BCD。虚拟机发出的访存地址必须经 VMM 维护的页表（影子页表或硬件辅助的两级翻译）转换成物理地址，不能直接使用，B 错；虚拟内存空间由客户机自行管理，与物理内存并非按块一一对应，C 错；开启内存复用后靠气球回收、页共享、换出等机制超分，可分配的虚拟机内存总量可以大于物理内存，D 错。只有 A 正确。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-189","note":"","flag":"","pnum":189,"ex_src":"编写"},{"num":190,"stem":"部署华为云计算解决方案时，前期的规划设计一般涉及哪些方面？","type":"multi","options":[["A","架构设计"],["B","组件设计"],["C","网络设计"],["D","存储设计"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都是前期规划设计内容：架构设计确定整体方案与规模，组件设计确定各软件组件的部署形态与规格，网络设计规划管理、业务、存储网络与 VLAN，存储设计选择 SAN/NAS/本地盘并核算容量与性能，全选 ABCD。易漏 B，管理节点、数据库等组件的主备与规格必须在规划期定下。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-190","note":"","flag":"","pnum":190,"ex_src":"编写"},{"num":191,"stem":"在云数据中心中，虚拟机的虚拟交换技术包括哪几种类型？","type":"multi","options":[["A","基于软件的虚拟交换"],["B","基于智能网卡的虚拟交换 19"],["C","基于物理交换机的虚拟交换"],["D","基于 InfiniBand 网卡的虚拟交换"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"虚拟机虚拟交换有三种实现：基于软件的虚拟交换由宿主机内虚拟交换机转发，最灵活；基于智能网卡的把交换与封装卸载到网卡，降低宿主 CPU 开销；基于物理交换机的边缘交换思路把转发交给物理网络，便于统一策略与可视，选 ABC。InfiniBand 定位是高性能互联，教材未列为虚拟交换类型，属易误选项。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-191","note":"","flag":"","pnum":191,"ex_src":"编写"},{"num":192,"stem":"FusionAccess 虚拟应用组件 SBC 的主要特点是？","type":"multi","options":[["A","一个发布应用程序的解决方案，它使得应用程序虚拟化"],["B","支持在数据中心集中控制和管理，能够作为一个服务发布到任何地方，而不需要用户在本 地安装该应用程序"],["C","应用程序最终运行在后台服务器，它借用 Windows Server 的终端服务机制，为每个接入 用户建立一个 Session"],["D","应用程序通过 Web 接口展现所发布的应用，用户可以直接点击使用"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项都是 SBC 特点：应用集中发布、在服务器侧虚拟化运行（A、B）；借用 Windows 终端服务机制，为每个接入用户建立会话，程序实际跑在后台服务器（C）；用户通过 Web 入口直接点开使用，本地无需安装（D）。误判点在于把 C 的终端服务会话当成独立产品，SBC 正是基于该机制。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-192","note":"","flag":"","pnum":192,"ex_src":"编写"},{"num":193,"stem":"OceanStor 5800 v3 存储设备采用全冗余设计，主要是指哪些模块冗余？","type":"multi","options":[["A","控制器"],["B","风扇"],["C","电源"],["D","BBU"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"和 BBU 模块以及电源模块都提供冗余高可用特性。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-193","note":"","flag":"","pnum":193,"ex_src":"题源"},{"num":194,"stem":"FusionCompute 可以对哪些资源进行 QoS 控制？","type":"multi","options":[["A","CPU"],["B","内存"],["C","网络"],["D","存储"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"FusionCompute 可对四类资源做 QoS：按份额与预留调节虚拟机 CPU 竞争优先级，对内存做预留与份额控制，限制或保障网卡带宽，设置磁盘 I/O 权重与上限，全选 ABCD。易漏 B，内存 QoS 体现为预留和份额，不是带宽类指标。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-194","note":"","flag":"","pnum":194,"ex_src":"编写"},{"num":195,"stem":"华为可以提供从软件到硬件，端到端的云计算解决方案。下面哪些硬件组成部分在华为的云计算解决方案中是可选的？","type":"multi","options":[["A","服务器"],["B","负载均衡设备"],["C","防火墙"],["D","TC 瘦终端"]],"answer":["B","C","D"],"ans_raw":"BCD","explain":"判断标准是去掉该设备后方案能否仍交付核心能力。服务器承载虚拟化与存储软件，属必需项；负载均衡与防火墙按业务量和安全要求增减，TC 瘦终端只在桌面云场景需要，还可用软客户端或既有终端替代，故选 BCD。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-195","note":"","flag":"","pnum":195,"ex_src":"编写"},{"num":196,"stem":"FusionCompute 中存储资源裸设备映射有哪些限制？","type":"multi","options":[["A","不支持链接克隆"],["B","不支持存储精简置备"],["C","不支持存储增量快照"],["D","不支持存储热迁移"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"存储热迁移、存储 Qos 等，且只支持虚拟机操作系统为 Linux 场景。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-196","note":"","flag":"","pnum":196,"ex_src":"题源"},{"num":197,"stem":"FusionCompute 使用存储精简置备可以有效提高存储利用率， 降低存储成本。 如果 120GB的物理存储， 其上配置了 4 个虚拟机， 下面的虚拟机磁盘容量分配方案中哪些是可行的？（单 位 GB，暂不考虑实际存储情况）","type":"multi","options":[["A","10:20:30:40"],["B","10:100:20:200"],["C","120:120:120:120"],["D","30:30:30:30"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"精简置备只登记虚拟机的逻辑容量，物理空间随实际写入按需分配，各磁盘容量之和可以超过物理存储；题目又明确不考虑实际占用，故 A（100GB）、B（330GB）、C（480GB）、D（120GB）四种分配都可创建，全选。若改为厚置备会一次性占用全部容量，则 B、C 不可行，这是本题的关键区分点。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-197","note":"","flag":"","pnum":197,"ex_src":"编写"},{"num":198,"stem":"在 FusionManager 上对服务器进行监控需要使用 SNMP 协议或 SSH 协议，因此在接入服务器前需要收集如下哪些基本信息？","type":"multi","options":[["A","服务器的 IP 地址"],["B","服务器的 SNMP 端口号"],["C","服务器 SSH 用户名和密码"],["D","SNMP 的版本号"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"FusionManager 用 SNMP 读设备的 MIB 指标、用 SSH 下发命令做深度采集，因此接入前需备齐被管对象 IP 地址与 SNMP 端口号（默认 161，可自定义），又要确定 SNMP 版本号——v2c 用团体名、v3 用用户认证，取值方式不同；走 SSH 通道还需登录用户名与口令。缺任一项都建不起采集会话，故 ABCD 全选。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-198","note":"","flag":"","pnum":198,"ex_src":"编写"},{"num":199,"stem":"华为桌面云解决方案可看成由下面哪几块组成？","type":"multi","options":[["A","FusionAccess"],["B","FusionSphere"],["C","FusionInsight"],["D","TC 终端"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"FusionInsight 属于华为大数据居解决方案。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-199","note":"","flag":"","pnum":199,"ex_src":"题源"},{"num":200,"stem":"使用 FusionAccess 发放虚拟机时可以对下面哪些参数进行选择和设置？","type":"multi","options":[["A","虚拟机规格"],["B","虚拟机网络"],["C","虚拟机磁盘"],["D","虚拟机命名规则"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"FusionAccess 桌面发放向导里四项都是可设参数：虚拟机规格（vCPU 与内存）、虚拟机网络（端口组/VLAN，决定桌面接入平面）、虚拟机磁盘（数据存储位置与磁盘配置模式）、虚拟机命名规则（批量发放时的名称前缀与编号）。易漏项是 D：链接克隆批量发放时必须靠命名规则自动生成 VM 名，不能只挑规格。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-200","note":"","flag":"","pnum":200,"ex_src":"编写"},{"num":201,"stem":"E9000 服务器的主要特点是什么？","type":"multi","options":[["A","组网灵活"],["B","高计算密度"],["C","高存储密度"],["D","计算、存储和网络融合"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"E9000 是华为刀片平台：机框中板把计算刀片、本地/外接存储与交换模块合为一体，单框算力与盘位密度远高于同高度机架服务器，交换板可按 GE/10GE/FC/IB 等选型实现灵活组网，四项正是其宣传特点，故 ABCD。注意区分：X8000 属大数据存储类服务器，不是这种融合机框。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-201","note":"","flag":"","pnum":201,"ex_src":"编写"},{"num":202,"stem":"如下关于 FusionManager 核心组件功能的描述，哪些是正确的？ 20","type":"multi","options":[["A","UHM 是统一硬件管理组件，负责异构硬件监控"],["B","IRM 是集成资源管理组件，负责异构虚拟化资源管理"],["C","Fault Service 提供告警查询管理"],["D","AME 是应用管理引擎组件，负责应用自动化管理"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"四项分工描述均正确：UHM 统一硬件管理负责异构服务器/存储/网络设备的监控，IRM 集成资源管理负责异构虚拟化平台资源池的纳管，Fault Service 提供告警的采集与查询管理，AME 应用管理引擎负责应用自动化部署与生命周期管理，故 ABCD。区分点记住：UHM 面向物理硬件，IRM 面向虚拟资源。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-202","note":"","flag":"","pnum":202,"ex_src":"编写"},{"num":203,"stem":"云计算的商业模式有哪些？","type":"multi","options":[["A","IaaS"],["B","PaaS"],["C","Saas"],["D","DaaS"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"按教材与 NIST 口径，云计算的商业模式按服务层次划分为三种：IaaS 出租计算/存储/网络，PaaS 出租运行与开发平台，SaaS 直接交付可用软件，三者都是按需自助、计量收费。DaaS 只是把桌面当作交付内容（如 FusionAccess 桌面云），本身落在 IaaS/SaaS 之上，不构成独立一层，故不选 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-203","note":"","flag":"","pnum":203,"ex_src":"编写"},{"num":204,"stem":"华为统一管理技术，可以管理哪些设备和系统？","type":"multi","options":[["A","网络安全设备"],["B","存储和服务器"],["C","虚拟化资源"],["D","应用软件"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"华为统一管理技术（UCM/eSight 一类管理平台）的纳管对象是 ICT 基础设施层：网络与安全设备、存储与服务器等物理资源，以及运行其上的虚拟化资源。应用软件属业务应用层，其部署运维由应用管理平台等专门系统承担，不在统一基础设施管理清单内，故选 ABC 排除 D。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-204","note":"","flag":"","pnum":204,"ex_src":"编写"},{"num":205,"stem":"FusionManager 中管理员可以被赋予两种主要角色：ServiceAdmin 和 OperationAdmin，关于这两种角色说法正确的是？","type":"multi","options":[["A","OperationAdmin 着重于业务运营"],["B","ServiceAdmin 着重于资源池构建、管理和维护"],["C","ServiceAdmin 着重于业务运营"],["D","OperationAdmin 着重于资源池构建、管理和维护"]],"answer":["C","D"],"ans_raw":"CD","explain":"前者偏业务运营，后者偏资源池的构建、管理和维护。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-205","note":"","flag":"","pnum":205,"ex_src":"题源"},{"num":206,"stem":"创建虚拟机的过程包括哪些虚拟硬件的使用？","type":"multi","options":[["A","CPU"],["B","内存"],["C","硬盘"],["D","网卡"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"创建虚拟机本质是分配一组虚拟硬件：vCPU 从主机 CPU 资源中切分，虚拟内存可复用与超分，虚拟磁盘以数据存储上的文件形式承载，虚拟网卡绑定主机侧端口组获得网络。四项均为必配虚拟硬件，故 ABCD。配额与调度由 VRM 完成，但交付给 VM 的硬件形态仍是这四类。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-206","note":"","flag":"","pnum":206,"ex_src":"编写"},{"num":207,"stem":"FusionInsight 系统可靠性包含哪些？","type":"multi","options":[["A","业务无单点故障"],["B","管理节点 HA"],["C","跨 DC 容灾/备份"],["D","第三方备份系统集成"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"FusionInsight 的可靠性覆盖四个层面：HDFS/YARN 等组件多实例部署，消除业务链路单点；NameNode、ResourceManager 等管理节点主备 HA 保护；支持跨数据中心容灾与数据备份；并可对接第三方备份系统统一做备份恢复。四项均成立，故 ABCD，注意第 3、4 项常被误当成运维工具能力而漏选。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-207","note":"","flag":"","pnum":207,"ex_src":"编写"},{"num":208,"stem":"在云数据中心中，业务主机的虚拟硬件包含哪些？","type":"multi","options":[["A","CPU"],["B","内存"],["C","硬盘"],["D","网卡"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"云数据中心中业务主机即虚拟机，其虚拟硬件由虚拟化层抽象提供：vCPU、虚拟内存、虚拟磁盘（承载于 SAN/NAS 或本地数据存储）与虚拟网卡（接入端口组和 VLAN）。四项缺一不可，故 ABCD。易混点：物理主机自身的 CPU/内存/硬盘/网卡属物理硬件，不算虚拟硬件。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-208","note":"","flag":"","pnum":208,"ex_src":"编写"},{"num":209,"stem":"下列关于华为 S 系列盒式交换机堆叠的描述中，哪些是正确的？","type":"multi","options":[["A","只有相同型号的交换机才能进行堆叠"],["B","不同子系列交换机实现堆叠的方式不同"],["C","部分交换机不支持堆叠"],["D","全系列交换机均支持堆叠"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"堆叠成员要求同型号（个别同代次系列可跨型号，考试按同型号口径），A 成立；盒式交换机的堆叠承载有专用堆叠卡、固定堆叠端口和业务口堆叠等方式，子系列不同实现不同，B 成立；确有低端型号不具备堆叠能力，D「全系列均支持」说法绝对化，错误。故选 ABC。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-209","note":"","flag":"","pnum":209,"ex_src":"编写"},{"num":210,"stem":"计算虚拟化技术包括哪几个方面的虚拟化？","type":"multi","options":[["A","CPU 虚拟化"],["B","内存虚拟化"],["C","硬盘虚拟化"],["D","IO 虚拟化"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"关键技术点包括计算、存储和网络虚拟化以及虚拟机监控、调度和迁移。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-210","note":"","flag":"","pnum":210,"ex_src":"题源"},{"num":211,"stem":"云计算的产生是哪些因素共同促进的结果？","type":"multi","options":[["A","需求推动"],["B","技术进步"],["C","商业模式转变"],["D","行业变革"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"云计算是三股力量叠加的产物：互联网业务对弹性算力的海量需求形成推动力；虚拟化、分布式存储与宽带网络让大规模资源池在技术上可行；供给方从卖设备转向卖服务形成计费模式。行业变革是这三者作用之后呈现的结果，而非与它们并列的成因，故不选 D，答案 ABC。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-211","note":"","flag":"","pnum":211,"ex_src":"编写"},{"num":212,"stem":"如下关于 FusionCompute 基于 NUMA 架构的亲和性调整，哪些描述是正确的？","type":"multi","options":[["A","分配虚拟机资源时，会感知硬件 NUMA 架构，优先选择同一 Node 内的资源"],["B","当某虚拟机所需资源无法由 1 个 Node 提供时，会提示虚拟机资源分配失败"],["C","资源分配动态调整，而不是静态设置"],["D","根据就近原则分配距离较近的 Node 资源"]],"answer":["A","C"],"ans_raw":"AC","explain":"资源充足的 node 上，从而动态实现 node 间的 CPU 负载均衡。Host NUMA 根据当时主机内 存和 CPU 负载，选择一个负载较轻的 node 放置该 V。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-212","note":"","flag":"","pnum":212,"ex_src":"题源"},{"num":213,"stem":"下面哪些模块属于 OceanStor 5800 v3 存储设备的控制框组成部分？ 21","type":"multi","options":[["A","电源模块"],["B","管理模块"],["C","磁盘模块"],["D","接口模块"]],"answer":["A","B","D"],"ans_raw":"ABD","explain":"控制框是阵列的控制与接入部分，内含供电的电源模块（与风扇模块）、承担系统管理与集群协调的管理/控制模块，以及 FC、iSCSI、以太等主机接口模块。磁盘模块（盘位与硬盘托架）位于独立的磁盘柜 DAE 内，通过级联链路与控制框相连，不属于控制框组成，故排除 C，选 ABD。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-213","note":"","flag":"","pnum":213,"ex_src":"编写"},{"num":214,"stem":"VPC 中可以使用的网络类型包括下面哪些？","type":"multi","options":[["A","直连网络"],["B","路由网络"],["C","内部网络"],["D","封闭网络"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"查询网络， 网络包含 3 种类型，直连网络，内部网络，路由网络。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-214","note":"","flag":"","pnum":214,"ex_src":"题源"},{"num":215,"stem":"存储虚拟化的实现方式有哪些？","type":"multi","options":[["A","裸设备+逻辑卷"],["B","存储设备虚拟化"],["C","主机存储虚拟化+文件系统"],["D","主机存储化"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"存储虚拟化三条落地路径：主机侧用裸设备映射加 LVM 逻辑卷，把物理盘抽象为可调整大小的卷；在存储设备（阵列）内部做容量池化与 LUN 虚拟化，对外统一提供卷；主机侧存储虚拟化软件再叠加集群/分布式文件系统，聚合多设备容量。D「主机存储化」只是把主机当直连 DAS 使用，没有虚拟化层，故不选。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-215","note":"","flag":"","pnum":215,"ex_src":"编写"},{"num":216,"stem":"云计算的关键特征有哪些？","type":"multi","options":[["A","按需自助服务"],["B","与位置无关的资源池"],["C","按使用付费"],["D","快速弹性"]],"answer":["A","B","C","D"],"ans_raw":"ABCD","explain":"NIST 归纳的云计算五特征为按需自助服务、广泛网络接入、资源池化（与位置无关）、快速弹性、计量服务（按使用付费），本题四项全部在列，故 ABCD 无干扰项。「与位置无关」指用户无需知道资源物理位置，并不限制终端接入地点，理解时别误读。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-216","note":"","flag":"","pnum":216,"ex_src":"编写"},{"num":217,"stem":"FusionAccess 的主要功能是？","type":"multi","options":[["A","资产管理，管理用户与虚拟机的关系"],["B","用户接入，用户可查看操作自己的虚拟机"],["C","桌面传送，通过桌面链接协议使用虚拟机"],["D","资源调度，管理调度云平台计算、存储资源"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"FusionAccess 是桌面云解决方案：由 ITA/HDC 做桌面资产管理并维护用户与虚拟机的绑定关系，用户经接入鉴权后只能查看操作自己的桌面，HDP 桌面传输协议负责把画面与外设数据送到终端，故 ABC 正确。D 描述的集群计算/存储资源调度由下层 FusionCompute（VRM、DRS）完成，不是 FusionAccess 的职责。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-217","note":"","flag":"","pnum":217,"ex_src":"编写"},{"num":218,"stem":"华为云计算软件可以预先部署在特定的硬件上，软硬件结合形成一体机，销售给客户。下面哪种华为服务器支持一体机部署模式？","type":"multi","options":[["A","E9000"],["B","RH5885"],["C","RH2288H"],["D","X8000"]],"answer":["A","C"],"ans_raw":"AC","explain":"一体机要求机框同时承载计算、存储与交换并预集成云软件：E9000 刀片机框与 RH2288H 机架服务器都可作为载体，故 A、C 入选。RH5885 定位四路及以上关键业务，不作一体机标准机型；X8000 是面向大数据的存储节点服务器，两者排除。具体支持型号随版本略有变化，此处按考试口径记忆。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-218","note":"","flag":"","pnum":218,"ex_src":"编写"},{"num":219,"stem":"华为桌面云解决方案 FusionAccess 的授权模式包括下面哪几种？","type":"multi","options":[["A","用户数"],["B","并发用户数"],["C","虚拟桌面数"],["D","物理服务器台数"]],"answer":["A","B"],"ans_raw":"AB","explain":"License 授权模式分为用户数、并发用户数。两种授权模式的单价不一样。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-219","note":"","flag":"","pnum":219,"ex_src":"题源"},{"num":220,"stem":"下面哪些是 FusionCompute 的组成部件?","type":"multi","options":[["A","Ultra VR 组件"],["B","VRM 组件"],["C","FusionCompute 组件"],["D","CNA 组件"]],"answer":["B","D"],"ans_raw":"BD","explain":"VRM， FusionCompute 的管理节点，提供管理界面对虚拟化资源进行统一管理。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-220","note":"","flag":"","pnum":220,"ex_src":"题源"},{"num":221,"stem":"华为云计算 FusionCloud 品牌包括哪些解决方案？","type":"multi","options":[["A","FusionSphere 基础设施虚拟化"],["B","FusionServer 华为服务器"],["C","FusionAccess 云接入管理"],["D","FusionInsight 大数据处理"]],"answer":["A","C","D"],"ans_raw":"ACD","explain":"FusionCloud 是华为云计算解决方案品牌，涵盖 FusionSphere 基础设施虚拟化、FusionAccess 桌面云接入管理、FusionInsight 大数据处理及上层云管理组件，故选 ACD。FusionServer 是服务器硬件产品线品牌，属承载这些方案的物理设备，本身不在 FusionCloud 解决方案清单内，排除 B。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-221","note":"","flag":"","pnum":221,"ex_src":"编写"},{"num":222,"stem":"云计算虚拟化技术可以提高资源的利用率，包括下面哪些方面？","type":"multi","options":[["A","虚拟机资源调整"],["B","内存复用"],["C","提高服务器利用率"],["D","应用自动部署"]],"answer":["A","B","C"],"ans_raw":"ABC","explain":"虚拟化提升资源利用率的手段集中在资源层：虚拟机 CPU/内存动态调整让负载变化时不空转；内存复用（超分配、共享回收、交换）让同样物理内存承载更多 VM；配合集群调度把服务器整体利用率拉高，故 ABC 正确。D 应用自动部署改善的是交付效率与一致性，并不直接提高资源利用率，不选。","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-222","note":"","flag":"","pnum":222,"ex_src":"编写"},{"num":223,"stem":"谈到系统的可伸缩性，Scale Up 和 Scale Out 是两种典型的扩展模式。下面关于这两种扩展模式的说法中，哪些是错误的？","type":"multi","options":[["A","Scale Up 扩展时，重点提升单个节点的性能，整个系统容易达到性能瓶颈"],["B","云计算领域一般采用 Scale Up 模式进行扩展"],["C","Scale Out 扩展时，重点增加节点数量，系统性能得到整体提升"],["D","传统电信行业一般采用 Scale Out 模式进行扩展"]],"answer":["B","D"],"ans_raw":"BD","explain":"向扩展（ ScaleOut）：增加节点数量（而不是配置规格）来提高整个集群的性能及 QoS。 22","source":"华为认证HCNA-Cloud云计算题库.pdf","subject":"hcna_cloud","id":"hcna_cloud-223","note":"","flag":"","pnum":223,"ex_src":"题源"}]};
